insert into public.course_modules (id, course_id, orden, slug, titulo, descripcion, objetivos, requisitos, relacion, tiempo_min, conceptos_clave, terminologia, confusiones, recursos, estado)
values ('d646e09e-853b-5540-a901-76e40b559f0e', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 2, 'investigacion-psicologica', 'Cómo investiga la psicología', 'Por qué la psicología necesita investigar, qué métodos usa para describir la conducta, cómo distingue una correlación de una relación causa efecto y qué normas éticas protegen a los participantes.', '["Al terminar sabrás explicar por qué el conocimiento psicológico necesita datos y cómo se relacionan teoría e hipótesis.", "Al terminar sabrás distinguir estudios de caso, observación, encuestas e investigación de archivo, transversal y longitudinal.", "Al terminar sabrás diferenciar correlación y causalidad y describir las partes de un experimento.", "Al terminar sabrás explicar el consentimiento informado y las normas éticas con personas y animales."]'::jsonb, '{}'::text[], '', 76, '["Teoría e hipótesis", "Falsabilidad", "Métodos descriptivos", "Muestra representativa", "Correlación", "Variable de confusión", "Experimento", "Asignación aleatoria y doble ciego", "Ética", "Consentimiento informado"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"mapa": {"centro": "n1", "nodos": [{"id": "n1", "texto": "Investigación psicológica"}, {"id": "n2", "texto": "Teoría e hipótesis", "ref": "por-que-investigar#b8"}, {"id": "n3", "texto": "Falsabilidad", "ref": "por-que-investigar#b9"}, {"id": "n4", "texto": "Métodos descriptivos", "ref": "metodos-descriptivos#b2"}, {"id": "n5", "texto": "Muestra representativa", "ref": "metodos-descriptivos#b7"}, {"id": "n6", "texto": "Correlación", "ref": "correlacion-y-experimento#b2"}, {"id": "n7", "texto": "Variable de confusión", "ref": "correlacion-y-experimento#b4"}, {"id": "n8", "texto": "Experimento", "ref": "correlacion-y-experimento#b7"}, {"id": "n9", "texto": "Asignación aleatoria y doble ciego", "ref": "correlacion-y-experimento#b8"}, {"id": "n10", "texto": "Ética", "ref": "etica-en-investigacion#b4"}, {"id": "n11", "texto": "Consentimiento informado", "ref": "etica-en-investigacion#b5"}], "enlaces": [{"de": "n1", "a": "n2", "rotulo": "parte de una"}, {"de": "n2", "a": "n3", "rotulo": "exige"}, {"de": "n1", "a": "n4", "rotulo": "describe con"}, {"de": "n4", "a": "n5", "rotulo": "necesita una"}, {"de": "n1", "a": "n6", "rotulo": "relaciona variables con la"}, {"de": "n6", "a": "n7", "rotulo": "puede deberse a una"}, {"de": "n1", "a": "n8", "rotulo": "busca causas con el"}, {"de": "n8", "a": "n9", "rotulo": "se apoya en"}, {"de": "n1", "a": "n10", "rotulo": "se rige por la"}, {"de": "n10", "a": "n11", "rotulo": "exige el"}]}, "esquema": [{"texto": "Cómo investiga la psicología", "hijos": [{"texto": "Por qué investigar", "hijos": [{"texto": "El sentido común engaña"}, {"texto": "Deducción e inducción"}, {"texto": "Teoría, hipótesis, falsabilidad"}]}, {"texto": "Métodos descriptivos", "hijos": [{"texto": "Estudio de caso"}, {"texto": "Observación naturalista"}, {"texto": "Encuesta y muestra"}, {"texto": "Archivo, transversal, longitudinal"}]}, {"texto": "Correlación y experimento", "hijos": [{"texto": "Correlación no es causalidad"}, {"texto": "Variables independiente y dependiente"}, {"texto": "Asignación aleatoria, placebo, doble ciego"}, {"texto": "Fiabilidad, validez, replicación"}]}, {"texto": "Ética", "hijos": [{"texto": "Comité de ética"}, {"texto": "Consentimiento informado"}, {"texto": "Tres erres con animales"}]}]}], "tablas": [{"titulo": "Piezas de un experimento", "cab": ["Elemento", "Qué es"], "filas": [["Variable independiente", "Lo que el investigador manipula"], ["Variable dependiente", "Lo que se mide para ver el efecto"], ["Grupo control", "Grupo que no recibe la manipulación y sirve de comparación"]], "ref": ["correlacion-y-experimento#b10"], "evidencia": ["Lo que el investigador manipula", "Lo que se mide para ver el efecto"]}, {"titulo": "Transversal y longitudinal", "cab": ["Diseño", "Cómo se hace"], "filas": [["Transversal", "Se comparan a la vez grupos de distintas edades"], ["Longitudinal", "Se sigue a las mismas personas durante años"]], "ref": ["metodos-descriptivos#b10"], "evidencia": ["Se sigue a las mismas personas durante años"]}], "tarjetas": [{"id": "t1", "frente": "¿Qué es el razonamiento deductivo?", "reverso": "Partir de una idea general y deducir qué debería ocurrir en un caso concreto.", "ref": ["por-que-investigar#b5"], "evidencia": ["partimos de una idea general y deducimos"]}, {"id": "t2", "frente": "¿Qué es el razonamiento inductivo?", "reverso": "Llegar a una conclusión general a partir de muchas observaciones concretas.", "ref": ["por-que-investigar#b5"], "evidencia": ["a partir de muchas observaciones concretas llegamos a una conclusión general"]}, {"id": "t3", "frente": "¿Qué significa que una hipótesis sea falsable?", "reverso": "Que es posible diseñar un estudio que demuestre que es falsa.", "ref": ["por-que-investigar#b9"], "evidencia": ["debe ser posible diseñar un estudio que demuestre que es falsa"]}, {"id": "t4", "frente": "¿Cuál es el principal límite del estudio de caso?", "reverso": "Lo observado en una persona no se puede generalizar a la población.", "ref": ["metodos-descriptivos#b3"], "evidencia": ["no se puede generalizar a la población"]}, {"id": "t5", "frente": "¿Qué es la observación naturalista?", "reverso": "Estudiar la conducta en su entorno habitual, sin manipular nada.", "ref": ["metodos-descriptivos#b4"], "evidencia": ["se estudia la conducta en su entorno habitual"]}, {"id": "t6", "frente": "¿Qué es una muestra aleatoria?", "reverso": "Aquella en la que cada miembro de la población tiene la misma probabilidad de ser elegido.", "ref": ["metodos-descriptivos#b7"], "evidencia": ["cada miembro de la población tiene la misma probabilidad de ser elegido"]}, {"id": "t7", "frente": "¿Qué hace un estudio longitudinal?", "reverso": "Sigue a las mismas personas durante años.", "ref": ["metodos-descriptivos#b10"], "evidencia": ["Se sigue a las mismas personas durante años"]}, {"id": "t8", "frente": "¿Qué indica una correlación negativa?", "reverso": "Que cuando una variable sube, la otra baja.", "ref": ["correlacion-y-experimento#b2"], "evidencia": ["cuando una sube la otra baja"]}, {"id": "t9", "frente": "¿Qué es una variable de confusión?", "reverso": "Un tercer factor que explica la relación entre dos variables.", "ref": ["correlacion-y-experimento#b4"], "evidencia": ["A ese tercer factor se le llama variable de confusión"]}, {"id": "t10", "frente": "¿Qué es la correlación ilusoria?", "reverso": "Creer que existe una relación que en realidad no existe.", "ref": ["correlacion-y-experimento#b5"], "evidencia": ["creer que existe una relación que en realidad no existe"]}, {"id": "t11", "frente": "¿Qué es la variable independiente?", "reverso": "La que el investigador manipula.", "ref": ["correlacion-y-experimento#b7"], "evidencia": ["manipula una variable, la variable independiente"]}, {"id": "t12", "frente": "¿Para qué sirve la asignación aleatoria?", "reverso": "Para que las diferencias previas entre personas se repartan por igual entre los grupos.", "ref": ["correlacion-y-experimento#b8"], "evidencia": ["las diferencias previas entre personas se reparten por igual"]}, {"id": "t13", "frente": "¿Qué es un estudio doble ciego?", "reverso": "Aquel en que ni los participantes ni quienes recogen los datos saben quién está en cada grupo.", "ref": ["correlacion-y-experimento#b9"], "evidencia": ["ni los participantes ni quienes recogen los datos saben quién está en cada grupo"]}, {"id": "t14", "frente": "¿Qué diferencia hay entre fiabilidad y validez?", "reverso": "Fiable es la medida consistente; válida, la que mide lo que dice medir.", "ref": ["correlacion-y-experimento#b12"], "evidencia": ["es válida si mide lo que dice medir"]}, {"id": "t15", "frente": "¿Qué debe garantizar el consentimiento informado?", "reverso": "Que el participante conoce el estudio, sus riesgos y puede retirarse en cualquier momento sin consecuencias.", "ref": ["etica-en-investigacion#b5"], "evidencia": ["puede retirarse en cualquier momento sin ninguna consecuencia"]}, {"id": "t16", "frente": "¿Cuáles son las tres erres de la investigación con animales?", "reverso": "Reemplazar, reducir y refinar.", "ref": ["etica-en-investigacion#b10"], "evidencia": ["Usar métodos sin animales cuando sea posible"]}], "feynman": [{"id": "fy1", "concepto": "Correlación no es causalidad", "pregunta": "Explica con el ejemplo de los helados y los ahogamientos por qué una correlación no demuestra una causa.", "elementos": [{"idea": "Dos variables cambian juntas", "palabras": ["juntas", "correlación", "aumentan"]}, {"idea": "Un tercer factor las explica", "palabras": ["calor", "tercer", "confusión"]}, {"idea": "Hace falta un experimento para hablar de causa", "palabras": ["experimento", "causa", "manipular"]}], "ref": ["correlacion-y-experimento#b4"], "evidencia": ["A ese tercer factor se le llama variable de confusión"]}, {"id": "fy2", "concepto": "Cómo funciona un experimento", "pregunta": "Describe cómo diseñarías un experimento para saber si tomar notas a mano mejora la comprensión.", "elementos": [{"idea": "Manipular la variable independiente", "palabras": ["independiente", "manipula", "a mano"]}, {"idea": "Medir la variable dependiente", "palabras": ["dependiente", "mide", "recuerdan"]}, {"idea": "Asignar al azar a los grupos", "palabras": ["aleatoria", "azar", "control"]}], "ref": ["correlacion-y-experimento#b7", "correlacion-y-experimento#b8"], "evidencia": ["La clave es la asignación aleatoria"]}, {"id": "fy3", "concepto": "Ética con participantes", "pregunta": "Explica qué derechos tiene una persona que participa en un estudio psicológico.", "elementos": [{"idea": "Recibir información clara", "palabras": ["informado", "riesgos", "explica"]}, {"idea": "Retirarse sin consecuencias", "palabras": ["retirarse", "cualquier momento", "consecuencia"]}, {"idea": "Protección de sus datos", "palabras": ["confidencialidad", "datos", "proteger"]}], "ref": ["etica-en-investigacion#b5"], "evidencia": ["cómo se protegerá la confidencialidad"]}]}'::jsonb, 'publicado')
