insert into public.course_modules (id, course_id, orden, slug, titulo, descripcion, objetivos, requisitos, relacion, tiempo_min, conceptos_clave, terminologia, confusiones, recursos, estado)
values ('b1ee3556-0c8b-501a-b6b6-2c0d18a71f91', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 5, 'sensacion-y-percepcion', 'Sensación y percepción', 'Cómo los sentidos captan la energía del mundo y cómo el cerebro la convierte en experiencias: umbrales y atención, la visión, la audición, los demás sentidos y los principios de la Gestalt.', '["Al terminar sabrás distinguir sensación y percepción y explicar los umbrales, la adaptación sensorial y la atención.", "Al terminar sabrás describir el ojo, la retina, la visión del color y las claves de profundidad.", "Al terminar sabrás explicar cómo el oído convierte el sonido en señales nerviosas y los tipos de pérdida auditiva.", "Al terminar sabrás describir el gusto, el olfato, el tacto, el dolor y el equilibrio, y aplicar los principios de la Gestalt."]'::jsonb, '{}'::text[], '', 76, '["Transducción", "Umbrales", "Atención y expectativas", "Conos y bastones", "Visión del color", "Claves de profundidad", "Cóclea y células ciliadas", "Pérdida auditiva", "Gusto, olfato, tacto y dolor", "Principios de la Gestalt"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"mapa": {"centro": "n1", "nodos": [{"id": "n1", "texto": "Sensación y percepción"}, {"id": "n2", "texto": "Transducción", "ref": "sentir-y-percibir#b2"}, {"id": "n3", "texto": "Umbrales", "ref": "sentir-y-percibir#b3"}, {"id": "n4", "texto": "Atención y expectativas", "ref": "sentir-y-percibir#b7"}, {"id": "n5", "texto": "Conos y bastones", "ref": "la-vision#b5"}, {"id": "n6", "texto": "Visión del color", "ref": "la-vision#b8"}, {"id": "n7", "texto": "Claves de profundidad", "ref": "la-vision#b9"}, {"id": "n8", "texto": "Cóclea y células ciliadas", "ref": "la-audicion#b4"}, {"id": "n9", "texto": "Pérdida auditiva", "ref": "la-audicion#b9"}, {"id": "n10", "texto": "Gusto, olfato, tacto y dolor", "ref": "otros-sentidos-y-gestalt#b2"}, {"id": "n11", "texto": "Principios de la Gestalt", "ref": "otros-sentidos-y-gestalt#b9"}], "enlaces": [{"de": "n1", "a": "n2", "rotulo": "empieza con la"}, {"de": "n1", "a": "n3", "rotulo": "tiene límites o"}, {"de": "n1", "a": "n4", "rotulo": "depende de la"}, {"de": "n1", "a": "n5", "rotulo": "en la visión usa"}, {"de": "n5", "a": "n6", "rotulo": "permiten la"}, {"de": "n5", "a": "n7", "rotulo": "se completan con"}, {"de": "n1", "a": "n8", "rotulo": "en la audición usa"}, {"de": "n8", "a": "n9", "rotulo": "su daño causa"}, {"de": "n1", "a": "n10", "rotulo": "incluye además"}, {"de": "n1", "a": "n11", "rotulo": "organiza según los"}]}, "esquema": [{"texto": "Sensación y percepción", "hijos": [{"texto": "Conceptos básicos", "hijos": [{"texto": "Transducción"}, {"texto": "Umbral absoluto y diferencial"}, {"texto": "Adaptación, atención, expectativas"}]}, {"texto": "Visión", "hijos": [{"texto": "Longitud de onda y amplitud"}, {"texto": "Retina: conos y bastones"}, {"texto": "Tricromática y procesos oponentes"}, {"texto": "Claves binoculares y monoculares"}]}, {"texto": "Audición", "hijos": [{"texto": "Decibelios y hercios"}, {"texto": "Tímpano, huesecillos, cóclea"}, {"texto": "Conducción y neurosensorial"}]}, {"texto": "Otros sentidos y Gestalt", "hijos": [{"texto": "Gusto y olfato"}, {"texto": "Tacto, dolor, equilibrio"}, {"texto": "Figura y fondo, proximidad, semejanza, cierre"}]}]}], "tablas": [{"titulo": "Conos y bastones", "cab": ["Receptor", "Para qué sirve"], "filas": [["Conos", "Color, detalle y visión con buena luz"], ["Bastones", "Visión con poca luz y del movimiento, sin color"]], "ref": ["la-vision#b5"], "evidencia": ["Color, detalle y visión con buena luz"]}, {"titulo": "Principios de la Gestalt", "cab": ["Principio", "Qué hacemos"], "filas": [["Proximidad", "Agrupar los elementos que están cerca"], ["Cierre", "Completar figuras incompletas"]], "ref": ["otros-sentidos-y-gestalt#b9"], "evidencia": ["Completar figuras incompletas"]}], "tarjetas": [{"id": "t1", "frente": "¿Qué es la transducción?", "reverso": "La conversión de un estímulo en una señal nerviosa por un receptor sensorial.", "ref": ["sentir-y-percibir#b2"], "evidencia": ["Esa conversión se llama transducción"]}, {"id": "t2", "frente": "¿Qué es el umbral absoluto?", "reverso": "La intensidad mínima de un estímulo que detectamos la mitad de las veces.", "ref": ["sentir-y-percibir#b3"], "evidencia": ["la intensidad mínima de un estímulo que detectamos la mitad de las veces"]}, {"id": "t3", "frente": "¿Qué dice la ley de Weber?", "reverso": "La diferencia mínima que notamos es una proporción constante del estímulo.", "ref": ["sentir-y-percibir#b3"], "evidencia": ["esa diferencia es una proporción constante del estímulo"]}, {"id": "t4", "frente": "¿Qué es la adaptación sensorial?", "reverso": "Dejar de responder a un estímulo que no cambia.", "ref": ["sentir-y-percibir#b6"], "evidencia": ["Cuando un estímulo no cambia, los receptores dejan de responder"]}, {"id": "t5", "frente": "¿Qué es la ceguera por falta de atención?", "reverso": "No ver algo evidente porque la atención está en otra cosa.", "ref": ["sentir-y-percibir#b7"], "evidencia": ["Esto se llama ceguera por falta de atención"]}, {"id": "t6", "frente": "¿Qué es el procesamiento de arriba abajo?", "reverso": "El conocimiento y las expectativas guían la interpretación.", "ref": ["sentir-y-percibir#b8"], "evidencia": ["El conocimiento y las expectativas guían la interpretación"]}, {"id": "t7", "frente": "¿Qué determina la longitud de onda de la luz?", "reverso": "El color.", "ref": ["la-vision#b2"], "evidencia": ["la longitud de onda determina el color"]}, {"id": "t8", "frente": "¿Qué es la fóvea?", "reverso": "El centro de la retina, donde se concentran los conos y la visión es más nítida.", "ref": ["la-vision#b4"], "evidencia": ["concentra los conos y nos da la visión más nítida"]}, {"id": "t9", "frente": "¿Por qué tenemos un punto ciego?", "reverso": "Porque donde nace el nervio óptico no hay receptores.", "ref": ["la-vision#b4"], "evidencia": ["Donde este nace no hay receptores"]}, {"id": "t10", "frente": "¿Qué explica la teoría de los procesos oponentes?", "reverso": "Que el color se procesa en pares opuestos, lo que explica las posimágenes.", "ref": ["la-vision#b8"], "evidencia": ["el color se procesa en pares opuestos"]}, {"id": "t11", "frente": "¿Qué es la disparidad binocular?", "reverso": "La pequeña diferencia entre la imagen de cada ojo, que el cerebro usa para calcular la distancia.", "ref": ["la-vision#b9"], "evidencia": ["la pequeña diferencia entre la imagen de cada ojo"]}, {"id": "t12", "frente": "¿En qué unidad se mide el volumen del sonido?", "reverso": "En decibelios.", "ref": ["la-audicion#b2"], "evidencia": ["se mide en decibelios"]}, {"id": "t13", "frente": "¿Qué hacen las células ciliadas?", "reverso": "Transforman el movimiento del líquido de la cóclea en señales nerviosas.", "ref": ["la-audicion#b4"], "evidencia": ["transforman el movimiento del líquido en señales"]}, {"id": "t14", "frente": "¿Qué es la pérdida auditiva neurosensorial?", "reverso": "La causada por daño en las células ciliadas o en el nervio auditivo.", "ref": ["la-audicion#b9"], "evidencia": ["Las células ciliadas o el nervio auditivo están dañados"]}, {"id": "t15", "frente": "¿Cuáles son los cinco sabores básicos?", "reverso": "Dulce, salado, ácido, amargo y umami.", "ref": ["otros-sentidos-y-gestalt#b2"], "evidencia": ["dulce, salado, ácido, amargo y umami"]}, {"id": "t16", "frente": "¿Qué es el dolor neuropático?", "reverso": "El que se debe a un daño en los propios nervios.", "ref": ["otros-sentidos-y-gestalt#b5"], "evidencia": ["se debe a un daño en los propios nervios"]}], "feynman": [{"id": "fy1", "concepto": "Sensación y percepción", "pregunta": "Explica la diferencia entre sensación y percepción con el ejemplo de oír a un amigo en una fiesta.", "elementos": [{"idea": "La sensación capta el estímulo", "palabras": ["receptor", "ondas", "transducción"]}, {"idea": "La percepción interpreta", "palabras": ["interpretar", "reconocer", "significado"]}, {"idea": "La atención y las expectativas influyen", "palabras": ["atención", "expectativas", "nombre"]}], "ref": ["sentir-y-percibir#b2", "sentir-y-percibir#b7"], "evidencia": ["reconocer en ellas la voz de un amigo es percepción"]}, {"id": "fy2", "concepto": "Cómo vemos el color", "pregunta": "Explica por qué ves roja una bandera verde después de mirarla fijamente.", "elementos": [{"idea": "Hay tres tipos de conos", "palabras": ["conos", "tres", "tricromática"]}, {"idea": "El color se procesa en pares opuestos", "palabras": ["oponentes", "rojo", "verde"]}, {"idea": "El cansancio de un par produce la posimagen", "palabras": ["posimagen", "fijamente", "blanca"]}], "ref": ["la-vision#b8"], "evidencia": ["Esta segunda teoría explica las posimágenes"]}, {"id": "fy3", "concepto": "Del sonido al cerebro", "pregunta": "Describe el viaje de una nota musical desde el aire hasta tu cerebro.", "elementos": [{"idea": "El tímpano vibra", "palabras": ["tímpano", "vibra", "pabellón"]}, {"idea": "Los huesecillos llevan la vibración a la cóclea", "palabras": ["martillo", "estribo", "cóclea"]}, {"idea": "Las células ciliadas generan la señal nerviosa", "palabras": ["ciliadas", "nervio", "temporal"]}], "ref": ["la-audicion#b4"], "evidencia": ["transforman el movimiento del líquido en señales"]}]}'::jsonb, 'publicado')
