insert into public.course_modules (id, course_id, orden, slug, titulo, descripcion, objetivos, requisitos, relacion, tiempo_min, conceptos_clave, terminologia, confusiones, recursos, estado)
values ('493d207d-d989-55b4-85b1-5b2b6f9a310c', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 7, 'pensamiento-e-inteligencia', 'Pensamiento, lenguaje e inteligencia', 'Cómo organizamos el conocimiento en conceptos y esquemas, cómo adquirimos el lenguaje, cómo resolvemos problemas y qué sesgos nos engañan, y qué sabemos sobre la inteligencia, cómo se mide y de dónde viene.', '["Al terminar sabrás explicar qué son la cognición, los conceptos, los prototipos y los esquemas.", "Al terminar sabrás describir los componentes del lenguaje y las etapas de su desarrollo.", "Al terminar sabrás distinguir algoritmos y heurísticos y reconocer los principales sesgos cognitivos.", "Al terminar sabrás comparar las teorías de la inteligencia y explicar cómo se mide y qué influye en ella."]'::jsonb, '{}'::text[], '', 77, '["Conceptos y prototipos", "Esquemas", "Componentes del lenguaje", "Periodo sensible", "Algoritmos y heurísticos", "Fijeza funcional", "Sesgos cognitivos", "Teorías de la inteligencia", "Medida y curva normal", "Genes y ambiente"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"mapa": {"centro": "n1", "nodos": [{"id": "n1", "texto": "Pensamiento e inteligencia"}, {"id": "n2", "texto": "Conceptos y prototipos", "ref": "conceptos-y-esquemas#b4"}, {"id": "n3", "texto": "Esquemas", "ref": "conceptos-y-esquemas#b7"}, {"id": "n4", "texto": "Componentes del lenguaje", "ref": "el-lenguaje#b3"}, {"id": "n5", "texto": "Periodo sensible", "ref": "el-lenguaje#b7"}, {"id": "n6", "texto": "Algoritmos y heurísticos", "ref": "resolver-problemas#b2"}, {"id": "n7", "texto": "Fijeza funcional", "ref": "resolver-problemas#b5"}, {"id": "n8", "texto": "Sesgos cognitivos", "ref": "resolver-problemas#b7"}, {"id": "n9", "texto": "Teorías de la inteligencia", "ref": "la-inteligencia#b3"}, {"id": "n10", "texto": "Medida y curva normal", "ref": "la-inteligencia#b7"}, {"id": "n11", "texto": "Genes y ambiente", "ref": "la-inteligencia#b9"}], "enlaces": [{"de": "n1", "a": "n2", "rotulo": "organiza con"}, {"de": "n2", "a": "n3", "rotulo": "se amplían en"}, {"de": "n1", "a": "n4", "rotulo": "se expresa en el lenguaje con"}, {"de": "n4", "a": "n5", "rotulo": "se aprenden en un"}, {"de": "n1", "a": "n6", "rotulo": "resuelve problemas con"}, {"de": "n6", "a": "n7", "rotulo": "encuentran obstáculos como la"}, {"de": "n6", "a": "n8", "rotulo": "pueden producir"}, {"de": "n1", "a": "n9", "rotulo": "se explica con"}, {"de": "n9", "a": "n10", "rotulo": "se evalúa con"}, {"de": "n9", "a": "n11", "rotulo": "depende de"}]}, "esquema": [{"texto": "Pensamiento, lenguaje e inteligencia", "hijos": [{"texto": "Cognición", "hijos": [{"texto": "Conceptos naturales y artificiales"}, {"texto": "Prototipos"}, {"texto": "Esquemas de rol y de evento"}]}, {"texto": "Lenguaje", "hijos": [{"texto": "Fonema, morfema, semántica, sintaxis"}, {"texto": "Etapas del desarrollo"}, {"texto": "Chomsky y periodo sensible"}, {"texto": "Sapir y Whorf"}]}, {"texto": "Problemas", "hijos": [{"texto": "Ensayo y error, algoritmo, heurístico"}, {"texto": "Fijeza funcional"}, {"texto": "Sesgos: anclaje, confirmación, disponibilidad"}]}, {"texto": "Inteligencia", "hijos": [{"texto": "Spearman, Cattell, Sternberg, Gardner"}, {"texto": "Tests estandarizados, media 100"}, {"texto": "Genes, ambiente, efecto Flynn"}]}]}], "tablas": [{"titulo": "Sesgos cognitivos", "cab": ["Sesgo", "En qué consiste"], "filas": [["Anclaje", "Fijarse demasiado en el primer dato que recibimos"], ["Confirmación", "Buscar solo lo que confirma lo que ya creemos"], ["Disponibilidad", "Juzgar la frecuencia por lo fácil que nos viene un ejemplo"]], "ref": ["resolver-problemas#b7"], "evidencia": ["Buscar solo lo que confirma lo que ya creemos"]}, {"titulo": "Teorías de la inteligencia", "cab": ["Autor", "Propuesta"], "filas": [["Spearman", "Un factor general (g) presente en todas las capacidades"], ["Sternberg", "Teoría triárquica: analítica, creativa y práctica"]], "ref": ["la-inteligencia#b3"], "evidencia": ["Teoría triárquica: analítica, creativa y práctica"]}], "tarjetas": [{"id": "t1", "frente": "¿Qué es la cognición?", "reverso": "El pensamiento: los procesos con los que adquirimos, comprendemos, recordamos y usamos el conocimiento.", "ref": ["conceptos-y-esquemas#b2"], "evidencia": ["La cognición es el pensamiento"]}, {"id": "t2", "frente": "¿Qué es un prototipo?", "reverso": "El ejemplo más típico de un concepto.", "ref": ["conceptos-y-esquemas#b5"], "evidencia": ["un prototipo, el ejemplo más típico"]}, {"id": "t3", "frente": "¿Qué es un esquema de evento?", "reverso": "Una secuencia habitual de acciones, como comportarse en un ascensor.", "ref": ["conceptos-y-esquemas#b7"], "evidencia": ["describen secuencias de acciones habituales"]}, {"id": "t4", "frente": "¿Qué es un fonema?", "reverso": "La unidad mínima de sonido que distingue palabras.", "ref": ["el-lenguaje#b3"], "evidencia": ["Unidad mínima de sonido que distingue palabras"]}, {"id": "t5", "frente": "¿Qué es un morfema?", "reverso": "La unidad mínima con significado.", "ref": ["el-lenguaje#b3"], "evidencia": ["Unidad mínima con significado"]}, {"id": "t6", "frente": "¿Qué propuso Chomsky sobre el lenguaje?", "reverso": "Que nacemos con una capacidad innata, un dispositivo de adquisición del lenguaje.", "ref": ["el-lenguaje#b6"], "evidencia": ["dispositivo de adquisición del lenguaje"]}, {"id": "t7", "frente": "¿Qué demuestra el caso de Genie?", "reverso": "Que existe un periodo sensible para aprender el lenguaje.", "ref": ["el-lenguaje#b7"], "evidencia": ["Esto apoya la idea de un periodo sensible"]}, {"id": "t8", "frente": "¿Qué es un algoritmo?", "reverso": "Un procedimiento paso a paso que garantiza la solución.", "ref": ["resolver-problemas#b2"], "evidencia": ["un procedimiento paso a paso que garantiza la solución"]}, {"id": "t9", "frente": "¿Qué es un heurístico?", "reverso": "Un atajo mental basado en la experiencia, rápido pero no siempre acertado.", "ref": ["resolver-problemas#b2"], "evidencia": ["un atajo mental basado en la experiencia"]}, {"id": "t10", "frente": "¿Qué es la fijeza funcional?", "reverso": "La incapacidad de ver un objeto con un uso distinto del habitual.", "ref": ["resolver-problemas#b5"], "evidencia": ["la incapacidad de ver un objeto con un uso distinto del habitual"]}, {"id": "t11", "frente": "¿Qué es el sesgo de anclaje?", "reverso": "Fijarse demasiado en el primer dato que recibimos.", "ref": ["resolver-problemas#b7"], "evidencia": ["Fijarse demasiado en el primer dato que recibimos"]}, {"id": "t12", "frente": "¿Qué es el sesgo de disponibilidad?", "reverso": "Juzgar la frecuencia de algo por lo fácil que nos viene un ejemplo a la mente.", "ref": ["resolver-problemas#b7"], "evidencia": ["Juzgar la frecuencia por lo fácil que nos viene un ejemplo"]}, {"id": "t13", "frente": "¿Qué diferencia hay entre inteligencia fluida y cristalizada?", "reverso": "La fluida resuelve problemas nuevos; la cristalizada es el conocimiento acumulado.", "ref": ["la-inteligencia#b2"], "evidencia": ["el conocimiento acumulado, que sigue creciendo con la edad"]}, {"id": "t14", "frente": "¿Qué es el pensamiento divergente?", "reverso": "El que busca muchas respuestas posibles a un problema.", "ref": ["la-inteligencia#b4"], "evidencia": ["que busca muchas respuestas posibles a un problema"]}, {"id": "t15", "frente": "¿Cuál es la media y la desviación típica del cociente intelectual?", "reverso": "Media 100 y desviación típica 15.", "ref": ["la-inteligencia#b7"], "evidencia": ["El cociente intelectual medio es 100, con una desviación típica de 15"]}, {"id": "t16", "frente": "¿Qué es el efecto Flynn?", "reverso": "La subida de las puntuaciones medias de inteligencia generación tras generación.", "ref": ["la-inteligencia#b9"], "evidencia": ["la subida de las puntuaciones medias generación tras generación"]}], "feynman": [{"id": "fy1", "concepto": "Los esquemas", "pregunta": "Explica qué es un esquema con el ejemplo de lo que haces al entrar en un ascensor, y cuándo puede fallar.", "elementos": [{"idea": "Es un marco mental que dice qué esperar", "palabras": ["marco", "esperar", "organiza"]}, {"idea": "Los guiones son secuencias de acciones", "palabras": ["guion", "secuencia", "ascensor"]}, {"idea": "Pueden fallar si no se ajustan a la situación", "palabras": ["estereotipos", "piloto automático", "error"]}], "ref": ["conceptos-y-esquemas#b7", "conceptos-y-esquemas#b9"], "evidencia": ["Un esquema es un marco mental que organiza lo que sabemos"]}, {"id": "fy2", "concepto": "Heurísticos y sesgos", "pregunta": "Explica por qué mucha gente teme más volar que ir en coche aunque el coche sea más peligroso.", "elementos": [{"idea": "Usamos atajos mentales", "palabras": ["heurístico", "atajo", "rápido"]}, {"idea": "Lo llamativo nos viene antes a la mente", "palabras": ["disponibilidad", "llamativos", "mente"]}, {"idea": "Sobrestimamos su probabilidad", "palabras": ["probabilidad", "sobrestimamos", "frecuentes"]}], "ref": ["resolver-problemas#b8"], "evidencia": ["sobrestimamos su probabilidad"]}, {"id": "fy3", "concepto": "Interpretar el cociente intelectual", "pregunta": "Explica a un familiar qué significa que un niño tenga un cociente intelectual de 115.", "elementos": [{"idea": "La media es 100 con desviación típica 15", "palabras": ["100", "15", "media"]}, {"idea": "La curva normal agrupa a la mayoría en el centro", "palabras": ["curva", "campana", "68"]}, {"idea": "No resume todo el valor de la persona", "palabras": ["límites", "sesgo", "capacidades"]}], "ref": ["la-inteligencia#b7", "la-inteligencia#b10"], "evidencia": ["cerca del 68 por ciento de la población puntúa entre 85 y 115"]}]}'::jsonb, 'publicado')
