insert into public.course_modules (id, course_id, orden, slug, titulo, descripcion, objetivos, requisitos, relacion, tiempo_min, conceptos_clave, terminologia, confusiones, recursos, estado)
values ('f1986a53-6723-546e-9556-6e82798e5b54', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 8, 'memoria', 'La memoria', 'Cómo codificamos, almacenamos y recuperamos la información, qué estructuras cerebrales lo hacen posible, por qué olvidamos y recordamos mal, y qué técnicas con base científica ayudan a recordar mejor.', '["Al terminar sabrás describir la codificación, el almacenamiento y la recuperación, y el modelo de memoria en tres almacenes.", "Al terminar sabrás relacionar el hipocampo, la amígdala, el cerebelo y la corteza prefrontal con distintos tipos de memoria.", "Al terminar sabrás explicar la amnesia, el olvido, la interferencia y los recuerdos falsos.", "Al terminar sabrás aplicar estrategias eficaces para estudiar y recordar."]'::jsonb, '{}'::text[], '', 74, '["Codificación, almacenamiento, recuperación", "Tres almacenes", "Explícita e implícita", "Hipocampo y H. M.", "Consolidación", "Recuerdos de destello", "Amnesia", "Interferencia", "Recuerdos falsos", "Práctica espaciada y de recuperación"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"mapa": {"centro": "n1", "nodos": [{"id": "n1", "texto": "Memoria"}, {"id": "n2", "texto": "Codificación, almacenamiento, recuperación", "ref": "como-funciona-la-memoria#b2"}, {"id": "n3", "texto": "Tres almacenes", "ref": "como-funciona-la-memoria#b6"}, {"id": "n4", "texto": "Explícita e implícita", "ref": "como-funciona-la-memoria#b9"}, {"id": "n5", "texto": "Hipocampo y H. M.", "ref": "memoria-y-cerebro#b4"}, {"id": "n6", "texto": "Consolidación", "ref": "memoria-y-cerebro#b6"}, {"id": "n7", "texto": "Recuerdos de destello", "ref": "memoria-y-cerebro#b8"}, {"id": "n8", "texto": "Amnesia", "ref": "olvido-y-recuerdos-falsos#b2"}, {"id": "n9", "texto": "Interferencia", "ref": "olvido-y-recuerdos-falsos#b7"}, {"id": "n10", "texto": "Recuerdos falsos", "ref": "olvido-y-recuerdos-falsos#b9"}, {"id": "n11", "texto": "Práctica espaciada y de recuperación", "ref": "mejorar-la-memoria#b5"}], "enlaces": [{"de": "n1", "a": "n2", "rotulo": "funciona en tres pasos"}, {"de": "n2", "a": "n3", "rotulo": "pasa por"}, {"de": "n3", "a": "n4", "rotulo": "a largo plazo se divide en"}, {"de": "n1", "a": "n5", "rotulo": "depende del"}, {"de": "n5", "a": "n6", "rotulo": "permite la"}, {"de": "n6", "a": "n7", "rotulo": "se intensifica en los"}, {"de": "n1", "a": "n8", "rotulo": "se pierde en la"}, {"de": "n1", "a": "n9", "rotulo": "falla por"}, {"de": "n9", "a": "n10", "rotulo": "y se deforma en"}, {"de": "n1", "a": "n11", "rotulo": "mejora con la"}]}, "esquema": [{"texto": "La memoria", "hijos": [{"texto": "Funcionamiento", "hijos": [{"texto": "Codificar, almacenar, recuperar"}, {"texto": "Sensorial, corto y largo plazo"}, {"texto": "Explícita: episódica y semántica"}, {"texto": "Implícita: procedimental y priming"}]}, {"texto": "Cerebro", "hijos": [{"texto": "Hipocampo, amígdala, cerebelo, prefrontal"}, {"texto": "Consolidación y sueño"}, {"texto": "Recuerdos de destello"}]}, {"texto": "Fallos", "hijos": [{"texto": "Amnesia anterógrada y retrógrada"}, {"texto": "Curva del olvido"}, {"texto": "Interferencia proactiva y retroactiva"}, {"texto": "Información engañosa"}]}, {"texto": "Mejorar", "hijos": [{"texto": "Repaso elaborativo y mnemotecnias"}, {"texto": "Práctica espaciada"}, {"texto": "Práctica de recuperación"}, {"texto": "Sueño y sin multitarea"}]}]}], "tablas": [{"titulo": "Los tres almacenes", "cab": ["Almacén", "Duración"], "filas": [["Sensorial", "Menos de un segundo a unos pocos segundos"], ["Corto plazo", "Unos 20 segundos sin repaso"], ["Largo plazo", "De minutos a toda la vida"]], "ref": ["como-funciona-la-memoria#b6"], "evidencia": ["Unos 20 segundos sin repaso"]}, {"titulo": "Estrategias de estudio", "cab": ["Estrategia", "Eficacia"], "filas": [["Releer y subrayar", "Baja"], ["Práctica espaciada", "Alta"], ["Práctica de recuperación", "Alta"]], "ref": ["mejorar-la-memoria#b6"], "evidencia": ["Recordar sin mirar refuerza las vías de acceso"]}], "tarjetas": [{"id": "t1", "frente": "¿Cuáles son los tres procesos de la memoria?", "reverso": "Codificación, almacenamiento y recuperación.", "ref": ["como-funciona-la-memoria#b2"], "evidencia": ["La codificación es la entrada"]}, {"id": "t2", "frente": "¿Qué es el efecto de autorreferencia?", "reverso": "Recordamos mejor lo que relacionamos con nosotros mismos.", "ref": ["como-funciona-la-memoria#b3"], "evidencia": ["recordamos mejor lo que relacionamos con nosotros mismos"]}, {"id": "t3", "frente": "¿Cuántos elementos retiene la memoria a corto plazo?", "reverso": "Unos siete, más o menos dos.", "ref": ["como-funciona-la-memoria#b7"], "evidencia": ["siete elementos, más o menos dos"]}, {"id": "t4", "frente": "¿Qué es la memoria de trabajo?", "reverso": "Un espacio donde mantenemos y manipulamos información, como al hacer una cuenta mental.", "ref": ["como-funciona-la-memoria#b7"], "evidencia": ["un espacio donde manipulamos la información"]}, {"id": "t5", "frente": "¿Qué guarda la memoria episódica?", "reverso": "Vivencias situadas en un momento y lugar.", "ref": ["como-funciona-la-memoria#b10"], "evidencia": ["guarda vivencias situadas en un momento y lugar"]}, {"id": "t6", "frente": "¿Qué es la memoria procedimental?", "reverso": "La memoria de habilidades, como conducir o montar en bicicleta.", "ref": ["como-funciona-la-memoria#b10"], "evidencia": ["La procedimental guarda habilidades"]}, {"id": "t7", "frente": "¿Qué es el priming?", "reverso": "Que un estímulo previo facilita el reconocimiento de otro sin darnos cuenta.", "ref": ["como-funciona-la-memoria#b10"], "evidencia": ["un estímulo previo facilita el reconocimiento de otro"]}, {"id": "t8", "frente": "¿Qué demostró el caso de H. M.?", "reverso": "Que la memoria explícita y la implícita dependen de sistemas distintos; el hipocampo es clave para los recuerdos explícitos nuevos.", "ref": ["memoria-y-cerebro#b4"], "evidencia": ["la memoria explícita y la implícita dependen de sistemas distintos"]}, {"id": "t9", "frente": "¿Qué es la consolidación?", "reverso": "La estabilización de un recuerdo nuevo con el tiempo, en la que el hipocampo lo transfiere a la corteza.", "ref": ["memoria-y-cerebro#b6"], "evidencia": ["se estabiliza mediante la consolidación"]}, {"id": "t10", "frente": "¿Qué tienen de especial los recuerdos de destello?", "reverso": "Son vívidos y generan mucha seguridad, pero no son necesariamente exactos.", "ref": ["memoria-y-cerebro#b8"], "evidencia": ["Lo que se mantiene es la seguridad, no la exactitud"]}, {"id": "t11", "frente": "¿Qué es la amnesia anterógrada?", "reverso": "La incapacidad de formar recuerdos nuevos tras el daño.", "ref": ["olvido-y-recuerdos-falsos#b2"], "evidencia": ["La capacidad de formar recuerdos nuevos tras el daño"]}, {"id": "t12", "frente": "¿Qué muestra la curva del olvido de Ebbinghaus?", "reverso": "Que perdemos mucha información en las primeras horas y después el olvido se hace más lento.", "ref": ["olvido-y-recuerdos-falsos#b5"], "evidencia": ["perdemos mucha información en las primeras horas"]}, {"id": "t13", "frente": "¿Qué es la interferencia retroactiva?", "reverso": "Lo nuevo dificulta recordar lo antiguo.", "ref": ["olvido-y-recuerdos-falsos#b7"], "evidencia": ["lo nuevo dificulta recordar lo antiguo"]}, {"id": "t14", "frente": "¿Qué es el efecto de la información engañosa?", "reverso": "La alteración de un recuerdo por información recibida después del suceso.", "ref": ["olvido-y-recuerdos-falsos#b9"], "evidencia": ["Es el efecto de la información engañosa"]}, {"id": "t15", "frente": "¿Qué es la práctica espaciada?", "reverso": "Repartir el estudio en varias sesiones separadas por días.", "ref": ["mejorar-la-memoria#b5"], "evidencia": ["repartir el estudio en varias sesiones separadas por días"]}, {"id": "t16", "frente": "¿Por qué releer es poco eficaz?", "reverso": "Porque da una falsa sensación de dominio al resultar familiar el texto.", "ref": ["mejorar-la-memoria#b5"], "evidencia": ["Releer da una falsa sensación de dominio"]}], "feynman": [{"id": "fy1", "concepto": "El viaje de un recuerdo", "pregunta": "Explica qué le pasa a un número de teléfono desde que lo oyes hasta que, si lo usas mucho, lo recuerdas durante años.", "elementos": [{"idea": "Entra en la memoria sensorial y pasa a corto plazo si lo atiendes", "palabras": ["sensorial", "atención", "corto plazo"]}, {"idea": "La corto plazo tiene poca capacidad y duración", "palabras": ["siete", "20 segundos", "bloques"]}, {"idea": "El repaso lo pasa a largo plazo", "palabras": ["repaso", "largo plazo", "consolidación"]}], "ref": ["como-funciona-la-memoria#b5", "como-funciona-la-memoria#b7"], "evidencia": ["pasa a la memoria a largo plazo"]}, {"id": "fy2", "concepto": "La memoria reconstruye", "pregunta": "Explica por qué un testigo sincero puede recordar algo que no ocurrió.", "elementos": [{"idea": "La memoria reconstruye al recordar", "palabras": ["reconstruye", "recordar", "nueva"]}, {"idea": "La información posterior altera el recuerdo", "palabras": ["engañosa", "Loftus", "estrellaron"]}, {"idea": "La seguridad no garantiza la exactitud", "palabras": ["seguridad", "exactitud", "sincero"]}], "ref": ["olvido-y-recuerdos-falsos#b9", "olvido-y-recuerdos-falsos#b10"], "evidencia": ["recuerdan con sinceridad algo que no ocurrió así"]}, {"id": "fy3", "concepto": "Estudiar con ciencia", "pregunta": "Diseña un plan para estudiar este curso usando lo que sabes sobre la memoria.", "elementos": [{"idea": "Repartir el estudio en varias sesiones", "palabras": ["espaciada", "sesiones", "días"]}, {"idea": "Ponerse a prueba sin mirar", "palabras": ["recuperación", "tarjetas", "preguntas"]}, {"idea": "Dormir y evitar distracciones", "palabras": ["dormir", "multitarea", "móvil"]}], "ref": ["mejorar-la-memoria#b5", "mejorar-la-memoria#b8"], "evidencia": ["fortalece el recuerdo más que releer"]}]}'::jsonb, 'publicado')
