insert into public.course_modules (id, course_id, orden, slug, titulo, descripcion, objetivos, requisitos, relacion, tiempo_min, conceptos_clave, terminologia, confusiones, recursos, estado)
values ('c32a2753-b62a-570e-885d-83656c2d46e3', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 9, 'desarrollo-a-lo-largo-de-la-vida', 'El desarrollo a lo largo de la vida', 'Cómo cambiamos desde la concepción hasta la vejez: los grandes debates y teorías del desarrollo, el embarazo y la infancia, el apego, la adolescencia, la adultez y la forma en que afrontamos la muerte y el duelo.', '["Al terminar sabrás explicar los debates del desarrollo y las teorías de Erikson, Piaget y Kohlberg.", "Al terminar sabrás describir el desarrollo prenatal, los riesgos de los teratógenos y los tipos de apego.", "Al terminar sabrás describir los cambios de la adolescencia y de las etapas de la adultez.", "Al terminar sabrás explicar el modelo de Kübler Ross, sus límites y el valor de los cuidados paliativos."]'::jsonb, '{}'::text[], '', 74, '["Físico, cognitivo y psicosocial", "Etapas de Erikson", "Etapas de Piaget", "Razonamiento moral de Kohlberg", "Desarrollo prenatal y teratógenos", "Apego", "Adolescencia", "Etapas de la adultez", "Kübler Ross", "Cuidados paliativos"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"mapa": {"centro": "n1", "nodos": [{"id": "n1", "texto": "Desarrollo a lo largo de la vida"}, {"id": "n2", "texto": "Físico, cognitivo y psicosocial", "ref": "teorias-del-desarrollo#b2"}, {"id": "n3", "texto": "Etapas de Erikson", "ref": "teorias-del-desarrollo#b7"}, {"id": "n4", "texto": "Etapas de Piaget", "ref": "teorias-del-desarrollo#b10"}, {"id": "n5", "texto": "Razonamiento moral de Kohlberg", "ref": "teorias-del-desarrollo#b11"}, {"id": "n6", "texto": "Desarrollo prenatal y teratógenos", "ref": "embarazo-e-infancia#b2"}, {"id": "n7", "texto": "Apego", "ref": "embarazo-e-infancia#b8"}, {"id": "n8", "texto": "Adolescencia", "ref": "adolescencia-y-adultez#b2"}, {"id": "n9", "texto": "Etapas de la adultez", "ref": "adolescencia-y-adultez#b7"}, {"id": "n10", "texto": "Kübler Ross", "ref": "muerte-y-duelo#b2"}, {"id": "n11", "texto": "Cuidados paliativos", "ref": "muerte-y-duelo#b6"}], "enlaces": [{"de": "n1", "a": "n2", "rotulo": "abarca lo"}, {"de": "n1", "a": "n3", "rotulo": "se explica con las"}, {"de": "n1", "a": "n4", "rotulo": "se explica con las"}, {"de": "n4", "a": "n5", "rotulo": "inspiró los niveles de"}, {"de": "n1", "a": "n6", "rotulo": "empieza con el"}, {"de": "n6", "a": "n7", "rotulo": "sigue con el"}, {"de": "n7", "a": "n8", "rotulo": "continúa en la"}, {"de": "n8", "a": "n9", "rotulo": "da paso a las"}, {"de": "n9", "a": "n10", "rotulo": "termina con la muerte según"}, {"de": "n10", "a": "n11", "rotulo": "se acompaña con"}]}, "esquema": [{"texto": "Desarrollo a lo largo de la vida", "hijos": [{"texto": "Teorías", "hijos": [{"texto": "Dominios y debates"}, {"texto": "Erikson: ocho conflictos"}, {"texto": "Piaget: cuatro etapas"}, {"texto": "Kohlberg: tres niveles morales"}]}, {"texto": "Embarazo e infancia", "hijos": [{"texto": "Germinal, embrionaria, fetal"}, {"texto": "Teratógenos"}, {"texto": "Reflejos, hitos motores, permanencia del objeto"}, {"texto": "Apego y sus tipos"}]}, {"texto": "Adolescencia y adultez", "hijos": [{"texto": "Pubertad y cerebro"}, {"texto": "Identidad"}, {"texto": "Adultez emergente, media y tardía"}]}, {"texto": "Muerte y duelo", "hijos": [{"texto": "Kübler Ross y sus límites"}, {"texto": "Cuidados paliativos"}, {"texto": "Instrucciones previas"}, {"texto": "Duelo"}]}]}], "tablas": [{"titulo": "Etapas de Piaget", "cab": ["Etapa", "Edad"], "filas": [["Sensoriomotora", "0 a 2 años"], ["Preoperacional", "2 a 7 años"], ["Operaciones concretas", "7 a 11 años"], ["Operaciones formales", "Desde los 12 años"]], "ref": ["teorias-del-desarrollo#b10"], "evidencia": ["Piensa en abstracto e hipotético"]}, {"titulo": "Tipos de apego", "cab": ["Tipo", "Conducta"], "filas": [["Seguro", "Explora con el cuidador presente, se inquieta cuando sale y se calma al volver"], ["Evitativo", "Apenas reacciona cuando el cuidador sale ni cuando vuelve"]], "ref": ["embarazo-e-infancia#b10"], "evidencia": ["se calma al volver"]}], "tarjetas": [{"id": "t1", "frente": "¿Cuáles son los tres dominios del desarrollo?", "reverso": "Físico, cognitivo y psicosocial.", "ref": ["teorias-del-desarrollo#b2"], "evidencia": ["El psicosocial incluye las emociones, la personalidad y las relaciones"]}, {"id": "t2", "frente": "¿Qué conflicto describe Erikson para la adolescencia?", "reverso": "Identidad frente a confusión de roles.", "ref": ["teorias-del-desarrollo#b7"], "evidencia": ["Identidad frente a confusión de roles"]}, {"id": "t3", "frente": "¿Qué conflicto describe Erikson para el primer año?", "reverso": "Confianza frente a desconfianza.", "ref": ["teorias-del-desarrollo#b7"], "evidencia": ["Confianza frente a desconfianza"]}, {"id": "t4", "frente": "¿Qué es la acomodación según Piaget?", "reverso": "Cambiar los esquemas cuando lo nuevo no encaja.", "ref": ["teorias-del-desarrollo#b9"], "evidencia": ["al cambiar sus esquemas cuando lo nuevo no encaja"]}, {"id": "t5", "frente": "¿En qué etapa de Piaget se domina la conservación?", "reverso": "En la de operaciones concretas, de 7 a 11 años.", "ref": ["teorias-del-desarrollo#b10"], "evidencia": ["Razona con lógica sobre lo concreto; domina la conservación"]}, {"id": "t6", "frente": "¿Qué caracteriza el nivel posconvencional de Kohlberg?", "reverso": "El razonamiento guiado por principios éticos universales.", "ref": ["teorias-del-desarrollo#b11"], "evidencia": ["guiado por principios éticos universales"]}, {"id": "t7", "frente": "¿Cuál es la etapa prenatal más vulnerable?", "reverso": "La embrionaria, cuando se forman los órganos principales.", "ref": ["embarazo-e-infancia#b2"], "evidencia": ["por eso es el periodo más vulnerable"]}, {"id": "t8", "frente": "¿Qué es un teratógeno?", "reverso": "Un agente que puede dañar al embrión o al feto, como el alcohol.", "ref": ["embarazo-e-infancia#b3"], "evidencia": ["son agentes que pueden dañar al embrión o al feto"]}, {"id": "t9", "frente": "¿Qué es la permanencia del objeto?", "reverso": "Entender que las cosas siguen existiendo aunque no se vean.", "ref": ["embarazo-e-infancia#b6"], "evidencia": ["entiende que las cosas siguen existiendo aunque no las vea"]}, {"id": "t10", "frente": "¿Qué demostró Harlow con sus monos?", "reverso": "Que el apego depende del contacto y el consuelo, no solo de la comida.", "ref": ["embarazo-e-infancia#b8"], "evidencia": ["el apego depende del contacto y el consuelo"]}, {"id": "t11", "frente": "¿Qué es la situación extraña?", "reverso": "Una prueba de Ainsworth para observar el tipo de apego según cómo reacciona el niño al reencuentro.", "ref": ["embarazo-e-infancia#b9"], "evidencia": ["Mary Ainsworth diseñó la situación extraña"]}, {"id": "t12", "frente": "¿Qué es el temperamento?", "reverso": "El estilo emocional con el que nace cada niño.", "ref": ["embarazo-e-infancia#b11"], "evidencia": ["el estilo emocional con el que nace cada niño"]}, {"id": "t13", "frente": "¿Por qué los adolescentes buscan más riesgos?", "reverso": "Porque la corteza prefrontal madura más tarde que el sistema emocional y de recompensa.", "ref": ["adolescencia-y-adultez#b3"], "evidencia": ["no termina de madurar hasta pasados los veinte años"]}, {"id": "t14", "frente": "¿Qué es la adultez emergente?", "reverso": "Una etapa de exploración entre los 18 y los 25 años aproximadamente.", "ref": ["adolescencia-y-adultez#b6"], "evidencia": ["entre los 18 y los 25 años aproximadamente"]}, {"id": "t15", "frente": "¿Cuáles son las cinco reacciones de Kübler Ross?", "reverso": "Negación, ira, negociación, depresión y aceptación.", "ref": ["muerte-y-duelo#b3"], "evidencia": ["Negación: rechazar la noticia"]}, {"id": "t16", "frente": "¿Qué buscan los cuidados paliativos?", "reverso": "Aliviar síntomas, cuidar el bienestar y apoyar a la familia, no alargar la vida a toda costa.", "ref": ["muerte-y-duelo#b6"], "evidencia": ["no es alargar la vida a toda costa"]}], "feynman": [{"id": "fy1", "concepto": "Cómo piensan los niños", "pregunta": "Explica a unos padres por qué su hijo de cuatro años cree que hay más zumo en un vaso alto y estrecho que en uno bajo y ancho.", "elementos": [{"idea": "Está en la etapa preoperacional", "palabras": ["preoperacional", "2 a 7", "etapa"]}, {"idea": "Aún no domina la conservación", "palabras": ["conservación", "cantidad", "forma"]}, {"idea": "La dominará en las operaciones concretas", "palabras": ["concretas", "7", "lógica"]}], "ref": ["teorias-del-desarrollo#b10"], "evidencia": ["no domina la conservación"]}, {"id": "fy2", "concepto": "El apego", "pregunta": "Explica qué es el apego seguro y por qué importa, usando el experimento de Harlow.", "elementos": [{"idea": "El apego depende del contacto y el consuelo", "palabras": ["contacto", "consuelo", "felpa"]}, {"idea": "El cuidador es una base segura", "palabras": ["base segura", "explorar", "Bowlby"]}, {"idea": "Predice mejores relaciones", "palabras": ["seguro", "relaciones", "sensible"]}], "ref": ["embarazo-e-infancia#b8", "embarazo-e-infancia#b11"], "evidencia": ["predice mejores relaciones sociales"]}, {"id": "fy3", "concepto": "El cerebro adolescente", "pregunta": "Explica por qué un adolescente puede ser muy inteligente y aun así tomar decisiones arriesgadas con sus amigos.", "elementos": [{"idea": "El sistema emocional madura antes", "palabras": ["emociones", "recompensa", "pronto"]}, {"idea": "La corteza prefrontal madura tarde", "palabras": ["prefrontal", "impulsos", "veinte"]}, {"idea": "Los iguales aumentan el riesgo", "palabras": ["amigos", "iguales", "sensaciones"]}], "ref": ["adolescencia-y-adultez#b3"], "evidencia": ["sobre todo cuando están con amigos"]}]}'::jsonb, 'publicado')
on conflict (id) do update set orden = excluded.orden, slug = excluded.slug, titulo = excluded.titulo, descripcion = excluded.descripcion, objetivos = excluded.objetivos, requisitos = excluded.requisitos, relacion = excluded.relacion, tiempo_min = excluded.tiempo_min, conceptos_clave = excluded.conceptos_clave, terminologia = excluded.terminologia, confusiones = excluded.confusiones, recursos = excluded.recursos, estado = 'publicado';
insert into public.course_lessons (id, module_id, orden, slug, titulo, minutos, objetivos, secciones, lo_esencial, bloques, figuras_previstas, correlacion_clinica, origen, fuentes, estado)
values ('1109963a-a0e8-580a-bddc-66cf26a56f31', 'c32a2753-b62a-570e-885d-83656c2d46e3', 1, 'teorias-del-desarrollo', 'Debates y teorías del desarrollo', 22, '["Describir los tres dominios y los grandes debates del desarrollo.", "Explicar las etapas psicosociales de Erikson.", "Explicar las etapas cognitivas de Piaget y los niveles morales de Kohlberg."]'::jsonb, '["Qué estudia la psicología del desarrollo", "Erikson: ocho etapas psicosociales", "Piaget: cómo piensan los niños"]'::jsonb, '["El desarrollo es físico, cognitivo y psicosocial, y dura toda la vida.", "Erikson describió ocho etapas, cada una con un conflicto que resolver.", "Piaget describió cuatro etapas del pensamiento infantil.", "Kohlberg describió tres niveles de razonamiento moral."]'::jsonb, '[{"id": "b1", "t": "h", "texto": "Qué estudia la psicología del desarrollo"}, {"id": "b2", "t": "p", "texto": "La **psicología del desarrollo** estudia cómo cambiamos a lo largo de toda la vida en tres dominios. El **físico** incluye el crecimiento del cuerpo y del cerebro, las capacidades sensoriales y motoras y la salud. El **cognitivo** incluye el aprendizaje, la atención, la memoria, el lenguaje y el razonamiento. El **psicosocial** incluye las emociones, la personalidad y las relaciones. Los tres se influyen: un niño que empieza a caminar explora más, lo que estimula su pensamiento y cambia su relación con los demás."}, {"id": "b3", "t": "compara", "titulo": "Tres grandes debates", "cab": ["Debate", "Una postura", "La otra postura"], "filas": [["¿Continuo o por etapas?", "El cambio es gradual y acumulativo", "Hay saltos cualitativos entre etapas"], ["¿Un camino o muchos?", "Todos seguimos la misma secuencia", "El contexto y la cultura crean caminos distintos"], ["¿Naturaleza o crianza?", "Lo decisivo son los genes", "Lo decisivo es el ambiente"]]}, {"id": "b4", "t": "p", "texto": "Hoy se acepta una visión integradora: algunos cambios son graduales y otros parecen etapas, hay secuencias comunes que la cultura modula y, como vimos en el tema de biopsicología, genes y ambiente interactúan siempre."}, {"id": "b5", "t": "h", "texto": "Erikson: ocho etapas psicosociales"}, {"id": "b6", "t": "p", "texto": "**Erik Erikson** amplió las ideas de Freud y propuso que el desarrollo dura toda la vida. En cada una de sus ocho etapas aparece un **conflicto psicosocial** que, si se resuelve bien, deja una fortaleza. Un bebé cuyas necesidades se atienden de forma constante desarrolla confianza básica; uno desatendido, desconfianza."}, {"t": "imagen", "src": "cursos/img/psi-9-4.webp", "w": 244, "h": 305, "alt": "Fotografía de Erik Erikson en sus últimos años.", "pie": "Erik Erikson describió ocho etapas psicosociales que abarcan toda la vida.", "credito": {"autor": "OpenStax, Psychology 2e (Spielman, Jenkins y Lovett)", "licencia": "CC BY 4.0", "url_licencia": "https://creativecommons.org/licenses/by/4.0/", "pagina": "https://espanol.libretexts.org/Bookshelves/Ciencias_Sociales/Psicologia/Psicolog%C3%ADa_Introductoria_2e_(OpenStax)/09%3A_Desarrollo_de_la_vida_%C3%BAtil/9.03%3A_Teor%C3%ADas_de_la_Vida"}}, {"id": "b7", "t": "tabla", "titulo": "Las etapas de Erikson", "cab": ["Edad aproximada", "Conflicto", "Logro si se resuelve"], "filas": [["0 a 1 año", "Confianza frente a desconfianza", "Esperanza"], ["1 a 3 años", "Autonomía frente a vergüenza y duda", "Voluntad"], ["3 a 6 años", "Iniciativa frente a culpa", "Propósito"], ["7 a 11 años", "Laboriosidad frente a inferioridad", "Competencia"], ["12 a 18 años", "Identidad frente a confusión de roles", "Fidelidad"], ["Adultez temprana", "Intimidad frente a aislamiento", "Amor"], ["Adultez media", "Generatividad frente a estancamiento", "Cuidado"], ["Vejez", "Integridad frente a desesperación", "Sabiduría"]]}, {"id": "b8", "t": "h", "texto": "Piaget: cómo piensan los niños"}, {"id": "b9", "t": "p", "texto": "**Jean Piaget** observó que los niños no son adultos en miniatura: piensan de forma distinta. Propuso que construyen su conocimiento mediante **esquemas** que amplían por **asimilación**, al encajar lo nuevo en lo que ya saben, y por **acomodación**, al cambiar sus esquemas cuando lo nuevo no encaja. Un niño que llama perro a una vaca está asimilando; cuando aprende que es otro animal, acomoda."}, {"t": "imagen", "src": "cursos/img/psi-9-5.webp", "w": 244, "h": 408, "alt": "Fotografía de Jean Piaget en sus últimos años.", "pie": "Jean Piaget estudió cómo cambia el pensamiento de los niños con la edad.", "credito": {"autor": "OpenStax, Psychology 2e (Spielman, Jenkins y Lovett)", "licencia": "CC BY 4.0", "url_licencia": "https://creativecommons.org/licenses/by/4.0/", "pagina": "https://espanol.libretexts.org/Bookshelves/Ciencias_Sociales/Psicologia/Psicolog%C3%ADa_Introductoria_2e_(OpenStax)/09%3A_Desarrollo_de_la_vida_%C3%BAtil/9.03%3A_Teor%C3%ADas_de_la_Vida"}}, {"id": "b10", "t": "tabla", "titulo": "Las etapas de Piaget", "cab": ["Etapa", "Edad", "Logros y límites"], "filas": [["Sensoriomotora", "0 a 2 años", "Conoce el mundo con los sentidos y la acción; adquiere la permanencia del objeto"], ["Preoperacional", "2 a 7 años", "Usa símbolos y lenguaje; pensamiento egocéntrico; no domina la conservación"], ["Operaciones concretas", "7 a 11 años", "Razona con lógica sobre lo concreto; domina la conservación"], ["Operaciones formales", "Desde los 12 años", "Piensa en abstracto e hipotético"]]}, {"id": "b11", "t": "p", "texto": "**Lawrence Kohlberg** estudió el razonamiento moral planteando dilemas, como el de un hombre que roba un medicamento para salvar a su esposa. Lo que le interesaba no era la respuesta, sino el porqué. Describió tres niveles: **preconvencional**, centrado en evitar castigos y obtener premios; **convencional**, centrado en las normas y la aprobación social; y **posconvencional**, guiado por principios éticos universales. Carol Gilligan criticó que su teoría se basaba sobre todo en varones y dejaba fuera una ética del cuidado."}, {"t": "imagen", "src": "cursos/img/psi-9-6.webp", "w": 649, "h": 557, "alt": "Cuadro de tres niveles y seis estadios del razonamiento moral de Kohlberg.", "pie": "Los niveles de Kohlberg: preconvencional, convencional y posconvencional.", "credito": {"autor": "OpenStax, Psychology 2e (Spielman, Jenkins y Lovett)", "licencia": "CC BY 4.0", "url_licencia": "https://creativecommons.org/licenses/by/4.0/", "pagina": "https://espanol.libretexts.org/Bookshelves/Ciencias_Sociales/Psicologia/Psicolog%C3%ADa_Introductoria_2e_(OpenStax)/09%3A_Desarrollo_de_la_vida_%C3%BAtil/9.03%3A_Teor%C3%ADas_de_la_Vida"}}]'::jsonb, '[]'::jsonb, null, 'mixto', '[]'::jsonb, 'publicado')
on conflict (id) do update set module_id = excluded.module_id, orden = excluded.orden, titulo = excluded.titulo, minutos = excluded.minutos, objetivos = excluded.objetivos, secciones = excluded.secciones, lo_esencial = excluded.lo_esencial, bloques = excluded.bloques, figuras_previstas = excluded.figuras_previstas, correlacion_clinica = excluded.correlacion_clinica, origen = excluded.origen, fuentes = excluded.fuentes, estado = 'publicado';
insert into public.course_lessons (id, module_id, orden, slug, titulo, minutos, objetivos, secciones, lo_esencial, bloques, figuras_previstas, correlacion_clinica, origen, fuentes, estado)
values ('b1447c4a-febb-564c-bd46-10b0777b754e', 'c32a2753-b62a-570e-885d-83656c2d46e3', 2, 'embarazo-e-infancia', 'Del embarazo a la infancia', 20, '["Describir las etapas del desarrollo prenatal y los teratógenos.", "Explicar el desarrollo motor y cognitivo del bebé.", "Describir el apego y sus tipos."]'::jsonb, '["Antes de nacer", "El bebé", "El apego"]'::jsonb, '["El desarrollo prenatal tiene tres etapas: germinal, embrionaria y fetal.", "Los teratógenos, como el alcohol, pueden dañar al embrión y al feto.", "Harlow mostró que el apego depende del contacto y el consuelo, no solo de la comida.", "El apego seguro se asocia a mejores relaciones a lo largo de la vida."]'::jsonb, '[{"id": "b1", "t": "h", "texto": "Antes de nacer"}, {"id": "b2", "t": "p", "texto": "El desarrollo empieza con la **concepción**, cuando un espermatozoide fecunda un óvulo y forma el **cigoto**. La **etapa germinal**, las dos primeras semanas, termina cuando el cigoto se implanta en el útero. La **etapa embrionaria**, hasta la semana ocho, es cuando se forman los órganos principales, y por eso es el periodo más vulnerable. En la **etapa fetal**, desde la semana nueve hasta el nacimiento, el feto crece y sus sistemas maduran."}, {"t": "imagen", "src": "cursos/img/psi-9-8.webp", "w": 731, "h": 763, "alt": "Serie de imágenes del embrión y el feto en distintas semanas de desarrollo.", "pie": "El desarrollo prenatal: los órganos se forman en la etapa embrionaria y el feto crece y madura después.", "credito": {"autor": "OpenStax, Psychology 2e (Spielman, Jenkins y Lovett)", "licencia": "CC BY 4.0", "url_licencia": "https://creativecommons.org/licenses/by/4.0/", "pagina": "https://espanol.libretexts.org/Bookshelves/Ciencias_Sociales/Psicologia/Psicolog%C3%ADa_Introductoria_2e_(OpenStax)/09%3A_Desarrollo_de_la_vida_%C3%BAtil/9.04%3A_Etapas_de_Desarrollo"}}, {"id": "b3", "t": "p", "texto": "Los **teratógenos** son agentes que pueden dañar al embrión o al feto: el alcohol, el tabaco, algunas drogas y fármacos, ciertas infecciones y la contaminación. El alcohol puede causar el **síndrome alcohólico fetal**, con rasgos faciales característicos, problemas de crecimiento y discapacidad intelectual. No se conoce una cantidad segura de alcohol durante el embarazo, por lo que se recomienda no beber nada. Por eso son tan importantes los **cuidados prenatales**."}, {"id": "b4", "t": "h", "texto": "El bebé"}, {"id": "b5", "t": "p", "texto": "El recién nacido no es una hoja en blanco. Nace con **reflejos** que le ayudan a sobrevivir, como el de búsqueda, que le hace girar la cabeza hacia lo que le roza la mejilla, y el de succión. Prefiere la voz de su madre y las caras humanas. Su **desarrollo motor** sigue una secuencia bastante fija: sostener la cabeza, sentarse, gatear, ponerse de pie y caminar, en torno al año. Los niños alcanzan estos hitos a ritmos algo distintos, y la cultura influye en ellos."}, {"t": "imagen", "src": "cursos/img/psi-9-10.webp", "w": 975, "h": 244, "alt": "Cuatro fotos de bebés cada vez mayores: sosteniendo la cabeza, sentado, gateando y de pie.", "pie": "Los hitos motores siguen una secuencia: sostener la cabeza, sentarse, gatear y caminar.", "credito": {"autor": "OpenStax, Psychology 2e (Spielman, Jenkins y Lovett). Crédito “izquierda”: modificación de obra de Kerry Ceszyk; crédito “media-izquierda”: modificación de obra de Kristi Fausel; crédito “media-derecha”: modificación de obra por “devinf” /Flickr; crédito “derecho”: modificación de obra por Rose Spielman", "licencia": "CC BY 4.0", "url_licencia": "https://creativecommons.org/licenses/by/4.0/", "pagina": "https://espanol.libretexts.org/Bookshelves/Ciencias_Sociales/Psicologia/Psicolog%C3%ADa_Introductoria_2e_(OpenStax)/09%3A_Desarrollo_de_la_vida_%C3%BAtil/9.04%3A_Etapas_de_Desarrollo"}}, {"id": "b6", "t": "p", "texto": "Hacia los ocho meses, el bebé adquiere la **permanencia del objeto**: entiende que las cosas siguen existiendo aunque no las vea. Antes, si escondemos un juguete bajo una manta, actúa como si hubiera desaparecido. Estudios posteriores sugieren que los bebés entienden más de lo que Piaget pensaba: se sorprenden cuando un objeto atraviesa otro sólido."}, {"t": "imagen", "src": "cursos/img/psi-9-11.webp", "w": 975, "h": 188, "alt": "Ilustración de un camión de juguete que rueda por una vía, a veces tapada por una pantalla.", "pie": "Estudios con objetos que se ocultan muestran que los bebés entienden más de lo que se creía.", "credito": {"autor": "OpenStax, Psychology 2e (Spielman, Jenkins y Lovett)", "licencia": "CC BY 4.0", "url_licencia": "https://creativecommons.org/licenses/by/4.0/", "pagina": "https://espanol.libretexts.org/Bookshelves/Ciencias_Sociales/Psicologia/Psicolog%C3%ADa_Introductoria_2e_(OpenStax)/09%3A_Desarrollo_de_la_vida_%C3%BAtil/9.04%3A_Etapas_de_Desarrollo"}}, {"id": "b7", "t": "h", "texto": "El apego"}, {"id": "b8", "t": "p", "texto": "El **apego** es el vínculo emocional entre el niño y su cuidador. Harry Harlow crió monos recién nacidos con dos madres artificiales: una de alambre que daba leche y otra de felpa que no daba comida. Los monos pasaban casi todo el tiempo con la de felpa, sobre todo cuando se asustaban. Demostró que el apego depende del **contacto y el consuelo**, no solo de la alimentación. John Bowlby propuso que el apego es una necesidad biológica que da al niño una **base segura** desde la que explorar."}, {"id": "b9", "t": "p", "texto": "Mary Ainsworth diseñó la **situación extraña**: el niño juega en una sala con su cuidador, entra un desconocido, el cuidador sale y luego vuelve. La forma en que el niño reacciona al reencuentro revela su tipo de apego."}, {"id": "b10", "t": "tabla", "titulo": "Tipos de apego", "cab": ["Tipo", "Conducta del niño"], "filas": [["Seguro", "Explora con el cuidador presente, se inquieta cuando sale y se calma al volver"], ["Evitativo", "Apenas reacciona cuando el cuidador sale ni cuando vuelve"], ["Ambivalente o resistente", "Se angustia mucho y al volver busca al cuidador pero se resiste a ser consolado"], ["Desorganizado", "Conductas confusas y contradictorias, a menudo ligadas a cuidados aterradores"]]}, {"id": "b11", "t": "p", "texto": "El **apego seguro** se asocia a un cuidador sensible y disponible, y predice mejores relaciones sociales y regulación emocional más adelante. También influye el **temperamento**, el estilo emocional con el que nace cada niño: unos son tranquilos y fáciles, otros más difíciles o lentos para adaptarse."}]'::jsonb, '[]'::jsonb, null, 'mixto', '[]'::jsonb, 'publicado')
