insert into public.course_modules (id, course_id, orden, slug, titulo, descripcion, objetivos, requisitos, relacion, tiempo_min, conceptos_clave, terminologia, confusiones, recursos, estado)
values ('2fdef6dd-e714-5f16-84da-38c7e5f6e003', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 11, 'personalidad', 'La personalidad', 'Qué es la personalidad y cómo la han explicado el psicoanálisis, los neofreudianos, el humanismo, el aprendizaje, la biología y las teorías de rasgos, cómo influye la cultura y cómo se evalúa.', '["Al terminar sabrás definir la personalidad y explicar el modelo de Freud, sus estructuras, defensas y etapas.", "Al terminar sabrás describir las aportaciones de Adler, Jung, Horney, Rogers y Maslow.", "Al terminar sabrás explicar el locus de control, la autoeficacia, el temperamento y el modelo de los Cinco Grandes.", "Al terminar sabrás comparar las culturas individualistas y colectivistas y los tests de autoinforme y proyectivos."]'::jsonb, '{}'::text[], '', 74, '["Inconsciente de Freud", "Ello, yo y superyó", "Mecanismos de defensa", "Neofreudianos", "Rogers: yo real e ideal", "Autoeficacia y locus de control", "Temperamento y genética", "Cinco Grandes", "Individualismo y colectivismo", "Autoinforme y proyectivos"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"mapa": {"centro": "n1", "nodos": [{"id": "n1", "texto": "Personalidad"}, {"id": "n2", "texto": "Inconsciente de Freud", "ref": "personalidad-y-psicoanalisis#b5"}, {"id": "n3", "texto": "Ello, yo y superyó", "ref": "personalidad-y-psicoanalisis#b6"}, {"id": "n4", "texto": "Mecanismos de defensa", "ref": "personalidad-y-psicoanalisis#b8"}, {"id": "n5", "texto": "Neofreudianos", "ref": "neofreudianos-y-humanistas#b6"}, {"id": "n6", "texto": "Rogers: yo real e ideal", "ref": "neofreudianos-y-humanistas#b8"}, {"id": "n7", "texto": "Autoeficacia y locus de control", "ref": "aprendizaje-biologia-y-rasgos#b3"}, {"id": "n8", "texto": "Temperamento y genética", "ref": "aprendizaje-biologia-y-rasgos#b5"}, {"id": "n9", "texto": "Cinco Grandes", "ref": "aprendizaje-biologia-y-rasgos#b8"}, {"id": "n10", "texto": "Individualismo y colectivismo", "ref": "cultura-y-evaluacion#b2"}, {"id": "n11", "texto": "Autoinforme y proyectivos", "ref": "cultura-y-evaluacion#b7"}], "enlaces": [{"de": "n1", "a": "n2", "rotulo": "Freud la basó en el"}, {"de": "n2", "a": "n3", "rotulo": "se organiza en"}, {"de": "n3", "a": "n4", "rotulo": "se protege con"}, {"de": "n2", "a": "n5", "rotulo": "lo revisaron los"}, {"de": "n1", "a": "n6", "rotulo": "el humanismo destaca a"}, {"de": "n1", "a": "n7", "rotulo": "el aprendizaje destaca la"}, {"de": "n1", "a": "n8", "rotulo": "tiene una base en el"}, {"de": "n1", "a": "n9", "rotulo": "se describe con los"}, {"de": "n1", "a": "n10", "rotulo": "varía según el"}, {"de": "n1", "a": "n11", "rotulo": "se evalúa con tests de"}]}, "esquema": [{"texto": "La personalidad", "hijos": [{"texto": "Psicoanálisis", "hijos": [{"texto": "Consciente, preconsciente, inconsciente"}, {"texto": "Ello, yo, superyó"}, {"texto": "Mecanismos de defensa"}, {"texto": "Etapas psicosexuales"}]}, {"texto": "Neofreudianos y humanistas", "hijos": [{"texto": "Adler, Jung, Horney"}, {"texto": "Rogers: congruencia y aceptación incondicional"}, {"texto": "Maslow: autorrealización"}]}, {"texto": "Aprendizaje, biología y rasgos", "hijos": [{"texto": "Determinismo recíproco y locus de control"}, {"texto": "Temperamento y gemelos"}, {"texto": "Allport, Cattell, Eysenck"}, {"texto": "Cinco Grandes"}]}, {"texto": "Cultura y evaluación", "hijos": [{"texto": "Individualismo y colectivismo"}, {"texto": "MMPI y escalas de validez"}, {"texto": "Rorschach, TAT y sus límites"}]}]}], "tablas": [{"titulo": "Estructuras de Freud", "cab": ["Estructura", "Qué hace"], "filas": [["Ello", "Busca satisfacer impulsos de inmediato"], ["Superyó", "Representa las normas interiorizadas y genera culpa"], ["Yo", "Media entre el ello, el superyó y la realidad"]], "ref": ["personalidad-y-psicoanalisis#b6"], "evidencia": ["Media entre el ello, el superyó y la realidad"]}, {"titulo": "Cinco Grandes", "cab": ["Rasgo", "Puntuación alta"], "filas": [["Responsabilidad", "Organizado, constante, cumplidor"], ["Neuroticismo", "Ansioso, inestable emocionalmente"]], "ref": ["aprendizaje-biologia-y-rasgos#b8"], "evidencia": ["Organizado, constante, cumplidor"]}], "tarjetas": [{"id": "t1", "frente": "¿Qué es la personalidad?", "reverso": "El patrón duradero de pensamientos, emociones y conductas que caracteriza a una persona.", "ref": ["personalidad-y-psicoanalisis#b2"], "evidencia": ["el patrón duradero de pensamientos, emociones y conductas"]}, {"id": "t2", "frente": "¿Qué es el ello?", "reverso": "La estructura que busca satisfacer impulsos de inmediato, guiada por el principio del placer.", "ref": ["personalidad-y-psicoanalisis#b6"], "evidencia": ["Busca satisfacer impulsos de inmediato"]}, {"id": "t3", "frente": "¿Qué hace el yo según Freud?", "reverso": "Media entre el ello, el superyó y la realidad.", "ref": ["personalidad-y-psicoanalisis#b6"], "evidencia": ["Media entre el ello, el superyó y la realidad"]}, {"id": "t4", "frente": "¿Qué es el desplazamiento?", "reverso": "Descargar un impulso sobre un objetivo más seguro, como gritar a la pareja tras una mala jornada.", "ref": ["personalidad-y-psicoanalisis#b8"], "evidencia": ["Gritar a la pareja tras una mala jornada con el jefe"]}, {"id": "t5", "frente": "¿Qué es la sublimación?", "reverso": "Canalizar un impulso inaceptable hacia algo socialmente valorado.", "ref": ["personalidad-y-psicoanalisis#b8"], "evidencia": ["Canalizar la agresividad en un deporte"]}, {"id": "t6", "frente": "¿Qué es el complejo de inferioridad según Adler?", "reverso": "Un sentimiento de inferioridad excesivo.", "ref": ["neofreudianos-y-humanistas#b3"], "evidencia": ["Cuando ese sentimiento es excesivo hablaba de complejo de inferioridad"]}, {"id": "t7", "frente": "¿Qué es el inconsciente colectivo?", "reverso": "Según Jung, un inconsciente compartido por toda la humanidad con arquetipos universales.", "ref": ["neofreudianos-y-humanistas#b4"], "evidencia": ["compartido por toda la humanidad"]}, {"id": "t8", "frente": "¿Qué es la ansiedad básica según Horney?", "reverso": "La sensación de soledad e indefensión ante un mundo hostil.", "ref": ["neofreudianos-y-humanistas#b5"], "evidencia": ["la sensación de soledad e indefensión ante un mundo hostil"]}, {"id": "t9", "frente": "¿Qué es la congruencia según Rogers?", "reverso": "La coincidencia entre el yo real y el yo ideal.", "ref": ["neofreudianos-y-humanistas#b8"], "evidencia": ["Cuando ambos coinciden hay congruencia y bienestar"]}, {"id": "t10", "frente": "¿Qué es la aceptación incondicional?", "reverso": "Sentirse valorado por lo que uno es y no solo por lo que hace.", "ref": ["neofreudianos-y-humanistas#b8"], "evidencia": ["nos sentimos valorados por lo que somos"]}, {"id": "t11", "frente": "¿Qué es el determinismo recíproco?", "reverso": "La influencia mutua entre persona, conducta y ambiente.", "ref": ["aprendizaje-biologia-y-rasgos#b2"], "evidencia": ["su conducta y el ambiente se influyen mutuamente"]}, {"id": "t12", "frente": "¿Qué es el locus de control interno?", "reverso": "Creer que lo que nos ocurre depende sobre todo de nuestros actos.", "ref": ["aprendizaje-biologia-y-rasgos#b3"], "evidencia": ["creen que lo que les ocurre depende sobre todo de sus actos"]}, {"id": "t13", "frente": "¿Qué es el temperamento?", "reverso": "La base biológica de la personalidad: estilos emocionales desde el nacimiento.", "ref": ["aprendizaje-biologia-y-rasgos#b5"], "evidencia": ["es la base biológica de la personalidad"]}, {"id": "t14", "frente": "¿Cuáles son los Cinco Grandes?", "reverso": "Apertura, responsabilidad, extraversión, amabilidad y neuroticismo.", "ref": ["aprendizaje-biologia-y-rasgos#b8"], "evidencia": ["Apertura a la experiencia"]}, {"id": "t15", "frente": "¿Para qué sirven las escalas de validez del MMPI?", "reverso": "Para detectar respuestas al azar, exageradas o que buscan dar buena imagen.", "ref": ["cultura-y-evaluacion#b5"], "evidencia": ["Incluye escalas de validez"]}, {"id": "t16", "frente": "¿Cuál es el principal problema de los tests proyectivos?", "reverso": "Su interpretación es subjetiva, con baja fiabilidad y validez.", "ref": ["cultura-y-evaluacion#b6"], "evidencia": ["tienen problemas de fiabilidad y validez"]}], "feynman": [{"id": "fy1", "concepto": "El modelo de Freud", "pregunta": "Explica con un ejemplo cotidiano cómo interactúan el ello, el superyó y el yo.", "elementos": [{"idea": "El ello quiere placer inmediato", "palabras": ["ello", "placer", "impulso"]}, {"idea": "El superyó impone la moral", "palabras": ["superyó", "moral", "culpa"]}, {"idea": "El yo busca una solución realista", "palabras": ["yo", "realidad", "media"]}], "ref": ["personalidad-y-psicoanalisis#b6"], "evidencia": ["Principio de realidad"]}, {"id": "fy2", "concepto": "Congruencia y bienestar", "pregunta": "Explica según Rogers por qué alguien muy exigente consigo mismo puede sentirse mal.", "elementos": [{"idea": "Hay un yo real y un yo ideal", "palabras": ["real", "ideal", "autoconcepto"]}, {"idea": "La distancia entre ambos genera malestar", "palabras": ["alejados", "malestar", "congruencia"]}, {"idea": "La aceptación incondicional ayuda", "palabras": ["aceptación", "incondicional", "valorados"]}], "ref": ["neofreudianos-y-humanistas#b8"], "evidencia": ["cuando están muy alejados, malestar"]}, {"id": "fy3", "concepto": "Los Cinco Grandes", "pregunta": "Describe tu personalidad con los Cinco Grandes y explica por qué cada rasgo es un continuo.", "elementos": [{"idea": "Nombrar los cinco rasgos", "palabras": ["apertura", "responsabilidad", "neuroticismo"]}, {"idea": "Cada rasgo va de bajo a alto", "palabras": ["continuo", "intermedio", "alta"]}, {"idea": "Los rasgos predicen conductas", "palabras": ["predicen", "salud", "laboral"]}], "ref": ["aprendizaje-biologia-y-rasgos#b8", "aprendizaje-biologia-y-rasgos#b9"], "evidencia": ["Cada rasgo es un continuo"]}]}'::jsonb, 'publicado')
