insert into public.course_modules (id, course_id, orden, slug, titulo, descripcion, objetivos, requisitos, relacion, tiempo_min, conceptos_clave, terminologia, confusiones, recursos, estado)
values ('dc79e25a-aa73-5db8-99ba-804cc686a8ab', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 12, 'psicologia-social', 'Psicología social', 'Cómo explicamos la conducta de los demás, cómo influyen los roles, las actitudes y la persuasión, por qué nos conformamos y obedecemos, y qué hay detrás del prejuicio, la agresión, la ayuda y la atracción.', '["Al terminar sabrás explicar el error fundamental de atribución y la fuerza de los roles sociales.", "Al terminar sabrás describir la disonancia cognitiva y las dos rutas de la persuasión.", "Al terminar sabrás describir los experimentos de Asch y Milgram y el pensamiento grupal.", "Al terminar sabrás distinguir estereotipo, prejuicio y discriminación y explicar el efecto espectador y la atracción."]'::jsonb, '{}'::text[], '', 76, '["Error fundamental de atribución", "Roles y normas", "Actitudes", "Disonancia cognitiva", "Rutas de la persuasión", "Conformidad (Asch)", "Obediencia (Milgram)", "Pensamiento grupal", "Prejuicio y discriminación", "Efecto espectador"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"mapa": {"centro": "n1", "nodos": [{"id": "n1", "texto": "Psicología social"}, {"id": "n2", "texto": "Error fundamental de atribución", "ref": "atribucion-y-roles#b3"}, {"id": "n3", "texto": "Roles y normas", "ref": "atribucion-y-roles#b7"}, {"id": "n4", "texto": "Actitudes", "ref": "actitudes-y-persuasion#b2"}, {"id": "n5", "texto": "Disonancia cognitiva", "ref": "actitudes-y-persuasion#b4"}, {"id": "n6", "texto": "Rutas de la persuasión", "ref": "actitudes-y-persuasion#b8"}, {"id": "n7", "texto": "Conformidad (Asch)", "ref": "conformidad-y-obediencia#b2"}, {"id": "n8", "texto": "Obediencia (Milgram)", "ref": "conformidad-y-obediencia#b6"}, {"id": "n9", "texto": "Pensamiento grupal", "ref": "conformidad-y-obediencia#b9"}, {"id": "n10", "texto": "Prejuicio y discriminación", "ref": "prejuicio-agresion-y-ayuda#b2"}, {"id": "n11", "texto": "Efecto espectador", "ref": "prejuicio-agresion-y-ayuda#b7"}], "enlaces": [{"de": "n1", "a": "n2", "rotulo": "al explicar a otros cae en el"}, {"de": "n1", "a": "n3", "rotulo": "muestra la fuerza de los"}, {"de": "n1", "a": "n4", "rotulo": "estudia las"}, {"de": "n4", "a": "n5", "rotulo": "cambian por la"}, {"de": "n4", "a": "n6", "rotulo": "cambian con las"}, {"de": "n1", "a": "n7", "rotulo": "estudia la"}, {"de": "n7", "a": "n8", "rotulo": "y la"}, {"de": "n7", "a": "n9", "rotulo": "en grupos lleva al"}, {"de": "n1", "a": "n10", "rotulo": "estudia el"}, {"de": "n1", "a": "n11", "rotulo": "explica la falta de ayuda con el"}]}, "esquema": [{"texto": "Psicología social", "hijos": [{"texto": "Atribución y roles", "hijos": [{"texto": "Interna y externa"}, {"texto": "Error fundamental, actor observador, autoservicio"}, {"texto": "Mundo justo"}, {"texto": "Roles, normas y la cárcel de Stanford"}]}, {"texto": "Actitudes y persuasión", "hijos": [{"texto": "ABC de las actitudes"}, {"texto": "Disonancia cognitiva"}, {"texto": "Ruta central y periférica"}, {"texto": "Pie en la puerta"}]}, {"texto": "Influencia social", "hijos": [{"texto": "Asch: conformidad"}, {"texto": "Milgram: obediencia"}, {"texto": "Pensamiento grupal y polarización"}, {"texto": "Facilitación y holgazanería social"}]}, {"texto": "Relaciones", "hijos": [{"texto": "Estereotipo, prejuicio, discriminación"}, {"texto": "Agresión y acoso"}, {"texto": "Efecto espectador y altruismo"}, {"texto": "Atracción y amor"}]}]}], "tablas": [{"titulo": "Estereotipo, prejuicio y discriminación", "cab": ["Concepto", "Componente"], "filas": [["Estereotipo", "Cognitivo"], ["Prejuicio", "Afectivo"], ["Discriminación", "Conductual"]], "ref": ["prejuicio-agresion-y-ayuda#b2"], "evidencia": ["Trato injusto por pertenecer a un grupo"]}, {"titulo": "Efectos de grupo", "cab": ["Fenómeno", "Qué ocurre"], "filas": [["Facilitación social", "Rendimos mejor en tareas fáciles o bien aprendidas cuando nos observan"], ["Holgazanería social", "Nos esforzamos menos cuando el esfuerzo individual no se ve"]], "ref": ["conformidad-y-obediencia#b10"], "evidencia": ["Nos esforzamos menos cuando el esfuerzo individual no se ve"]}], "tarjetas": [{"id": "t1", "frente": "¿Qué es el error fundamental de atribución?", "reverso": "Explicar la conducta ajena por la personalidad e infravalorar la situación.", "ref": ["atribucion-y-roles#b3"], "evidencia": ["es el error fundamental de atribución"]}, {"id": "t2", "frente": "¿Qué es el sesgo de autoservicio?", "reverso": "Atribuir los éxitos a uno mismo y los fracasos a las circunstancias.", "ref": ["atribucion-y-roles#b4"], "evidencia": ["Atribuir los éxitos a uno mismo y los fracasos a las circunstancias"]}, {"id": "t3", "frente": "¿Qué riesgo tiene la creencia en un mundo justo?", "reverso": "Culpar a las víctimas de lo que les ocurre.", "ref": ["atribucion-y-roles#b5"], "evidencia": ["puede llevarnos a culpar a las víctimas"]}, {"id": "t4", "frente": "¿Qué es un rol social?", "reverso": "El conjunto de conductas que se esperan de alguien según su posición.", "ref": ["atribucion-y-roles#b7"], "evidencia": ["el conjunto de conductas que se esperan de alguien según su posición"]}, {"id": "t5", "frente": "¿Cuál es el ABC de las actitudes?", "reverso": "Componente afectivo, conductual y cognitivo.", "ref": ["actitudes-y-persuasion#b2"], "evidencia": ["el ABC de las actitudes"]}, {"id": "t6", "frente": "¿Qué es la disonancia cognitiva?", "reverso": "El malestar de tener ideas, o ideas y conductas, que se contradicen.", "ref": ["actitudes-y-persuasion#b4"], "evidencia": ["sentimos malestar cuando dos de nuestras ideas"]}, {"id": "t7", "frente": "¿Qué produce la ruta central de la persuasión?", "reverso": "Un cambio duradero basado en la calidad de los argumentos.", "ref": ["actitudes-y-persuasion#b8"], "evidencia": ["La calidad de los argumentos"]}, {"id": "t8", "frente": "¿Qué es la técnica del pie en la puerta?", "reverso": "Conseguir un favor pequeño para luego pedir uno mayor.", "ref": ["actitudes-y-persuasion#b10"], "evidencia": ["quien acepta un favor pequeño tiene más probabilidades de aceptar después uno mayor"]}, {"id": "t9", "frente": "¿Qué mostró el experimento de Asch?", "reverso": "Que muchas personas siguen al grupo aunque esté claramente equivocado.", "ref": ["conformidad-y-obediencia#b2"], "evidencia": ["tres de cada cuatro participantes se conformaron al menos una vez"]}, {"id": "t10", "frente": "¿Qué es la influencia informativa?", "reverso": "Seguir al grupo porque creemos que los demás saben más.", "ref": ["conformidad-y-obediencia#b4"], "evidencia": ["porque pensamos que los demás saben más"]}, {"id": "t11", "frente": "¿Qué porcentaje llegó a la descarga máxima en el estudio de Milgram?", "reverso": "Alrededor del 65 por ciento.", "ref": ["conformidad-y-obediencia#b6"], "evidencia": ["Alrededor del 65 por ciento llegó a la descarga máxima"]}, {"id": "t12", "frente": "¿Qué es el pensamiento grupal?", "reverso": "Valorar tanto la unanimidad que el grupo deja de considerar alternativas.", "ref": ["conformidad-y-obediencia#b9"], "evidencia": ["valora tanto la unanimidad que deja de considerar alternativas"]}, {"id": "t13", "frente": "¿Qué es la holgazanería social?", "reverso": "Esforzarse menos cuando el esfuerzo individual no se ve.", "ref": ["conformidad-y-obediencia#b10"], "evidencia": ["Nos esforzamos menos cuando el esfuerzo individual no se ve"]}, {"id": "t14", "frente": "¿Qué es una profecía autocumplida?", "reverso": "Una expectativa que provoca la conducta que se esperaba.", "ref": ["prejuicio-agresion-y-ayuda#b3"], "evidencia": ["Los estereotipos pueden convertirse en profecías autocumplidas"]}, {"id": "t15", "frente": "¿Qué es la difusión de la responsabilidad?", "reverso": "Pensar que otro actuará, lo que reduce la ayuda cuando hay muchos testigos.", "ref": ["prejuicio-agresion-y-ayuda#b7"], "evidencia": ["cada uno piensa que otro actuará"]}, {"id": "t16", "frente": "¿Cuáles son los componentes del amor según Sternberg?", "reverso": "Intimidad, pasión y compromiso.", "ref": ["prejuicio-agresion-y-ayuda#b11"], "evidencia": ["intimidad, pasión y compromiso"]}], "feynman": [{"id": "fy1", "concepto": "El error fundamental de atribución", "pregunta": "Explica por qué juzgamos al conductor que nos adelanta mal como un «maleducado» y cómo podríamos equivocarnos.", "elementos": [{"idea": "Hacemos atribuciones internas sobre otros", "palabras": ["personalidad", "interna", "carácter"]}, {"idea": "Ignoramos la situación", "palabras": ["situación", "circunstancias", "externa"]}, {"idea": "Con nosotros hacemos lo contrario", "palabras": ["actor", "observador", "propia"]}], "ref": ["atribucion-y-roles#b3", "atribucion-y-roles#b4"], "evidencia": ["tendemos a sobrestimar lo interno y a infravalorar la situación"]}, {"id": "fy2", "concepto": "Obediencia a la autoridad", "pregunta": "Resume el experimento de Milgram y explica qué factores reducían la obediencia.", "elementos": [{"idea": "Se pedía dar descargas crecientes", "palabras": ["descargas", "alumno", "voltios"]}, {"idea": "La mayoría obedeció hasta el final", "palabras": ["65", "obedeció", "máxima"]}, {"idea": "La distancia de la autoridad y la cercanía de la víctima reducían la obediencia", "palabras": ["teléfono", "misma sala", "se negaban"]}], "ref": ["conformidad-y-obediencia#b6", "conformidad-y-obediencia#b7"], "evidencia": ["cuando otros participantes se negaban"]}, {"id": "fy3", "concepto": "El efecto espectador", "pregunta": "Explica por qué es más fácil recibir ayuda en una calle con dos personas que en una plaza llena, y cómo pedirla.", "elementos": [{"idea": "Más testigos reducen la ayuda", "palabras": ["espectador", "testigos", "menos"]}, {"idea": "Se difunde la responsabilidad", "palabras": ["difusión", "responsabilidad", "otro"]}, {"idea": "Dirigirse a una persona concreta", "palabras": ["concreta", "persona", "112"]}], "ref": ["prejuicio-agresion-y-ayuda#b7", "prejuicio-agresion-y-ayuda#b8"], "evidencia": ["cuantas más personas presencian una emergencia, menos probable es que una de ellas ayude"]}]}'::jsonb, 'publicado')
