insert into public.course_modules (id, course_id, orden, slug, titulo, descripcion, objetivos, requisitos, relacion, tiempo_min, conceptos_clave, terminologia, confusiones, recursos, estado)
values ('d2e85041-8f26-57e1-8402-42ca488be33e', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 15, 'trastornos-psicologicos', 'Los trastornos psicológicos', 'Qué es un trastorno psicológico y cómo se diagnostica, y los rasgos principales de los trastornos de ansiedad, el TOC, el estrés postraumático, los trastornos del estado de ánimo, la esquizofrenia, los disociativos, los del desarrollo y los de la personalidad.', '["Al terminar sabrás explicar los criterios de un trastorno psicológico, el DSM y la CIE, y el modelo de diátesis y estrés.", "Al terminar sabrás describir los trastornos de ansiedad, el trastorno obsesivo compulsivo y el estrés postraumático.", "Al terminar sabrás describir la depresión, el trastorno bipolar y la esquizofrenia, y reconocer señales de riesgo de suicidio.", "Al terminar sabrás describir el TDAH, el autismo, los trastornos disociativos y los de la personalidad."]'::jsonb, '{}'::text[], '', 76, '["Malestar e interferencia", "DSM y CIE", "Diátesis y estrés", "Trastornos de ansiedad", "TOC", "TEPT", "Depresión y bipolaridad", "Esquizofrenia", "TDAH y autismo", "Trastornos de la personalidad"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"mapa": {"centro": "n1", "nodos": [{"id": "n1", "texto": "Trastornos psicológicos"}, {"id": "n2", "texto": "Malestar e interferencia", "ref": "que-es-un-trastorno#b3"}, {"id": "n3", "texto": "DSM y CIE", "ref": "que-es-un-trastorno#b6"}, {"id": "n4", "texto": "Diátesis y estrés", "ref": "que-es-un-trastorno#b10"}, {"id": "n5", "texto": "Trastornos de ansiedad", "ref": "ansiedad-toc-y-tept#b3"}, {"id": "n6", "texto": "TOC", "ref": "ansiedad-toc-y-tept#b6"}, {"id": "n7", "texto": "TEPT", "ref": "ansiedad-toc-y-tept#b8"}, {"id": "n8", "texto": "Depresión y bipolaridad", "ref": "animo-y-esquizofrenia#b2"}, {"id": "n9", "texto": "Esquizofrenia", "ref": "animo-y-esquizofrenia#b8"}, {"id": "n10", "texto": "TDAH y autismo", "ref": "otros-trastornos#b2"}, {"id": "n11", "texto": "Trastornos de la personalidad", "ref": "otros-trastornos#b8"}], "enlaces": [{"de": "n1", "a": "n2", "rotulo": "se definen por"}, {"de": "n1", "a": "n3", "rotulo": "se diagnostican con"}, {"de": "n1", "a": "n4", "rotulo": "se explican por"}, {"de": "n1", "a": "n5", "rotulo": "incluyen los"}, {"de": "n5", "a": "n6", "rotulo": "se relacionan con el"}, {"de": "n5", "a": "n7", "rotulo": "y con el"}, {"de": "n1", "a": "n8", "rotulo": "afectan al ánimo en"}, {"de": "n1", "a": "n9", "rotulo": "afectan a la realidad en la"}, {"de": "n1", "a": "n10", "rotulo": "aparecen en la infancia como"}, {"de": "n1", "a": "n11", "rotulo": "afectan al carácter en los"}]}, "esquema": [{"texto": "Trastornos psicológicos", "hijos": [{"texto": "Concepto", "hijos": [{"texto": "Malestar, interferencia, duración"}, {"texto": "DSM-5-TR y CIE-11"}, {"texto": "Diátesis y estrés"}, {"texto": "Estigma"}]}, {"texto": "Ansiedad y relacionados", "hijos": [{"texto": "Fobias, pánico, ansiedad social y generalizada"}, {"texto": "TOC: obsesiones y compulsiones"}, {"texto": "TEPT"}]}, {"texto": "Ánimo y psicosis", "hijos": [{"texto": "Depresión mayor y tríada de Beck"}, {"texto": "Trastorno bipolar"}, {"texto": "Esquizofrenia: positivos y negativos"}]}, {"texto": "Otros", "hijos": [{"texto": "TDAH y autismo"}, {"texto": "Disociativos"}, {"texto": "Personalidad: grupos A, B, C"}]}]}], "tablas": [{"titulo": "Trastornos de ansiedad", "cab": ["Trastorno", "Rasgo principal"], "filas": [["Trastorno de pánico", "Crisis repentinas de miedo intenso y temor persistente a que se repitan"], ["Ansiedad generalizada", "Preocupación excesiva y difícil de controlar sobre muchos temas"]], "ref": ["ansiedad-toc-y-tept#b3"], "evidencia": ["Preocupación excesiva y difícil de controlar sobre muchos temas"]}, {"titulo": "Grupos de la personalidad", "cab": ["Grupo", "Rasgo común"], "filas": [["A", "Raros o excéntricos"], ["B", "Dramáticos, emocionales o erráticos"], ["C", "Ansiosos o temerosos"]], "ref": ["otros-trastornos#b8"], "evidencia": ["Dramáticos, emocionales o erráticos"]}], "tarjetas": [{"id": "t1", "frente": "¿Basta con que algo sea poco común para hablar de trastorno?", "reverso": "No: hace falta malestar o interferencia en la vida.", "ref": ["que-es-un-trastorno#b2"], "evidencia": ["Que algo sea poco común no basta"]}, {"id": "t2", "frente": "¿Qué es la comorbilidad?", "reverso": "Tener más de un trastorno a la vez.", "ref": ["que-es-un-trastorno#b7"], "evidencia": ["que una misma persona tenga más de un trastorno a la vez"]}, {"id": "t3", "frente": "¿Qué sistema de clasificación usa oficialmente la sanidad española?", "reverso": "La CIE, de la Organización Mundial de la Salud.", "ref": ["que-es-un-trastorno#b6"], "evidencia": ["es la que usan oficialmente los sistemas de salud de muchos países, incluida España"]}, {"id": "t4", "frente": "¿Qué es la diátesis?", "reverso": "Una vulnerabilidad genética, biológica o psicológica.", "ref": ["que-es-un-trastorno#b10"], "evidencia": ["La diátesis es una vulnerabilidad"]}, {"id": "t5", "frente": "¿Qué es la ansiedad social?", "reverso": "Miedo intenso a ser evaluado o a hacer el ridículo ante los demás.", "ref": ["ansiedad-toc-y-tept#b3"], "evidencia": ["Miedo intenso a ser evaluado o a hacer el ridículo ante los demás"]}, {"id": "t6", "frente": "¿Es peligrosa una crisis de pánico?", "reverso": "Es muy angustiosa, pero no es peligrosa.", "ref": ["ansiedad-toc-y-tept#b4"], "evidencia": ["aunque es muy angustiosa, no es peligrosa"]}, {"id": "t7", "frente": "¿Qué son las compulsiones?", "reverso": "Conductas o actos mentales repetitivos para reducir la angustia de las obsesiones.", "ref": ["ansiedad-toc-y-tept#b6"], "evidencia": ["conductas o actos mentales repetitivos"]}, {"id": "t8", "frente": "¿Qué es el trastorno dismórfico corporal?", "reverso": "La preocupación excesiva por un defecto físico mínimo o inexistente.", "ref": ["ansiedad-toc-y-tept#b6"], "evidencia": ["la preocupación excesiva por un defecto físico mínimo o inexistente"]}, {"id": "t9", "frente": "¿Qué protege tras un trauma?", "reverso": "El apoyo social es uno de los factores de protección más importantes.", "ref": ["ansiedad-toc-y-tept#b10"], "evidencia": ["El apoyo social tras el suceso es uno de los factores de protección más importantes"]}, {"id": "t10", "frente": "¿Cuánto deben durar los síntomas para diagnosticar depresión mayor?", "reverso": "Al menos dos semanas, casi todos los días.", "ref": ["animo-y-esquizofrenia#b2"], "evidencia": ["casi todos los días durante al menos dos semanas"]}, {"id": "t11", "frente": "¿Qué es la tríada cognitiva de Beck?", "reverso": "Una visión negativa de uno mismo, del mundo y del futuro.", "ref": ["animo-y-esquizofrenia#b3"], "evidencia": ["una visión negativa de uno mismo"]}, {"id": "t12", "frente": "¿Qué es la manía?", "reverso": "Un episodio de euforia o irritabilidad con poco sueño, habla rápida e ideas grandiosas.", "ref": ["animo-y-esquizofrenia#b4"], "evidencia": ["se siente eufórica o muy irritable"]}, {"id": "t13", "frente": "¿Qué son los síntomas positivos de la esquizofrenia?", "reverso": "Alucinaciones y delirios.", "ref": ["animo-y-esquizofrenia#b8"], "evidencia": ["Alucinaciones, como oír voces"]}, {"id": "t14", "frente": "¿Qué neurotransmisor se relaciona con la esquizofrenia?", "reverso": "La dopamina, con un exceso de actividad en ciertas vías.", "ref": ["animo-y-esquizofrenia#b9"], "evidencia": ["un exceso de actividad de la dopamina"]}, {"id": "t15", "frente": "¿Causan autismo las vacunas?", "reverso": "No. Numerosos estudios lo han descartado y el artículo que lo afirmó fue retirado por fraude.", "ref": ["otros-trastornos#b3"], "evidencia": ["las vacunas no causan autismo"]}, {"id": "t16", "frente": "¿Qué terapia ha mostrado buenos resultados en el trastorno límite?", "reverso": "La terapia dialéctica conductual.", "ref": ["otros-trastornos#b9"], "evidencia": ["La terapia dialéctica conductual ha mostrado buenos resultados"]}], "feynman": [{"id": "fy1", "concepto": "Normal o trastorno", "pregunta": "Explica la diferencia entre estar triste tras una ruptura y tener una depresión.", "elementos": [{"idea": "La tristeza tras una pérdida es normal", "palabras": ["normal", "ruptura", "esperable"]}, {"idea": "Importan la intensidad y la duración", "palabras": ["intensidad", "duración", "dos semanas"]}, {"idea": "Lo clave es la interferencia en la vida", "palabras": ["interfiere", "vida", "malestar"]}], "ref": ["que-es-un-trastorno#b4", "animo-y-esquizofrenia#b2"], "evidencia": ["Lo que cambia en un trastorno es la intensidad, la duración"]}, {"id": "fy2", "concepto": "El ciclo del TOC", "pregunta": "Explica por qué comprobar muchas veces la cerradura mantiene el problema en lugar de resolverlo.", "elementos": [{"idea": "La obsesión genera angustia", "palabras": ["obsesión", "angustia", "intrusivo"]}, {"idea": "La compulsión alivia brevemente", "palabras": ["compulsión", "alivio", "comprobar"]}, {"idea": "El alivio refuerza el ciclo", "palabras": ["refuerza", "ciclo", "repetir"]}], "ref": ["ansiedad-toc-y-tept#b6"], "evidencia": ["El alivio es breve y refuerza el ciclo"]}, {"id": "fy3", "concepto": "Diátesis y estrés", "pregunta": "Explica por qué dos personas que viven el mismo suceso pueden reaccionar de forma muy distinta.", "elementos": [{"idea": "Hay una vulnerabilidad previa", "palabras": ["vulnerabilidad", "diátesis", "genética"]}, {"idea": "El estrés la activa", "palabras": ["estrés", "suceso", "desencadenante"]}, {"idea": "El apoyo social protege", "palabras": ["apoyo", "protección", "social"]}], "ref": ["que-es-un-trastorno#b10", "ansiedad-toc-y-tept#b10"], "evidencia": ["Dos personas pueden vivir el mismo suceso y solo una desarrollar depresión"]}]}'::jsonb, 'publicado')
on conflict (id) do update set orden = excluded.orden, slug = excluded.slug, titulo = excluded.titulo, descripcion = excluded.descripcion, objetivos = excluded.objetivos, requisitos = excluded.requisitos, relacion = excluded.relacion, tiempo_min = excluded.tiempo_min, conceptos_clave = excluded.conceptos_clave, terminologia = excluded.terminologia, confusiones = excluded.confusiones, recursos = excluded.recursos, estado = 'publicado';
insert into public.course_lessons (id, module_id, orden, slug, titulo, minutos, objetivos, secciones, lo_esencial, bloques, figuras_previstas, correlacion_clinica, origen, fuentes, estado)
values ('88b42530-9af7-5a45-aeda-8b2039098527', 'd2e85041-8f26-57e1-8402-42ca488be33e', 1, 'que-es-un-trastorno', 'Qué es un trastorno psicológico', 19, '["Explicar los criterios que definen un trastorno psicológico.", "Describir el DSM y la CIE.", "Comparar las perspectivas sobrenatural, biológica y de diátesis y estrés."]'::jsonb, '["Dónde está el límite", "Cómo se diagnostica", "Cómo se han explicado"]'::jsonb, '["Un trastorno implica alteraciones del pensamiento, la emoción o la conducta que causan malestar o interfieren en la vida.", "Ser poco común no basta para hablar de trastorno.", "El DSM y la CIE son los sistemas de diagnóstico más usados.", "Según el modelo de diátesis y estrés, una vulnerabilidad se convierte en trastorno cuando hay estrés."]'::jsonb, '[{"id": "b1", "t": "h", "texto": "Dónde está el límite"}, {"id": "b2", "t": "p", "texto": "Un **trastorno psicológico** es una alteración significativa del pensamiento, la regulación emocional o la conducta que refleja un problema en el funcionamiento psicológico, biológico o del desarrollo. Decidir dónde está el límite no es fácil. Que algo sea **poco común** no basta: tener un talento excepcional es raro y no es un trastorno. Tampoco basta con que vaya **contra las normas**, porque las normas cambian con la cultura y la época."}, {"id": "b3", "t": "lista", "titulo": "Lo que suele indicar un trastorno", "items": ["Malestar significativo para la persona.", "Interferencia en el trabajo, los estudios, las relaciones o el cuidado de uno mismo.", "Pensamientos, emociones o conductas poco habituales en su contexto cultural.", "Duración suficiente, no una reacción breve y esperable ante un suceso."]}, {"id": "b4", "t": "p", "texto": "Sentir tristeza tras una ruptura o nervios antes de una entrevista es **normal**. Lo que cambia en un trastorno es la intensidad, la duración y, sobre todo, el grado en que **interfiere** en la vida de la persona. La homosexualidad, por ejemplo, se consideró un trastorno hasta 1973 en el DSM; hoy se sabe que no lo es."}, {"id": "b5", "t": "h", "texto": "Cómo se diagnostica"}, {"id": "b6", "t": "p", "texto": "Los profesionales usan sistemas de clasificación para diagnosticar con criterios comunes. El **DSM**, de la Asociación Americana de Psiquiatría, va por su versión **DSM-5-TR**. La **CIE**, de la Organización Mundial de la Salud, va por la **CIE-11** y es la que usan oficialmente los sistemas de salud de muchos países, incluida España. Ambos describen los síntomas, su duración y los criterios necesarios para cada diagnóstico."}, {"id": "b7", "t": "p", "texto": "Los trastornos psicológicos son muy frecuentes: se estima que alrededor de una de cada cuatro o cinco personas sufrirá alguno a lo largo de su vida. Es habitual la **comorbilidad**, que una misma persona tenga más de un trastorno a la vez, como ansiedad y depresión."}, {"id": "b8", "t": "h", "texto": "Cómo se han explicado"}, {"id": "b9", "t": "compara", "titulo": "Perspectivas sobre los trastornos", "cab": ["Perspectiva", "Explicación", "Época o ejemplo"], "filas": [["Sobrenatural", "Posesión, brujería o castigo divino", "Edad Media: exorcismos y la «piedra de la locura»"], ["Biológica", "Genes, química cerebral y alteraciones del cerebro", "Estudios de gemelos y neuroimagen"], ["Psicológica", "Aprendizaje, pensamientos y experiencias", "Modelos cognitivos y conductuales"], ["Diátesis y estrés", "Una vulnerabilidad previa más un estrés desencadenante", "Modelo integrador actual"]]}, {"t": "imagen", "src": "cursos/img/psi-15-6.webp", "w": 325, "h": 500, "alt": "Pintura antigua de un médico extrayendo una piedra de la cabeza de un hombre.", "pie": "La extracción de la piedra de la locura: en otras épocas se atribuían los trastornos a causas sobrenaturales o absurdas.", "credito": {"autor": "OpenStax, Psychology 2e (Spielman, Jenkins y Lovett)", "licencia": "CC BY 4.0", "url_licencia": "https://creativecommons.org/licenses/by/4.0/", "pagina": "https://espanol.libretexts.org/Bookshelves/Ciencias_Sociales/Psicologia/Psicolog%C3%ADa_Introductoria_2e_(OpenStax)/15%3A_Trastornos_Psicol%C3%B3gicos/15.04%3A_Perspectivas_sobre_los_Trastornos_Psicol%C3%B3gicos"}}, {"id": "b10", "t": "p", "texto": "Hoy predomina el **modelo de diátesis y estrés**. La **diátesis** es una vulnerabilidad, que puede ser genética, biológica o psicológica. Por sí sola no produce el trastorno, pero si la persona vive un **estrés** importante, el trastorno puede aparecer. Dos personas pueden vivir el mismo suceso y solo una desarrollar depresión, según su vulnerabilidad."}, {"t": "imagen", "src": "cursos/img/psi-15-8.webp", "w": 975, "h": 556, "alt": "Gráfico de barras con el riesgo de esquizofrenia según el grado de parentesco con un familiar afectado.", "pie": "Cuanto más cercano es el parentesco con una persona con esquizofrenia, mayor es el riesgo: muestra de la vulnerabilidad genética.", "credito": {"autor": "OpenStax, Psychology 2e (Spielman, Jenkins y Lovett)", "licencia": "CC BY 4.0", "url_licencia": "https://creativecommons.org/licenses/by/4.0/", "pagina": "https://espanol.libretexts.org/Bookshelves/Ciencias_Sociales/Psicologia/Psicolog%C3%ADa_Introductoria_2e_(OpenStax)/15%3A_Trastornos_Psicol%C3%B3gicos/15.04%3A_Perspectivas_sobre_los_Trastornos_Psicol%C3%B3gicos"}}, {"id": "b11", "t": "clinica", "titulo": "Contra el estigma", "texto": "Tener un trastorno psicológico no es un fallo personal ni una debilidad. Son problemas de salud frecuentes y tratables. El estigma hace que muchas personas no pidan ayuda; hablar de ellos con naturalidad ayuda a cambiarlo."}]'::jsonb, '[]'::jsonb, null, 'mixto', '[]'::jsonb, 'publicado')
