insert into public.course_modules (id, course_id, orden, slug, titulo, descripcion, objetivos, requisitos, relacion, tiempo_min, conceptos_clave, terminologia, confusiones, recursos, estado)
values ('e4f88da1-4700-5108-989e-539f65ae5248', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 16, 'terapia-y-tratamiento', 'Terapia y tratamiento', 'Cómo ha cambiado el tratamiento de los trastornos psicológicos, cómo pedir ayuda, qué ofrecen las principales psicoterapias y los tratamientos biomédicos, qué formatos existen y qué hace que una terapia funcione.', '["Al terminar sabrás describir la evolución histórica del tratamiento y cómo acceder a la atención en salud mental.", "Al terminar sabrás comparar el psicoanálisis, la terapia humanista, la conductual, la cognitiva y la cognitivo conductual.", "Al terminar sabrás describir los principales psicofármacos, otros tratamientos biomédicos y los formatos de terapia.", "Al terminar sabrás explicar el tratamiento de las adicciones, la competencia cultural y qué factores hacen eficaz una terapia."]'::jsonb, '{}'::text[], '', 74, '["Pinel y Dorothea Dix", "Desinstitucionalización", "Psicoanálisis", "Terapia centrada en el cliente", "Exposición y desensibilización", "Terapia cognitivo conductual", "Psicofármacos", "Formatos de terapia", "Adicciones y patología dual", "Alianza terapéutica"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"mapa": {"centro": "n1", "nodos": [{"id": "n1", "texto": "Terapia y tratamiento"}, {"id": "n2", "texto": "Pinel y Dorothea Dix", "ref": "historia-y-acceso#b3"}, {"id": "n3", "texto": "Desinstitucionalización", "ref": "historia-y-acceso#b4"}, {"id": "n4", "texto": "Psicoanálisis", "ref": "las-psicoterapias#b2"}, {"id": "n5", "texto": "Terapia centrada en el cliente", "ref": "las-psicoterapias#b5"}, {"id": "n6", "texto": "Exposición y desensibilización", "ref": "las-psicoterapias#b7"}, {"id": "n7", "texto": "Terapia cognitivo conductual", "ref": "las-psicoterapias#b11"}, {"id": "n8", "texto": "Psicofármacos", "ref": "tratamientos-biomedicos-y-formatos#b2"}, {"id": "n9", "texto": "Formatos de terapia", "ref": "tratamientos-biomedicos-y-formatos#b7"}, {"id": "n10", "texto": "Adicciones y patología dual", "ref": "adicciones-cultura-y-eficacia#b2"}, {"id": "n11", "texto": "Alianza terapéutica", "ref": "adicciones-cultura-y-eficacia#b9"}], "enlaces": [{"de": "n1", "a": "n2", "rotulo": "se humanizó con"}, {"de": "n2", "a": "n3", "rotulo": "y llegó a la"}, {"de": "n1", "a": "n4", "rotulo": "empezó con el"}, {"de": "n1", "a": "n5", "rotulo": "incluye la"}, {"de": "n1", "a": "n6", "rotulo": "incluye la"}, {"de": "n6", "a": "n7", "rotulo": "se integra en la"}, {"de": "n1", "a": "n8", "rotulo": "se complementa con"}, {"de": "n1", "a": "n9", "rotulo": "se ofrece en distintos"}, {"de": "n1", "a": "n10", "rotulo": "se adapta a las"}, {"de": "n1", "a": "n11", "rotulo": "funciona gracias a la"}]}, "esquema": [{"texto": "Terapia y tratamiento", "hijos": [{"texto": "Historia y acceso", "hijos": [{"texto": "Manicomios"}, {"texto": "Pinel y Dix"}, {"texto": "Desinstitucionalización"}, {"texto": "Atención primaria, centro de salud mental, 024"}]}, {"texto": "Psicoterapias", "hijos": [{"texto": "Psicoanálisis y juego"}, {"texto": "Centrada en el cliente"}, {"texto": "Exposición y desensibilización"}, {"texto": "Cognitiva y TCC"}]}, {"texto": "Biomédico y formatos", "hijos": [{"texto": "Antidepresivos, ansiolíticos, antipsicóticos, estabilizadores"}, {"texto": "TEC y EMT"}, {"texto": "Individual, grupo, pareja, familia"}]}, {"texto": "Adicciones y eficacia", "hijos": [{"texto": "Desintoxicación y prevención de recaídas"}, {"texto": "Patología dual"}, {"texto": "Competencia cultural"}, {"texto": "Alianza terapéutica"}]}]}], "tablas": [{"titulo": "Psicofármacos", "cab": ["Grupo", "Para qué se usan"], "filas": [["Antidepresivos", "Depresión y algunos trastornos de ansiedad"], ["Antipsicóticos", "Esquizofrenia y otros trastornos psicóticos"], ["Estabilizadores del ánimo", "Trastorno bipolar"]], "ref": ["tratamientos-biomedicos-y-formatos#b2"], "evidencia": ["Esquizofrenia y otros trastornos psicóticos"]}, {"titulo": "Psicoterapias", "cab": ["Terapia", "Objetivo"], "filas": [["Psicoanálisis", "Hacer consciente lo inconsciente"], ["Cognitivo conductual", "Cambiar pensamientos y conductas"]], "ref": ["las-psicoterapias#b12"], "evidencia": ["Hacer consciente lo inconsciente"]}], "tarjetas": [{"id": "t1", "frente": "¿Qué hizo Philippe Pinel?", "reverso": "Quitó las cadenas a los pacientes y defendió el tratamiento moral.", "ref": ["historia-y-acceso#b3"], "evidencia": ["mandó quitar las cadenas a los pacientes"]}, {"id": "t2", "frente": "¿Qué logró Dorothea Dix?", "reverso": "Denunció las condiciones de los asilos y logró hospitales públicos más dignos.", "ref": ["historia-y-acceso#b3"], "evidencia": ["logró que se construyeran hospitales públicos más dignos"]}, {"id": "t3", "frente": "¿Qué es la desinstitucionalización?", "reverso": "El cierre de los grandes hospitales psiquiátricos y el paso a la atención en la comunidad.", "ref": ["historia-y-acceso#b4"], "evidencia": ["el cierre de los grandes hospitales psiquiátricos"]}, {"id": "t4", "frente": "¿Cuál suele ser el primer paso para pedir ayuda en la sanidad pública española?", "reverso": "El médico de atención primaria.", "ref": ["historia-y-acceso#b7"], "evidencia": ["el primer paso suele ser el médico de atención primaria"]}, {"id": "t5", "frente": "¿Qué es la transferencia?", "reverso": "Los sentimientos que el paciente traslada al terapeuta.", "ref": ["las-psicoterapias#b2"], "evidencia": ["los sentimientos que el paciente traslada al terapeuta"]}, {"id": "t6", "frente": "¿Para qué sirve la terapia de juego?", "reverso": "Para que los niños pequeños expresen emociones y conflictos que no pueden decir con palabras.", "ref": ["las-psicoterapias#b3"], "evidencia": ["el niño expresa sus emociones y conflictos"]}, {"id": "t7", "frente": "¿Qué cualidades crea el terapeuta en la terapia centrada en el cliente?", "reverso": "Empatía, autenticidad y aceptación incondicional.", "ref": ["las-psicoterapias#b5"], "evidencia": ["crea un clima de empatía, autenticidad y aceptación incondicional"]}, {"id": "t8", "frente": "¿Qué es una jerarquía de miedo?", "reverso": "Una lista de situaciones ordenadas de menos a más angustiosas que se recorren poco a poco.", "ref": ["las-psicoterapias#b7"], "evidencia": ["una lista de situaciones ordenadas de menos a más angustiosas"]}, {"id": "t9", "frente": "¿Qué son los pensamientos automáticos?", "reverso": "Pensamientos negativos que surgen sin querer y que la terapia cognitiva ayuda a revisar.", "ref": ["las-psicoterapias#b10"], "evidencia": ["detectar los pensamientos automáticos negativos"]}, {"id": "t10", "frente": "¿Qué caracteriza a la terapia cognitivo conductual?", "reverso": "Es estructurada, breve, centrada en el presente y cambia pensamientos y conductas.", "ref": ["las-psicoterapias#b11"], "evidencia": ["Es estructurada, breve, centrada en el presente"]}, {"id": "t11", "frente": "¿Cómo actúan los antipsicóticos?", "reverso": "Bloquean receptores de dopamina.", "ref": ["tratamientos-biomedicos-y-formatos#b2"], "evidencia": ["Bloquean receptores de dopamina"]}, {"id": "t12", "frente": "¿Pueden recetar los psicólogos en España?", "reverso": "No; los psicofármacos los receta un médico.", "ref": ["tratamientos-biomedicos-y-formatos#b3"], "evidencia": ["en España, los psicólogos no recetan"]}, {"id": "t13", "frente": "¿Para qué se usa hoy la terapia electroconvulsiva?", "reverso": "Para la depresión grave que no responde a otros tratamientos.", "ref": ["tratamientos-biomedicos-y-formatos#b5"], "evidencia": ["para la depresión grave que no responde a otros tratamientos"]}, {"id": "t14", "frente": "¿Qué es la patología dual?", "reverso": "Tener a la vez una adicción y otro trastorno psicológico.", "ref": ["adicciones-cultura-y-eficacia#b3"], "evidencia": ["Es lo que se llama patología dual"]}, {"id": "t15", "frente": "¿Qué es la competencia cultural?", "reverso": "La capacidad del terapeuta de entender y respetar la cultura del paciente y adaptar el tratamiento.", "ref": ["adicciones-cultura-y-eficacia#b5"], "evidencia": ["La competencia cultural es la capacidad del terapeuta"]}, {"id": "t16", "frente": "¿Qué es la alianza terapéutica?", "reverso": "La relación de confianza en la que paciente y terapeuta trabajan juntos hacia objetivos compartidos.", "ref": ["adicciones-cultura-y-eficacia#b9"], "evidencia": ["es uno de los mejores predictores del éxito"]}], "feynman": [{"id": "fy1", "concepto": "La terapia de exposición", "pregunta": "Explica cómo ayudarías a alguien con miedo a volar usando la desensibilización sistemática.", "elementos": [{"idea": "Construir una jerarquía de miedo", "palabras": ["jerarquía", "lista", "menos a más"]}, {"idea": "Combinar relajación y exposición gradual", "palabras": ["relajación", "gradual", "poco a poco"]}, {"idea": "El miedo baja por extinción", "palabras": ["extinción", "disminuye", "sin escapar"]}], "ref": ["las-psicoterapias#b7", "las-psicoterapias#b8"], "evidencia": ["combina la relajación con una jerarquía de miedo"]}, {"id": "fy2", "concepto": "Fármacos y psicoterapia", "pregunta": "Explica a un amigo con depresión por qué no conviene dejar de golpe un antidepresivo y por qué combinarlo con terapia puede ayudar.", "elementos": [{"idea": "Los fármacos actúan sobre neurotransmisores y tardan semanas", "palabras": ["serotonina", "semanas", "efecto"]}, {"idea": "No se dejan de golpe sin consultar", "palabras": ["golpe", "consultar", "médico"]}, {"idea": "La combinación funciona mejor", "palabras": ["combinación", "psicoterapia", "mejor"]}], "ref": ["tratamientos-biomedicos-y-formatos#b3"], "evidencia": ["Nunca deben dejarse de golpe sin consultar"]}, {"id": "fy3", "concepto": "Qué hace que una terapia funcione", "pregunta": "Explica qué tiene en común una buena terapia, sea del enfoque que sea.", "elementos": [{"idea": "La alianza terapéutica", "palabras": ["alianza", "confianza", "colaboración"]}, {"idea": "La empatía y los objetivos compartidos", "palabras": ["empatía", "objetivos", "acordados"]}, {"idea": "La implicación del paciente", "palabras": ["implicación", "activa", "sesiones"]}], "ref": ["adicciones-cultura-y-eficacia#b8", "adicciones-cultura-y-eficacia#b9"], "evidencia": ["La alianza terapéutica: una relación de confianza y colaboración"]}]}'::jsonb, 'publicado')
