insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('4b1045d4-9f29-5ad3-99e2-353f2b0c76c4', 'f11-psi-4', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dfc0db45-c4aa-52bc-a76b-02e345f90eed', '913fc30f-2da2-5e92-a329-7b1909ec52ca', 'relacionar', 'Relaciona cada escuela con su idea central.', null, '{"izquierda": ["Conductismo", "Estructuralismo", "Funcionalismo", "Humanismo"], "derecha": ["Descomponer la experiencia consciente mediante la introspección", "El potencial de las personas para crecer", "Estudiar solo la conducta observable", "Para qué sirve la mente en la adaptación al entorno"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('4b1045d4-9f29-5ad3-99e2-353f2b0c76c4', '{"pares": {"Estructuralismo": "Descomponer la experiencia consciente mediante la introspección", "Funcionalismo": "Para qué sirve la mente en la adaptación al entorno", "Conductismo": "Estudiar solo la conducta observable", "Humanismo": "El potencial de las personas para crecer"}}'::jsonb, 'Cada escuela se preguntó algo distinto: de qué está hecha la mente, para qué sirve, qué conducta se observa o cómo crece la persona.', '{"leccion": "historia-de-la-psicologia", "bloque": "b13", "titulo": "Las grandes escuelas de su historia", "fragmento": "Las grandes escuelas de un vistazo: Estructuralismo | Wundt | Descomponer la experiencia consciente mediante la introspección · Funcionalismo | James | Para qué sirve la mente en la adaptación al entorno · Psicoanálisis | Freud | El inconsciente influye en la conducta consciente · Gestalt | Wertheimer, Koffka, Köhler | El todo es distinto de la suma de las partes · Conductismo | Watson, Skinner | Estudiar solo la conducta observable · Humanismo | Maslow, Rogers | El potencial de las personas para crecer · Cognitivismo | Chomsky y otros | Los procesos mentales explican la conducta", "evidencia": ["Estudiar solo la conducta observable"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('d0a79b34-f5cd-593f-8b09-b61293a6eeff', 'f11-psi-5', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dfc0db45-c4aa-52bc-a76b-02e345f90eed', '913fc30f-2da2-5e92-a329-7b1909ec52ca', 'seleccion_multiple', '¿Cuál era el principal problema de la introspección como método?', null, '{"opciones": ["Resultaba muy subjetiva y distintas personas describían la misma experiencia de forma diferente", "Estaba prohibida en Alemania", "Necesitaba aparatos demasiado caros", "Solo se podía usar con animales"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('d0a79b34-f5cd-593f-8b09-b61293a6eeff', '{"correcta": [0]}'::jsonb, 'La introspección dependía de lo que cada persona decía sentir, por eso era difícil llegar a acuerdos.', '{"leccion": "historia-de-la-psicologia", "bloque": "b2", "titulo": "Las grandes escuelas de su historia", "fragmento": "Se suele considerar a **Wilhelm Wundt** (1832 a 1920) uno de los fundadores de la psicología científica. En 1879 creó en Leipzig, Alemania, el primer laboratorio dedicado a la investigación psicológica. Wundt quería descomponer la experiencia consciente en sus partes más simples, como se descompone un compuesto químico en elementos. Para ello usaba la **introspección**: personas entrenadas describían con detalle lo que sentían ante un estímulo, por ejemplo un sonido. A este enfoque se le llamó **estructuralismo**. Su problema era que la introspección resultaba muy subjetiva y distintas personas describían la misma experiencia de forma diferente.", "evidencia": ["la introspección resultaba muy subjetiva"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('312c1337-1e1a-5fb0-b278-062e4d6d654a', 'f11-psi-6', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dfc0db45-c4aa-52bc-a76b-02e345f90eed', '913fc30f-2da2-5e92-a329-7b1909ec52ca', 'respuesta_breve', 'Freud sostuvo que gran parte de la conducta depende de deseos y conflictos del ___.', null, '{"completar": true}'::jsonb, null, 1, array['fase11','completar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('312c1337-1e1a-5fb0-b278-062e4d6d654a', '{"aceptadas": ["inconsciente", "el inconsciente"], "solucion": "inconsciente"}'::jsonb, 'La teoría psicoanalítica pone el inconsciente en el centro de la conducta.', '{"leccion": "historia-de-la-psicologia", "bloque": "b6", "titulo": "Las grandes escuelas de su historia", "fragmento": "**Sigmund Freud** (1856 a 1939), médico vienés, es una de las figuras más conocidas de la historia de la psicología. Sostuvo que gran parte de lo que hacemos depende de deseos y conflictos de los que no somos conscientes. Para acceder a ese **inconsciente** analizaba los sueños, los lapsus al hablar y la **asociación libre**, en la que el paciente dice todo lo que le viene a la mente. Su **teoría psicoanalítica** dominó la psicología clínica durante décadas, aunque muchas de sus ideas son difíciles de comprobar con el método científico.", "evidencia": ["Para acceder a ese inconsciente analizaba los sueños"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('81bb0858-0be3-57d0-9572-dcfda5dba928', 'f11-psi-7', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dfc0db45-c4aa-52bc-a76b-02e345f90eed', '913fc30f-2da2-5e92-a329-7b1909ec52ca', 'seleccion_multiple', '¿Qué favoreció la revolución cognitiva de los años cincuenta y sesenta?', null, '{"opciones": ["La neurociencia, la informática y críticas como la de Chomsky al conductismo", "La prohibición del conductismo", "El regreso a la introspección de Wundt", "El abandono total del método científico"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('81bb0858-0be3-57d0-9572-dcfda5dba928', '{"correcta": [0]}'::jsonb, 'Neurociencia, informática y la crítica de Chomsky impulsaron el regreso al estudio de los procesos mentales.', '{"leccion": "historia-de-la-psicologia", "bloque": "b12", "titulo": "Las grandes escuelas de su historia", "fragmento": "En los años cincuenta y sesenta llegó la **revolución cognitiva**. Gracias a la neurociencia, a la informática y a autores como Noam Chomsky, que criticó la explicación conductista del lenguaje, la psicología volvió a estudiar los procesos mentales: atención, memoria, lenguaje y resolución de problemas. Hoy se entiende que la cognición es esencial para comprender la conducta.", "evidencia": ["Gracias a la neurociencia, a la informática y a autores como Noam Chomsky"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('113cc126-7eaa-5902-9bb4-da4d5b824d70', 'f11-psi-8', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dfc0db45-c4aa-52bc-a76b-02e345f90eed', 'ed7b1677-b3b6-5365-874a-d640971f881f', 'relacionar', 'Relaciona cada área con lo que estudia.', null, '{"izquierda": ["Biopsicología", "Psicología cognitiva", "Psicología del desarrollo", "Psicología social"], "derecha": ["Cómo influyen los demás en lo que pensamos y hacemos", "Cómo la biología influye en la conducta", "Los cambios a lo largo de toda la vida", "Los pensamientos y su relación con la experiencia y la acción"]}'::jsonb, null, 1, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('113cc126-7eaa-5902-9bb4-da4d5b824d70', '{"pares": {"Biopsicología": "Cómo la biología influye en la conducta", "Psicología cognitiva": "Los pensamientos y su relación con la experiencia y la acción", "Psicología del desarrollo": "Los cambios a lo largo de toda la vida", "Psicología social": "Cómo influyen los demás en lo que pensamos y hacemos"}}'::jsonb, 'Cada área se centra en un aspecto de la conducta: la biología, el pensamiento, el cambio con la edad o la influencia de los demás.', '{"leccion": "areas-de-la-psicologia", "bloque": "b4", "titulo": "Las áreas de la psicología actual", "fragmento": "Áreas centradas en procesos básicos: Biopsicología | Cómo la biología influye en la conducta | ¿Qué ocurre en el cerebro cuando sentimos miedo? · Psicología evolutiva | El origen evolutivo de la conducta | ¿Por qué nos atraen ciertos rasgos en otras personas? · Sensación y percepción | Cómo recibimos e interpretamos la información de los sentidos | ¿Por qué vemos ilusiones ópticas? · Psicología cognitiva | Los pensamientos y su relación con la experiencia y la acción | ¿Cómo resolvemos un problema? · Psicología del desarrollo | Los cambios a lo largo de toda la vida | ¿Cuándo aprende un bebé que los objetos siguen existiendo? · Psicología de la personalidad | Los patrones de pensamiento y conducta que hacen único a cada individuo | ¿Por qué unas personas son más sociables que otras? · Psicología social | Cómo influyen los demás en lo que pensamos y hacemos | ¿Por qué obedecemos a la autoridad?", "evidencia": ["Cómo la biología influye en la conducta"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('e274520c-4c47-5f36-ba38-4799b318e8b2', 'f11-psi-9', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dfc0db45-c4aa-52bc-a76b-02e345f90eed', 'ed7b1677-b3b6-5365-874a-d640971f881f', 'caso_clinico', '¿Qué enfoque explica mejor su situación?', 'Marcos tiene depresión desde hace meses. En su familia hay antecedentes de depresión, tiende a pensar que todo lo hace mal y hace poco perdió su empleo.', '{"opciones": ["El modelo biopsicosocial, porque combina factores biológicos, psicológicos y sociales", "Solo el desempleo, porque es lo más reciente", "Solo la genética, porque hay antecedentes familiares", "Solo su forma de pensar, porque es lo que puede cambiar"]}'::jsonb, null, 2, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('e274520c-4c47-5f36-ba38-4799b318e8b2', '{"correcta": [0]}'::jsonb, 'El modelo biopsicosocial considera a la vez los genes, la forma de interpretar lo que pasa y el entorno social.', '{"leccion": "areas-de-la-psicologia", "bloque": "b10", "titulo": "Las áreas de la psicología actual", "fragmento": "Para entender la salud, la psicología actual usa el **modelo biopsicosocial**, que afirma que la biología, la psicología y los factores sociales interactúan para determinar la salud de una persona. Pensemos en alguien con depresión: pueden influir sus genes y la química de su cerebro (biológico), su forma de interpretar lo que le pasa (psicológico) y la pérdida reciente de su trabajo (social). Ninguno de los tres factores explica por sí solo el problema.", "evidencia": ["la biología, la psicología y los factores sociales interactúan"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('63338e79-8935-58ba-947f-5c138c945e52', 'f11-psi-10', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dfc0db45-c4aa-52bc-a76b-02e345f90eed', 'ed7b1677-b3b6-5365-874a-d640971f881f', 'verdadero_falso_razonado', 'Un psicólogo clínico y un psiquiatra son la misma profesión.', null, '{"razones": ["Falso, porque el psiquiatra es un médico especialista que puede recetar fármacos.", "Falso, porque el psicólogo clínico solo hace investigación.", "Verdadero, porque ambos tratan trastornos psicológicos."]}'::jsonb, null, 1, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('63338e79-8935-58ba-947f-5c138c945e52', '{"valor": false, "razon": 0}'::jsonb, 'Ambos atienden trastornos, pero el psiquiatra es médico y puede recetar; el psicólogo clínico trabaja sobre todo con psicoterapia.', '{"leccion": "areas-de-la-psicologia", "bloque": "b8", "titulo": "Las áreas de la psicología actual", "fragmento": "La **psicología clínica** es el área más conocida y la que más profesionales reúne. Quien trabaja en ella evalúa, diagnostica y trata problemas como la ansiedad, la depresión o las adicciones, normalmente con psicoterapia. No debe confundirse con la psiquiatría: el psiquiatra es un médico especialista que puede recetar fármacos.", "evidencia": ["el psiquiatra es un médico especialista que puede recetar fármacos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('943c2d65-7f2b-5d99-9b6d-e0a888f63f33', 'f11-psi-11', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dfc0db45-c4aa-52bc-a76b-02e345f90eed', 'b4724b50-17e4-5b9d-a171-38120da055b6', 'respuesta_breve', 'En España, ¿con qué siglas se conoce la residencia de cuatro años para ser especialista en Psicología Clínica?', null, '{}'::jsonb, null, 1, array['fase11','respuesta_breve']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('943c2d65-7f2b-5d99-9b6d-e0a888f63f33', '{"aceptadas": ["PIR", "el PIR"], "solucion": "PIR"}'::jsonb, 'El PIR, Psicólogo Interno Residente, es la vía de acceso a la especialidad en Psicología Clínica.', '{"leccion": "formacion-y-profesion", "bloque": "b4", "titulo": "Formación y profesión en psicología", "fragmento": "En España, la psicología sanitaria está regulada. Tener el grado no basta para atender a pacientes en un contexto de salud. Hay dos caminos principales. El primero es el **Máster en Psicología General Sanitaria**, de dos años, que habilita para evaluar e intervenir en la salud psicológica de las personas en centros sanitarios. El segundo es la especialidad en **Psicología Clínica**, a la que se accede por el **PIR** (Psicólogo Interno Residente): una prueba nacional seguida de cuatro años de formación como residente en hospitales y centros de salud mental públicos.", "evidencia": ["Psicólogo Interno Residente"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('ead06015-02f1-5f88-9eb9-2089805c64e7', 'f11-psi-12', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dfc0db45-c4aa-52bc-a76b-02e345f90eed', 'b4724b50-17e4-5b9d-a171-38120da055b6', 'seleccion_multiple', 'En España, ¿qué necesita una persona con el grado en psicología para atender pacientes en un centro sanitario?', null, '{"opciones": ["El Máster en Psicología General Sanitaria o la especialidad vía PIR", "Un curso en línea de pocas horas", "Nada más, el grado es suficiente", "Un doctorado en cualquier universidad"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('ead06015-02f1-5f88-9eb9-2089805c64e7', '{"correcta": [0]}'::jsonb, 'La psicología sanitaria está regulada: hace falta el máster habilitante o la especialidad en Psicología Clínica.', '{"leccion": "formacion-y-profesion", "bloque": "b4", "titulo": "Formación y profesión en psicología", "fragmento": "En España, la psicología sanitaria está regulada. Tener el grado no basta para atender a pacientes en un contexto de salud. Hay dos caminos principales. El primero es el **Máster en Psicología General Sanitaria**, de dos años, que habilita para evaluar e intervenir en la salud psicológica de las personas en centros sanitarios. El segundo es la especialidad en **Psicología Clínica**, a la que se accede por el **PIR** (Psicólogo Interno Residente): una prueba nacional seguida de cuatro años de formación como residente en hospitales y centros de salud mental públicos.", "evidencia": ["Tener el grado no basta para atender a pacientes"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('84d8b24a-483e-5ff7-b3bf-7634c4c38fc3', 'f11-psi-13', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dfc0db45-c4aa-52bc-a76b-02e345f90eed', '4ad94ec4-94d2-5cc5-a11b-6edc0459e348', 'seleccion_multiple', '¿Por qué se dice que la psicología es también una ciencia social?', null, '{"opciones": ["Porque nuestra conducta depende de las demás personas, de la cultura y del entorno", "Porque no usa el método científico", "Porque solo estudia grupos y nunca individuos", "Porque nació dentro de la sociología"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('84d8b24a-483e-5ff7-b3bf-7634c4c38fc3', '{"correcta": [0]}'::jsonb, 'Ningún organismo vive aislado: los demás y la cultura influyen en lo que hacemos.', '{"leccion": "la-ciencia-de-la-mente", "bloque": "b9", "titulo": "La ciencia de la mente y la conducta", "fragmento": "Hasta finales del siglo XIX, las preguntas sobre la mente pertenecían a la filosofía. Cuando la psicología se convirtió en disciplina propia, adoptó dos caras. Como toda conducta tiene una base biológica, una parte de la psicología se parece a la biología y estudia el cerebro, las hormonas o los genes. Pero ningún organismo vive aislado: nuestra conducta depende de las demás personas, de la cultura y del entorno. Por eso la psicología es también una **ciencia social**.", "evidencia": ["nuestra conducta depende de las demás personas"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
