insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('eef48632-a9f0-54c3-be10-86ea1d5fc8f8', '{"aceptadas": ["conductas", "las conductas", "conducta", "comportamientos"], "solucion": "conductas"}'::jsonb, 'Este triángulo es la base de muchas terapias actuales.', '{"leccion": "areas-de-la-psicologia", "bloque": "b12", "titulo": "Las áreas de la psicología actual", "fragmento": "Muchas áreas comparten otra idea sencilla: pensamientos, emociones y conductas se influyen mutuamente. Si piensas que vas a fracasar en una entrevista, te sentirás nervioso y quizá evites prepararla, lo que a su vez confirma tu pensamiento. Este triángulo es la base de muchas terapias actuales.", "evidencia": ["pensamientos, emociones y conductas se influyen mutuamente"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('c6a09d8e-24ba-592b-98f7-4168a3441158', 'f11-psi-15', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dfc0db45-c4aa-52bc-a76b-02e345f90eed', 'b4724b50-17e4-5b9d-a171-38120da055b6', 'verdadero_falso_razonado', 'Para dedicarse a la investigación universitaria lo habitual es hacer un doctorado.', null, '{"razones": ["Verdadero, porque el doctorado es lo mismo que el PIR.", "Verdadero, porque el doctorado forma en investigación original que se defiende en una tesis.", "Falso, porque basta con el grado."]}'::jsonb, null, 1, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('c6a09d8e-24ba-592b-98f7-4168a3441158', '{"valor": true, "razon": 1}'::jsonb, 'El doctorado culmina con una tesis doctoral basada en una investigación original.', '{"leccion": "formacion-y-profesion", "bloque": "b8", "titulo": "Formación y profesión en psicología", "fragmento": "Quien quiere dedicarse a la investigación o a la docencia universitaria suele hacer un **doctorado**. Durante varios años, el doctorando realiza una investigación original bajo supervisión y la defiende en una **tesis doctoral**. Después es frecuente pasar por contratos **posdoctorales**, en los que el investigador amplía su experiencia en otros grupos, a menudo en el extranjero.", "evidencia": ["realiza una investigación original bajo supervisión"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('e2a4334e-1c40-5bfc-8c46-e2bc5651210d', 'f11-psi-16', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dfc0db45-c4aa-52bc-a76b-02e345f90eed', 'b4724b50-17e4-5b9d-a171-38120da055b6', 'seleccion_multiple', 'Si buscas un psicólogo para ti, ¿qué conviene comprobar?', null, '{"opciones": ["Que tiene muchos seguidores en redes sociales", "Que ofrece sesiones muy baratas", "Que ha hecho un curso en línea de psicología", "Que es psicólogo sanitario o especialista en psicología clínica colegiado"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('e2a4334e-1c40-5bfc-8c46-e2bc5651210d', '{"correcta": [3]}'::jsonb, 'Los colegios oficiales permiten verificar que un profesional está habilitado para ejercer.', '{"leccion": "formacion-y-profesion", "bloque": "b10", "titulo": "Formación y profesión en psicología", "fragmento": "Antes de pedir ayuda. Si buscas un profesional para ti o para alguien cercano, comprueba que es psicólogo sanitario o especialista en psicología clínica colegiado. Muchos colegios oficiales tienen un buscador público para verificarlo. Este curso es formación general y no habilita para ejercer.", "evidencia": ["comprueba que es psicólogo sanitario o especialista en psicología clínica colegiado"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('b98cb0b5-b108-5e23-bcfc-3b4fcc40d749', 'f11-inv-1', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd646e09e-853b-5540-a901-76e40b559f0e', '44110e0d-67e8-5083-9992-7c75c2171afc', 'seleccion_multiple', '¿Por qué la psicología no se conforma con el sentido común?', null, '{"opciones": ["Porque muchas ideas que parecen obvias resultan falsas y hacen falta pruebas", "Porque solo los expertos pueden opinar", "Porque los refranes están prohibidos en ciencia", "Porque el sentido común siempre se equivoca"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('b98cb0b5-b108-5e23-bcfc-3b4fcc40d749', '{"correcta": [0]}'::jsonb, 'La historia muestra creencias firmes y equivocadas; la evidencia permite comprobarlas.', '{"leccion": "por-que-investigar", "bloque": "b2", "titulo": "Por qué investigar: del sentido común a la ciencia", "fragmento": "Hace miles de años, algunas culturas hacían agujeros en el cráneo de personas con conductas extrañas, convencidas de que así salían los espíritus malignos. Era una creencia firme, compartida y equivocada. La historia está llena de ideas que parecían de sentido común y resultaron falsas. Por eso la psicología no se conforma con lo que parece obvio: necesita **pruebas**.", "evidencia": ["La historia está llena de ideas que parecían de sentido común y resultaron falsas"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('8f1cafa7-6831-5407-9702-702bb671f970', 'f11-inv-2', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd646e09e-853b-5540-a901-76e40b559f0e', '44110e0d-67e8-5083-9992-7c75c2171afc', 'relacionar', 'Relaciona cada concepto con su definición.', null, '{"izquierda": ["Falsabilidad", "Hipótesis", "Razonamiento inductivo", "Teoría"], "derecha": ["Conjunto bien desarrollado de ideas que explica un fenómeno", "De muchas observaciones concretas a una conclusión general", "Posibilidad de demostrar que una hipótesis es falsa", "Predicción concreta que se puede comprobar"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('8f1cafa7-6831-5407-9702-702bb671f970', '{"pares": {"Teoría": "Conjunto bien desarrollado de ideas que explica un fenómeno", "Hipótesis": "Predicción concreta que se puede comprobar", "Razonamiento inductivo": "De muchas observaciones concretas a una conclusión general", "Falsabilidad": "Posibilidad de demostrar que una hipótesis es falsa"}}'::jsonb, 'La teoría genera hipótesis; la inducción generaliza a partir de casos; una hipótesis científica debe ser falsable.', '{"leccion": "por-que-investigar", "bloque": "b8", "titulo": "Por qué investigar: del sentido común a la ciencia", "fragmento": "Una **teoría** es un conjunto bien desarrollado de ideas que explica un fenómeno. A partir de ella se formulan **hipótesis**, predicciones concretas que se pueden comprobar. Si los datos apoyan la hipótesis, la teoría sale reforzada; si no, hay que revisarla. Es un ciclo continuo: teoría, hipótesis, investigación, observaciones, nuevas ideas y vuelta a empezar. En el **razonamiento deductivo** partimos de una idea general y deducimos qué debería ocurrir en un caso concreto. Si creemos que el ejercicio mejora el ánimo, deducimos que un grupo de personas que empiece a correr debería sentirse mejor en unas semanas. En el **razonamiento inductivo** hacemos lo contrario: a partir de muchas observaciones concretas llegamos a una conclusión general. Si vemos una y otra vez que quienes duermen poco rinden peor, inducimos que el sueño influye en el rendimiento. Una buena hipótesis tiene que ser **falsable**: debe ser posible diseñar un estudio que demuestre que es falsa. El modelo de la mente de Freud, con su inconsciente imposible de observar, se critica precisamente por ser difícil de falsar. En cambio, la idea de que dormir menos de seis horas empeora la memoria al día siguiente sí puede", "evidencia": ["predicciones concretas que se pueden comprobar"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('59423c6c-ded1-5b45-80c8-12c53da75ab8', 'f11-inv-3', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd646e09e-853b-5540-a901-76e40b559f0e', '44110e0d-67e8-5083-9992-7c75c2171afc', 'verdadero_falso_razonado', 'Una teoría científica, una vez demostrada, ya no puede cambiar.', null, '{"razones": ["Falso, porque las teorías nunca se ponen a prueba.", "Falso, porque cualquier idea puede cambiar si aparecen datos nuevos.", "Verdadero, porque las teorías son leyes definitivas."]}'::jsonb, null, 1, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('59423c6c-ded1-5b45-80c8-12c53da75ab8', '{"valor": false, "razon": 1}'::jsonb, 'La ciencia acumula pruebas a favor o en contra; siempre está abierta a revisión.', '{"leccion": "por-que-investigar", "bloque": "b10", "titulo": "Por qué investigar: del sentido común a la ciencia", "fragmento": "En ciencia no se demuestra que una teoría es verdadera para siempre. Se acumulan pruebas a favor o en contra, y cualquier idea puede cambiar si aparecen datos nuevos.", "evidencia": ["cualquier idea puede cambiar si aparecen datos nuevos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('eb3d16e1-4c92-5b19-a317-5775c92fd4fe', 'f11-inv-4', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd646e09e-853b-5540-a901-76e40b559f0e', '44110e0d-67e8-5083-9992-7c75c2171afc', 'seleccion_multiple', '¿Qué hipótesis es falsable?', null, '{"opciones": ["Dormir menos de seis horas empeora la memoria al día siguiente", "Las personas buenas tienen un alma más pura", "El inconsciente guarda deseos que nunca se pueden observar", "Todo ocurre por una razón"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('eb3d16e1-4c92-5b19-a317-5775c92fd4fe', '{"correcta": [0]}'::jsonb, 'Solo la primera puede comprobarse o refutarse con un estudio.', '{"leccion": "por-que-investigar", "bloque": "b9", "titulo": "Por qué investigar: del sentido común a la ciencia", "fragmento": "Una buena hipótesis tiene que ser **falsable**: debe ser posible diseñar un estudio que demuestre que es falsa. El modelo de la mente de Freud, con su inconsciente imposible de observar, se critica precisamente por ser difícil de falsar. En cambio, la idea de que dormir menos de seis horas empeora la memoria al día siguiente sí puede comprobarse o refutarse.", "evidencia": ["dormir menos de seis horas empeora la memoria al día siguiente"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('4d320e1f-2f46-5704-9b97-ade1078f96c5', 'f11-inv-5', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd646e09e-853b-5540-a901-76e40b559f0e', '1831e6d6-c2ef-5863-b32c-02b4d0cdf3fe', 'relacionar', 'Relaciona cada método con su principal límite.', null, '{"izquierda": ["Archivo", "Encuesta", "Estudio de caso", "Observación naturalista"], "derecha": ["Calidad que no controlamos", "Poca generalización", "Riesgo de que el observador influya", "Riesgo de respuestas poco sinceras"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('4d320e1f-2f46-5704-9b97-ade1078f96c5', '{"pares": {"Estudio de caso": "Poca generalización", "Observación naturalista": "Riesgo de que el observador influya", "Encuesta": "Riesgo de respuestas poco sinceras", "Archivo": "Calidad que no controlamos"}}'::jsonb, 'Cada método descriptivo tiene ventajas y un límite característico.', '{"leccion": "metodos-descriptivos", "bloque": "b12", "titulo": "Describir la conducta: casos, observación y encuestas", "fragmento": "Fortalezas y límites de los métodos descriptivos: Estudio de caso: gran detalle, poca generalización.; Observación naturalista: conducta real, riesgo de que el observador influya.; Encuesta: muchos datos, riesgo de respuestas poco sinceras.; Archivo: datos ya disponibles, calidad que no controlamos.", "evidencia": ["Estudio de caso: gran detalle, poca generalización"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('6dc7718b-4f60-5cbd-b6e9-1c9941769a38', 'f11-inv-6', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd646e09e-853b-5540-a901-76e40b559f0e', '1831e6d6-c2ef-5863-b32c-02b4d0cdf3fe', 'caso_clinico', '¿Cuál es el problema principal de este estudio?', 'Un equipo quiere saber qué opina la población española sobre la salud mental y encuesta solo a estudiantes de su facultad.', '{"opciones": ["Debería haber sido un estudio de caso", "Las encuestas nunca sirven para nada", "La muestra no es representativa de la población", "Faltan grupos control y placebo"]}'::jsonb, null, 2, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('6dc7718b-4f60-5cbd-b6e9-1c9941769a38', '{"correcta": [2]}'::jsonb, 'Para generalizar a la población hace falta una muestra representativa, idealmente aleatoria.', '{"leccion": "metodos-descriptivos", "bloque": "b7", "titulo": "Describir la conducta: casos, observación y encuestas", "fragmento": "Casi nunca se puede estudiar a todo el grupo que nos interesa, la **población**. Se trabaja con una **muestra**, un subconjunto de ella. Para poder generalizar, la muestra debe ser **representativa**, y la mejor forma de lograrlo es la **muestra aleatoria**, en la que cada miembro de la población tiene la misma probabilidad de ser elegido. Si encuestamos solo a estudiantes universitarios, no sabremos qué piensa la población general.", "evidencia": ["Si encuestamos solo a estudiantes universitarios, no sabremos qué piensa la población general"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('e72f304b-db22-542d-80fb-57723b392321', 'f11-inv-7', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd646e09e-853b-5540-a901-76e40b559f0e', '1831e6d6-c2ef-5863-b32c-02b4d0cdf3fe', 'respuesta_breve', 'El gran problema de los estudios longitudinales es el ___ de participantes con los años.', null, '{"completar": true}'::jsonb, null, 1, array['fase11','completar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('e72f304b-db22-542d-80fb-57723b392321', '{"aceptadas": ["abandono", "el abandono"], "solucion": "abandono"}'::jsonb, 'Con los años algunos participantes dejan el estudio y la muestra puede dejar de ser representativa.', '{"leccion": "metodos-descriptivos", "bloque": "b11", "titulo": "Describir la conducta: casos, observación y encuestas", "fragmento": "Un ejemplo de estudio **longitudinal** es seguir a un grupo de niños desde los 5 hasta los 30 años para ver cómo influye la infancia en la salud adulta. Su gran problema es el **abandono**: con los años, algunos participantes se mudan, se cansan o fallecen, y la muestra que queda puede dejar de ser representativa.", "evidencia": ["Su gran problema es el abandono"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('2d37d046-9b00-5d48-8945-0ce40cc5773b', 'f11-inv-8', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd646e09e-853b-5540-a901-76e40b559f0e', '1831e6d6-c2ef-5863-b32c-02b4d0cdf3fe', 'seleccion_multiple', '¿Qué descubrió Jane Goodall con la observación naturalista?', null, '{"opciones": ["Que los chimpancés no aprenden de otros", "Que los chimpancés fabrican herramientas", "Que los chimpancés hablan con signos de forma espontánea", "Que los chimpancés no forman grupos"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('2d37d046-9b00-5d48-8945-0ce40cc5773b', '{"correcta": [1]}'::jsonb, 'Décadas de observación en libertad le permitieron documentar el uso de herramientas.', '{"leccion": "metodos-descriptivos", "bloque": "b4", "titulo": "Describir la conducta: casos, observación y encuestas", "fragmento": "En la **observación naturalista** se estudia la conducta en su entorno habitual. Jane Goodall pasó décadas observando chimpancés en libertad en Tanzania y descubrió, entre otras cosas, que fabrican herramientas. El problema es que, si los observados saben que se les mira, pueden cambiar su conducta, igual que conducimos con más cuidado cuando vemos un coche de policía. Para reducir el sesgo, varios observadores registran lo mismo y se comprueba su **fiabilidad entre observadores**.", "evidencia": ["descubrió, entre otras cosas, que fabrican herramientas"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('057fa21e-73fc-5d79-a343-68a319137ca2', 'f11-inv-9', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd646e09e-853b-5540-a901-76e40b559f0e', '3b8d33c7-4211-5744-a660-7ea8d4d0c067', 'caso_clinico', '¿Qué conclusión es correcta?', 'Un periódico titula: «Quienes desayunan cereales pesan menos». El estudio solo comparó lo que la gente decía desayunar con su peso.', '{"opciones": ["Solo hay una correlación; puede haber una variable de confusión", "Comer cereales engorda", "El estudio es un experimento con doble ciego", "Está demostrado que los cereales adelgazan"]}'::jsonb, null, 2, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('057fa21e-73fc-5d79-a343-68a319137ca2', '{"correcta": [0]}'::jsonb, 'Sin manipular la variable ni asignar al azar, solo sabemos que las dos cosas van juntas.', '{"leccion": "correlacion-y-experimento", "bloque": "b4", "titulo": "Correlación y experimento", "fragmento": "Que dos cosas vayan juntas no significa que una cause la otra. En verano aumentan a la vez las ventas de helado y los ahogamientos, pero el helado no ahoga a nadie: ambos dependen de un tercer factor, el calor. A ese tercer factor se le llama **variable de confusión**. Por eso, cuando una noticia dice que quienes desayunan cereales pesan menos, no podemos concluir que los cereales adelgacen.", "evidencia": ["no podemos concluir que los cereales adelgacen"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('605c6112-dedc-50f5-9cd0-c60a89ccc6ff', 'f11-inv-10', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd646e09e-853b-5540-a901-76e40b559f0e', '3b8d33c7-4211-5744-a660-7ea8d4d0c067', 'ordenar', 'Ordena los pasos para montar un experimento sencillo.', null, '{"elementos": ["Aplicar la manipulación solo al grupo experimental", "Asignar al azar a los participantes a los grupos", "Comparar los resultados de los dos grupos", "Elegir la variable independiente que se va a manipular", "Medir la variable dependiente en ambos grupos"]}'::jsonb, null, 2, array['fase11','ordenar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('605c6112-dedc-50f5-9cd0-c60a89ccc6ff', '{"orden": ["Elegir la variable independiente que se va a manipular", "Asignar al azar a los participantes a los grupos", "Aplicar la manipulación solo al grupo experimental", "Medir la variable dependiente en ambos grupos", "Comparar los resultados de los dos grupos"]}'::jsonb, 'Primero se define qué se manipula, luego se reparten los grupos al azar, se aplica la manipulación, se mide y se compara.', '{"leccion": "correlacion-y-experimento", "bloque": "b7", "titulo": "Correlación y experimento", "fragmento": "Para saber si algo causa otra cosa hace falta un **experimento**. El investigador manipula una variable, la **variable independiente**, y mide su efecto en otra, la **variable dependiente**. Un estudio real comparó a estudiantes que tomaban notas a mano con otros que lo hacían en un portátil: la forma de tomar notas era la variable independiente y lo que recordaban después, la dependiente. Los que escribían a mano comprendían mejor el contenido. Los participantes se dividen en un **grupo experimental**, que recibe la manipulación, y un **grupo control**, que no la recibe o recibe un **placebo**, una sustancia o tratamiento sin efecto real. La clave es la **asignación aleatoria**: cada participante tiene la misma probabilidad de acabar en cualquier grupo. Así, las diferencias previas entre personas se reparten por igual y no explican el resultado.", "evidencia": ["La clave es la asignación aleatoria"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('e43f555b-3bbf-598a-bbb3-5fc041aef109', 'f11-inv-11', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd646e09e-853b-5540-a901-76e40b559f0e', '3b8d33c7-4211-5744-a660-7ea8d4d0c067', 'verdadero_falso_razonado', 'Una correlación de menos 0,9 indica una relación débil.', null, '{"razones": ["Falso, porque las correlaciones no pueden ser negativas.", "Falso, porque cuanto más cerca está de menos uno, más fuerte es la relación.", "Verdadero, porque los números negativos indican ausencia de relación."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('e43f555b-3bbf-598a-bbb3-5fc041aef109', '{"valor": false, "razon": 1}'::jsonb, 'El signo indica la dirección; la cercanía a uno o menos uno, la fuerza.', '{"leccion": "correlacion-y-experimento", "bloque": "b2", "titulo": "Correlación y experimento", "fragmento": "Existe una **correlación** cuando dos variables cambian juntas. Se mide con el **coeficiente de correlación**, un número entre menos uno y uno. En una **correlación positiva**, ambas aumentan o disminuyen juntas, como la estatura y el peso. En una **correlación negativa**, cuando una sube la otra baja, como las horas de sueño perdidas y la atención. Cuanto más cerca está el número de uno o de menos uno, más fuerte es la relación; cerca de cero, apenas hay relación.", "evidencia": ["Cuanto más cerca está el número de uno o de menos uno, más fuerte es la relación"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('64e432f7-2d31-5b5b-865b-dd2fc541517b', 'f11-inv-12', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd646e09e-853b-5540-a901-76e40b559f0e', '3b8d33c7-4211-5744-a660-7ea8d4d0c067', 'respuesta_breve', '¿Cómo se llama la mejora que aparece solo porque la persona cree que recibe un tratamiento?', null, '{}'::jsonb, null, 1, array['fase11','respuesta_breve']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('64e432f7-2d31-5b5b-865b-dd2fc541517b', '{"aceptadas": ["efecto placebo", "placebo", "el efecto placebo"], "solucion": "efecto placebo"}'::jsonb, 'Las expectativas pueden mejorar los síntomas aunque el tratamiento no tenga efecto real.', '{"leccion": "correlacion-y-experimento", "bloque": "b9", "titulo": "Correlación y experimento", "fragmento": "Las expectativas también influyen. El **efecto placebo** aparece cuando una persona mejora solo porque cree que recibe un tratamiento. Y el **sesgo del experimentador** surge cuando el investigador, sin querer, trata distinto a cada grupo. Para evitar ambos se usa el **doble ciego**: ni los participantes ni quienes recogen los datos saben quién está en cada grupo.", "evidencia": ["mejora solo porque cree que recibe un tratamiento"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('1a7cbd75-9b4f-5a07-bfb5-46ef0d8f5132', 'f11-inv-13', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd646e09e-853b-5540-a901-76e40b559f0e', '48ed56a8-917e-50f6-ba95-62b80a2f7420', 'seleccion_multiple', '¿Qué derecho debe garantizar siempre el consentimiento informado?', null, '{"opciones": ["Cobrar por participar", "Conocer los datos de los demás participantes", "Retirarse en cualquier momento sin ninguna consecuencia", "Elegir el grupo en el que participa"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('1a7cbd75-9b4f-5a07-bfb5-46ef0d8f5132', '{"correcta": [2]}'::jsonb, 'La participación es voluntaria de principio a fin.', '{"leccion": "etica-en-investigacion", "bloque": "b5", "titulo": "La ética en la investigación", "fragmento": "Cada participante debe dar su **consentimiento informado**: un documento escrito en lenguaje claro que explica en qué consiste el estudio, qué riesgos y beneficios tiene, cómo se protegerá la confidencialidad y, muy importante, que puede **retirarse en cualquier momento** sin ninguna consecuencia. En el caso de menores, firman sus padres o tutores y el menor da su asentimiento.", "evidencia": ["puede retirarse en cualquier momento sin ninguna consecuencia"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('128d80ba-75e6-5af5-ac0c-6a4c05947a15', 'f11-inv-14', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd646e09e-853b-5540-a901-76e40b559f0e', '48ed56a8-917e-50f6-ba95-62b80a2f7420', 'verdadero_falso_razonado', 'El engaño en un estudio nunca está permitido.', null, '{"razones": ["Verdadero, porque cualquier engaño es ilegal.", "Falso, porque se permite si es imprescindible, no causa daño y va seguido de una explicación final.", "Falso, porque se permite siempre que el investigador quiera."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('128d80ba-75e6-5af5-ac0c-6a4c05947a15', '{"valor": false, "razon": 1}'::jsonb, 'El comité puede autorizar cierto engaño con condiciones, y al final se cuenta la verdad.', '{"leccion": "etica-en-investigacion", "bloque": "b7", "titulo": "La ética en la investigación", "fragmento": "A veces, contar todo el objetivo de un estudio cambiaría la conducta de los participantes. En esos casos el comité puede permitir cierto **engaño**, siempre que sea imprescindible y no cause daño. Al terminar, el investigador hace una **explicación final**, en la que cuenta la verdad, aclara por qué fue necesario el engaño y resuelve dudas.", "evidencia": ["siempre que sea imprescindible y no cause daño"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('7ffde4b8-586f-5643-aa95-25cf9bd25ab3', 'f11-inv-15', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd646e09e-853b-5540-a901-76e40b559f0e', '48ed56a8-917e-50f6-ba95-62b80a2f7420', 'relacionar', 'Relaciona cada principio de las tres erres con lo que exige.', null, '{"izquierda": ["Reducir", "Reemplazar", "Refinar"], "derecha": ["Emplear el menor número de animales necesario", "Mejorar los procedimientos para minimizar el dolor y el estrés", "Usar métodos sin animales cuando sea posible"]}'::jsonb, null, 1, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('7ffde4b8-586f-5643-aa95-25cf9bd25ab3', '{"pares": {"Reemplazar": "Usar métodos sin animales cuando sea posible", "Reducir": "Emplear el menor número de animales necesario", "Refinar": "Mejorar los procedimientos para minimizar el dolor y el estrés"}}'::jsonb, 'Las tres erres guían la investigación con animales.', '{"leccion": "etica-en-investigacion", "bloque": "b10", "titulo": "La ética en la investigación", "fragmento": "El principio de las tres erres: Reemplazar | Usar métodos sin animales cuando sea posible · Reducir | Emplear el menor número de animales necesario · Refinar | Mejorar los procedimientos para minimizar el dolor y el estrés", "evidencia": ["Emplear el menor número de animales necesario"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('07f30a0c-322f-5f65-bd69-e40f3f8cf152', 'f11-inv-16', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd646e09e-853b-5540-a901-76e40b559f0e', '48ed56a8-917e-50f6-ba95-62b80a2f7420', 'seleccion_multiple', '¿Por qué es tan recordado el estudio de Tuskegee?', null, '{"opciones": ["Porque fue el primer experimento doble ciego", "Porque no se informó a los participantes y se les negó el tratamiento con penicilina", "Porque descubrió la cura de la sífilis", "Porque usó solo animales"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('07f30a0c-322f-5f65-bd69-e40f3f8cf152', '{"correcta": [1]}'::jsonb, 'Fue un abuso grave que impulsó las normas éticas actuales.', '{"leccion": "etica-en-investigacion", "bloque": "b2", "titulo": "La ética en la investigación", "fragmento": "Entre 1932 y 1972, el servicio de salud pública de Estados Unidos estudió la evolución de la sífilis en cientos de hombres afroamericanos pobres de Tuskegee, Alabama. No se les explicó qué tenían y, cuando apareció la penicilina, no se les dio el tratamiento. Muchos murieron y contagiaron a sus parejas e hijos. Casos como este llevaron a crear normas estrictas para proteger a quienes participan en una investigación.", "evidencia": ["cuando apareció la penicilina, no se les dio el tratamiento"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('8689861a-0c64-5abc-bdff-971909d6d6ea', 'f11-bio-1', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '128977df-8867-58a6-86a6-e1988869671f', '7482f91b-7b88-5a18-a943-705cc9dd44d0', 'seleccion_multiple', '¿Por qué el gen de la anemia falciforme es más frecuente donde hay malaria?', null, '{"opciones": ["Porque en esas regiones no hay selección natural", "Porque tener una sola copia protege frente a la malaria", "Porque es un alelo dominante sin riesgos", "Porque la malaria produce el gen"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
