insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('8689861a-0c64-5abc-bdff-971909d6d6ea', '{"correcta": [1]}'::jsonb, 'La ventaja de portar una copia compensa el riesgo de la enfermedad en esas zonas.', '{"leccion": "genes-y-evolucion", "bloque": "b3", "titulo": "Genes, ambiente y evolución", "fragmento": "Un ejemplo clásico es la **anemia falciforme**, una enfermedad hereditaria en la que los glóbulos rojos tienen forma de hoz. Tener una sola copia del gen que la produce protege frente a la malaria. Por eso este gen es más frecuente en regiones donde la malaria es común: allí, la ventaja de portarlo compensa el riesgo de la enfermedad.", "evidencia": ["Tener una sola copia del gen que la produce protege frente a la malaria"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('028d30f5-eea7-51f5-a128-85850640537e', 'f11-bio-2', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '128977df-8867-58a6-86a6-e1988869671f', '7482f91b-7b88-5a18-a943-705cc9dd44d0', 'relacionar', 'Relaciona cada término con su definición.', null, '{"izquierda": ["Alelo", "Fenotipo", "Genotipo", "Mutación"], "derecha": ["Cambio en el ADN", "Composición genética de una persona", "Rasgos que se observan", "Versión de un gen"]}'::jsonb, null, 1, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('028d30f5-eea7-51f5-a128-85850640537e', '{"pares": {"Genotipo": "Composición genética de una persona", "Fenotipo": "Rasgos que se observan", "Alelo": "Versión de un gen", "Mutación": "Cambio en el ADN"}}'::jsonb, 'Son los conceptos básicos de la herencia.', '{"leccion": "genes-y-evolucion", "bloque": "b5", "titulo": "Genes, ambiente y evolución", "fragmento": "Cada persona recibe la mitad de sus **cromosomas** de cada progenitor. Los cromosomas están hechos de **ADN** y contienen los **genes**, las unidades de la herencia. El **genotipo** es nuestra composición genética; el **fenotipo**, los rasgos que se observan, como el color de los ojos o la estatura. Cada gen puede presentarse en distintas versiones llamadas **alelos**. Un alelo **dominante** se expresa aunque solo haya una copia; uno **recesivo** solo se expresa si hay dos copias. Pocos rasgos dependen de un solo gen. La mayoría, como la inteligencia, la personalidad o el riesgo de depresión, son **poligénicos**: intervienen muchos genes, cada uno con un efecto pequeño. Además, el ADN puede cambiar por **mutaciones**, que a veces son perjudiciales y otras veces aportan variedad sobre la que actúa la selección natural.", "evidencia": ["El genotipo es nuestra composición genética"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('21198917-aa3d-5dd2-979b-39d393d4a369', 'f11-bio-3', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '128977df-8867-58a6-86a6-e1988869671f', '7482f91b-7b88-5a18-a943-705cc9dd44d0', 'verdadero_falso_razonado', 'Dos gemelos idénticos serán siempre iguales en todo porque tienen el mismo ADN.', null, '{"razones": ["Verdadero, porque el ADN lo determina todo.", "Falso, porque los gemelos idénticos tienen ADN distinto.", "Falso, porque el ambiente puede activar o silenciar genes y diferenciarlos con los años."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('21198917-aa3d-5dd2-979b-39d393d4a369', '{"valor": false, "razon": 2}'::jsonb, 'La epigenética explica por qué personas con el mismo ADN pueden diferir.', '{"leccion": "genes-y-evolucion", "bloque": "b10", "titulo": "Genes, ambiente y evolución", "fragmento": "La **epigenética** estudia cómo el ambiente puede activar o silenciar genes sin cambiar la secuencia del ADN. El estrés intenso, la alimentación o el cuidado recibido en la infancia pueden dejar marcas que cambian qué genes se expresan. Por eso dos gemelos idénticos, con el mismo ADN, pueden diferir cada vez más con los años.", "evidencia": ["dos gemelos idénticos, con el mismo ADN, pueden diferir cada vez más"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
