insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('5b4a35e3-0030-5d37-b78c-3edc47f27f08', '{"aceptadas": ["poligénicos", "poligenicos", "rasgos poligénicos"], "solucion": "poligénicos"}'::jsonb, 'La inteligencia o la personalidad son rasgos poligénicos.', '{"leccion": "genes-y-evolucion", "bloque": "b7", "titulo": "Genes, ambiente y evolución", "fragmento": "Pocos rasgos dependen de un solo gen. La mayoría, como la inteligencia, la personalidad o el riesgo de depresión, son **poligénicos**: intervienen muchos genes, cada uno con un efecto pequeño. Además, el ADN puede cambiar por **mutaciones**, que a veces son perjudiciales y otras veces aportan variedad sobre la que actúa la selección natural.", "evidencia": ["La mayoría, como la inteligencia, la personalidad o el riesgo de depresión, son poligénicos"]}'::jsonb)
