values ('0e6c80fd-d4cb-564c-938e-0290b32c9cd6', 'f11-bio-5', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '128977df-8867-58a6-86a6-e1988869671f', '79db5103-4de8-51ae-aa51-5091075e044c', 'ordenar', 'Ordena el recorrido de la señal nerviosa.', null, '{"elementos": ["El potencial de acción recorre el axón", "La neurona alcanza el umbral de excitación", "Las dendritas reciben señales de otras neuronas", "Los botones terminales liberan neurotransmisores", "Los neurotransmisores se unen a receptores de la neurona siguiente"]}'::jsonb, null, 2, array['fase11','ordenar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('0e6c80fd-d4cb-564c-938e-0290b32c9cd6', '{"orden": ["Las dendritas reciben señales de otras neuronas", "La neurona alcanza el umbral de excitación", "El potencial de acción recorre el axón", "Los botones terminales liberan neurotransmisores", "Los neurotransmisores se unen a receptores de la neurona siguiente"]}'::jsonb, 'La señal entra por las dendritas, se convierte en impulso en el axón y pasa químicamente en la sinapsis.', '{"leccion": "neuronas-y-sinapsis", "bloque": "b6", "titulo": "Neuronas, impulsos y neurotransmisores", "fragmento": "En reposo, el interior de la neurona tiene carga negativa respecto al exterior, unos menos 70 milivoltios: es el **potencial de reposo**. Cuando la neurona recibe suficiente estimulación y alcanza el **umbral de excitación**, se abren canales en la membrana, entran iones de sodio cargados positivamente y la carga se invierte por un instante. Ese cambio, el **potencial de acción**, recorre el axón como una ola. Entre una neurona y la siguiente queda un pequeño espacio, la **hendidura sináptica**. Cuando el impulso llega a los botones terminales, estos liberan **neurotransmisores**, mensajeros químicos que cruzan el espacio y se unen a **receptores** de la neurona siguiente como una llave en su cerradura. Después, los neurotransmisores sobrantes se reabsorben, en un proceso llamado **recaptación**, o se degradan.", "evidencia": ["se unen a receptores de la neurona siguiente"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('d5bcb009-07c2-5ab5-b8e2-7528e9214fbf', 'f11-bio-6', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '128977df-8867-58a6-86a6-e1988869671f', '79db5103-4de8-51ae-aa51-5091075e044c', 'relacionar', 'Relaciona cada neurotransmisor con su función principal.', null, '{"izquierda": ["Dopamina", "Endorfinas", "GABA", "Serotonina"], "derecha": ["Alivio del dolor y bienestar", "Estado de ánimo, sueño y apetito", "Movimiento, motivación y recompensa", "Principal inhibidor: frena la actividad neuronal"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
