insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('d5bcb009-07c2-5ab5-b8e2-7528e9214fbf', '{"pares": {"Dopamina": "Movimiento, motivación y recompensa", "Serotonina": "Estado de ánimo, sueño y apetito", "GABA": "Principal inhibidor: frena la actividad neuronal", "Endorfinas": "Alivio del dolor y bienestar"}}'::jsonb, 'Cada neurotransmisor participa en funciones concretas.', '{"leccion": "neuronas-y-sinapsis", "bloque": "b10", "titulo": "Neuronas, impulsos y neurotransmisores", "fragmento": "Algunos neurotransmisores: Acetilcolina | Movimiento muscular, atención y memoria · Dopamina | Movimiento, motivación y recompensa · Serotonina | Estado de ánimo, sueño y apetito · Noradrenalina | Alerta y respuesta de estrés · GABA | Principal inhibidor: frena la actividad neuronal · Glutamato | Principal excitador: aprendizaje y memoria · Endorfinas | Alivio del dolor y bienestar", "evidencia": ["Principal inhibidor: frena la actividad neuronal"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('1047f949-4a4c-5d2a-8512-ecc58646d2b2', 'f11-bio-7', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '128977df-8867-58a6-86a6-e1988869671f', '79db5103-4de8-51ae-aa51-5091075e044c', 'seleccion_multiple', '¿Cómo codifica una neurona un estímulo más intenso?', null, '{"opciones": ["Disparando potenciales de acción más grandes", "Alargando el axón", "Cambiando de neurotransmisor", "Disparando más veces por segundo"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('1047f949-4a4c-5d2a-8512-ecc58646d2b2', '{"correcta": [3]}'::jsonb, 'Por el principio de todo o nada, la intensidad se codifica por la frecuencia de disparo.', '{"leccion": "neuronas-y-sinapsis", "bloque": "b7", "titulo": "Neuronas, impulsos y neurotransmisores", "fragmento": "El potencial de acción sigue el principio de **todo o nada**: o se produce completo o no se produce. Una neurona no dispara más fuerte ante un estímulo intenso; dispara más veces por segundo. Después de cada disparo hay un breve periodo en el que la neurona recupera su carga y no puede volver a disparar.", "evidencia": ["dispara más veces por segundo"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('976e1157-1254-5273-a2bd-a993eccb606c', 'f11-bio-8', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '128977df-8867-58a6-86a6-e1988869671f', '79db5103-4de8-51ae-aa51-5091075e044c', 'caso_clinico', '¿Qué efecto busca el fármaco en la sinapsis?', 'A Elena le recetan un antidepresivo que impide la recaptación de serotonina.', '{"opciones": ["Bloquear la liberación de dopamina", "Que la serotonina permanezca más tiempo en la hendidura sináptica", "Aumentar la mielina de los axones", "Destruir los receptores de serotonina"]}'::jsonb, null, 2, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
