insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('976e1157-1254-5273-a2bd-a993eccb606c', '{"correcta": [1]}'::jsonb, 'Al bloquear la recaptación, la serotonina actúa más tiempo sobre los receptores.', '{"leccion": "neuronas-y-sinapsis", "bloque": "b11", "titulo": "Neuronas, impulsos y neurotransmisores", "fragmento": "Muchos fármacos actúan sobre la sinapsis. Un **agonista** imita o potencia a un neurotransmisor; un **antagonista** lo bloquea. Algunos antidepresivos, por ejemplo, impiden la recaptación de serotonina para que permanezca más tiempo en la hendidura. Los antipsicóticos clásicos bloquean receptores de dopamina.", "evidencia": ["impiden la recaptación de serotonina para que permanezca más tiempo en la hendidura"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('6266cd5d-0a0e-5b76-a6b8-f4bbea4a184d', 'f11-bio-9', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '128977df-8867-58a6-86a6-e1988869671f', 'd5d4a9d4-080d-55ff-b8ad-82ee978cba94', 'seleccion_multiple', '¿Qué forma el sistema nervioso central?', null, '{"opciones": ["Las glándulas endocrinas", "El sistema simpático y el parasimpático", "Los nervios de brazos y piernas", "El encéfalo y la médula espinal"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('6266cd5d-0a0e-5b76-a6b8-f4bbea4a184d', '{"correcta": [3]}'::jsonb, 'El resto de nervios forman el sistema nervioso periférico.', '{"leccion": "sistema-nervioso-y-corteza", "bloque": "b2", "titulo": "El sistema nervioso y la corteza cerebral", "fragmento": "El sistema nervioso se divide en dos grandes partes. El **sistema nervioso central** está formado por el encéfalo y la médula espinal. El **sistema nervioso periférico** son los nervios que conectan el sistema central con el resto del cuerpo. Dentro del periférico, el **sistema somático** controla los movimientos voluntarios y lleva la información de los sentidos, y el **sistema autónomo** regula de forma automática los órganos internos, como el corazón o la digestión.", "evidencia": ["está formado por el encéfalo y la médula espinal"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
