insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('fbf38763-95f5-5378-b800-b663d9f19d1f', '{"pares": {"Frontal": "Movimiento voluntario, planificación, juicio, personalidad y habla", "Parietal": "Tacto, temperatura, dolor y orientación en el espacio", "Temporal": "Audición, comprensión del lenguaje y memoria", "Occipital": "Visión"}}'::jsonb, 'Cada lóbulo se especializa en funciones distintas, aunque trabajan en red.', '{"leccion": "sistema-nervioso-y-corteza", "bloque": "b7", "titulo": "El sistema nervioso y la corteza cerebral", "fragmento": "Los lóbulos de la corteza: Frontal | Movimiento voluntario, planificación, juicio, personalidad y habla · Parietal | Tacto, temperatura, dolor y orientación en el espacio · Temporal | Audición, comprensión del lenguaje y memoria · Occipital | Visión", "evidencia": ["Tacto, temperatura, dolor y orientación en el espacio"]}'::jsonb)
