insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('cfb0c014-871b-56f1-b9f9-8b6d06fd0819', 'f11-bio-11', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '128977df-8867-58a6-86a6-e1988869671f', 'd5d4a9d4-080d-55ff-b8ad-82ee978cba94', 'caso_clinico', '¿Qué área es más probable que esté dañada?', 'Tras un ictus, Antonio habla con fluidez, pero lo que dice no tiene sentido y no entiende lo que le preguntan.', '{"opciones": ["El cerebelo", "El área de Broca", "El área de Wernicke", "El lóbulo occipital"]}'::jsonb, null, 3, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('cfb0c014-871b-56f1-b9f9-8b6d06fd0819', '{"correcta": [2]}'::jsonb, 'La lesión de Wernicke afecta a la comprensión y produce un habla fluida pero sin sentido.', '{"leccion": "sistema-nervioso-y-corteza", "bloque": "b9", "titulo": "El sistema nervioso y la corteza cerebral", "fragmento": "El lenguaje se apoya sobre todo en el hemisferio izquierdo. El **área de Broca**, en el lóbulo frontal, interviene en la producción del habla: si se lesiona, la persona entiende pero le cuesta mucho hablar. El **área de Wernicke**, en el temporal, interviene en la comprensión: su lesión produce un habla fluida pero sin sentido. Las cortezas **motora** y **somatosensorial** dedican más espacio a las partes del cuerpo más finas, como las manos y la cara.", "evidencia": ["su lesión produce un habla fluida pero sin sentido"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('9fccce70-7ae2-5522-92fe-fcbfc3708c10', 'f11-bio-12', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '128977df-8867-58a6-86a6-e1988869671f', 'd5d4a9d4-080d-55ff-b8ad-82ee978cba94', 'verdadero_falso_razonado', 'Hay personas que usan solo el hemisferio derecho y otras solo el izquierdo.', null, '{"razones": ["Falso, porque en casi todas las tareas trabajan los dos hemisferios juntos.", "Verdadero, porque los artistas usan solo el derecho.", "Falso, porque solo usamos el diez por ciento del cerebro."]}'::jsonb, null, 1, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('9fccce70-7ae2-5522-92fe-fcbfc3708c10', '{"valor": false, "razon": 0}'::jsonb, 'Existe cierta especialización, pero ambos hemisferios colaboran.', '{"leccion": "sistema-nervioso-y-corteza", "bloque": "b10", "titulo": "El sistema nervioso y la corteza cerebral", "fragmento": "Los estudios con personas a las que se cortó el cuerpo calloso para tratar una epilepsia grave mostraron cierta **lateralización**: el hemisferio izquierdo destaca en lenguaje y el derecho en tareas espaciales y en reconocer caras. Aun así, la idea popular de personas de cerebro derecho o izquierdo es un mito: en casi todas las tareas trabajan los dos hemisferios juntos.", "evidencia": ["en casi todas las tareas trabajan los dos hemisferios juntos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
