values ('22da777b-86ea-519a-a6b6-127478f44efc', 'f11-bio-13', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '128977df-8867-58a6-86a6-e1988869671f', 'fa8850ae-40e1-576b-962a-6cb12e11e63e', 'seleccion_multiple', '¿Qué estructura actúa como estación de relevo de la información sensorial?', null, '{"opciones": ["El tálamo", "El bulbo raquídeo", "El cerebelo", "La amígdala"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
