insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('22da777b-86ea-519a-a6b6-127478f44efc', '{"correcta": [0]}'::jsonb, 'El tálamo recibe casi toda la información de los sentidos y la envía a la corteza.', '{"leccion": "cerebro-profundo-y-hormonas", "bloque": "b2", "titulo": "El cerebro profundo, cómo se estudia y las hormonas", "fragmento": "En el centro del encéfalo está el **tálamo**, una estación de relevo que recibe la información de casi todos los sentidos y la envía a la zona adecuada de la corteza. Debajo se encuentra el **hipotálamo**, pequeño pero esencial: regula el hambre, la sed, la temperatura, el sueño y la conducta sexual, y controla la hipófisis.", "evidencia": ["una estación de relevo que recibe la información de casi todos los sentidos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
