insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('55a56565-7cf1-537e-81d0-06fb3688cb89', '{"pares": {"Resonancia magnética (RM)": "Estructura con mucho detalle, mediante campos magnéticos", "Resonancia funcional (RMf)": "Actividad, según el flujo de sangre oxigenada", "Electroencefalograma (EEG)": "Actividad eléctrica con gran precisión temporal"}}'::jsonb, 'Unas técnicas muestran la estructura y otras la actividad.', '{"leccion": "cerebro-profundo-y-hormonas", "bloque": "b7", "titulo": "El cerebro profundo, cómo se estudia y las hormonas", "fragmento": "Técnicas para estudiar el cerebro: Tomografía computarizada (TC) | Estructura, mediante rayos X | Detectar un tumor o una hemorragia · Resonancia magnética (RM) | Estructura con mucho detalle, mediante campos magnéticos | Ver una lesión pequeña · Resonancia funcional (RMf) | Actividad, según el flujo de sangre oxigenada | Ver qué zonas se activan al leer · Tomografía por emisión de positrones (PET) | Actividad, mediante un marcador radiactivo | Estudiar el metabolismo cerebral · Electroencefalograma (EEG) | Actividad eléctrica con gran precisión temporal | Estudiar el sueño o la epilepsia", "evidencia": ["Actividad, según el flujo de sangre oxigenada"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
