insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('fd64a4ec-2db7-50ef-a3dd-1d7dd0fccec0', '{"aceptadas": ["melatonina", "la melatonina"], "solucion": "melatonina"}'::jsonb, 'La melatonina aumenta con la oscuridad y favorece el sueño.', '{"leccion": "cerebro-profundo-y-hormonas", "bloque": "b11", "titulo": "El cerebro profundo, cómo se estudia y las hormonas", "fragmento": "Glándulas principales: Hipófisis: hormona del crecimiento y control de otras glándulas.; Tiroides: regula el metabolismo.; Suprarrenales: adrenalina y cortisol en la respuesta de estrés.; Páncreas: insulina para regular el azúcar en sangre.; Gónadas (ovarios y testículos): hormonas sexuales.; Glándula pineal: melatonina, que regula el sueño.", "evidencia": ["Glándula pineal: melatonina, que regula el sueño"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
