values ('0a8134ff-4ad7-5818-a5c7-2c0b6310888c', 'f11-bio-16', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '128977df-8867-58a6-86a6-e1988869671f', 'fa8850ae-40e1-576b-962a-6cb12e11e63e', 'seleccion_multiple', '¿En qué se diferencia el sistema endocrino del nervioso?', null, '{"opciones": ["Es más lento, pero sus efectos duran más", "No interviene en el estrés", "Es más rápido y preciso", "Solo funciona durante el sueño"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('0a8134ff-4ad7-5818-a5c7-2c0b6310888c', '{"correcta": [0]}'::jsonb, 'Las hormonas viajan por la sangre: tardan más, pero su efecto es más duradero.', '{"leccion": "cerebro-profundo-y-hormonas", "bloque": "b10", "titulo": "El cerebro profundo, cómo se estudia y las hormonas", "fragmento": "Además del sistema nervioso, el cuerpo tiene otro sistema de comunicación: el **sistema endocrino**, formado por **glándulas** que liberan **hormonas** a la sangre. Las hormonas son más lentas que los impulsos nerviosos, pero sus efectos duran más. La **hipófisis**, controlada por el hipotálamo, se considera la glándula maestra porque regula a muchas otras.", "evidencia": ["Las hormonas son más lentas que los impulsos nerviosos, pero sus efectos duran más"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('65388517-8292-5469-a045-fff75fade66b', 'f11-con-1', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '80f4d8fe-20dc-5e55-8ee1-c42ff6ec1aac', 'c959bd45-f379-593c-ab59-9d98aa1be0a0', 'verdadero_falso_razonado', 'La conciencia funciona como un interruptor: o estamos conscientes o no lo estamos.', null, '{"razones": ["Verdadero, porque el cerebro se apaga al dormir.", "Falso, porque nunca dejamos de estar plenamente alerta.", "Falso, porque es un continuo que va de la alerta plena al sueño profundo o el coma."]}'::jsonb, null, 1, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('65388517-8292-5469-a045-fff75fade66b', '{"valor": false, "razon": 2}'::jsonb, 'Entre la alerta plena y la pérdida de conciencia hay muchos estados intermedios.', '{"leccion": "conciencia-y-ritmos", "bloque": "b2", "titulo": "La conciencia y los ritmos del cuerpo", "fragmento": "La **conciencia** es el darnos cuenta de lo que ocurre dentro y fuera de nosotros: lo que vemos, oímos, pensamos y sentimos. No es un interruptor de encendido y apagado, sino un continuo. En un extremo está la **alerta plena**, cuando resolvemos un problema difícil; en el otro, el **sueño profundo** o el coma. En medio hay muchos estados, como la somnolencia, la ensoñación despierta o la concentración absorta en una tarea.", "evidencia": ["No es un interruptor de encendido y apagado, sino un continuo"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
