insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('cbb1098d-e120-5659-80b4-f6f33f9f0cc7', '{"correcta": [0]}'::jsonb, 'La luz informa al reloj biológico de que es de día y frena la melatonina.', '{"leccion": "conciencia-y-ritmos", "bloque": "b6", "titulo": "La conciencia y los ritmos del cuerpo", "fragmento": "Este reloj está en el **núcleo supraquiasmático**, un pequeño grupo de neuronas del hipotálamo. Recibe información sobre la luz desde los ojos y la usa para sincronizar el cuerpo con el día y la noche. Cuando oscurece, la **glándula pineal** libera **melatonina**, una hormona que favorece el sueño. La luz intensa, incluida la de las pantallas por la noche, frena su liberación.", "evidencia": ["La luz intensa, incluida la de las pantallas por la noche, frena su liberación"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
