insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('c0168d0a-0869-5005-a0b0-db0342ccdff8', '{"aceptadas": ["supraquiasmático", "supraquiasmatico"], "solucion": "supraquiasmático"}'::jsonb, 'El núcleo supraquiasmático sincroniza el cuerpo con la luz.', '{"leccion": "conciencia-y-ritmos", "bloque": "b6", "titulo": "La conciencia y los ritmos del cuerpo", "fragmento": "Este reloj está en el **núcleo supraquiasmático**, un pequeño grupo de neuronas del hipotálamo. Recibe información sobre la luz desde los ojos y la usa para sincronizar el cuerpo con el día y la noche. Cuando oscurece, la **glándula pineal** libera **melatonina**, una hormona que favorece el sueño. La luz intensa, incluida la de las pantallas por la noche, frena su liberación.", "evidencia": ["Este reloj está en el núcleo supraquiasmático"]}'::jsonb)
