insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('1f2bdd62-8bac-5a29-b05e-89ce2e82c9d1', 'f11-con-4', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '80f4d8fe-20dc-5e55-8ee1-c42ff6ec1aac', 'c959bd45-f379-593c-ab59-9d98aa1be0a0', 'seleccion_multiple', '¿Qué ocurre tras varias noches seguidas durmiendo poco?', null, '{"opciones": ["Solo empeora el humor, pero no la atención", "Mejora la memoria por el estrés", "Se acumula una deuda de sueño con un deterioro parecido a pasar una noche en vela", "El cuerpo se acostumbra y deja de necesitar sueño"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('1f2bdd62-8bac-5a29-b05e-89ce2e82c9d1', '{"correcta": [2]}'::jsonb, 'Las noches cortas suman deuda de sueño con efectos claros en el rendimiento.', '{"leccion": "conciencia-y-ritmos", "bloque": "b9", "titulo": "La conciencia y los ritmos del cuerpo", "fragmento": "La **privación de sueño** es muy común. Los adultos necesitan en general entre siete y nueve horas, y los adolescentes algo más, pero muchos duermen bastante menos. La **deuda de sueño** se acumula: varias noches cortas seguidas producen un deterioro parecido al de pasar una noche en vela. Dormir poco empeora la atención, la memoria, el estado de ánimo y la capacidad de conducir, y a largo plazo se relaciona con obesidad, diabetes, hipertensión y depresión.", "evidencia": ["varias noches cortas seguidas producen un deterioro parecido al de pasar una noche en vela"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
