values ('1b1807e5-beba-5541-957b-44bd620213f9', 'f11-con-5', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '80f4d8fe-20dc-5e55-8ee1-c42ff6ec1aac', '9bc593f1-4779-5066-b305-e0c44b44fcf6', 'ordenar', 'Ordena las fases por las que se pasa en el primer ciclo de sueño.', null, '{"elementos": ["N1: transición entre vigilia y sueño", "N2: sueño ligero con husos de sueño", "N3: sueño profundo de ondas delta", "REM: sueños vívidos y músculos paralizados"]}'::jsonb, null, 2, array['fase11','ordenar']::text[], 'Material integrado del tema', 'publicada')
