insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('1b1807e5-beba-5541-957b-44bd620213f9', '{"orden": ["N1: transición entre vigilia y sueño", "N2: sueño ligero con husos de sueño", "N3: sueño profundo de ondas delta", "REM: sueños vívidos y músculos paralizados"]}'::jsonb, 'El sueño se profundiza de N1 a N3 y luego llega el REM.', '{"leccion": "fases-del-sueno", "bloque": "b5", "titulo": "Por qué dormimos y las fases del sueño", "fragmento": "Las fases del sueño: N1 | Transición entre vigilia y sueño; ondas theta; es fácil despertar · N2 | Sueño ligero; aparecen husos de sueño y complejos K; baja la temperatura · N3 | Sueño profundo o de ondas lentas; ondas delta; es muy difícil despertar · REM | Ojos que se mueven rápido, cerebro muy activo, músculos paralizados y sueños vívidos", "evidencia": ["Transición entre vigilia y sueño"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('cf51c408-b56f-59e1-b697-591b61bf2a5e', 'f11-con-6', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '80f4d8fe-20dc-5e55-8ee1-c42ff6ec1aac', '9bc593f1-4779-5066-b305-e0c44b44fcf6', 'relacionar', 'Relaciona cada teoría con su idea principal.', null, '{"izquierda": ["Activación y síntesis", "Procesamiento de información", "Psicoanalítica (Freud)"], "derecha": ["El cerebro da sentido a señales nerviosas aleatorias", "Los sueños expresan deseos inconscientes disfrazados", "Soñar ayuda a ordenar y consolidar lo vivido"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
