insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('cf51c408-b56f-59e1-b697-591b61bf2a5e', '{"pares": {"Psicoanalítica (Freud)": "Los sueños expresan deseos inconscientes disfrazados", "Activación y síntesis": "El cerebro da sentido a señales nerviosas aleatorias", "Procesamiento de información": "Soñar ayuda a ordenar y consolidar lo vivido"}}'::jsonb, 'Hay varias explicaciones de los sueños y ninguna es definitiva.', '{"leccion": "fases-del-sueno", "bloque": "b9", "titulo": "Por qué dormimos y las fases del sueño", "fragmento": "Teorías sobre los sueños: Psicoanalítica (Freud) | Los sueños expresan deseos inconscientes disfrazados; se distingue el contenido manifiesto del latente · Jung | Los sueños conectan con un inconsciente colectivo compartido por todos los seres humanos · Activación y síntesis | El cerebro intenta dar sentido a señales nerviosas aleatorias durante el REM · Procesamiento de información | Soñar ayuda a ordenar y consolidar lo vivido y lo aprendido", "evidencia": ["Soñar ayuda a ordenar y consolidar lo vivido y lo aprendido"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('e616b900-607d-5234-a36f-81e14b301f50', 'f11-con-7', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '80f4d8fe-20dc-5e55-8ee1-c42ff6ec1aac', '9bc593f1-4779-5066-b305-e0c44b44fcf6', 'seleccion_multiple', '¿Para qué sirve la parálisis muscular del sueño REM?', null, '{"opciones": ["Ahorra energía para el día siguiente", "Evita que representemos con el cuerpo lo que soñamos", "Produce los movimientos oculares", "Aumenta la temperatura corporal"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('e616b900-607d-5234-a36f-81e14b301f50', '{"correcta": [1]}'::jsonb, 'Sin esa parálisis, actuaríamos los sueños.', '{"leccion": "fases-del-sueno", "bloque": "b6", "titulo": "Por qué dormimos y las fases del sueño", "fragmento": "El **sueño REM** es paradójico: el cerebro muestra una actividad parecida a la de la vigilia, pero los músculos voluntarios quedan casi paralizados. Es en esta fase donde se dan los sueños más vívidos y con argumento. La parálisis tiene sentido: evita que representemos con el cuerpo lo que soñamos. Si se nos priva de REM, a la noche siguiente pasamos más tiempo en esta fase, lo que se conoce como **rebote de REM**.", "evidencia": ["evita que representemos con el cuerpo lo que soñamos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('7e48d0fd-df50-5d44-942d-79598c03b533', 'f11-con-8', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '80f4d8fe-20dc-5e55-8ee1-c42ff6ec1aac', '9bc593f1-4779-5066-b305-e0c44b44fcf6', 'verdadero_falso_razonado', 'El sueño profundo predomina al final de la noche.', null, '{"razones": ["Verdadero, porque estamos más cansados al amanecer.", "Falso, porque el sueño profundo solo aparece en la siesta.", "Falso, porque el sueño profundo predomina en los primeros ciclos y el REM se alarga hacia la mañana."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('7e48d0fd-df50-5d44-942d-79598c03b533', '{"valor": false, "razon": 2}'::jsonb, 'Al inicio de la noche domina N3; al final, el REM.', '{"leccion": "fases-del-sueno", "bloque": "b7", "titulo": "Por qué dormimos y las fases del sueño", "fragmento": "Las fases se suceden en **ciclos de unos 90 minutos**, que se repiten cuatro o cinco veces por noche. En los primeros ciclos predomina el sueño profundo N3; hacia la mañana, los periodos REM se alargan. Por eso, si nos despertamos al final de la noche, es fácil que recordemos un sueño.", "evidencia": ["En los primeros ciclos predomina el sueño profundo N3"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('0c9a4a15-0461-58ad-9f95-141bb95f8573', 'f11-con-9', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '80f4d8fe-20dc-5e55-8ee1-c42ff6ec1aac', '7c37f95b-5f52-5b65-a164-593a4431c062', 'caso_clinico', '¿Qué trastorno es más probable?', 'Javier, de 52 años, ronca muy fuerte. Su pareja nota que deja de respirar durante unos segundos varias veces por noche. Él dice que duerme ocho horas pero se queda dormido en las reuniones.', '{"opciones": ["Terrores nocturnos", "Apnea obstructiva del sueño", "Narcolepsia", "Sonambulismo"]}'::jsonb, null, 2, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('0c9a4a15-0461-58ad-9f95-141bb95f8573', '{"correcta": [1]}'::jsonb, 'Ronquidos, pausas respiratorias y somnolencia diurna sugieren apnea obstructiva.', '{"leccion": "trastornos-del-sueno", "bloque": "b5", "titulo": "Trastornos del sueño e higiene del sueño", "fragmento": "En la **apnea del sueño** la respiración se interrumpe muchas veces durante la noche. En la forma **obstructiva**, la más común, la vía aérea se cierra; la persona ronca fuerte, se despierta brevemente sin darse cuenta y al día siguiente está muy somnolienta. Se asocia a obesidad y a problemas cardiovasculares. Se trata con un aparato llamado **CPAP**, una mascarilla que mantiene abierta la vía aérea con presión de aire.", "evidencia": ["la persona ronca fuerte, se despierta brevemente sin darse cuenta"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
