insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('b08addfb-155a-5030-9c83-6d54a65c6583', '{"pares": {"Insomnio": "Dificultad persistente para dormirse o mantener el sueño", "Sonambulismo": "Caminar o actuar durante el sueño profundo sin recordarlo", "Narcolepsia": "Ataques irresistibles de sueño durante el día"}}'::jsonb, 'Cada trastorno afecta a una parte distinta del sueño.', '{"leccion": "trastornos-del-sueno", "bloque": "b8", "titulo": "Trastornos del sueño e higiene del sueño", "fragmento": "Trastornos del sueño: Insomnio | Dificultad persistente para dormirse o mantener el sueño · Apnea obstructiva | La respiración se interrumpe repetidamente por cierre de la vía aérea · Sonambulismo | Caminar o actuar durante el sueño profundo sin recordarlo · Narcolepsia | Ataques irresistibles de sueño durante el día", "evidencia": ["Ataques irresistibles de sueño durante el día"]}'::jsonb)
