insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('cbe936fa-f70e-53f7-a14b-f3a8589690ca', '{"correcta": [2]}'::jsonb, 'Así la cama se asocia con dormir y no con estar despierto preocupado.', '{"leccion": "trastornos-del-sueno", "bloque": "b10", "titulo": "Trastornos del sueño e higiene del sueño", "fragmento": "Recomendaciones de higiene del sueño: Acostarse y levantarse a la misma hora, incluso el fin de semana.; Usar la cama solo para dormir; si no duermes en unos veinte minutos, levántate y vuelve cuando tengas sueño.; Evitar cafeína por la tarde, alcohol y comidas copiosas antes de dormir.; Reducir la luz de las pantallas en la última hora del día.; Hacer ejercicio con regularidad, pero no justo antes de acostarse.; Mantener el dormitorio oscuro, silencioso y fresco.", "evidencia": ["si no duermes en unos veinte minutos, levántate y vuelve cuando tengas sueño"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
