values ('326a481d-fbbe-570b-a242-79244265ae5e', 'f11-con-13', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '80f4d8fe-20dc-5e55-8ee1-c42ff6ec1aac', '8ed87bf3-548f-5a64-9e2c-1c12284a0050', 'relacionar', 'Relaciona cada grupo de sustancias con un ejemplo.', null, '{"izquierda": ["Alucinógenas", "Depresoras", "Estimulantes", "Opioides"], "derecha": ["Alcohol", "Cafeína", "LSD", "Morfina"]}'::jsonb, null, 1, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
