insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('326a481d-fbbe-570b-a242-79244265ae5e', '{"pares": {"Depresoras": "Alcohol", "Estimulantes": "Cafeína", "Opioides": "Morfina", "Alucinógenas": "LSD"}}'::jsonb, 'Las sustancias se agrupan por su efecto principal sobre el sistema nervioso.', '{"leccion": "sustancias-y-otros-estados", "bloque": "b5", "titulo": "Sustancias psicoactivas, hipnosis y meditación", "fragmento": "Clasificación por su efecto principal: Depresoras | Alcohol, benzodiacepinas, barbitúricos | Frenan el sistema nervioso; muchas potencian el GABA · Estimulantes | Cafeína, nicotina, cocaína, anfetaminas | Aumentan la activación; muchas elevan la dopamina · Opioides | Morfina, heroína, fentanilo | Alivian el dolor y producen euforia; actúan como las endorfinas · Alucinógenas | LSD, psilocibina, cannabis en dosis altas | Alteran la percepción y el pensamiento", "evidencia": ["Alcohol, benzodiacepinas, barbitúricos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('1e4737fc-546d-57c3-a82d-3d789ef6f3cf', 'f11-con-14', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '80f4d8fe-20dc-5e55-8ee1-c42ff6ec1aac', '8ed87bf3-548f-5a64-9e2c-1c12284a0050', 'seleccion_multiple', '¿Por qué es peligroso combinar alcohol y benzodiacepinas?', null, '{"opciones": ["Porque sus efectos depresores se suman y pueden frenar la respiración", "Porque se anulan entre sí", "Porque ambas son estimulantes", "Porque producen alucinaciones"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('1e4737fc-546d-57c3-a82d-3d789ef6f3cf', '{"correcta": [0]}'::jsonb, 'Los depresores combinados potencian su efecto sobre funciones vitales.', '{"leccion": "sustancias-y-otros-estados", "bloque": "b6", "titulo": "Sustancias psicoactivas, hipnosis y meditación", "fragmento": "El **alcohol** es la sustancia depresora más consumida. En pequeñas cantidades desinhibe, pero empeora el juicio, la coordinación y la memoria. Combinar depresores, por ejemplo alcohol y benzodiacepinas, es especialmente peligroso porque sus efectos se suman y pueden frenar la respiración.", "evidencia": ["sus efectos se suman y pueden frenar la respiración"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('6d3dac4a-d73e-5e26-b834-5f49e913316e', 'f11-con-15', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '80f4d8fe-20dc-5e55-8ee1-c42ff6ec1aac', '8ed87bf3-548f-5a64-9e2c-1c12284a0050', 'verdadero_falso_razonado', 'La hipnosis es una forma fiable de recuperar recuerdos olvidados.', null, '{"razones": ["Verdadero, porque desbloquea el inconsciente.", "Falso, porque nadie puede ser hipnotizado.", "Falso, porque aumenta los recuerdos falsos."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('6d3dac4a-d73e-5e26-b834-5f49e913316e', '{"valor": false, "razon": 2}'::jsonb, 'La hipnosis puede aliviar el dolor, pero no sirve para recuperar recuerdos de forma fiable.', '{"leccion": "sustancias-y-otros-estados", "bloque": "b10", "titulo": "Sustancias psicoactivas, hipnosis y meditación", "fragmento": "La **hipnosis** es un estado de atención muy concentrada y mayor **sugestionabilidad**, en el que la persona responde con más facilidad a las sugerencias de otra. No es dormir ni perder el control: nadie hace bajo hipnosis algo que vaya contra sus valores. Hay dos explicaciones principales. La **teoría de la disociación** propone que la conciencia se divide en dos partes; la **teoría sociocognitiva** sostiene que la persona adopta el papel que espera de alguien hipnotizado. Se usa con cierto éxito para aliviar el dolor, pero no para recuperar recuerdos, porque aumenta los recuerdos falsos.", "evidencia": ["no para recuperar recuerdos, porque aumenta los recuerdos falsos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('61c6ee16-e7d1-544c-8c17-ab5a5a978551', 'f11-con-16', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '80f4d8fe-20dc-5e55-8ee1-c42ff6ec1aac', '8ed87bf3-548f-5a64-9e2c-1c12284a0050', 'respuesta_breve', '¿Cómo se llama el conjunto de síntomas que aparece al dejar de consumir una sustancia de la que se depende?', null, '{}'::jsonb, null, 1, array['fase11','respuesta_breve']::text[], 'Material integrado del tema', 'publicada')
