insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('61c6ee16-e7d1-544c-8c17-ab5a5a978551', '{"aceptadas": ["síndrome de abstinencia", "abstinencia", "el síndrome de abstinencia"], "solucion": "síndrome de abstinencia"}'::jsonb, 'Sus síntomas suelen ser opuestos al efecto de la sustancia.', '{"leccion": "sustancias-y-otros-estados", "bloque": "b2", "titulo": "Sustancias psicoactivas, hipnosis y meditación", "fragmento": "Las **sustancias psicoactivas** son las que cambian la conciencia, el ánimo o la percepción porque actúan sobre los neurotransmisores. Algunas son legales, como la cafeína, el alcohol o el tabaco; otras son fármacos con receta y otras están prohibidas. Con el uso repetido aparece la **tolerancia**: hace falta más cantidad para obtener el mismo efecto. Si se deja de consumir, surge el **síndrome de abstinencia**, con síntomas desagradables, a menudo opuestos al efecto de la sustancia.", "evidencia": ["surge el síndrome de abstinencia"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('e53827e1-e69e-5889-9dd0-6eb284642dda', 'f11-sen-1', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'b1ee3556-0c8b-501a-b6b6-2c0d18a71f91', '6eb206ae-f0aa-518f-856e-f467bc1b3160', 'seleccion_multiple', '¿Qué ejemplo corresponde a la percepción y no solo a la sensación?', null, '{"opciones": ["Que la luz llegue a la retina", "Reconocer la voz de un amigo", "Que el tímpano vibre", "Que un receptor convierta la presión en señal nerviosa"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('e53827e1-e69e-5889-9dd0-6eb284642dda', '{"correcta": [1]}'::jsonb, 'La percepción organiza e interpreta lo que captan los sentidos.', '{"leccion": "sentir-y-percibir", "bloque": "b2", "titulo": "Sentir no es lo mismo que percibir", "fragmento": "La **sensación** ocurre cuando un receptor sensorial detecta un estímulo, como la luz o una vibración, y lo convierte en una señal nerviosa. Esa conversión se llama **transducción**. La **percepción** es lo que el cerebro hace después: organizar, interpretar y dar significado a esas señales. Las ondas que llegan al oído son sensación; reconocer en ellas la voz de un amigo es percepción.", "evidencia": ["reconocer en ellas la voz de un amigo es percepción"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('4fc3dfb9-b66a-5e26-a511-62d1bec64527', 'f11-sen-2', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'b1ee3556-0c8b-501a-b6b6-2c0d18a71f91', '6eb206ae-f0aa-518f-856e-f467bc1b3160', 'caso_clinico', '¿Qué explica lo que le ocurre?', 'Lucía entra en una panadería y nota un fuerte olor a pan. A los diez minutos, mientras espera su turno, ya no lo percibe.', '{"opciones": ["La adaptación sensorial", "La disparidad binocular", "La ceguera por falta de atención", "El umbral absoluto"]}'::jsonb, null, 1, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('4fc3dfb9-b66a-5e26-a511-62d1bec64527', '{"correcta": [0]}'::jsonb, 'Ante un estímulo constante, los receptores dejan de responder.', '{"leccion": "sentir-y-percibir", "bloque": "b6", "titulo": "Sentir no es lo mismo que percibir", "fragmento": "Cuando un estímulo no cambia, los receptores dejan de responder. Es la **adaptación sensorial**: al poco de ponernos un reloj ya no lo notamos, y al entrar en una casa dejamos de percibir su olor en unos minutos. Así el sistema se centra en lo que cambia, que suele ser lo importante.", "evidencia": ["Cuando un estímulo no cambia, los receptores dejan de responder"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('f508cc19-ae1d-50f2-9977-9a432fefae01', 'f11-sen-3', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'b1ee3556-0c8b-501a-b6b6-2c0d18a71f91', '6eb206ae-f0aa-518f-856e-f467bc1b3160', 'verdadero_falso_razonado', 'La publicidad subliminal cambia de forma clara lo que la gente compra.', null, '{"razones": ["Falso, porque solo puede influir levemente y durante poco tiempo.", "Verdadero, porque actúa sobre el inconsciente sin defensa posible.", "Falso, porque los mensajes subliminales no existen."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('f508cc19-ae1d-50f2-9977-9a432fefae01', '{"valor": false, "razon": 0}'::jsonb, 'No hay pruebas de efectos importantes y duraderos de la publicidad subliminal.', '{"leccion": "sentir-y-percibir", "bloque": "b4", "titulo": "Sentir no es lo mismo que percibir", "fragmento": "Los mensajes **subliminales** están por debajo del umbral de conciencia. Pueden influir levemente y durante poco tiempo, por ejemplo si ya tenemos sed, pero no hay pruebas de que la publicidad subliminal cambie de verdad lo que compramos o votamos.", "evidencia": ["no hay pruebas de que la publicidad subliminal cambie de verdad lo que compramos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('1a2d3da1-6ba7-5e69-bacc-fb058815497a', 'f11-sen-4', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'b1ee3556-0c8b-501a-b6b6-2c0d18a71f91', '6eb206ae-f0aa-518f-856e-f467bc1b3160', 'relacionar', 'Relaciona cada concepto con su ejemplo.', null, '{"izquierda": ["Ceguera por falta de atención", "Efecto cóctel", "Procesamiento de arriba abajo"], "derecha": ["Leer bien una palabra con letras desordenadas", "No ver al gorila mientras se cuentan pases", "Oír tu nombre en una fiesta ruidosa"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('1a2d3da1-6ba7-5e69-bacc-fb058815497a', '{"pares": {"Ceguera por falta de atención": "No ver al gorila mientras se cuentan pases", "Efecto cóctel": "Oír tu nombre en una fiesta ruidosa", "Procesamiento de arriba abajo": "Leer bien una palabra con letras desordenadas"}}'::jsonb, 'La atención y el conocimiento previo moldean lo que percibimos.', '{"leccion": "sentir-y-percibir", "bloque": "b7", "titulo": "Sentir no es lo mismo que percibir", "fragmento": "La percepción también depende de la **atención**. En un estudio famoso, se pidió a la gente que contara pases de baloncesto en un vídeo; la mitad no vio a una persona disfrazada de gorila que cruzaba la escena. Esto se llama **ceguera por falta de atención**. En sentido contrario, el **efecto cóctel** muestra que oímos nuestro nombre en una fiesta ruidosa aunque no estuviéramos atentos a esa conversación. Dos formas de procesar: De abajo arriba | Se construye la percepción a partir de los datos sensoriales | Ver líneas y curvas y reconocer una letra · De arriba abajo | El conocimiento y las expectativas guían la interpretación | Leer bien una palabra con letras desordenadas", "evidencia": ["Leer bien una palabra con letras desordenadas"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('ac7591b4-0dd9-55c3-af75-de1b278519e3', 'f11-sen-5', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'b1ee3556-0c8b-501a-b6b6-2c0d18a71f91', 'bea6eea3-50ec-5f15-8200-48cd2bd489b0', 'relacionar', 'Relaciona cada parte del ojo con su función.', null, '{"izquierda": ["Cristalino", "Fóvea", "Iris", "Nervio óptico"], "derecha": ["Concentra los conos y da la visión más nítida", "Enfoca la luz sobre la retina", "Lleva las señales fuera del ojo", "Regula el tamaño de la pupila"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('ac7591b4-0dd9-55c3-af75-de1b278519e3', '{"pares": {"Iris": "Regula el tamaño de la pupila", "Cristalino": "Enfoca la luz sobre la retina", "Fóvea": "Concentra los conos y da la visión más nítida", "Nervio óptico": "Lleva las señales fuera del ojo"}}'::jsonb, 'Cada parte cumple una función en el camino de la luz hasta el cerebro.', '{"leccion": "la-vision", "bloque": "b4", "titulo": "La visión", "fragmento": "La luz entra por la **córnea**, atraviesa la **pupila**, cuyo tamaño regula el **iris**, y el **cristalino** la enfoca sobre la **retina**, al fondo del ojo. En la retina están los **fotorreceptores**. En el centro, la **fóvea** concentra los conos y nos da la visión más nítida. Las señales salen del ojo por el **nervio óptico**. Donde este nace no hay receptores, así que cada ojo tiene un **punto ciego**, aunque el cerebro rellena el hueco y no lo notamos.", "evidencia": ["el cristalino la enfoca sobre la retina"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('13c9fccf-60d0-53a6-be8c-875109cb65d1', 'f11-sen-6', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'b1ee3556-0c8b-501a-b6b6-2c0d18a71f91', 'bea6eea3-50ec-5f15-8200-48cd2bd489b0', 'seleccion_multiple', '¿Por qué de noche vemos peor los colores?', null, '{"opciones": ["Porque la pupila se cierra", "Porque con poca luz funcionan sobre todo los bastones, que no captan el color", "Porque los conos funcionan mejor con poca luz", "Porque el punto ciego se agranda"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('13c9fccf-60d0-53a6-be8c-875109cb65d1', '{"correcta": [1]}'::jsonb, 'Los bastones permiten ver con poca luz pero no distinguen colores.', '{"leccion": "la-vision", "bloque": "b5", "titulo": "La visión", "fragmento": "Conos y bastones: Conos | En la fóvea, en el centro de la retina | Color, detalle y visión con buena luz · Bastones | En la periferia de la retina | Visión con poca luz y del movimiento, sin color", "evidencia": ["Visión con poca luz y del movimiento, sin color"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('8b35d73f-7bb2-5e33-be9a-78e3632a9e44', 'f11-sen-7', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'b1ee3556-0c8b-501a-b6b6-2c0d18a71f91', 'bea6eea3-50ec-5f15-8200-48cd2bd489b0', 'respuesta_breve', 'Según la teoría ___, hay tres tipos de conos sensibles al azul, al verde y al rojo.', null, '{"completar": true}'::jsonb, null, 1, array['fase11','completar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('8b35d73f-7bb2-5e33-be9a-78e3632a9e44', '{"aceptadas": ["tricromática", "tricromatica"], "solucion": "tricromática"}'::jsonb, 'La teoría tricromática explica la visión del color a nivel de los conos.', '{"leccion": "la-vision", "bloque": "b8", "titulo": "La visión", "fragmento": "Dos teorías explican la visión del color y ambas son correctas en distintos niveles. Según la **teoría tricromática**, hay tres tipos de conos, sensibles al azul, al verde y al rojo, y todos los colores salen de su combinación. Según la **teoría de los procesos oponentes**, el color se procesa en pares opuestos: rojo y verde, azul y amarillo, blanco y negro. Esta segunda teoría explica las **posimágenes**: si miras fijamente una bandera verde y luego una superficie blanca, la ves roja. Las personas con daltonismo carecen de algún tipo de cono o este funciona mal.", "evidencia": ["Según la teoría tricromática, hay tres tipos de conos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('2b7d3a95-addc-58c8-9b97-1191cfacdfe0', 'f11-sen-8', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'b1ee3556-0c8b-501a-b6b6-2c0d18a71f91', 'bea6eea3-50ec-5f15-8200-48cd2bd489b0', 'seleccion_multiple', '¿Qué clave de profundidad hace que los bordes de una carretera parezcan juntarse a lo lejos?', null, '{"opciones": ["La superposición", "La disparidad binocular", "El tamaño relativo", "La perspectiva lineal"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('2b7d3a95-addc-58c8-9b97-1191cfacdfe0', '{"correcta": [3]}'::jsonb, 'En la perspectiva lineal, las líneas paralelas convergen a lo lejos.', '{"leccion": "la-vision", "bloque": "b9", "titulo": "La visión", "fragmento": "Aunque la retina es plana, vemos en tres dimensiones gracias a varias claves. Las **claves binoculares** necesitan los dos ojos: la **disparidad binocular** es la pequeña diferencia entre la imagen de cada ojo, y el cerebro la usa para calcular la distancia. Las **claves monoculares** funcionan con un solo ojo y las usan los pintores: por ejemplo, la **perspectiva lineal**, en la que las líneas paralelas, como los bordes de una carretera, parecen juntarse a lo lejos.", "evidencia": ["las líneas paralelas, como los bordes de una carretera, parecen juntarse a lo lejos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('e254a58f-b47e-57cb-901e-b00889a809c2', 'f11-sen-9', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'b1ee3556-0c8b-501a-b6b6-2c0d18a71f91', '132a894f-b206-5505-a83f-18eb5b10e2e6', 'ordenar', 'Ordena el recorrido del sonido hasta el cerebro.', null, '{"elementos": ["El líquido de la cóclea se mueve y dobla las células ciliadas.", "El nervio auditivo lleva la señal al lóbulo temporal.", "El pabellón recoge las ondas sonoras.", "El tímpano vibra.", "Martillo, yunque y estribo amplifican la vibración."]}'::jsonb, null, 1, array['fase11','ordenar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('e254a58f-b47e-57cb-901e-b00889a809c2', '{"orden": ["El pabellón recoge las ondas sonoras.", "El tímpano vibra.", "Martillo, yunque y estribo amplifican la vibración.", "El líquido de la cóclea se mueve y dobla las células ciliadas.", "El nervio auditivo lleva la señal al lóbulo temporal."]}'::jsonb, 'La vibración pasa del aire al tímpano, a los huesecillos, a la cóclea y al nervio.', '{"leccion": "la-audicion", "bloque": "b5", "titulo": "La audición", "fragmento": "Del aire al cerebro: El pabellón recoge las ondas sonoras.; El tímpano vibra.; Martillo, yunque y estribo amplifican la vibración.; El líquido de la cóclea se mueve y dobla las células ciliadas.; El nervio auditivo lleva la señal al lóbulo temporal.", "evidencia": ["El tímpano vibra"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('ff42f7a7-225c-5cf2-ae93-4cac0eb17ea5', 'f11-sen-10', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'b1ee3556-0c8b-501a-b6b6-2c0d18a71f91', '132a894f-b206-5505-a83f-18eb5b10e2e6', 'seleccion_multiple', '¿Qué característica del sonido percibimos como tono?', null, '{"opciones": ["La duración", "La amplitud", "El decibelio", "La frecuencia"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('ff42f7a7-225c-5cf2-ae93-4cac0eb17ea5', '{"correcta": [3]}'::jsonb, 'La frecuencia se percibe como tono y la amplitud, como volumen.', '{"leccion": "la-audicion", "bloque": "b2", "titulo": "La audición", "fragmento": "El sonido son ondas de presión que viajan por el aire. Su **amplitud** se percibe como **volumen** y se mide en **decibelios**: una conversación normal ronda los 60, y un concierto de rock puede superar los 110. Su **frecuencia** se percibe como **tono** y se mide en hercios: cuantas más vibraciones por segundo, más agudo. Los humanos oímos aproximadamente entre 20 y 20.000 hercios.", "evidencia": ["Su frecuencia se percibe como tono"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('06467d0a-ef1b-5358-8ab9-97c35cf8b08c', 'f11-sen-11', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'b1ee3556-0c8b-501a-b6b6-2c0d18a71f91', '132a894f-b206-5505-a83f-18eb5b10e2e6', 'caso_clinico', '¿Qué tipo de pérdida auditiva tiene?', 'Pedro, de 30 años, ha trabajado años con maquinaria ruidosa sin protección. Ahora oye mal y el otorrino le dice que sus células ciliadas están dañadas.', '{"opciones": ["Por cerumen", "Neurosensorial", "De conducción", "Temporal y reversible"]}'::jsonb, null, 2, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('06467d0a-ef1b-5358-8ab9-97c35cf8b08c', '{"correcta": [1]}'::jsonb, 'El daño de las células ciliadas produce una pérdida neurosensorial.', '{"leccion": "la-audicion", "bloque": "b9", "titulo": "La audición", "fragmento": "Tipos de pérdida auditiva: De conducción | El tímpano o los huesecillos no transmiten bien la vibración | Cirugía o audífonos · Neurosensorial | Las células ciliadas o el nervio auditivo están dañados | Audífonos o implante coclear", "evidencia": ["Las células ciliadas o el nervio auditivo están dañados"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('765cbc5c-8989-5465-862c-9864a73530f5', 'f11-sen-12', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'b1ee3556-0c8b-501a-b6b6-2c0d18a71f91', '132a894f-b206-5505-a83f-18eb5b10e2e6', 'respuesta_breve', '¿A partir de cuántos decibelios la exposición prolongada puede dañar el oído?', null, '{}'::jsonb, null, 1, array['fase11','respuesta_breve']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('765cbc5c-8989-5465-862c-9864a73530f5', '{"aceptadas": ["85", "85 decibelios", "más de 85"], "solucion": "85"}'::jsonb, 'Por encima de unos 85 decibelios, la exposición continuada destruye células ciliadas.', '{"leccion": "la-audicion", "bloque": "b10", "titulo": "La audición", "fragmento": "Cuida tus oídos. La exposición prolongada a sonidos de más de 85 decibelios, como auriculares a todo volumen, conciertos o maquinaria, puede destruir células ciliadas que no se regeneran. Baja el volumen y usa protección en entornos ruidosos.", "evidencia": ["sonidos de más de 85 decibelios"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('64a0f867-2541-58e5-89a1-68b0e666b119', 'f11-sen-13', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'b1ee3556-0c8b-501a-b6b6-2c0d18a71f91', '2faa14f4-0d3a-5c56-9c82-4093039a2907', 'verdadero_falso_razonado', 'Gran parte de lo que llamamos sabor depende en realidad del olfato.', null, '{"razones": ["Falso, porque el sabor depende solo de la lengua.", "Verdadero, porque la lengua no tiene receptores.", "Verdadero, porque con la nariz tapada una manzana y una cebolla cruda saben parecido."]}'::jsonb, null, 1, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('64a0f867-2541-58e5-89a1-68b0e666b119', '{"valor": true, "razon": 2}'::jsonb, 'El olfato aporta gran parte de la experiencia del sabor.', '{"leccion": "otros-sentidos-y-gestalt", "bloque": "b2", "titulo": "Los demás sentidos y la Gestalt", "fragmento": "El gusto y el olfato son **sentidos químicos**. En la lengua hay miles de **papilas gustativas** con receptores para cinco sabores básicos: **dulce, salado, ácido, amargo y umami**, el sabor sabroso del caldo o del queso curado. Pero gran parte de lo que llamamos sabor es en realidad olor: con la nariz tapada, una manzana y una cebolla cruda saben parecido. Los **receptores olfativos**, en la parte alta de la cavidad nasal, envían sus señales al bulbo olfativo, muy conectado con la emoción y la memoria. Por eso un olor puede traernos de golpe un recuerdo de la infancia.", "evidencia": ["gran parte de lo que llamamos sabor es en realidad olor"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('dfa17486-6eb1-5e72-903e-eccb972a9db5', 'f11-sen-14', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'b1ee3556-0c8b-501a-b6b6-2c0d18a71f91', '2faa14f4-0d3a-5c56-9c82-4093039a2907', 'relacionar', 'Relaciona cada principio de la Gestalt con lo que hacemos.', null, '{"izquierda": ["Cierre", "Continuidad", "Proximidad", "Semejanza"], "derecha": ["Agrupar los elementos que están cerca", "Agrupar los elementos que se parecen en color, forma o tamaño", "Completar figuras incompletas", "Ver líneas continuas en lugar de fragmentos"]}'::jsonb, null, 1, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('dfa17486-6eb1-5e72-903e-eccb972a9db5', '{"pares": {"Proximidad": "Agrupar los elementos que están cerca", "Semejanza": "Agrupar los elementos que se parecen en color, forma o tamaño", "Cierre": "Completar figuras incompletas", "Continuidad": "Ver líneas continuas en lugar de fragmentos"}}'::jsonb, 'El cerebro agrupa los estímulos siguiendo estas reglas.', '{"leccion": "otros-sentidos-y-gestalt", "bloque": "b9", "titulo": "Los demás sentidos y la Gestalt", "fragmento": "Principios de agrupación: Proximidad | Agrupar los elementos que están cerca · Semejanza | Agrupar los elementos que se parecen en color, forma o tamaño · Continuidad | Ver líneas continuas en lugar de fragmentos · Cierre | Completar figuras incompletas · Figura y fondo | Separar lo que destaca del resto", "evidencia": ["Agrupar los elementos que están cerca"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('ff7a3952-8c89-52e2-91e3-d6d24e4bb302', 'f11-sen-15', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'b1ee3556-0c8b-501a-b6b6-2c0d18a71f91', '2faa14f4-0d3a-5c56-9c82-4093039a2907', 'seleccion_multiple', '¿Qué sistema nos permite mantener el equilibrio?', null, '{"opciones": ["El sistema vestibular del oído interno", "La cóclea", "Los nociceptores", "El bulbo olfativo"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('ff7a3952-8c89-52e2-91e3-d6d24e4bb302', '{"correcta": [0]}'::jsonb, 'Los canales semicirculares detectan la posición y el movimiento de la cabeza.', '{"leccion": "otros-sentidos-y-gestalt", "bloque": "b6", "titulo": "Los demás sentidos y la Gestalt", "fragmento": "Dos sentidos nos informan de nuestro cuerpo. El **sistema vestibular**, formado por los canales semicirculares del oído interno, detecta la posición y los movimientos de la cabeza y mantiene el equilibrio. La **propiocepción** nos dice dónde están las partes del cuerpo sin mirarlas, gracias a receptores en músculos y articulaciones.", "evidencia": ["detecta la posición y los movimientos de la cabeza y mantiene el equilibrio"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('14e2da55-f050-5666-839e-060109f92270', 'f11-sen-16', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'b1ee3556-0c8b-501a-b6b6-2c0d18a71f91', '2faa14f4-0d3a-5c56-9c82-4093039a2907', 'seleccion_multiple', '¿Qué demuestra que la ilusión de Müller Lyer sea más fuerte en culturas con edificios de esquinas rectas?', null, '{"opciones": ["Que la ilusión es innata e igual en todos", "Que la experiencia moldea cómo percibimos", "Que las ilusiones dependen solo de la retina", "Que esas personas ven peor"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('14e2da55-f050-5666-839e-060109f92270', '{"correcta": [1]}'::jsonb, 'El ambiente en que crecemos influye en la percepción.', '{"leccion": "otros-sentidos-y-gestalt", "bloque": "b10", "titulo": "Los demás sentidos y la Gestalt", "fragmento": "Las **ilusiones visuales** muestran cómo funciona la percepción. En la ilusión de **Müller Lyer**, dos líneas iguales parecen de distinta longitud según hacia dónde apunten las flechas de sus extremos. Curiosamente, esta ilusión es más fuerte en personas de culturas acostumbradas a edificios con esquinas rectas, lo que demuestra que la experiencia moldea cómo vemos.", "evidencia": ["lo que demuestra que la experiencia moldea cómo vemos"]}'::jsonb)
