insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('cefc5ffb-88f8-50af-991d-53f3ee61a364', 'f11-apr-1', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '7d9a1386-83c9-5e1f-b35e-8b643d8d2f20', 'ac2de915-c149-5c2c-b8e5-9f8b3debff9c', 'relacionar', 'Relaciona cada conducta con su tipo.', null, '{"izquierda": ["La migración de las aves", "Retirar la mano del fuego", "Saber que una comida concreta sienta mal"], "derecha": ["Aprendizaje", "Instinto", "Reflejo"]}'::jsonb, null, 1, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
