insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('cefc5ffb-88f8-50af-991d-53f3ee61a364', '{"pares": {"Retirar la mano del fuego": "Reflejo", "La migración de las aves": "Instinto", "Saber que una comida concreta sienta mal": "Aprendizaje"}}'::jsonb, 'Reflejos e instintos son innatos; el aprendizaje depende de la experiencia.', '{"leccion": "que-es-aprender", "bloque": "b4", "titulo": "Qué es aprender", "fragmento": "Innato y aprendido: Reflejo | Innato, respuesta simple y automática | Retirar la mano del fuego · Instinto | Innato, conducta compleja de toda la especie | La migración de las aves · Aprendizaje | Experiencia | Saber que una comida concreta sienta mal", "evidencia": ["Retirar la mano del fuego"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('ac64291c-dfdd-54d0-a9ee-306720c6aeaa', 'f11-apr-2', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '7d9a1386-83c9-5e1f-b35e-8b643d8d2f20', 'ac2de915-c149-5c2c-b8e5-9f8b3debff9c', 'seleccion_multiple', '¿Qué define el aprendizaje?', null, '{"opciones": ["Una conducta innata de toda la especie", "Un cambio relativamente duradero debido a la experiencia", "Una respuesta automática a un estímulo", "Cualquier cambio de conducta, aunque se deba al cansancio"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('ac64291c-dfdd-54d0-a9ee-306720c6aeaa', '{"correcta": [1]}'::jsonb, 'El aprendizaje depende de la experiencia y es duradero.', '{"leccion": "que-es-aprender", "bloque": "b3", "titulo": "Qué es aprender", "fragmento": "El **aprendizaje**, en cambio, es un cambio relativamente duradero en la conducta o en el conocimiento que se debe a la experiencia. Es lo que nos permite adaptarnos a un entorno que cambia: aprender qué alimentos sientan mal, a qué personas acercarnos o cómo se usa un móvil nuevo. Ni los reflejos ni los instintos requieren experiencia; el aprendizaje sí.", "evidencia": ["un cambio relativamente duradero en la conducta o en el conocimiento que se debe a la experiencia"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('f5509602-6dd3-540f-8889-10c4151360ff', 'f11-apr-3', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '7d9a1386-83c9-5e1f-b35e-8b643d8d2f20', 'ac2de915-c149-5c2c-b8e5-9f8b3debff9c', 'respuesta_breve', 'En el condicionamiento ___ asociamos una conducta con su consecuencia.', null, '{"completar": true}'::jsonb, null, 1, array['fase11','completar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('f5509602-6dd3-540f-8889-10c4151360ff', '{"aceptadas": ["operante"], "solucion": "operante"}'::jsonb, 'El condicionamiento operante relaciona conductas con sus consecuencias.', '{"leccion": "que-es-aprender", "bloque": "b6", "titulo": "Qué es aprender", "fragmento": "Gran parte de lo que aprendemos es **aprendizaje asociativo**: conectamos cosas que ocurren juntas. En el **condicionamiento clásico** asociamos dos estímulos, como el sonido de la nevera al abrirse y la comida. En el **condicionamiento operante** asociamos una conducta con su consecuencia: si hacer algo trae un premio, tendemos a repetirlo. Además, no hace falta vivirlo todo en primera persona: en el **aprendizaje por observación** aprendemos mirando lo que hacen otros y lo que les ocurre.", "evidencia": ["En el condicionamiento operante asociamos una conducta con su consecuencia"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('a3474cf0-93d0-567d-9ee8-36aa231ad5fb', 'f11-apr-4', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '7d9a1386-83c9-5e1f-b35e-8b643d8d2f20', 'ac2de915-c149-5c2c-b8e5-9f8b3debff9c', 'verdadero_falso_razonado', 'En la vida real, cada conducta se aprende por un solo tipo de aprendizaje.', null, '{"razones": ["Falso, porque nada se aprende: todo es innato.", "Falso, porque los tres tipos de aprendizaje suelen actuar a la vez.", "Verdadero, porque el cerebro solo usa un mecanismo cada vez."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('a3474cf0-93d0-567d-9ee8-36aa231ad5fb', '{"valor": false, "razon": 1}'::jsonb, 'El ejemplo del perro y la golosina combina condicionamiento clásico y operante.', '{"leccion": "que-es-aprender", "bloque": "b8", "titulo": "Qué es aprender", "fragmento": "Pensemos en un perro que se sienta y espera con atención cuando su dueño saca una golosina. Ha aprendido que el gesto de la mano anuncia comida (condicionamiento clásico) y que sentarse le consigue el premio (condicionamiento operante). En la vida real, los tres tipos de aprendizaje suelen actuar a la vez.", "evidencia": ["los tres tipos de aprendizaje suelen actuar a la vez"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('acd6acd0-0ad8-59b5-a67b-a7e383ad5725', 'f11-apr-5', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '7d9a1386-83c9-5e1f-b35e-8b643d8d2f20', 'eedc346d-da46-542a-92a7-7a13c4f2dff7', 'relacionar', 'Relaciona cada elemento con el experimento de Pávlov.', null, '{"izquierda": ["Estímulo condicionado (EC)", "Estímulo incondicionado (EI)", "Estímulo neutro", "Respuesta condicionada (RC)"], "derecha": ["El timbre antes del aprendizaje", "El timbre después del aprendizaje", "La comida", "Salivar al oír el timbre"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
