insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('acd6acd0-0ad8-59b5-a67b-a7e383ad5725', '{"pares": {"Estímulo incondicionado (EI)": "La comida", "Estímulo neutro": "El timbre antes del aprendizaje", "Estímulo condicionado (EC)": "El timbre después del aprendizaje", "Respuesta condicionada (RC)": "Salivar al oír el timbre"}}'::jsonb, 'El timbre pasa de neutro a condicionado tras emparejarse con la comida.', '{"leccion": "condicionamiento-clasico", "bloque": "b4", "titulo": "El condicionamiento clásico", "fragmento": "Los elementos del condicionamiento clásico: Estímulo incondicionado (EI) | La comida · Respuesta incondicionada (RI) | Salivar ante la comida · Estímulo neutro | El timbre antes del aprendizaje · Estímulo condicionado (EC) | El timbre después del aprendizaje · Respuesta condicionada (RC) | Salivar al oír el timbre", "evidencia": ["El timbre después del aprendizaje"]}'::jsonb)
