insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('dac82ba1-cf88-5e34-bcf3-8ff561febbf8', 'f11-apr-6', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '7d9a1386-83c9-5e1f-b35e-8b643d8d2f20', 'eedc346d-da46-542a-92a7-7a13c4f2dff7', 'caso_clinico', '¿Qué proceso explica que tema también a los perros pequeños?', 'Tras una mala experiencia con un perro grande, Ana siente miedo ante cualquier perro, incluso los pequeños.', '{"opciones": ["La extinción", "La discriminación", "La generalización", "El refuerzo positivo"]}'::jsonb, null, 2, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('dac82ba1-cf88-5e34-bcf3-8ff561febbf8', '{"correcta": [2]}'::jsonb, 'En la generalización, estímulos parecidos al condicionado provocan la misma respuesta.', '{"leccion": "condicionamiento-clasico", "bloque": "b6", "titulo": "El condicionamiento clásico", "fragmento": "Cinco procesos clave: Adquisición: el periodo en que se forma la asociación entre el estímulo neutro y el incondicionado.; Extinción: si el EC se presenta muchas veces sin el EI, la respuesta condicionada se debilita.; Recuperación espontánea: tras una pausa, una respuesta extinguida reaparece brevemente.; Generalización: estímulos parecidos al EC también provocan la respuesta.; Discriminación: el organismo aprende a responder solo al EC y no a estímulos parecidos.", "evidencia": ["estímulos parecidos al EC también provocan la respuesta"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('a59c0522-4f76-5b3d-8045-72347e87ff27', 'f11-apr-7', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '7d9a1386-83c9-5e1f-b35e-8b643d8d2f20', 'eedc346d-da46-542a-92a7-7a13c4f2dff7', 'seleccion_multiple', '¿Qué técnica terapéutica usa la extinción para reducir una fobia?', null, '{"opciones": ["La exposición repetida a lo que se teme sin que ocurra nada malo", "El refuerzo de la evitación", "La hipnosis", "El castigo cada vez que aparece el miedo"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('a59c0522-4f76-5b3d-8045-72347e87ff27', '{"correcta": [0]}'::jsonb, 'Si el estímulo temido aparece sin consecuencias negativas, el miedo condicionado se extingue.', '{"leccion": "condicionamiento-clasico", "bloque": "b11", "titulo": "El condicionamiento clásico", "fragmento": "El condicionamiento clásico está por todas partes. La **publicidad** asocia productos con personas atractivas, música agradable o momentos felices para que el producto despierte esas mismas emociones. Y en terapia se usa al revés: la **exposición** repetida a lo que se teme, sin que ocurra nada malo, extingue poco a poco el miedo condicionado.", "evidencia": ["la exposición repetida a lo que se teme, sin que ocurra nada malo"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('39868fa8-e238-5b87-a28e-f1f98df65782', 'f11-apr-8', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '7d9a1386-83c9-5e1f-b35e-8b643d8d2f20', 'eedc346d-da46-542a-92a7-7a13c4f2dff7', 'ordenar', 'Ordena lo que ocurrió en el experimento del pequeño Albert.', null, '{"elementos": ["Albert empezó a llorar al ver la rata", "Albert temía también otros objetos peludos", "Albert tocaba la rata blanca sin miedo", "Se hacía un ruido fuerte cada vez que la tocaba"]}'::jsonb, null, 2, array['fase11','ordenar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('39868fa8-e238-5b87-a28e-f1f98df65782', '{"orden": ["Albert tocaba la rata blanca sin miedo", "Se hacía un ruido fuerte cada vez que la tocaba", "Albert empezó a llorar al ver la rata", "Albert temía también otros objetos peludos"]}'::jsonb, 'Se condicionó el miedo y después se generalizó a estímulos parecidos.', '{"leccion": "condicionamiento-clasico", "bloque": "b10", "titulo": "El condicionamiento clásico", "fragmento": "En 1920, **John B. Watson** y Rosalie Rayner condicionaron miedo a un bebé de once meses, conocido como el pequeño Albert. Cada vez que el niño tocaba una rata blanca, hacían un ruido fuerte detrás de él. Pronto Albert lloraba al ver la rata e incluso ante otros objetos peludos, un ejemplo de generalización. Este experimento sería hoy inaceptable por razones éticas, pero mostró que las **fobias** pueden aprenderse.", "evidencia": ["Pronto Albert lloraba al ver la rata"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('b987da5c-99ec-51f1-9166-27a273aba9bb', 'f11-apr-9', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '7d9a1386-83c9-5e1f-b35e-8b643d8d2f20', '0286c7d5-03c6-58ba-a436-9338f28ab3c0', 'relacionar', 'Relaciona cada consecuencia con su ejemplo.', null, '{"izquierda": ["Castigo negativo", "Castigo positivo", "Refuerzo negativo", "Refuerzo positivo"], "derecha": ["El pitido del coche cesa al ponerte el cinturón", "Elogiar a un niño cuando recoge sus juguetes", "Quitar el móvil tras una pelea", "Una multa por aparcar mal"]}'::jsonb, null, 3, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
