insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('b987da5c-99ec-51f1-9166-27a273aba9bb', '{"pares": {"Refuerzo positivo": "Elogiar a un niño cuando recoge sus juguetes", "Refuerzo negativo": "El pitido del coche cesa al ponerte el cinturón", "Castigo positivo": "Una multa por aparcar mal", "Castigo negativo": "Quitar el móvil tras una pelea"}}'::jsonb, 'Positivo es añadir, negativo es retirar; el refuerzo aumenta la conducta y el castigo la disminuye.', '{"leccion": "condicionamiento-operante", "bloque": "b5", "titulo": "El condicionamiento operante", "fragmento": "Refuerzo y castigo: Refuerzo positivo | Añadir algo agradable | Aumenta | Elogiar a un niño cuando recoge sus juguetes · Refuerzo negativo | Retirar algo desagradable | Aumenta | El pitido del coche cesa al ponerte el cinturón · Castigo positivo | Añadir algo desagradable | Disminuye | Una multa por aparcar mal · Castigo negativo | Retirar algo agradable | Disminuye | Quitar el móvil tras una pelea", "evidencia": ["El pitido del coche cesa al ponerte el cinturón"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('78bc2f03-ee09-51eb-92d6-bd38be7a068d', 'f11-apr-10', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '7d9a1386-83c9-5e1f-b35e-8b643d8d2f20', '0286c7d5-03c6-58ba-a436-9338f28ab3c0', 'verdadero_falso_razonado', 'El refuerzo negativo es un tipo de castigo.', null, '{"razones": ["Falso, porque el refuerzo negativo no existe.", "Falso, porque el refuerzo siempre aumenta la conducta; negativo solo significa retirar algo.", "Verdadero, porque negativo significa malo."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('78bc2f03-ee09-51eb-92d6-bd38be7a068d', '{"valor": false, "razon": 1}'::jsonb, 'Es la confusión más común: refuerzo aumenta y castigo disminuye.', '{"leccion": "condicionamiento-operante", "bloque": "b6", "titulo": "El condicionamiento operante", "fragmento": "La confusión más común es pensar que refuerzo negativo significa castigo. No es así: **positivo** y **negativo** no indican bueno o malo, sino **añadir** o **retirar**. Y **refuerzo** siempre aumenta la conducta, mientras que **castigo** siempre la disminuye. Los expertos desaconsejan el castigo físico: enseña qué no hacer pero no qué hacer, genera miedo y agresividad y ofrece un modelo violento.", "evidencia": ["La confusión más común es pensar que refuerzo negativo significa castigo"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
