values ('9734a1ca-fa45-5272-85ea-10a0cceb229f', 'f11-apr-11', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '7d9a1386-83c9-5e1f-b35e-8b643d8d2f20', '0286c7d5-03c6-58ba-a436-9338f28ab3c0', 'seleccion_multiple', '¿Qué programa de refuerzo produce más respuestas y más resistencia a la extinción?', null, '{"opciones": ["Ningún refuerzo", "Refuerzo continuo", "Razón variable", "Intervalo fijo"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
