insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('9734a1ca-fa45-5272-85ea-10a0cceb229f', '{"correcta": [2]}'::jsonb, 'Como el premio puede llegar en cualquier momento, cuesta dejar de responder.', '{"leccion": "condicionamiento-operante", "bloque": "b10", "titulo": "El condicionamiento operante", "fragmento": "El **refuerzo continuo**, premiar cada respuesta, sirve para aprender rápido, pero la conducta se extingue enseguida si el premio desaparece. El **refuerzo parcial** produce conductas más resistentes. El programa de **razón variable** es el más poderoso: como el premio puede llegar en cualquier momento, la persona responde muchas veces y le cuesta parar. Por eso las tragaperras y algunos videojuegos y redes sociales enganchan tanto.", "evidencia": ["El programa de razón variable es el más poderoso"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('214b8419-aeb4-50fc-be43-db2519812a42', 'f11-apr-12', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '7d9a1386-83c9-5e1f-b35e-8b643d8d2f20', '0286c7d5-03c6-58ba-a436-9338f28ab3c0', 'respuesta_breve', '¿Cómo llamó Tolman a la representación mental del laberinto que formaban sus ratas?', null, '{}'::jsonb, null, 2, array['fase11','respuesta_breve']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('214b8419-aeb4-50fc-be43-db2519812a42', '{"aceptadas": ["mapa cognitivo", "un mapa cognitivo", "mapas cognitivos"], "solucion": "mapa cognitivo"}'::jsonb, 'Las ratas aprendieron el laberinto sin refuerzo y lo mostraron cuando hubo comida.', '{"leccion": "condicionamiento-operante", "bloque": "b11", "titulo": "El condicionamiento operante", "fragmento": "No todo aprendizaje se ve enseguida. Edward Tolman dejó ratas explorar un laberinto sin premio; cuando después puso comida al final, llegaron casi tan rápido como las ratas entrenadas. Habían formado un **mapa cognitivo** del laberinto. Este **aprendizaje latente** muestra que aprendemos aunque no haya refuerzo, y que este influye sobre todo en si mostramos lo aprendido.", "evidencia": ["Habían formado un mapa cognitivo del laberinto"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('1bce6ff0-431d-5b79-9e15-66e329421c94', 'f11-apr-13', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '7d9a1386-83c9-5e1f-b35e-8b643d8d2f20', 'ea8b655e-574f-571b-b3a5-afb188397b8b', 'seleccion_multiple', '¿Qué demostró el experimento del muñeco Bobo?', null, '{"opciones": ["Que la agresividad es solo innata", "Que los niños nunca imitan a los adultos", "Que los niños imitan la agresividad que observan en un adulto", "Que el castigo físico reduce la agresividad"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('1bce6ff0-431d-5b79-9e15-66e329421c94', '{"correcta": [2]}'::jsonb, 'Los niños que vieron al adulto agresivo lo imitaron.', '{"leccion": "aprendizaje-por-observacion", "bloque": "b2", "titulo": "Aprender observando a otros", "fragmento": "En los años sesenta, **Albert Bandura** mostró a un grupo de niños un vídeo en el que un adulto golpeaba, pateaba y gritaba a un muñeco hinchable llamado Bobo. Otros niños vieron a un adulto jugar tranquilamente. Después, cada niño quedaba solo con el muñeco. Quienes habían visto al adulto agresivo lo imitaban, a veces con las mismas palabras. Bandura llamó a este proceso **aprendizaje por observación** o **modelado**.", "evidencia": ["Quienes habían visto al adulto agresivo lo imitaban"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('80c88c33-3bb9-528a-a56d-acd905d9c34c', 'f11-apr-14', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '7d9a1386-83c9-5e1f-b35e-8b643d8d2f20', 'ea8b655e-574f-571b-b3a5-afb188397b8b', 'ordenar', 'Ordena los procesos necesarios para aprender de un modelo.', null, '{"elementos": ["Atención: fijarse en lo que hace el modelo.", "Motivación: tener una razón para hacerlo.", "Reproducción: ser capaz de hacerlo uno mismo.", "Retención: recordar lo que se ha observado."]}'::jsonb, null, 1, array['fase11','ordenar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('80c88c33-3bb9-528a-a56d-acd905d9c34c', '{"orden": ["Atención: fijarse en lo que hace el modelo.", "Retención: recordar lo que se ha observado.", "Reproducción: ser capaz de hacerlo uno mismo.", "Motivación: tener una razón para hacerlo."]}'::jsonb, 'Hay que atender, recordar, poder reproducir y querer hacerlo.', '{"leccion": "aprendizaje-por-observacion", "bloque": "b5", "titulo": "Aprender observando a otros", "fragmento": "Lo que hace falta para aprender de un modelo: Atención: fijarse en lo que hace el modelo.; Retención: recordar lo que se ha observado.; Reproducción: ser capaz de hacerlo uno mismo.; Motivación: tener una razón para hacerlo.", "evidencia": ["Retención: recordar lo que se ha observado"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('5e9515ef-fe04-5ecc-afa8-b4f0e1e7b3aa', 'f11-apr-15', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '7d9a1386-83c9-5e1f-b35e-8b643d8d2f20', 'ea8b655e-574f-571b-b3a5-afb188397b8b', 'caso_clinico', 'Según el aprendizaje por observación, ¿qué es más probable?', 'Unos padres piden a su hijo que no use el móvil en la mesa, pero ellos lo consultan constantemente durante las comidas.', '{"opciones": ["Que el niño imite lo que hacen sus padres más que lo que dicen", "Que el niño obedezca porque se lo han dicho", "Que la conducta de los padres no influya", "Que el niño deje de usar el móvil para siempre"]}'::jsonb, null, 2, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('5e9515ef-fe04-5ecc-afa8-b4f0e1e7b3aa', '{"correcta": [0]}'::jsonb, 'Los niños aprenden de lo que ven hacer; por eso se recomienda hacer lo que se pide.', '{"leccion": "aprendizaje-por-observacion", "bloque": "b8", "titulo": "Aprender observando a otros", "fragmento": "El modelado tiene **efectos prosociales**: los niños que ven a sus padres ayudar a otros, leer o resolver conflictos hablando tienden a hacer lo mismo. Por eso a los padres se les recomienda hacer lo que piden y no solo decirlo. También tiene **efectos antisociales**: los hijos que presencian violencia en casa tienen más riesgo de repetirla en sus relaciones. La investigación sobre la violencia en los medios sugiere que la exposición repetida se asocia a más pensamientos y conductas agresivas, aunque el efecto es moderado y depende de muchos factores.", "evidencia": ["a los padres se les recomienda hacer lo que piden y no solo decirlo"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('31006226-9754-5169-a9fb-8b2523ba2986', 'f11-apr-16', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '7d9a1386-83c9-5e1f-b35e-8b643d8d2f20', 'ea8b655e-574f-571b-b3a5-afb188397b8b', 'verdadero_falso_razonado', 'Si un niño ve castigar a un modelo, no aprende su conducta.', null, '{"razones": ["Verdadero, porque el castigo borra lo observado.", "Falso, porque el castigo vicario no existe.", "Falso, porque la aprende aunque no la muestre, y la reproduce si se le ofrece un premio."]}'::jsonb, null, 3, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('31006226-9754-5169-a9fb-8b2523ba2986', '{"valor": false, "razon": 2}'::jsonb, 'Aprender y mostrar lo aprendido son cosas distintas.', '{"leccion": "aprendizaje-por-observacion", "bloque": "b3", "titulo": "Aprender observando a otros", "fragmento": "En variantes del experimento, si el adulto recibía un premio por su conducta, los niños lo imitaban más; si era castigado, menos. Esto es el **refuerzo vicario** y el **castigo vicario**: aprendemos de las consecuencias que ven otros. Pero incluso los niños que vieron al adulto castigado eran capaces de reproducir la agresión si se les ofrecía un premio. Habían aprendido la conducta aunque no la mostraran.", "evidencia": ["Habían aprendido la conducta aunque no la mostraran"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('d55c668f-ad56-5db5-a3af-b472940c66e8', 'f11-pen-1', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '493d207d-d989-55b4-85b1-5b2b6f9a310c', '9570562c-271d-5547-8165-614b747fea44', 'seleccion_multiple', '¿Por qué tardamos más en decidir si un pingüino es un pájaro que si lo es un gorrión?', null, '{"opciones": ["Porque los conceptos artificiales son más lentos", "Porque el gorrión se parece más a nuestro prototipo de pájaro", "Porque el pingüino no es un pájaro", "Porque no tenemos esquemas sobre animales"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('d55c668f-ad56-5db5-a3af-b472940c66e8', '{"correcta": [1]}'::jsonb, 'Clasificamos más rápido lo que se parece al ejemplo típico del concepto.', '{"leccion": "conceptos-y-esquemas", "bloque": "b5", "titulo": "Cognición, conceptos y esquemas", "fragmento": "Para cada concepto solemos tener un **prototipo**, el ejemplo más típico. Si pensamos en un pájaro, a la mayoría nos viene a la mente algo parecido a un gorrión, no un pingüino ni un avestruz. Por eso tardamos más en decidir si un pingüino es un pájaro que si lo es un gorrión. Los prototipos cambian con la cultura y la experiencia de cada persona.", "evidencia": ["tardamos más en decidir si un pingüino es un pájaro"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
