values ('652bdac0-673e-55a6-abb0-40fa618b151b', 'f11-pen-2', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '493d207d-d989-55b4-85b1-5b2b6f9a310c', '9570562c-271d-5547-8165-614b747fea44', 'relacionar', 'Relaciona cada herramienta mental con su ejemplo.', null, '{"izquierda": ["Concepto", "Esquema de evento", "Esquema de rol", "Prototipo"], "derecha": ["Cómo comportarse en un ascensor", "Fruta", "Qué hace un médico", "Un gorrión como pájaro típico"]}'::jsonb, null, 1, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
