insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('652bdac0-673e-55a6-abb0-40fa618b151b', '{"pares": {"Concepto": "Fruta", "Prototipo": "Un gorrión como pájaro típico", "Esquema de rol": "Qué hace un médico", "Esquema de evento": "Cómo comportarse en un ascensor"}}'::jsonb, 'Son distintas formas de organizar el conocimiento.', '{"leccion": "conceptos-y-esquemas", "bloque": "b8", "titulo": "Cognición, conceptos y esquemas", "fragmento": "Herramientas para organizar el conocimiento: Concepto | Categoría de cosas parecidas | Fruta · Prototipo | El ejemplo más típico de un concepto | Un gorrión como pájaro típico · Esquema de rol | Lo que esperamos de alguien según su papel | Qué hace un médico · Esquema de evento | Secuencia habitual de acciones | Cómo comportarse en un ascensor", "evidencia": ["Cómo comportarse en un ascensor"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('9ca82b21-3a0e-50ed-8801-1a4c321c6dfa', 'f11-pen-3', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '493d207d-d989-55b4-85b1-5b2b6f9a310c', '9570562c-271d-5547-8165-614b747fea44', 'seleccion_multiple', '¿Qué es un concepto artificial?', null, '{"opciones": ["Uno que no existe en la realidad", "Uno definido por un conjunto preciso de rasgos, como el cuadrado", "Uno que cambia según la cultura", "Uno aprendido solo por la experiencia"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('9ca82b21-3a0e-50ed-8801-1a4c321c6dfa', '{"correcta": [1]}'::jsonb, 'Los conceptos artificiales tienen una definición exacta.', '{"leccion": "conceptos-y-esquemas", "bloque": "b4", "titulo": "Cognición, conceptos y esquemas", "fragmento": "Un **concepto** es una categoría que agrupa objetos, ideas, personas o situaciones parecidas, como silla, fruta o justicia. Algunos son **concretos**, como perro, y otros **abstractos**, como libertad. Los **conceptos artificiales** se definen por un conjunto preciso de rasgos: un cuadrado es una figura de cuatro lados iguales y cuatro ángulos rectos. Los **conceptos naturales** se forman con la experiencia y tienen límites más borrosos: aprendemos qué es la nieve viéndola, tocándola y oyendo a otros hablar de ella.", "evidencia": ["Los conceptos artificiales se definen por un conjunto preciso de rasgos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('ed60a8e5-523d-5499-9d9f-61287b4e8c5b', 'f11-pen-4', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '493d207d-d989-55b4-85b1-5b2b6f9a310c', '9570562c-271d-5547-8165-614b747fea44', 'verdadero_falso_razonado', 'Los esquemas siempre nos ayudan a interpretar bien la realidad.', null, '{"razones": ["Falso, porque los esquemas no influyen en la conducta.", "Falso, porque si no se ajustan a la situación pueden llevar a malinterpretar lo que ocurre.", "Verdadero, porque son fruto de la experiencia."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('ed60a8e5-523d-5499-9d9f-61287b4e8c5b', '{"valor": false, "razon": 1}'::jsonb, 'Ahorran esfuerzo, pero pueden llevar a errores y estereotipos.', '{"leccion": "conceptos-y-esquemas", "bloque": "b9", "titulo": "Cognición, conceptos y esquemas", "fragmento": "Los esquemas nos ahorran esfuerzo, pero pueden jugarnos malas pasadas. Conducir por la ruta de siempre en piloto automático y saltarse un desvío es un ejemplo. Más grave: si un esquema no se ajusta a la situación, podemos interpretar mal lo que ocurre o no detectar un peligro. Muchos **estereotipos** son esquemas sobre grupos de personas que no se corresponden con la realidad de cada individuo.", "evidencia": ["si un esquema no se ajusta a la situación, podemos interpretar mal lo que ocurre"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('7253ae49-094b-5328-b966-cdf734fe7860', 'f11-pen-5', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '493d207d-d989-55b4-85b1-5b2b6f9a310c', '8b7c94a0-777f-5879-afa1-cce9ef5f6230', 'ordenar', 'Ordena las etapas del desarrollo del lenguaje.', null, '{"elementos": ["Balbuceo de sílabas", "Frases completas", "Frases de dos palabras", "Primeras palabras", "Sonidos reflejos como el llanto"]}'::jsonb, null, 1, array['fase11','ordenar']::text[], 'Material integrado del tema', 'publicada')
