insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('7253ae49-094b-5328-b966-cdf734fe7860', '{"orden": ["Sonidos reflejos como el llanto", "Balbuceo de sílabas", "Primeras palabras", "Frases de dos palabras", "Frases completas"]}'::jsonb, 'El lenguaje avanza del llanto al balbuceo, las palabras y las frases.', '{"leccion": "el-lenguaje", "bloque": "b5", "titulo": "El lenguaje", "fragmento": "Etapas del desarrollo del lenguaje: De 0 a 3 meses: sonidos reflejos como el llanto.; De 4 a 6 meses: balbuceo de sílabas.; De 10 a 12 meses: primeras palabras.; De 12 a 18 meses: frases de una palabra.; De 18 a 24 meses: frases de dos palabras.; Desde los 2 años: frases completas y vocabulario en rápida expansión.", "evidencia": ["De 4 a 6 meses: balbuceo de sílabas"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('1d5870bf-f78f-5d39-84ff-3bf023233dc1', 'f11-pen-6', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '493d207d-d989-55b4-85b1-5b2b6f9a310c', '8b7c94a0-777f-5879-afa1-cce9ef5f6230', 'seleccion_multiple', '¿Qué muestra que un niño diga «yo sabo»?', null, '{"opciones": ["Que ha oído esa palabra a los adultos", "Que tiene un trastorno del lenguaje", "Que el lenguaje se aprende solo por refuerzo", "Que aplica reglas gramaticales y no solo imita"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('1d5870bf-f78f-5d39-84ff-3bf023233dc1', '{"correcta": [3]}'::jsonb, 'El error revela que el niño generaliza una regla de conjugación.', '{"leccion": "el-lenguaje", "bloque": "b6", "titulo": "El lenguaje", "fragmento": "Para **Noam Chomsky**, los niños nacen con una capacidad innata para el lenguaje, una especie de **dispositivo de adquisición del lenguaje**. Lo apoya que todos los niños del mundo aprenden a hablar a edades parecidas y que cometen errores reveladores, como decir «yo sabo» en lugar de «yo sé», que muestran que aplican reglas y no solo imitan. Skinner, en cambio, pensaba que el lenguaje se aprende por refuerzo. Hoy se acepta que ambas cosas importan: hay una base biológica y hace falta exposición al lenguaje.", "evidencia": ["muestran que aplican reglas y no solo imitan"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('cf261f94-746c-5a42-a7bd-e062d061d80f', 'f11-pen-7', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '493d207d-d989-55b4-85b1-5b2b6f9a310c', '8b7c94a0-777f-5879-afa1-cce9ef5f6230', 'respuesta_breve', 'En la palabra «gatos» hay dos ___: «gato» y «s».', null, '{"completar": true}'::jsonb, null, 1, array['fase11','completar']::text[], 'Material integrado del tema', 'publicada')
