insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('cf261f94-746c-5a42-a7bd-e062d061d80f', '{"aceptadas": ["morfemas"], "solucion": "morfemas"}'::jsonb, 'El morfema es la unidad mínima con significado.', '{"leccion": "el-lenguaje", "bloque": "b2", "titulo": "El lenguaje", "fragmento": "El **lenguaje** es un sistema de comunicación que usa palabras y reglas para transmitir información. Tiene un **léxico**, el conjunto de palabras, y una **gramática**, las reglas para combinarlas. El **fonema** es la unidad mínima de sonido que distingue palabras, como la diferencia entre pala y bala. El **morfema** es la unidad mínima con significado: en la palabra «gatos», «gato» y «s» son dos morfemas. La **semántica** se ocupa del significado y la **sintaxis**, del orden de las palabras.", "evidencia": ["«gato» y «s» son dos morfemas"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('cce508ed-7c7a-5f62-aa51-a8a9dfea90b3', 'f11-pen-8', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '493d207d-d989-55b4-85b1-5b2b6f9a310c', '8b7c94a0-777f-5879-afa1-cce9ef5f6230', 'verdadero_falso_razonado', 'Según la evidencia actual, el idioma determina por completo lo que podemos pensar.', null, '{"razones": ["Falso, porque la versión fuerte se rechaza; el lenguaje solo influye en lo que notamos y recordamos.", "Verdadero, porque sin palabras no hay pensamiento.", "Falso, porque el lenguaje no influye nada."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('cce508ed-7c7a-5f62-aa51-a8a9dfea90b3', '{"valor": false, "razon": 0}'::jsonb, 'Hoy se acepta una influencia moderada del lenguaje sobre el pensamiento.', '{"leccion": "el-lenguaje", "bloque": "b9", "titulo": "El lenguaje", "fragmento": "¿El idioma que hablamos cambia cómo pensamos? La **hipótesis de Sapir y Whorf** propone que sí. En su versión fuerte, que hoy se rechaza, el lenguaje determinaría el pensamiento. En una versión moderada, el lenguaje influye en lo que notamos y recordamos: por ejemplo, los hablantes de idiomas con más palabras para los tonos de azul distinguen esos tonos un poco más rápido. Pero también pensamos sin palabras, como hacen los bebés o al imaginar una imagen.", "evidencia": ["En su versión fuerte, que hoy se rechaza"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('d49a52c3-f733-59c1-8441-e9195648f875', 'f11-pen-9', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '493d207d-d989-55b4-85b1-5b2b6f9a310c', '45fc10c7-350e-58e2-8bea-a7c0b0102b5a', 'relacionar', 'Relaciona cada sesgo con su ejemplo.', null, '{"izquierda": ["Anclaje", "Confirmación", "Disponibilidad", "Retrospectivo"], "derecha": ["Decir «ya sabía que iba a pasar»", "Leer solo noticias que dan la razón a nuestra opinión", "Temer más volar que ir en coche tras ver un accidente aéreo", "Una rebaja nos parece enorme porque vemos primero el precio inflado"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
