insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('d49a52c3-f733-59c1-8441-e9195648f875', '{"pares": {"Anclaje": "Una rebaja nos parece enorme porque vemos primero el precio inflado", "Confirmación": "Leer solo noticias que dan la razón a nuestra opinión", "Retrospectivo": "Decir «ya sabía que iba a pasar»", "Disponibilidad": "Temer más volar que ir en coche tras ver un accidente aéreo"}}'::jsonb, 'Los sesgos son errores sistemáticos que todos cometemos.', '{"leccion": "resolver-problemas", "bloque": "b7", "titulo": "Resolver problemas y los sesgos del pensamiento", "fragmento": "Algunos sesgos frecuentes: Anclaje | Fijarse demasiado en el primer dato que recibimos | Una rebaja nos parece enorme porque vemos primero el precio inflado · Confirmación | Buscar solo lo que confirma lo que ya creemos | Leer solo noticias que dan la razón a nuestra opinión · Retrospectivo | Creer después que lo ocurrido era previsible | Decir «ya sabía que iba a pasar» · Representatividad | Juzgar por el parecido con un prototipo | Suponer que alguien tímido y ordenado es bibliotecario · Disponibilidad | Juzgar la frecuencia por lo fácil que nos viene un ejemplo | Temer más volar que ir en coche tras ver un accidente aéreo", "evidencia": ["Decir «ya sabía que iba a pasar»"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('4c21d641-1339-5bbf-95c7-a6b30dcc695f', 'f11-pen-10', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '493d207d-d989-55b4-85b1-5b2b6f9a310c', '45fc10c7-350e-58e2-8bea-a7c0b0102b5a', 'caso_clinico', '¿Qué obstáculo le impide resolverlo?', 'En una prueba de ingenio, Raúl debe fijar una vela a la pared con una caja de chinchetas y unas cerillas. No se le ocurre usar la caja vacía como soporte porque la ve solo como recipiente.', '{"opciones": ["El sesgo de anclaje", "El sesgo retrospectivo", "La fijeza funcional", "La inteligencia cristalizada"]}'::jsonb, null, 1, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('4c21d641-1339-5bbf-95c7-a6b30dcc695f', '{"correcta": [2]}'::jsonb, 'La fijeza funcional impide ver usos nuevos de un objeto.', '{"leccion": "resolver-problemas", "bloque": "b5", "titulo": "Resolver problemas y los sesgos del pensamiento", "fragmento": "A veces lo que sabemos nos estorba. La **fijeza funcional** es la incapacidad de ver un objeto con un uso distinto del habitual. En el clásico problema de la vela de Duncker, hay que fijar una vela a la pared con una caja de chinchetas y unas cerillas. La solución es vaciar la caja, clavarla a la pared y usarla como soporte, pero mucha gente no lo ve porque piensa en la caja solo como recipiente. La **disposición mental** es seguir usando una estrategia que funcionó antes aunque ya no sirva.", "evidencia": ["mucha gente no lo ve porque piensa en la caja solo como recipiente"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
