insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('f9f1fb92-d3b5-58ae-825e-ef8355aaa340', '{"correcta": [2]}'::jsonb, 'El algoritmo sigue pasos que llevan siempre a la solución, aunque pueda ser lento.', '{"leccion": "resolver-problemas", "bloque": "b3", "titulo": "Resolver problemas y los sesgos del pensamiento", "fragmento": "Formas de resolver problemas: Ensayo y error | No requiere saber nada de antemano | Puede ser muy lento · Algoritmo | Garantiza la solución | Puede ser largo y no siempre existe · Heurístico | Rápido y práctico | Puede llevar a errores", "evidencia": ["Garantiza la solución"]}'::jsonb)
