insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('3b4300df-613a-5572-abd2-357db8792981', '{"correcta": [2]}'::jsonb, 'Buscar datos en contra compensa la tendencia a confirmar lo que ya creemos.', '{"leccion": "resolver-problemas", "bloque": "b9", "titulo": "Resolver problemas y los sesgos del pensamiento", "fragmento": "Cómo pensar mejor: Buscar a propósito información que contradiga lo que crees.; Preguntarte si conoces datos reales o solo un ejemplo llamativo.; Considerar más de una solución antes de elegir.; Cambiar de perspectiva o descansar cuando te atasques.", "evidencia": ["Buscar a propósito información que contradiga lo que crees"]}'::jsonb)
