values ('c33b57a4-d695-56fa-8407-4f217181c16a', 'f11-pen-13', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '493d207d-d989-55b4-85b1-5b2b6f9a310c', '6c48ca56-ccd0-5ee5-b220-6188386de5ff', 'relacionar', 'Relaciona cada autor con su propuesta.', null, '{"izquierda": ["Cattell", "Spearman", "Sternberg"], "derecha": ["Inteligencia fluida y cristalizada", "Teoría triárquica: analítica, creativa y práctica", "Un factor general (g) presente en todas las capacidades"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
