insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('c33b57a4-d695-56fa-8407-4f217181c16a', '{"pares": {"Spearman": "Un factor general (g) presente en todas las capacidades", "Cattell": "Inteligencia fluida y cristalizada", "Sternberg": "Teoría triárquica: analítica, creativa y práctica"}}'::jsonb, 'Son tres formas distintas de entender la inteligencia.', '{"leccion": "la-inteligencia", "bloque": "b3", "titulo": "La inteligencia: teorías, medida y origen", "fragmento": "Teorías de la inteligencia: Spearman | Un factor general (g) presente en todas las capacidades · Cattell | Inteligencia fluida y cristalizada · Sternberg | Teoría triárquica: analítica, creativa y práctica · Gardner | Inteligencias múltiples: lingüística, lógico matemática, musical, espacial, corporal, interpersonal, intrapersonal y naturalista · Salovey, Mayer y Goleman | Inteligencia emocional: reconocer y regular las emociones propias y ajenas", "evidencia": ["Inteligencia fluida y cristalizada"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('f4b03aff-aab4-5507-996b-9ee07d58b4ef', 'f11-pen-14', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '493d207d-d989-55b4-85b1-5b2b6f9a310c', '6c48ca56-ccd0-5ee5-b220-6188386de5ff', 'respuesta_breve', '¿Cuál es el cociente intelectual medio de la población?', null, '{}'::jsonb, null, 1, array['fase11','respuesta_breve']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('f4b03aff-aab4-5507-996b-9ee07d58b4ef', '{"aceptadas": ["100", "cien"], "solucion": "100"}'::jsonb, 'Los tests se construyen para que la media sea 100 con desviación típica de 15.', '{"leccion": "la-inteligencia", "bloque": "b7", "titulo": "La inteligencia: teorías, medida y origen", "fragmento": "Las puntuaciones de inteligencia siguen una **distribución normal** o curva de campana: la mayoría de la gente se agrupa en el centro y pocas personas están en los extremos. El **cociente intelectual** medio es **100**, con una desviación típica de **15**: cerca del 68 por ciento de la población puntúa entre 85 y 115. Una puntuación por debajo de 70, junto con dificultades en la vida diaria que aparecen en la infancia, puede indicar **discapacidad intelectual**; por encima de 130 se habla de altas capacidades.", "evidencia": ["El cociente intelectual medio es 100"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('3b24c91b-eb4f-5262-8778-caa7d0de994c', 'f11-pen-15', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '493d207d-d989-55b4-85b1-5b2b6f9a310c', '6c48ca56-ccd0-5ee5-b220-6188386de5ff', 'seleccion_multiple', '¿Por qué el efecto Flynn sugiere que el ambiente influye en la inteligencia?', null, '{"opciones": ["Porque la inteligencia no se puede medir", "Porque los tests cambian cada año", "Porque los gemelos se parecen", "Porque las puntuaciones subieron demasiado rápido para deberse a los genes"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('3b24c91b-eb4f-5262-8778-caa7d0de994c', '{"correcta": [3]}'::jsonb, 'Un cambio en pocas generaciones apunta a mejoras en nutrición, escolarización y estimulación.', '{"leccion": "la-inteligencia", "bloque": "b9", "titulo": "La inteligencia: teorías, medida y origen", "fragmento": "Los estudios con gemelos y familias muestran que los genes influyen: los gemelos idénticos criados por separado se parecen más en inteligencia que los mellizos criados juntos. Pero el ambiente también pesa mucho. La nutrición, la estimulación en la infancia, la escolarización y el nivel socioeconómico influyen en las puntuaciones. El **efecto Flynn**, la subida de las puntuaciones medias generación tras generación durante el siglo XX, es demasiado rápido para deberse a los genes.", "evidencia": ["es demasiado rápido para deberse a los genes"]}'::jsonb)
