insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('e20d596c-dff3-5349-a900-db3c75e88374', 'f11-pen-16', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '493d207d-d989-55b4-85b1-5b2b6f9a310c', '6c48ca56-ccd0-5ee5-b220-6188386de5ff', 'verdadero_falso_razonado', 'Recordar un estereotipo negativo sobre el propio grupo antes de una prueba puede empeorar el rendimiento.', null, '{"razones": ["Falso, porque los tests son totalmente objetivos.", "Verdadero, es la amenaza del estereotipo.", "Verdadero, porque el estereotipo baja la inteligencia de forma permanente."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('e20d596c-dff3-5349-a900-db3c75e88374', '{"valor": true, "razon": 1}'::jsonb, 'La amenaza del estereotipo afecta al rendimiento en el momento, no a la capacidad.', '{"leccion": "la-inteligencia", "bloque": "b10", "titulo": "La inteligencia: teorías, medida y origen", "fragmento": "Los tests también tienen límites. Pueden contener **sesgo cultural** si sus preguntas favorecen a quien conoce una cultura concreta. Y la **amenaza del estereotipo** muestra que, cuando a alguien le recuerdan un estereotipo negativo sobre su grupo antes de una prueba, rinde peor. Una puntuación de cociente intelectual es útil, pero no resume todo el valor ni todas las capacidades de una persona.", "evidencia": ["la amenaza del estereotipo muestra que"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('2ba82f36-e18f-566d-a174-00af6f3fb2fd', 'f11-mem-1', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'f1986a53-6723-546e-9556-6e82798e5b54', 'c00926ed-3f61-5a18-8c2b-73da63e679f9', 'ordenar', 'Ordena los tres procesos de la memoria.', null, '{"elementos": ["Almacenamiento", "Codificación", "Recuperación"]}'::jsonb, null, 1, array['fase11','ordenar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('2ba82f36-e18f-566d-a174-00af6f3fb2fd', '{"orden": ["Codificación", "Almacenamiento", "Recuperación"]}'::jsonb, 'Primero se transforma la información, luego se guarda y después se recupera.', '{"leccion": "como-funciona-la-memoria", "bloque": "b2", "titulo": "Cómo funciona la memoria", "fragmento": "La **memoria** es un sistema que procesa información en tres pasos. La **codificación** es la entrada: transformar lo que percibimos en un formato que el cerebro pueda guardar. El **almacenamiento** es mantener esa información a lo largo del tiempo. La **recuperación** es sacarla de nuevo a la conciencia cuando la necesitamos. Un fallo en cualquiera de los tres produce olvido.", "evidencia": ["La codificación es la entrada"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('6103e19b-1816-5339-a328-964841c1dfb3', 'f11-mem-2', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'f1986a53-6723-546e-9556-6e82798e5b54', 'c00926ed-3f61-5a18-8c2b-73da63e679f9', 'seleccion_multiple', '¿Qué tipo de codificación deja recuerdos más duraderos?', null, '{"opciones": ["Todas por igual", "La acústica, centrada en el sonido", "La semántica, centrada en el significado", "La visual, centrada en la forma de las letras"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
