insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('6103e19b-1816-5339-a328-964841c1dfb3', '{"correcta": [2]}'::jsonb, 'Lo que tiene significado se recuerda mejor.', '{"leccion": "como-funciona-la-memoria", "bloque": "b3", "titulo": "Cómo funciona la memoria", "fragmento": "Parte de la codificación es **automática**: sin proponérnoslo, sabemos qué comimos ayer o por qué calle fuimos. Otra parte requiere **esfuerzo**, como aprender vocabulario nuevo. Codificamos mejor lo que tiene **significado**: la **codificación semántica**, centrada en el sentido de las palabras, deja recuerdos más duraderos que la visual o la acústica. Y recordamos mejor lo que relacionamos con nosotros mismos, el llamado **efecto de autorreferencia**.", "evidencia": ["deja recuerdos más duraderos que la visual o la acústica"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('a0ed93e8-b998-5fd3-97dd-6285c58f65e3', 'f11-mem-3', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'f1986a53-6723-546e-9556-6e82798e5b54', 'c00926ed-3f61-5a18-8c2b-73da63e679f9', 'relacionar', 'Relaciona cada tipo de memoria con su ejemplo.', null, '{"izquierda": ["Episódica", "Procedimental", "Semántica"], "derecha": ["Conducir sin pensar en cada movimiento", "Que Madrid es la capital de España", "Tu último cumpleaños"]}'::jsonb, null, 1, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('a0ed93e8-b998-5fd3-97dd-6285c58f65e3', '{"pares": {"Episódica": "Tu último cumpleaños", "Semántica": "Que Madrid es la capital de España", "Procedimental": "Conducir sin pensar en cada movimiento"}}'::jsonb, 'Episódica y semántica son explícitas; la procedimental es implícita.', '{"leccion": "como-funciona-la-memoria", "bloque": "b10", "titulo": "Cómo funciona la memoria", "fragmento": "La **memoria episódica** guarda vivencias situadas en un momento y lugar, como tu último cumpleaños. La **semántica** guarda conocimientos generales, como que Madrid es la capital de España. La **procedimental** guarda habilidades: puedes conducir sin pensar en cada movimiento. El **priming** ocurre cuando un estímulo previo facilita el reconocimiento de otro sin que nos demos cuenta.", "evidencia": ["como que Madrid es la capital de España"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('9889417e-e6ed-5b4a-875c-337db15d58c3', 'f11-mem-4', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'f1986a53-6723-546e-9556-6e82798e5b54', 'c00926ed-3f61-5a18-8c2b-73da63e679f9', 'respuesta_breve', 'Según Miller, la memoria a corto plazo retiene unos ___ elementos, más o menos dos.', null, '{"completar": true}'::jsonb, null, 1, array['fase11','completar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('9889417e-e6ed-5b4a-875c-337db15d58c3', '{"aceptadas": ["siete", "7"], "solucion": "siete"}'::jsonb, 'Por eso agrupamos los números de teléfono en bloques.', '{"leccion": "como-funciona-la-memoria", "bloque": "b7", "titulo": "Cómo funciona la memoria", "fragmento": "George Miller observó que la memoria a corto plazo retiene unos **siete elementos, más o menos dos**. Por eso es más fácil recordar un número de teléfono si lo agrupamos en bloques. Hoy se habla también de **memoria de trabajo**, para subrayar que no es solo un almacén, sino un espacio donde manipulamos la información, como al hacer una cuenta mental.", "evidencia": ["siete elementos, más o menos dos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('19c624d0-e0d8-5edd-851c-e7b03e84002c', 'f11-mem-5', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'f1986a53-6723-546e-9556-6e82798e5b54', '7340f73d-1a9e-5455-9c73-74e3eb8dde39', 'caso_clinico', '¿Qué conclusión es correcta?', 'Tras una operación en la que se le extirpó el hipocampo, un paciente no recuerda a las personas que conoce cada día, pero mejora con la práctica en una tarea de dibujo con espejo, aunque no recuerda haberla hecho.', '{"opciones": ["El paciente finge no recordar", "El hipocampo guarda las habilidades motoras", "No puede aprender nada nuevo", "La memoria explícita y la implícita dependen de sistemas distintos"]}'::jsonb, null, 2, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('19c624d0-e0d8-5edd-851c-e7b03e84002c', '{"correcta": [3]}'::jsonb, 'Es el caso de H. M.: perdió la memoria explícita nueva pero conservó el aprendizaje procedimental.', '{"leccion": "memoria-y-cerebro", "bloque": "b4", "titulo": "La memoria en el cerebro", "fragmento": "El papel del **hipocampo** se conoció gracias a un paciente, Henry Molaison, conocido como H. M. En 1953 se le extirpó parte de ambos lóbulos temporales, incluido el hipocampo, para tratar una epilepsia grave. Desde entonces no pudo formar recuerdos explícitos nuevos: olvidaba a las personas que acababa de conocer. Sin embargo, sí aprendía habilidades nuevas, como dibujar mirando en un espejo, aunque no recordara haber practicado. Su caso demostró que la memoria explícita y la implícita dependen de sistemas distintos.", "evidencia": ["la memoria explícita y la implícita dependen de sistemas distintos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('7853187b-94d6-5d49-86ae-606bb29c5292', 'f11-mem-6', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'f1986a53-6723-546e-9556-6e82798e5b54', '7340f73d-1a9e-5455-9c73-74e3eb8dde39', 'relacionar', 'Relaciona cada estructura con su papel en la memoria.', null, '{"izquierda": ["Amígdala", "Cerebelo", "Corteza prefrontal", "Hipocampo"], "derecha": ["Dar carga emocional a los recuerdos, sobre todo al miedo", "Formar recuerdos explícitos nuevos y consolidarlos", "Memoria de trabajo y recuerdo de información semántica", "Memoria procedimental y condicionamiento clásico"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
