insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('7853187b-94d6-5d49-86ae-606bb29c5292', '{"pares": {"Hipocampo": "Formar recuerdos explícitos nuevos y consolidarlos", "Amígdala": "Dar carga emocional a los recuerdos, sobre todo al miedo", "Cerebelo": "Memoria procedimental y condicionamiento clásico", "Corteza prefrontal": "Memoria de trabajo y recuerdo de información semántica"}}'::jsonb, 'La memoria está distribuida entre varias estructuras.', '{"leccion": "memoria-y-cerebro", "bloque": "b3", "titulo": "La memoria en el cerebro", "fragmento": "Estructuras y memoria: Hipocampo | Formar recuerdos explícitos nuevos y consolidarlos · Amígdala | Dar carga emocional a los recuerdos, sobre todo al miedo · Cerebelo | Memoria procedimental y condicionamiento clásico · Corteza prefrontal | Memoria de trabajo y recuerdo de información semántica", "evidencia": ["Memoria procedimental y condicionamiento clásico"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('844edb51-30eb-531f-bd7d-f73c4c5604f4', 'f11-mem-7', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'f1986a53-6723-546e-9556-6e82798e5b54', '7340f73d-1a9e-5455-9c73-74e3eb8dde39', 'verdadero_falso_razonado', 'Los recuerdos de destello son muy exactos porque se viven con emoción intensa.', null, '{"razones": ["Verdadero, porque la amígdala graba cada detalle sin errores.", "Falso, porque nadie recuerda dónde estaba en un suceso impactante.", "Falso, porque cambian mucho con el tiempo; lo que se mantiene es la seguridad."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('844edb51-30eb-531f-bd7d-f73c4c5604f4', '{"valor": false, "razon": 2}'::jsonb, 'Se sienten muy claros, pero los estudios muestran que se distorsionan.', '{"leccion": "memoria-y-cerebro", "bloque": "b8", "titulo": "La memoria en el cerebro", "fragmento": "Los **recuerdos de destello** son recuerdos muy vívidos de dónde estábamos y qué hacíamos cuando ocurrió un acontecimiento impactante, como los atentados del 11 de septiembre de 2001. Las personas tienen gran confianza en ellos. Sin embargo, los estudios que preguntaron a la misma gente al día siguiente y meses después muestran que cambian mucho con el tiempo. Lo que se mantiene es la **seguridad**, no la **exactitud**.", "evidencia": ["Lo que se mantiene es la seguridad, no la exactitud"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('79dd0782-635a-51b2-ac63-744558454768', 'f11-mem-8', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'f1986a53-6723-546e-9556-6e82798e5b54', '7340f73d-1a9e-5455-9c73-74e3eb8dde39', 'seleccion_multiple', '¿Qué concluyó Lashley de sus experimentos con ratas?', null, '{"opciones": ["Que las ratas no tienen memoria", "Que el cerebelo guarda todos los recuerdos", "Que la memoria está distribuida por el cerebro", "Que cada recuerdo está en una sola neurona"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('79dd0782-635a-51b2-ac63-744558454768', '{"correcta": [2]}'::jsonb, 'Las ratas recordaban el laberinto aunque lesionara distintas zonas.', '{"leccion": "memoria-y-cerebro", "bloque": "b2", "titulo": "La memoria en el cerebro", "fragmento": "Durante décadas se buscó el lugar exacto donde se guarda cada recuerdo, el llamado **engrama**. Karl Lashley lesionaba distintas zonas del cerebro de ratas que habían aprendido un laberinto y comprobaba que seguían recordándolo bastante bien. Concluyó que la memoria no está en un único punto, sino **distribuida** por el cerebro. Hoy sabemos que distintas estructuras se encargan de distintos aspectos.", "evidencia": ["Concluyó que la memoria no está en un único punto, sino distribuida"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('a1c5f08c-d2bd-5979-9add-2f2c1a2ecc98', 'f11-mem-9', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'f1986a53-6723-546e-9556-6e82798e5b54', 'b683c8d0-3cd7-5bc8-9189-95481af4bbc5', 'relacionar', 'Relaciona cada concepto con su ejemplo.', null, '{"izquierda": ["Fallo de codificación", "Interferencia proactiva", "Interferencia retroactiva"], "derecha": ["No recordar cómo es una moneda de un euro", "Seguir escribiendo tu antigua contraseña", "Tras aprender italiano te cuesta recordar el francés"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
