insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('a1c5f08c-d2bd-5979-9add-2f2c1a2ecc98', '{"pares": {"Interferencia proactiva": "Seguir escribiendo tu antigua contraseña", "Interferencia retroactiva": "Tras aprender italiano te cuesta recordar el francés", "Fallo de codificación": "No recordar cómo es una moneda de un euro"}}'::jsonb, 'La interferencia puede ir de lo viejo a lo nuevo o al revés.', '{"leccion": "olvido-y-recuerdos-falsos", "bloque": "b7", "titulo": "Olvido, amnesia y recuerdos falsos", "fragmento": "Mucho olvido se debe a la **interferencia** entre recuerdos. En la **interferencia proactiva**, lo antiguo dificulta recordar lo nuevo: sigues escribiendo tu antigua contraseña. En la **interferencia retroactiva**, lo nuevo dificulta recordar lo antiguo: tras aprender italiano te cuesta recordar el francés que estudiaste antes. Otras veces el fallo es de codificación: no recordamos cómo es exactamente una moneda de un euro porque nunca le prestamos atención.", "evidencia": ["sigues escribiendo tu antigua contraseña"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('03efa98e-bd6a-5f44-aa49-02744cb642c6', 'f11-mem-10', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'f1986a53-6723-546e-9556-6e82798e5b54', 'b683c8d0-3cd7-5bc8-9189-95481af4bbc5', 'caso_clinico', '¿Qué tipo de amnesia presenta?', 'Tras un accidente de moto con conmoción cerebral, Diego recuerda bien su vida, pero no lo ocurrido en los minutos anteriores al golpe.', '{"opciones": ["Infantil", "Anterógrada", "Retrógrada", "Procedimental"]}'::jsonb, null, 2, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
