insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('03efa98e-bd6a-5f44-aa49-02744cb642c6', '{"correcta": [2]}'::jsonb, 'Ha perdido recuerdos de antes del daño, que aún no estaban consolidados.', '{"leccion": "olvido-y-recuerdos-falsos", "bloque": "b3", "titulo": "Olvido, amnesia y recuerdos falsos", "fragmento": "La **amnesia** es la pérdida de memoria por daño cerebral, enfermedad o trauma. En la retrógrada, los recuerdos más cercanos al daño son los más vulnerables, porque todavía no estaban consolidados. Por eso tras una conmoción cerebral es habitual no recordar el accidente.", "evidencia": ["tras una conmoción cerebral es habitual no recordar el accidente"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('9d28fe1d-3e09-5d15-8727-f8d45904f8df', 'f11-mem-11', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'f1986a53-6723-546e-9556-6e82798e5b54', 'b683c8d0-3cd7-5bc8-9189-95481af4bbc5', 'seleccion_multiple', 'En el estudio de Loftus, ¿qué efecto tuvo preguntar si los coches «se estrellaron»?', null, '{"opciones": ["Se estimaron velocidades más altas y más personas recordaron cristales rotos que no existían", "Los participantes se negaron a responder", "La gente recordó mejor el accidente", "No cambió nada"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('9d28fe1d-3e09-5d15-8727-f8d45904f8df', '{"correcta": [0]}'::jsonb, 'La forma de preguntar alteró el recuerdo del suceso.', '{"leccion": "olvido-y-recuerdos-falsos", "bloque": "b9", "titulo": "Olvido, amnesia y recuerdos falsos", "fragmento": "La memoria **reconstruye** los hechos cada vez que los recordamos, y en esa reconstrucción puede colarse información nueva. **Elizabeth Loftus** mostró vídeos de accidentes de coche y luego preguntó a qué velocidad iban los coches cuando «se estrellaron» o cuando «se tocaron». Con el verbo más fuerte, la gente estimaba velocidades más altas y, una semana después, más personas recordaban haber visto cristales rotos que no existían. Es el **efecto de la información engañosa**.", "evidencia": ["más personas recordaban haber visto cristales rotos que no existían"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
