values ('1ade875d-91e3-5245-9e8f-9f3d306eae44', 'f11-mem-12', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'f1986a53-6723-546e-9556-6e82798e5b54', 'b683c8d0-3cd7-5bc8-9189-95481af4bbc5', 'seleccion_multiple', '¿Qué forma de medir el recuerdo usa un test de opción múltiple?', null, '{"opciones": ["Reaprendizaje", "Reconocimiento", "Priming", "Recuerdo libre"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
