insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('1ade875d-91e3-5245-9e8f-9f3d306eae44', '{"correcta": [1]}'::jsonb, 'Se trata de identificar la información correcta entre opciones.', '{"leccion": "olvido-y-recuerdos-falsos", "bloque": "b6", "titulo": "Olvido, amnesia y recuerdos falsos", "fragmento": "Tres formas de medir el recuerdo: Recuerdo libre: sacar la información sin pistas, como en una pregunta abierta.; Reconocimiento: identificar la información entre opciones, como en un test de opción múltiple.; Reaprendizaje: comprobar cuánto menos se tarda en volver a aprender algo.", "evidencia": ["identificar la información entre opciones"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('6636a893-cd30-5921-aed4-90488432a8d3', 'f11-mem-13', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'f1986a53-6723-546e-9556-6e82798e5b54', 'a8e84f81-fcb3-559d-9477-b912d3356e12', 'seleccion_multiple', '¿Qué estrategia de estudio es más eficaz a largo plazo?', null, '{"opciones": ["Estudiar todo de golpe la noche anterior", "Releer y subrayar el día antes", "Copiar el texto varias veces", "Repartir el estudio en varias sesiones y ponerse a prueba sin mirar"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('6636a893-cd30-5921-aed4-90488432a8d3', '{"correcta": [3]}'::jsonb, 'La práctica espaciada y la de recuperación son las mejor respaldadas.', '{"leccion": "mejorar-la-memoria", "bloque": "b5", "titulo": "Cómo recordar mejor", "fragmento": "Dos estrategias destacan por la evidencia que las apoya. La **práctica espaciada**: repartir el estudio en varias sesiones separadas por días es mucho más eficaz que concentrarlo todo la noche anterior. Y la **práctica de recuperación**: intentar recordar la información sin mirarla, con preguntas, tarjetas o explicándosela a alguien, fortalece el recuerdo más que releer. Releer da una falsa sensación de dominio porque el texto nos resulta familiar.", "evidencia": ["es mucho más eficaz que concentrarlo todo la noche anterior"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('223ddb06-78bb-5954-9268-dfff03519ed3', 'f11-mem-14', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'f1986a53-6723-546e-9556-6e82798e5b54', 'a8e84f81-fcb3-559d-9477-b912d3356e12', 'verdadero_falso_razonado', 'Releer muchas veces un texto es la mejor forma de aprenderlo.', null, '{"razones": ["Falso, porque da una falsa sensación de dominio; recordar sin mirar es más eficaz.", "Verdadero, porque cuanto más se lee más se graba.", "Falso, porque leer no sirve para nada."]}'::jsonb, null, 1, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
