insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('24370a7b-b77a-56cd-a81f-40086dd08f59', '{"aceptadas": ["método de los lugares", "metodo de los lugares", "el método de los lugares", "loci", "método loci"], "solucion": "método de los lugares"}'::jsonb, 'Aprovecha nuestra buena memoria espacial.', '{"leccion": "mejorar-la-memoria", "bloque": "b3", "titulo": "Cómo recordar mejor", "fragmento": "Agrupar la información en bloques con sentido, lo que se llama **agrupamiento**, amplía lo que podemos manejar. Y las **reglas mnemotécnicas** ayudan con listas difíciles: los **acrónimos**, que forman una palabra con las iniciales, o el **método de los lugares**, que consiste en imaginar cada elemento en un sitio de un recorrido que conoces bien, como tu casa.", "evidencia": ["el método de los lugares"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
