insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('b85ab748-1e6d-5097-8440-42ee482a77cd', '{"correcta": [2]}'::jsonb, 'El sueño ayuda a consolidar los recuerdos.', '{"leccion": "mejorar-la-memoria", "bloque": "b8", "titulo": "Cómo recordar mejor", "fragmento": "Hábitos que ayudan a la memoria: Dormir lo suficiente, sobre todo después de estudiar.; Evitar la multitarea: el móvil durante el estudio reduce lo que se codifica.; Hacer ejercicio físico con regularidad.; Estudiar en sesiones cortas con descansos.; Cambiar de lugar y de tipo de ejercicio de vez en cuando.", "evidencia": ["Dormir lo suficiente, sobre todo después de estudiar"]}'::jsonb)
