insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('05761ca5-d116-5f02-ac94-c2a09eeae785', 'f11-des-1', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'c32a2753-b62a-570e-885d-83656c2d46e3', '1109963a-a0e8-580a-bddc-66cf26a56f31', 'relacionar', 'Relaciona cada etapa de Piaget con su edad.', null, '{"izquierda": ["Operaciones concretas", "Operaciones formales", "Preoperacional", "Sensoriomotora"], "derecha": ["0 a 2 años", "2 a 7 años", "7 a 11 años", "Desde los 12 años"]}'::jsonb, null, 1, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
