insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('05761ca5-d116-5f02-ac94-c2a09eeae785', '{"pares": {"Sensoriomotora": "0 a 2 años", "Preoperacional": "2 a 7 años", "Operaciones concretas": "7 a 11 años", "Operaciones formales": "Desde los 12 años"}}'::jsonb, 'Las etapas siguen un orden fijo, aunque la edad es aproximada.', '{"leccion": "teorias-del-desarrollo", "bloque": "b10", "titulo": "Debates y teorías del desarrollo", "fragmento": "Las etapas de Piaget: Sensoriomotora | 0 a 2 años | Conoce el mundo con los sentidos y la acción; adquiere la permanencia del objeto · Preoperacional | 2 a 7 años | Usa símbolos y lenguaje; pensamiento egocéntrico; no domina la conservación · Operaciones concretas | 7 a 11 años | Razona con lógica sobre lo concreto; domina la conservación · Operaciones formales | Desde los 12 años | Piensa en abstracto e hipotético", "evidencia": ["Operaciones formales"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('93f8fb5c-2a1f-5e56-911a-260e6f6cf096', 'f11-des-2', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'c32a2753-b62a-570e-885d-83656c2d46e3', '1109963a-a0e8-580a-bddc-66cf26a56f31', 'seleccion_multiple', 'Un niño llama «perro» a una vaca. Según Piaget, ¿qué está haciendo?', null, '{"opciones": ["Acomodar su esquema", "Asimilar lo nuevo a un esquema que ya tiene", "Razonar en el nivel posconvencional", "Mostrar permanencia del objeto"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('93f8fb5c-2a1f-5e56-911a-260e6f6cf096', '{"correcta": [1]}'::jsonb, 'Encaja el animal nuevo en su esquema de perro; cuando lo corrija, acomodará.', '{"leccion": "teorias-del-desarrollo", "bloque": "b9", "titulo": "Debates y teorías del desarrollo", "fragmento": "**Jean Piaget** observó que los niños no son adultos en miniatura: piensan de forma distinta. Propuso que construyen su conocimiento mediante **esquemas** que amplían por **asimilación**, al encajar lo nuevo en lo que ya saben, y por **acomodación**, al cambiar sus esquemas cuando lo nuevo no encaja. Un niño que llama perro a una vaca está asimilando; cuando aprende que es otro animal, acomoda.", "evidencia": ["Un niño que llama perro a una vaca está asimilando"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('3feed955-08ab-5ec9-9060-b1adfb27f847', 'f11-des-3', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'c32a2753-b62a-570e-885d-83656c2d46e3', '1109963a-a0e8-580a-bddc-66cf26a56f31', 'ordenar', 'Ordena estos conflictos de Erikson según la edad en que aparecen.', null, '{"elementos": ["Autonomía frente a vergüenza y duda", "Confianza frente a desconfianza", "Generatividad frente a estancamiento", "Identidad frente a confusión de roles", "Integridad frente a desesperación"]}'::jsonb, null, 2, array['fase11','ordenar']::text[], 'Material integrado del tema', 'publicada')
