insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('3feed955-08ab-5ec9-9060-b1adfb27f847', '{"orden": ["Confianza frente a desconfianza", "Autonomía frente a vergüenza y duda", "Identidad frente a confusión de roles", "Generatividad frente a estancamiento", "Integridad frente a desesperación"]}'::jsonb, 'Van de la infancia a la vejez.', '{"leccion": "teorias-del-desarrollo", "bloque": "b7", "titulo": "Debates y teorías del desarrollo", "fragmento": "Las etapas de Erikson: 0 a 1 año | Confianza frente a desconfianza | Esperanza · 1 a 3 años | Autonomía frente a vergüenza y duda | Voluntad · 3 a 6 años | Iniciativa frente a culpa | Propósito · 7 a 11 años | Laboriosidad frente a inferioridad | Competencia · 12 a 18 años | Identidad frente a confusión de roles | Fidelidad · Adultez temprana | Intimidad frente a aislamiento | Amor · Adultez media | Generatividad frente a estancamiento | Cuidado · Vejez | Integridad frente a desesperación | Sabiduría", "evidencia": ["Integridad frente a desesperación"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('1b27d10f-fb66-59e1-b6d6-deecb2253bff', 'f11-des-4', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'c32a2753-b62a-570e-885d-83656c2d46e3', '1109963a-a0e8-580a-bddc-66cf26a56f31', 'seleccion_multiple', '¿Qué interesaba a Kohlberg al plantear dilemas morales?', null, '{"opciones": ["El razonamiento que justificaba la respuesta", "La emoción que mostraba la cara", "El tiempo que tardaba la persona en responder", "Si la respuesta era sí o no"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('1b27d10f-fb66-59e1-b6d6-deecb2253bff', '{"correcta": [0]}'::jsonb, 'Clasificaba el nivel moral por el porqué, no por la respuesta.', '{"leccion": "teorias-del-desarrollo", "bloque": "b11", "titulo": "Debates y teorías del desarrollo", "fragmento": "**Lawrence Kohlberg** estudió el razonamiento moral planteando dilemas, como el de un hombre que roba un medicamento para salvar a su esposa. Lo que le interesaba no era la respuesta, sino el porqué. Describió tres niveles: **preconvencional**, centrado en evitar castigos y obtener premios; **convencional**, centrado en las normas y la aprobación social; y **posconvencional**, guiado por principios éticos universales. Carol Gilligan criticó que su teoría se basaba sobre todo en varones y dejaba fuera una ética del cuidado.", "evidencia": ["Lo que le interesaba no era la respuesta, sino el porqué"]}'::jsonb)
