insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('01c8a91b-1e0f-539e-8afa-5d7177424b1e', 'f11-des-5', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'c32a2753-b62a-570e-885d-83656c2d46e3', 'b1447c4a-febb-564c-bd46-10b0777b754e', 'ordenar', 'Ordena las etapas del desarrollo prenatal.', null, '{"elementos": ["Embrionaria", "Fetal", "Germinal"]}'::jsonb, null, 1, array['fase11','ordenar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('01c8a91b-1e0f-539e-8afa-5d7177424b1e', '{"orden": ["Germinal", "Embrionaria", "Fetal"]}'::jsonb, 'Germinal hasta la implantación, embrionaria hasta la semana ocho y fetal hasta el nacimiento.', '{"leccion": "embarazo-e-infancia", "bloque": "b2", "titulo": "Del embarazo a la infancia", "fragmento": "El desarrollo empieza con la **concepción**, cuando un espermatozoide fecunda un óvulo y forma el **cigoto**. La **etapa germinal**, las dos primeras semanas, termina cuando el cigoto se implanta en el útero. La **etapa embrionaria**, hasta la semana ocho, es cuando se forman los órganos principales, y por eso es el periodo más vulnerable. En la **etapa fetal**, desde la semana nueve hasta el nacimiento, el feto crece y sus sistemas maduran.", "evidencia": ["La etapa germinal, las dos primeras semanas"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('63d5a082-5d5f-5638-81f3-e8ae0d1c9051', 'f11-des-6', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'c32a2753-b62a-570e-885d-83656c2d46e3', 'b1447c4a-febb-564c-bd46-10b0777b754e', 'verdadero_falso_razonado', 'Un poco de alcohol durante el embarazo es seguro.', null, '{"razones": ["Falso, porque el alcohol solo afecta en la etapa fetal.", "Falso, porque no se conoce una cantidad segura y se recomienda no beber nada.", "Verdadero, porque solo el consumo diario causa daños."]}'::jsonb, null, 1, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('63d5a082-5d5f-5638-81f3-e8ae0d1c9051', '{"valor": false, "razon": 1}'::jsonb, 'El alcohol es un teratógeno y puede causar el síndrome alcohólico fetal.', '{"leccion": "embarazo-e-infancia", "bloque": "b3", "titulo": "Del embarazo a la infancia", "fragmento": "Los **teratógenos** son agentes que pueden dañar al embrión o al feto: el alcohol, el tabaco, algunas drogas y fármacos, ciertas infecciones y la contaminación. El alcohol puede causar el **síndrome alcohólico fetal**, con rasgos faciales característicos, problemas de crecimiento y discapacidad intelectual. No se conoce una cantidad segura de alcohol durante el embarazo, por lo que se recomienda no beber nada. Por eso son tan importantes los **cuidados prenatales**.", "evidencia": ["No se conoce una cantidad segura de alcohol durante el embarazo"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('167e9c8d-f093-5401-8723-ed42fdb0a83f', 'f11-des-7', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'c32a2753-b62a-570e-885d-83656c2d46e3', 'b1447c4a-febb-564c-bd46-10b0777b754e', 'relacionar', 'Relaciona cada tipo de apego con la conducta del niño.', null, '{"izquierda": ["Ambivalente o resistente", "Evitativo", "Seguro"], "derecha": ["Apenas reacciona cuando el cuidador sale ni cuando vuelve", "Busca al cuidador pero se resiste a ser consolado", "Se inquieta cuando el cuidador sale y se calma al volver"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('167e9c8d-f093-5401-8723-ed42fdb0a83f', '{"pares": {"Seguro": "Se inquieta cuando el cuidador sale y se calma al volver", "Evitativo": "Apenas reacciona cuando el cuidador sale ni cuando vuelve", "Ambivalente o resistente": "Busca al cuidador pero se resiste a ser consolado"}}'::jsonb, 'La reacción al reencuentro en la situación extraña revela el tipo de apego.', '{"leccion": "embarazo-e-infancia", "bloque": "b10", "titulo": "Del embarazo a la infancia", "fragmento": "Tipos de apego: Seguro | Explora con el cuidador presente, se inquieta cuando sale y se calma al volver · Evitativo | Apenas reacciona cuando el cuidador sale ni cuando vuelve · Ambivalente o resistente | Se angustia mucho y al volver busca al cuidador pero se resiste a ser consolado · Desorganizado | Conductas confusas y contradictorias, a menudo ligadas a cuidados aterradores", "evidencia": ["Apenas reacciona cuando el cuidador sale ni cuando vuelve"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('895bb1e7-724b-57d1-9692-3bc6ea639057', 'f11-des-8', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'c32a2753-b62a-570e-885d-83656c2d46e3', 'b1447c4a-febb-564c-bd46-10b0777b754e', 'seleccion_multiple', '¿Qué madre eligían los monos de Harlow cuando se asustaban?', null, '{"opciones": ["La de felpa, aunque no daba leche", "La que estuviera más cerca de la comida", "Ninguna de las dos", "La de alambre, porque daba leche"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('895bb1e7-724b-57d1-9692-3bc6ea639057', '{"correcta": [0]}'::jsonb, 'El contacto reconfortante pesaba más que la comida.', '{"leccion": "embarazo-e-infancia", "bloque": "b8", "titulo": "Del embarazo a la infancia", "fragmento": "El **apego** es el vínculo emocional entre el niño y su cuidador. Harry Harlow crió monos recién nacidos con dos madres artificiales: una de alambre que daba leche y otra de felpa que no daba comida. Los monos pasaban casi todo el tiempo con la de felpa, sobre todo cuando se asustaban. Demostró que el apego depende del **contacto y el consuelo**, no solo de la alimentación. John Bowlby propuso que el apego es una necesidad biológica que da al niño una **base segura** desde la que explorar.", "evidencia": ["pasaban casi todo el tiempo con la de felpa, sobre todo cuando se asustaban"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('ba53318a-08b4-5abb-9cd7-91b9e0c2feb8', 'f11-des-9', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'c32a2753-b62a-570e-885d-83656c2d46e3', 'f94fc8be-440e-508e-8236-fccecdd3840f', 'respuesta_breve', 'La ___ es el periodo de maduración sexual que da inicio a la adolescencia.', null, '{"completar": true}'::jsonb, null, 1, array['fase11','completar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('ba53318a-08b4-5abb-9cd7-91b9e0c2feb8', '{"aceptadas": ["pubertad", "la pubertad"], "solucion": "pubertad"}'::jsonb, 'En ella aparecen los caracteres sexuales primarios y secundarios.', '{"leccion": "adolescencia-y-adultez", "bloque": "b2", "titulo": "Adolescencia y adultez", "fragmento": "La **adolescencia** es la transición entre la infancia y la adultez. Empieza con la **pubertad**, el periodo de maduración sexual en que aparecen los **caracteres sexuales primarios**, relacionados con la reproducción, y los **secundarios**, como el vello o el cambio de voz. Las chicas suelen empezar antes que los chicos. Madurar mucho antes o mucho después que los compañeros puede afectar a la autoestima.", "evidencia": ["Empieza con la pubertad, el periodo de maduración sexual"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('f775775c-96cb-5521-8073-577134c8535a', 'f11-des-10', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'c32a2753-b62a-570e-885d-83656c2d46e3', 'f94fc8be-440e-508e-8236-fccecdd3840f', 'seleccion_multiple', '¿Qué ayuda a explicar la mayor búsqueda de riesgos en la adolescencia?', null, '{"opciones": ["Los adolescentes tienen menos neuronas", "El hipocampo deja de funcionar", "Las hormonas del crecimiento bloquean el miedo", "La corteza prefrontal madura más tarde que el sistema emocional"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('f775775c-96cb-5521-8073-577134c8535a', '{"correcta": [3]}'::jsonb, 'El control de los impulsos llega más tarde que la sensibilidad a la recompensa.', '{"leccion": "adolescencia-y-adultez", "bloque": "b3", "titulo": "Adolescencia y adultez", "fragmento": "El cerebro adolescente sigue madurando. El sistema relacionado con las emociones y la recompensa se desarrolla pronto, pero la **corteza prefrontal**, que controla los impulsos y planifica, no termina de madurar hasta pasados los veinte años. Este desfase ayuda a explicar por qué los adolescentes buscan más sensaciones y riesgos, sobre todo cuando están con amigos.", "evidencia": ["no termina de madurar hasta pasados los veinte años"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('caf722b1-2d22-5b5e-b534-c4305320b386', 'f11-des-11', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'c32a2753-b62a-570e-885d-83656c2d46e3', 'f94fc8be-440e-508e-8236-fccecdd3840f', 'verdadero_falso_razonado', 'La demencia es una parte normal del envejecimiento.', null, '{"razones": ["Falso, porque la memoria mejora con la edad en todo.", "Falso, aunque su riesgo aumenta con la edad, no es parte normal de envejecer.", "Verdadero, porque todas las personas mayores la sufren."]}'::jsonb, null, 1, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('caf722b1-2d22-5b5e-b534-c4305320b386', '{"valor": false, "razon": 1}'::jsonb, 'Envejecer trae cambios, pero la demencia es una enfermedad.', '{"leccion": "adolescencia-y-adultez", "bloque": "b8", "titulo": "Adolescencia y adultez", "fragmento": "Envejecer no es solo perder. Con la edad se pierde algo de velocidad de procesamiento y de memoria de trabajo, pero se mantiene o crece el conocimiento acumulado y la sabiduría práctica. Muchos estudios encuentran que las personas mayores sienten más emociones positivas y menos negativas que los jóvenes, quizá porque eligen mejor a qué dedicar su tiempo. Mantenerse activo física, mental y socialmente protege la salud y la memoria. La **demencia** no es una parte normal del envejecimiento, aunque su riesgo aumenta con la edad.", "evidencia": ["La demencia no es una parte normal del envejecimiento"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('6600d4ab-24f4-5ad1-b766-edae5ec6b8d5', 'f11-des-12', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'c32a2753-b62a-570e-885d-83656c2d46e3', 'f94fc8be-440e-508e-8236-fccecdd3840f', 'seleccion_multiple', '¿Qué encuentran muchos estudios sobre las emociones en la vejez?', null, '{"opciones": ["Las personas mayores sienten más emociones positivas y menos negativas que los jóvenes", "Solo aumenta la ira", "Las emociones desaparecen con la edad", "Las personas mayores son siempre más tristes"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
