insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('8261873b-9392-5d4a-a329-c3fb08fbe396', 'f11-des-13', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'c32a2753-b62a-570e-885d-83656c2d46e3', 'b303c48d-c47f-5090-9334-c41349e3e118', 'relacionar', 'Relaciona cada reacción de Kübler Ross con su ejemplo.', null, '{"izquierda": ["Ira", "Negación", "Negociación"], "derecha": ["«Esto no me puede estar pasando»", "«Si me curo, cambiaré mi vida»", "«¿Por qué a mí?»"]}'::jsonb, null, 1, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
