insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('8261873b-9392-5d4a-a329-c3fb08fbe396', '{"pares": {"Negación": "«Esto no me puede estar pasando»", "Ira": "«¿Por qué a mí?»", "Negociación": "«Si me curo, cambiaré mi vida»"}}'::jsonb, 'Son reacciones frecuentes, aunque no una secuencia obligatoria.', '{"leccion": "muerte-y-duelo", "bloque": "b2", "titulo": "La muerte y el duelo", "fragmento": "La psiquiatra **Elisabeth Kübler Ross** entrevistó a cientos de personas con enfermedades terminales y describió cinco reacciones ante la cercanía de la muerte: **negación**, «esto no me puede estar pasando»; **ira**, «¿por qué a mí?»; **negociación**, «si me curo, cambiaré mi vida»; **depresión**, tristeza profunda por lo que se pierde; y **aceptación**, una paz serena ante lo inevitable.", "evidencia": ["«¿por qué a mí?»"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('0e5f234d-366e-5a8e-b503-0ede93d68484', 'f11-des-14', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'c32a2753-b62a-570e-885d-83656c2d46e3', 'b303c48d-c47f-5090-9334-c41349e3e118', 'verdadero_falso_razonado', 'Todas las personas pasan por las cinco reacciones de Kübler Ross en el mismo orden.', null, '{"razones": ["Verdadero, porque es una secuencia biológica.", "Falso, porque nadie siente ira ante la muerte.", "Falso, porque muchas no pasan por todas, las viven en otro orden o vuelven atrás."]}'::jsonb, null, 1, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('0e5f234d-366e-5a8e-b503-0ede93d68484', '{"valor": false, "razon": 2}'::jsonb, 'El modelo es útil, pero no una lista que haya que cumplir.', '{"leccion": "muerte-y-duelo", "bloque": "b4", "titulo": "La muerte y el duelo", "fragmento": "Su trabajo cambió la forma de atender a los moribundos, pero hoy se sabe que no es una secuencia fija. Muchas personas no pasan por todas las reacciones, las viven en otro orden o vuelven atrás. Usar el modelo como una lista que hay que cumplir puede hacer que alguien sienta que vive su duelo de forma equivocada.", "evidencia": ["hoy se sabe que no es una secuencia fija"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
