insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('c99ad8fd-7680-5b37-911f-d40530ab7717', '{"aceptadas": ["instrucciones previas", "documento de instrucciones previas", "voluntades anticipadas", "testamento vital"], "solucion": "instrucciones previas"}'::jsonb, 'También se conoce como documento de voluntades anticipadas.', '{"leccion": "muerte-y-duelo", "bloque": "b7", "titulo": "La muerte y el duelo", "fragmento": "En España, el **documento de instrucciones previas**, también llamado de voluntades anticipadas, permite a cualquier adulto dejar por escrito qué cuidados desea o rechaza si llega un momento en que no puede expresarlo, y nombrar a un representante. Hablar de estos deseos con la familia, aunque cueste, evita decisiones difíciles en momentos de angustia.", "evidencia": ["el documento de instrucciones previas"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('2e8bbc7d-f2e4-55bc-a41c-5ef1b05ab63b', 'f11-des-16', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'c32a2753-b62a-570e-885d-83656c2d46e3', 'b303c48d-c47f-5090-9334-c41349e3e118', 'caso_clinico', '¿Qué es lo más adecuado?', 'Rosa perdió a su marido hace dos años. Sigue sin poder salir de casa, no duerme, ha dejado de ver a sus amigas y dice que no le encuentra sentido a seguir viviendo.', '{"opciones": ["Animarla a pedir ayuda profesional, porque el duelo le impide hacer vida normal y tiene ideas de no querer vivir", "Esperar, porque el duelo siempre se pasa solo", "Decirle que ya debería haberlo superado", "Evitar hablar de su marido"]}'::jsonb, null, 2, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('2e8bbc7d-f2e4-55bc-a41c-5ef1b05ab63b', '{"correcta": [0]}'::jsonb, 'Un duelo que impide la vida normal y se acompaña de ideas de no querer vivir necesita ayuda profesional.', '{"leccion": "muerte-y-duelo", "bloque": "b10", "titulo": "La muerte y el duelo", "fragmento": "Cuándo buscar ayuda. Si pasado mucho tiempo el dolor sigue siendo tan intenso que impide hacer vida normal, o aparecen ideas de no querer vivir, conviene pedir ayuda profesional. En España, ante ideas de hacerse daño, puedes llamar al 024.", "evidencia": ["conviene pedir ayuda profesional"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('20e7e5ec-d96d-572c-aaf3-66088f151a9d', 'f11-emo-1', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '48f5079e-bd85-56ae-afab-8763d0c16ba1', '1718b2d9-1a0e-53ba-9b4d-01f7d08c5ff8', 'seleccion_multiple', 'Marta toca el piano cada tarde porque disfruta haciéndolo. ¿Qué tipo de motivación muestra?', null, '{"opciones": ["Por homeostasis", "Intrínseca", "Por sobrejustificación", "Extrínseca"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('20e7e5ec-d96d-572c-aaf3-66088f151a9d', '{"correcta": [1]}'::jsonb, 'Lo hace por el placer de la actividad en sí.', '{"leccion": "la-motivacion", "bloque": "b2", "titulo": "Qué nos mueve: la motivación", "fragmento": "La **motivación** es lo que impulsa, dirige y mantiene una conducta. Puede ser **intrínseca**, cuando hacemos algo porque nos resulta interesante o satisfactorio en sí mismo, como leer una novela por placer; o **extrínseca**, cuando lo hacemos por una recompensa externa o para evitar un castigo, como trabajar por el sueldo. Casi siempre actúan las dos.", "evidencia": ["como leer una novela por placer"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('0505f29b-9fd5-5f98-b893-8e68f28dd1af', 'f11-emo-2', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '48f5079e-bd85-56ae-afab-8763d0c16ba1', '1718b2d9-1a0e-53ba-9b4d-01f7d08c5ff8', 'verdadero_falso_razonado', 'Pagar a un niño por dibujar, algo que ya le encanta, siempre aumenta su motivación.', null, '{"razones": ["Falso, porque los niños no responden a recompensas.", "Falso, porque puede reducir la motivación intrínseca por el efecto de sobrejustificación.", "Verdadero, porque el dinero siempre motiva."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('0505f29b-9fd5-5f98-b893-8e68f28dd1af', '{"valor": false, "razon": 1}'::jsonb, 'Cuando el premio desaparece, el niño dibuja menos.', '{"leccion": "la-motivacion", "bloque": "b3", "titulo": "Qué nos mueve: la motivación", "fragmento": "Curiosamente, premiar algo que ya nos gusta puede reducir la motivación intrínseca: es el **efecto de sobrejustificación**. Niños a los que se paga por dibujar, algo que ya disfrutaban, dibujan menos cuando el premio desaparece. Sin embargo, los elogios sinceros y las recompensas que informan de que lo hacemos bien no suelen tener ese efecto.", "evidencia": ["dibujan menos cuando el premio desaparece"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('59c3dfd9-fe71-5033-a213-6108bc8e9c33', 'f11-emo-3', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '48f5079e-bd85-56ae-afab-8763d0c16ba1', '1718b2d9-1a0e-53ba-9b4d-01f7d08c5ff8', 'ordenar', 'Ordena la pirámide de Maslow desde la base hasta la cima.', null, '{"elementos": ["Autorrealización: desarrollar el propio potencial.", "Estima: reconocimiento y respeto.", "Fisiológicas: comida, agua, sueño.", "Pertenencia y amor: amistad, pareja, grupo.", "Seguridad: protección y estabilidad."]}'::jsonb, null, 1, array['fase11','ordenar']::text[], 'Material integrado del tema', 'publicada')
