insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('59c3dfd9-fe71-5033-a213-6108bc8e9c33', '{"orden": ["Fisiológicas: comida, agua, sueño.", "Seguridad: protección y estabilidad.", "Pertenencia y amor: amistad, pareja, grupo.", "Estima: reconocimiento y respeto.", "Autorrealización: desarrollar el propio potencial."]}'::jsonb, 'Las necesidades básicas están en la base y la autorrealización en la cima.', '{"leccion": "la-motivacion", "bloque": "b10", "titulo": "Qué nos mueve: la motivación", "fragmento": "La jerarquía de necesidades de Maslow, de la base a la cima: Fisiológicas: comida, agua, sueño.; Seguridad: protección y estabilidad.; Pertenencia y amor: amistad, pareja, grupo.; Estima: reconocimiento y respeto.; Autorrealización: desarrollar el propio potencial.", "evidencia": ["Seguridad: protección y estabilidad"]}'::jsonb)
