insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('88f1a8b2-6245-5f8e-a018-188d6d5e34c9', 'f11-emo-4', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '48f5079e-bd85-56ae-afab-8763d0c16ba1', '1718b2d9-1a0e-53ba-9b4d-01f7d08c5ff8', 'relacionar', 'Relaciona cada teoría de la motivación con su idea principal.', null, '{"izquierda": ["Autoeficacia", "De la activación", "Del impulso"], "derecha": ["Buscamos un nivel óptimo de activación", "Nos motiva creer que somos capaces de lograr algo", "Una necesidad crea tensión que nos impulsa a recuperar la homeostasis"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('88f1a8b2-6245-5f8e-a018-188d6d5e34c9', '{"pares": {"Del impulso": "Una necesidad crea tensión que nos impulsa a recuperar la homeostasis", "De la activación": "Buscamos un nivel óptimo de activación", "Autoeficacia": "Nos motiva creer que somos capaces de lograr algo"}}'::jsonb, 'Cada teoría destaca un motor distinto de la conducta.', '{"leccion": "la-motivacion", "bloque": "b5", "titulo": "Qué nos mueve: la motivación", "fragmento": "Grandes teorías de la motivación: Del instinto (William James) | La conducta se debe a patrones innatos | Nombrar un instinto no explica la conducta · Del impulso | Una necesidad crea un estado de tensión que nos impulsa a reducirlo y recuperar la homeostasis | No explica por qué buscamos emociones fuertes · De la activación | Buscamos un nivel óptimo de activación, ni muy bajo ni muy alto | El nivel óptimo varía entre personas y tareas · Autoeficacia (Bandura) | Nos motiva creer que somos capaces de lograr algo | Depende de experiencias previas y del entorno", "evidencia": ["Nos motiva creer que somos capaces de lograr algo"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
