insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('983260b6-be7d-5222-901c-d3e53915a6ec', '{"pares": {"Grelina": "Estimula el hambre", "Leptina": "Reduce el apetito", "Insulina": "Regula la glucosa en sangre"}}'::jsonb, 'El hipotálamo integra estas señales para regular la ingesta.', '{"leccion": "hambre-y-alimentacion", "bloque": "b3", "titulo": "El hambre y la alimentación", "fragmento": "Señales del hambre y la saciedad: Grelina | Estómago | Estimula el hambre · Leptina | Tejido graso | Reduce el apetito · Insulina | Páncreas | Regula la glucosa en sangre · Distensión gástrica | Estómago lleno | Favorece la saciedad", "evidencia": ["Regula la glucosa en sangre"]}'::jsonb)
