insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('4d1b4694-1ce0-5ca4-afd2-c95fd6e652d0', 'f11-emo-6', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '48f5079e-bd85-56ae-afab-8763d0c16ba1', 'e2df1852-f4a1-5610-93f2-b2eb81a4c6c8', 'seleccion_multiple', 'Según la teoría del punto de equilibrio, ¿por qué fracasan a menudo las dietas muy restrictivas?', null, '{"opciones": ["Porque la leptina aumenta el hambre", "Porque la grelina desaparece", "Porque el metabolismo se ralentiza para ahorrar energía", "Porque el estómago se agranda"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('4d1b4694-1ce0-5ca4-afd2-c95fd6e652d0', '{"correcta": [2]}'::jsonb, 'El cuerpo defiende un peso en torno al que tiende a mantenerse.', '{"leccion": "hambre-y-alimentacion", "bloque": "b4", "titulo": "El hambre y la alimentación", "fragmento": "Según la teoría del **punto de equilibrio**, cada persona tiene un peso en torno al cual su cuerpo tiende a mantenerse, en parte por herencia genética. Cuando comemos menos, el metabolismo se ralentiza para ahorrar energía; por eso las dietas muy restrictivas suelen fracasar a largo plazo. Además, comemos por razones que no son el hambre: la hora, la presencia de otros, el aburrimiento, el estrés o la simple visión de un alimento apetecible.", "evidencia": ["el metabolismo se ralentiza para ahorrar energía"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('44a4c237-4727-5c55-bcc0-ea88bbfda83f', 'f11-emo-7', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '48f5079e-bd85-56ae-afab-8763d0c16ba1', 'e2df1852-f4a1-5610-93f2-b2eb81a4c6c8', 'relacionar', 'Relaciona cada trastorno con su rasgo principal.', null, '{"izquierda": ["Anorexia nerviosa", "Bulimia nerviosa", "Trastorno por atracón"], "derecha": ["Atracones repetidos con pérdida de control, sin conductas compensatorias", "Atracones seguidos de conductas compensatorias", "Restricción, miedo intenso a engordar e imagen corporal distorsionada"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
