insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('44a4c237-4727-5c55-bcc0-ea88bbfda83f', '{"pares": {"Anorexia nerviosa": "Restricción, miedo intenso a engordar e imagen corporal distorsionada", "Bulimia nerviosa": "Atracones seguidos de conductas compensatorias", "Trastorno por atracón": "Atracones repetidos con pérdida de control, sin conductas compensatorias"}}'::jsonb, 'Los tres son trastornos graves con tratamiento eficaz.', '{"leccion": "hambre-y-alimentacion", "bloque": "b9", "titulo": "El hambre y la alimentación", "fragmento": "Trastornos de la conducta alimentaria: Anorexia nerviosa | Restricción, miedo intenso a engordar e imagen corporal distorsionada · Bulimia nerviosa | Atracones seguidos de conductas compensatorias · Trastorno por atracón | Atracones repetidos con pérdida de control, sin conductas compensatorias", "evidencia": ["Atracones repetidos con pérdida de control"]}'::jsonb)
