insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('a6d0befd-eaa4-5d10-92be-7b6530746dff', 'f11-emo-8', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '48f5079e-bd85-56ae-afab-8763d0c16ba1', 'e2df1852-f4a1-5610-93f2-b2eb81a4c6c8', 'verdadero_falso_razonado', 'El estigma hacia las personas con obesidad les ayuda a cambiar sus hábitos.', null, '{"razones": ["Falso, porque perjudica su salud mental y no ayuda a cambiar.", "Verdadero, porque la presión social motiva.", "Falso, porque la obesidad no tiene relación con los hábitos."]}'::jsonb, null, 1, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('a6d0befd-eaa4-5d10-92be-7b6530746dff', '{"valor": false, "razon": 0}'::jsonb, 'El estigma añade sufrimiento y no favorece el cambio.', '{"leccion": "hambre-y-alimentacion", "bloque": "b6", "titulo": "El hambre y la alimentación", "fragmento": "La **obesidad** se ha convertido en un problema de salud mundial y se asocia a diabetes, enfermedades cardiovasculares y algunos cánceres. En ella influyen la genética, el metabolismo, la disponibilidad de comida muy calórica, el sedentarismo y factores psicológicos y sociales. Las personas con obesidad sufren además estigma, que perjudica su salud mental y no ayuda a cambiar. El tratamiento combina cambios de hábitos, apoyo psicológico y, en algunos casos, fármacos o cirugía bariátrica.", "evidencia": ["perjudica su salud mental y no ayuda a cambiar"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('fdade52d-6f9e-56e1-98aa-434becae9f10', 'f11-emo-9', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '48f5079e-bd85-56ae-afab-8763d0c16ba1', 'e6b1c6b2-b5d2-541b-a496-299c7c304292', 'ordenar', 'Ordena las fases de la respuesta sexual de Masters y Johnson.', null, '{"elementos": ["Excitación", "Meseta", "Orgasmo", "Resolución"]}'::jsonb, null, 1, array['fase11','ordenar']::text[], 'Material integrado del tema', 'publicada')
