insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('fdade52d-6f9e-56e1-98aa-434becae9f10', '{"orden": ["Excitación", "Meseta", "Orgasmo", "Resolución"]}'::jsonb, 'Es el ciclo descrito a partir de sus observaciones de laboratorio.', '{"leccion": "sexualidad", "bloque": "b4", "titulo": "La sexualidad humana", "fragmento": "**William Masters y Virginia Johnson** observaron en el laboratorio las respuestas fisiológicas de cientos de voluntarios y describieron el **ciclo de respuesta sexual** en cuatro fases: **excitación**, **meseta**, **orgasmo** y **resolución**. En los hombres suele seguir un **periodo refractario**, durante el que no es posible un nuevo orgasmo. Sus trabajos fueron la base de la terapia sexual moderna.", "evidencia": ["excitación, meseta, orgasmo y resolución"]}'::jsonb)
