insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('3a0ddac9-acd2-56a7-ad9a-a336c3fc973a', '{"pares": {"Sexo": "Características biológicas: cromosomas, gónadas, anatomía", "Identidad de género": "Cómo vive cada persona su propio género", "Orientación sexual": "Hacia quién se siente atracción emocional, romántica o sexual"}}'::jsonb, 'Son dimensiones distintas que no deben confundirse.', '{"leccion": "sexualidad", "bloque": "b7", "titulo": "La sexualidad humana", "fragmento": "Conceptos que conviene no confundir: Sexo | Características biológicas: cromosomas, gónadas, anatomía · Identidad de género | Cómo vive cada persona su propio género · Orientación sexual | Hacia quién se siente atracción emocional, romántica o sexual", "evidencia": ["Hacia quién se siente atracción emocional, romántica o sexual"]}'::jsonb)
