insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('a998ba7a-b72c-53b1-a61c-7caafcfbcfe6', 'f11-emo-11', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '48f5079e-bd85-56ae-afab-8763d0c16ba1', 'e6b1c6b2-b5d2-541b-a496-299c7c304292', 'seleccion_multiple', '¿Qué postura mantienen las principales organizaciones de psicología sobre las terapias de conversión?', null, '{"opciones": ["No tienen postura", "Las rechazan porque no funcionan y causan daño", "Las recomiendan en adolescentes", "Las consideran eficaces si el paciente lo pide"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('a998ba7a-b72c-53b1-a61c-7caafcfbcfe6', '{"correcta": [1]}'::jsonb, 'La orientación sexual no se elige ni se cambia con terapia.', '{"leccion": "sexualidad", "bloque": "b8", "titulo": "La sexualidad humana", "fragmento": "La **orientación sexual** puede ser heterosexual, homosexual, bisexual o asexual, entre otras. La investigación con gemelos y estudios biológicos sugiere que en ella influyen factores genéticos y prenatales; lo que está claro es que **no se elige** y que las llamadas terapias de conversión no funcionan y causan daño, por lo que las rechazan las principales organizaciones de psicología. Las personas **transgénero** tienen una identidad de género distinta del sexo que se les asignó al nacer. Desde 1990, la Organización Mundial de la Salud no considera la homosexualidad un trastorno.", "evidencia": ["no funcionan y causan daño"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
