values ('f64b1575-052c-5b23-bd74-b7d74c785ec6', 'f11-emo-12', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '48f5079e-bd85-56ae-afab-8763d0c16ba1', 'e6b1c6b2-b5d2-541b-a496-299c7c304292', 'respuesta_breve', 'Kinsey propuso que la orientación sexual es un ___ más que dos categorías cerradas.', null, '{"completar": true}'::jsonb, null, 1, array['fase11','completar']::text[], 'Material integrado del tema', 'publicada')
