values ('5e0a7469-bf6a-5d75-a61d-e3adff826c84', 'f11-emo-13', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '48f5079e-bd85-56ae-afab-8763d0c16ba1', 'b6ac7c94-2d04-5171-9e92-c35b2618256e', 'relacionar', 'Relaciona cada teoría con su propuesta.', null, '{"izquierda": ["Cannon y Bard", "James y Lange", "Lazarus", "Schachter y Singer"], "derecha": ["Activación más una etiqueta cognitiva", "Cuerpo y emoción se activan a la vez", "Estamos asustados porque temblamos", "La emoción depende de cómo evaluamos la situación"]}'::jsonb, null, 3, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
