insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('5e0a7469-bf6a-5d75-a61d-e3adff826c84', '{"pares": {"James y Lange": "Estamos asustados porque temblamos", "Cannon y Bard": "Cuerpo y emoción se activan a la vez", "Schachter y Singer": "Activación más una etiqueta cognitiva", "Lazarus": "La emoción depende de cómo evaluamos la situación"}}'::jsonb, 'Difieren en el orden y el papel del cuerpo y la interpretación.', '{"leccion": "la-emocion", "bloque": "b4", "titulo": "La emoción", "fragmento": "Teorías de la emoción: James y Lange | Estímulo, reacción del cuerpo y después la emoción: estamos asustados porque temblamos · Cannon y Bard | La reacción del cuerpo y la emoción ocurren a la vez y de forma independiente · Schachter y Singer (dos factores) | Activación más una etiqueta cognitiva que la interpreta · Lazarus (valoración cognitiva) | Primero evaluamos la situación; la emoción depende de esa evaluación", "evidencia": ["La reacción del cuerpo y la emoción ocurren a la vez"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('77adde30-0aac-56f3-99d8-ab9a58b01ba5', 'f11-emo-14', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '48f5079e-bd85-56ae-afab-8763d0c16ba1', 'b6ac7c94-2d04-5171-9e92-c35b2618256e', 'caso_clinico', '¿Qué fenómeno puede estar ocurriendo?', 'Tras cruzar un puente colgante muy inestable, Álex conoce a una persona y siente el corazón acelerado. Cree que se ha enamorado a primera vista.', '{"opciones": ["El efecto de sobrejustificación", "Una regla de expresión cultural", "Una atribución errónea de la activación", "La vía lenta de LeDoux"]}'::jsonb, null, 2, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('77adde30-0aac-56f3-99d8-ab9a58b01ba5', '{"correcta": [2]}'::jsonb, 'Atribuye a la atracción una activación que en realidad viene del miedo.', '{"leccion": "la-emocion", "bloque": "b6", "titulo": "La emoción", "fragmento": "Un experimento famoso apoya la teoría de los dos factores. Un entrevistador atractivo abordaba a hombres tras cruzar un puente colgante muy inestable o uno firme. Los del puente inestable, más activados, la llamaban más después para «resolver dudas». Atribuían su activación, que en realidad venía del miedo, a la atracción. Es una **atribución errónea de la activación**.", "evidencia": ["Es una atribución errónea de la activación"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('b8190732-7ecc-59e1-b5cc-3e753feae94b', 'f11-emo-15', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '48f5079e-bd85-56ae-afab-8763d0c16ba1', 'b6ac7c94-2d04-5171-9e92-c35b2618256e', 'seleccion_multiple', '¿Qué estructura evalúa con rapidez si algo es amenazante?', null, '{"opciones": ["El cerebelo", "La amígdala", "El lóbulo occipital", "La hipófisis"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
