insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('b8190732-7ecc-59e1-b5cc-3e753feae94b', '{"correcta": [1]}'::jsonb, 'La amígdala es clave en el miedo y recibe información por una vía rápida desde el tálamo.', '{"leccion": "la-emocion", "bloque": "b8", "titulo": "La emoción", "fragmento": "El **sistema límbico** es clave en la emoción, y en especial la **amígdala**, que evalúa con rapidez si algo es amenazante. Joseph LeDoux describió dos vías: una **vía rápida**, del tálamo directamente a la amígdala, que nos hace saltar ante una forma alargada en el suelo antes de saber qué es; y una **vía lenta**, que pasa por la corteza y nos permite comprobar si es una serpiente o un palo. El **hipocampo** aporta el contexto y la memoria.", "evidencia": ["la amígdala, que evalúa con rapidez si algo es amenazante"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('0663e247-c1f7-582c-b1c0-c46409a21db1', 'f11-emo-16', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '48f5079e-bd85-56ae-afab-8763d0c16ba1', 'b6ac7c94-2d04-5171-9e92-c35b2618256e', 'seleccion_multiple', '¿Qué demostró Ekman con personas de culturas muy distintas?', null, '{"opciones": ["Que las emociones no se expresan en la cara", "Que reconocen expresiones faciales básicas comunes", "Que solo existen dos emociones", "Que cada cultura tiene expresiones totalmente distintas"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('0663e247-c1f7-582c-b1c0-c46409a21db1', '{"correcta": [1]}'::jsonb, 'Al menos siete expresiones básicas se reconocen en todas las culturas.', '{"leccion": "la-emocion", "bloque": "b10", "titulo": "La emoción", "fragmento": "Paul Ekman mostró fotografías de caras a personas de culturas muy distintas, incluida una tribu de Nueva Guinea sin contacto con los medios occidentales, y encontró que todas reconocían al menos siete **expresiones básicas**: alegría, sorpresa, tristeza, miedo, ira, asco y desprecio. Esto apoya que estas expresiones son en parte **universales** e innatas. Pero cada cultura tiene **reglas de expresión** sobre cuándo y cuánto mostrarlas: en algunas se considera de mala educación mostrar enfado en público.", "evidencia": ["todas reconocían al menos siete expresiones básicas"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
