insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('35da7eb7-97c0-5835-87ff-362b1ce1363d', '{"pares": {"Ello": "Principio del placer", "Superyó": "La moral", "Yo": "Principio de realidad"}}'::jsonb, 'El yo media entre los impulsos del ello y las exigencias del superyó.', '{"leccion": "personalidad-y-psicoanalisis", "bloque": "b6", "titulo": "Qué es la personalidad y la teoría de Freud", "fragmento": "Las tres estructuras de la personalidad según Freud: Ello | Principio del placer | Busca satisfacer impulsos de inmediato · Superyó | La moral | Representa las normas interiorizadas y genera culpa · Yo | Principio de realidad | Media entre el ello, el superyó y la realidad", "evidencia": ["Principio del placer"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
