insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('ed3ec7d8-35d2-5014-98a7-68f43be20799', '{"correcta": [1]}'::jsonb, 'Descarga el enfado en un objetivo más seguro que su jefe.', '{"leccion": "personalidad-y-psicoanalisis", "bloque": "b8", "titulo": "Qué es la personalidad y la teoría de Freud", "fragmento": "Algunos mecanismos de defensa: Negación | Negarse a aceptar un diagnóstico grave · Desplazamiento | Gritar a la pareja tras una mala jornada con el jefe · Proyección | Acusar a otros de los propios sentimientos inaceptables · Racionalización | Buscar excusas lógicas para un fracaso · Regresión | Volver a conductas infantiles ante el estrés · Sublimación | Canalizar la agresividad en un deporte", "evidencia": ["Gritar a la pareja tras una mala jornada con el jefe"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
