insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('6034a202-44b4-5acc-9261-93545287143e', '{"correcta": [2]}'::jsonb, 'La mayor parte de la mente, según Freud, es inconsciente.', '{"leccion": "personalidad-y-psicoanalisis", "bloque": "b5", "titulo": "Qué es la personalidad y la teoría de Freud", "fragmento": "**Sigmund Freud** comparó la mente con un **iceberg**. La parte visible es lo **consciente**, lo que pensamos ahora. Justo bajo la superficie está lo **preconsciente**, lo que podemos recordar si nos lo proponemos. Y la enorme parte sumergida es el **inconsciente**, deseos e impulsos inaceptables que no conocemos pero que influyen en lo que hacemos y aparecen disfrazados en los sueños y los lapsus.", "evidencia": ["la enorme parte sumergida es el inconsciente"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('bee8c346-5ffb-5add-9898-1a2917ad3a8b', 'f11-per-4', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '2fdef6dd-e714-5f16-84da-38c7e5f6e003', '8e14aa31-ac27-5e7e-91dc-d9e60ca182cd', 'ordenar', 'Ordena las etapas psicosexuales de Freud.', null, '{"elementos": ["Anal", "Fálica", "Genital", "Latencia", "Oral"]}'::jsonb, null, 2, array['fase11','ordenar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('bee8c346-5ffb-5add-9898-1a2917ad3a8b', '{"orden": ["Oral", "Anal", "Fálica", "Latencia", "Genital"]}'::jsonb, 'Cada etapa centra el placer en una zona del cuerpo.', '{"leccion": "personalidad-y-psicoanalisis", "bloque": "b9", "titulo": "Qué es la personalidad y la teoría de Freud", "fragmento": "Freud propuso cinco **etapas psicosexuales**: **oral**, **anal**, **fálica**, de **latencia** y **genital**. En cada una, el placer se centra en una zona del cuerpo. Si una etapa no se resuelve bien, la persona puede quedar **fijada** en ella. Muchas de estas ideas son imposibles de comprobar y han sido muy criticadas, pero Freud dejó conceptos influyentes, como la importancia de la infancia y de los procesos inconscientes.", "evidencia": ["oral, anal, fálica, de latencia y genital"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('a029bd1e-7046-54bb-b4bc-48c96c739295', 'f11-per-5', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '2fdef6dd-e714-5f16-84da-38c7e5f6e003', '24092a3c-cd57-5947-89a3-fa491ac27933', 'relacionar', 'Relaciona cada autor con su idea clave.', null, '{"izquierda": ["Adler", "Horney", "Jung"], "derecha": ["Ansiedad básica y crítica al sesgo masculino de Freud", "Inconsciente colectivo, arquetipos, introversión y extraversión", "Sentimiento de inferioridad y afán de superación"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
