insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('a029bd1e-7046-54bb-b4bc-48c96c739295', '{"pares": {"Adler": "Sentimiento de inferioridad y afán de superación", "Jung": "Inconsciente colectivo, arquetipos, introversión y extraversión", "Horney": "Ansiedad básica y crítica al sesgo masculino de Freud"}}'::jsonb, 'Los neofreudianos dieron más peso a lo social y cultural.', '{"leccion": "neofreudianos-y-humanistas", "bloque": "b6", "titulo": "Neofreudianos y humanistas", "fragmento": "Los neofreudianos: Adler | Sentimiento de inferioridad y afán de superación · Jung | Inconsciente colectivo, arquetipos, introversión y extraversión · Horney | Ansiedad básica y crítica al sesgo masculino de Freud · Erikson | Ocho etapas psicosociales a lo largo de la vida", "evidencia": ["Sentimiento de inferioridad y afán de superación"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('cea5f63a-8d97-5eb1-8aac-1066b462c70a', 'f11-per-6', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '2fdef6dd-e714-5f16-84da-38c7e5f6e003', '24092a3c-cd57-5947-89a3-fa491ac27933', 'seleccion_multiple', 'Según Rogers, ¿cuándo hay bienestar psicológico?', null, '{"opciones": ["Cuando se resuelven las etapas psicosexuales", "Cuando el yo real y el yo ideal coinciden", "Cuando se tiene locus de control externo", "Cuando el ello domina al superyó"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('cea5f63a-8d97-5eb1-8aac-1066b462c70a', '{"correcta": [1]}'::jsonb, 'La congruencia entre el yo real y el ideal se asocia al bienestar.', '{"leccion": "neofreudianos-y-humanistas", "bloque": "b8", "titulo": "Neofreudianos y humanistas", "fragmento": "**Carl Rogers** creía que las personas tienden por naturaleza a crecer. En el centro de su teoría está el **autoconcepto**, lo que pensamos de nosotros mismos. Distinguía el **yo real**, cómo somos, del **yo ideal**, cómo creemos que deberíamos ser. Cuando ambos coinciden hay **congruencia** y bienestar; cuando están muy alejados, malestar. Rogers pensaba que la congruencia crece cuando recibimos **aceptación incondicional**, es decir, cuando nos sentimos valorados por lo que somos y no solo por lo que hacemos.", "evidencia": ["Cuando ambos coinciden hay congruencia y bienestar"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('b574cd62-51f0-5c67-8ac6-b7a2e65598ba', 'f11-per-7', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '2fdef6dd-e714-5f16-84da-38c7e5f6e003', '24092a3c-cd57-5947-89a3-fa491ac27933', 'respuesta_breve', 'Jung llamó ___ a las imágenes universales del inconsciente colectivo, como el héroe o la madre.', null, '{"completar": true}'::jsonb, null, 1, array['fase11','completar']::text[], 'Material integrado del tema', 'publicada')
