insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('b574cd62-51f0-5c67-8ac6-b7a2e65598ba', '{"aceptadas": ["arquetipos", "los arquetipos"], "solucion": "arquetipos"}'::jsonb, 'Aparecen en mitos y relatos de todas las culturas.', '{"leccion": "neofreudianos-y-humanistas", "bloque": "b4", "titulo": "Neofreudianos y humanistas", "fragmento": "**Carl Jung** añadió al inconsciente personal un **inconsciente colectivo**, compartido por toda la humanidad, con **arquetipos** o imágenes universales que aparecen en mitos y relatos de todas las culturas, como el héroe, la madre o la sombra. También introdujo los términos **introversión** y **extraversión**, que siguen usándose hoy.", "evidencia": ["con arquetipos o imágenes universales"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('df8bff6f-bc6f-5512-b672-0f6e0659f461', 'f11-per-8', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '2fdef6dd-e714-5f16-84da-38c7e5f6e003', '24092a3c-cd57-5947-89a3-fa491ac27933', 'verdadero_falso_razonado', 'A las teorías humanistas se les critica que sus conceptos son difíciles de medir.', null, '{"razones": ["Falso, porque se basan solo en experimentos.", "Verdadero, aunque han influido mucho en la psicoterapia y la educación.", "Verdadero, porque niegan que las personas puedan crecer."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('df8bff6f-bc6f-5512-b672-0f6e0659f461', '{"valor": true, "razon": 1}'::jsonb, 'Son optimistas e influyentes, pero conceptos como la autorrealización son difíciles de medir.', '{"leccion": "neofreudianos-y-humanistas", "bloque": "b9", "titulo": "Neofreudianos y humanistas", "fragmento": "**Abraham Maslow** estudió a personas que consideraba sanas y plenas, como Abraham Lincoln o Eleanor Roosevelt, y describió la **autorrealización**: desarrollar el propio potencial. Las teorías humanistas son optimistas y han influido mucho en la psicoterapia y la educación, aunque se les critica que sus conceptos son difíciles de medir.", "evidencia": ["se les critica que sus conceptos son difíciles de medir"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('8dc59db6-6f7d-5519-a048-610284566dbf', 'f11-per-9', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '2fdef6dd-e714-5f16-84da-38c7e5f6e003', 'e74e03b0-ff97-5509-955d-9e582751dc65', 'caso_clinico', '¿Qué refleja su forma de pensar?', 'Tras suspender una oposición, Irene dice: «No ha sido mala suerte; no estudié lo suficiente. La próxima vez me organizaré mejor».', '{"opciones": ["Un complejo de inferioridad", "Neuroticismo alto", "Un locus de control externo", "Un locus de control interno"]}'::jsonb, null, 1, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('8dc59db6-6f7d-5519-a048-610284566dbf', '{"correcta": [3]}'::jsonb, 'Atribuye el resultado a sus propios actos.', '{"leccion": "aprendizaje-biologia-y-rasgos", "bloque": "b3", "titulo": "Aprendizaje, biología y rasgos", "fragmento": "Julian Rotter propuso el **locus de control**. Las personas con locus **interno** creen que lo que les ocurre depende sobre todo de sus actos; las de locus **externo**, que depende de la suerte o de otros. El locus interno se asocia a más esfuerzo y mejor salud. Walter **Mischel** mostró, con su famosa prueba de la golosina, que la capacidad de un niño para esperar y obtener dos golosinas en lugar de una predecía ciertos logros futuros, aunque estudios posteriores señalan que el entorno familiar también explica mucho.", "evidencia": ["creen que lo que les ocurre depende sobre todo de sus actos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('78258749-5ae6-50d5-9fd4-c1fc0d8eff21', 'f11-per-10', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '2fdef6dd-e714-5f16-84da-38c7e5f6e003', 'e74e03b0-ff97-5509-955d-9e582751dc65', 'relacionar', 'Relaciona cada rasgo de los Cinco Grandes con una puntuación alta.', null, '{"izquierda": ["Apertura a la experiencia", "Extraversión", "Neuroticismo", "Responsabilidad"], "derecha": ["Ansioso, inestable emocionalmente", "Curioso, imaginativo, abierto a lo nuevo", "Organizado, constante, cumplidor", "Sociable, enérgico, hablador"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
