insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('78258749-5ae6-50d5-9fd4-c1fc0d8eff21', '{"pares": {"Apertura a la experiencia": "Curioso, imaginativo, abierto a lo nuevo", "Responsabilidad": "Organizado, constante, cumplidor", "Extraversión": "Sociable, enérgico, hablador", "Neuroticismo": "Ansioso, inestable emocionalmente"}}'::jsonb, 'Cada rasgo es un continuo entre dos polos.', '{"leccion": "aprendizaje-biologia-y-rasgos", "bloque": "b8", "titulo": "Aprendizaje, biología y rasgos", "fragmento": "Los Cinco Grandes: Apertura a la experiencia | Curioso, imaginativo, abierto a lo nuevo | Práctico, convencional · Responsabilidad | Organizado, constante, cumplidor | Impulsivo, desordenado · Extraversión | Sociable, enérgico, hablador | Reservado, tranquilo · Amabilidad | Cooperador, confiado, compasivo | Competitivo, desconfiado · Neuroticismo | Ansioso, inestable emocionalmente | Tranquilo, estable", "evidencia": ["Sociable, enérgico, hablador"]}'::jsonb)
