insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('bf01ca55-4c37-5d09-8342-bf03a4e0946c', 'f11-per-11', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '2fdef6dd-e714-5f16-84da-38c7e5f6e003', 'e74e03b0-ff97-5509-955d-9e582751dc65', 'seleccion_multiple', '¿Qué muestran los estudios con gemelos idénticos criados por separado?', null, '{"opciones": ["Que la personalidad es en parte heredable", "Que los gemelos no se parecen nada", "Que la personalidad depende solo de la familia", "Que el temperamento no existe"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('bf01ca55-4c37-5d09-8342-bf03a4e0946c', '{"correcta": [0]}'::jsonb, 'Se parecen mucho aunque hayan crecido en familias distintas.', '{"leccion": "aprendizaje-biologia-y-rasgos", "bloque": "b5", "titulo": "Aprendizaje, biología y rasgos", "fragmento": "El **temperamento** es la base biológica de la personalidad: estilos emocionales que aparecen desde el nacimiento, como la actividad, la sociabilidad o la reactividad. Alexander Thomas y Stella Chess clasificaron a los bebés en **fáciles**, **difíciles** y **lentos para adaptarse**. Los estudios con **gemelos** criados por separado, como el de Minnesota, muestran que los gemelos idénticos se parecen mucho en personalidad aunque hayan crecido en familias distintas. Se calcula que alrededor de la mitad de la variación en los rasgos se debe a la genética.", "evidencia": ["se parecen mucho en personalidad aunque hayan crecido en familias distintas"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('a7debb9f-9291-552d-aa2c-0db86fa7c5da', 'f11-per-12', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '2fdef6dd-e714-5f16-84da-38c7e5f6e003', 'e74e03b0-ff97-5509-955d-9e582751dc65', 'respuesta_breve', '¿Cómo se llama la confianza en la propia capacidad para lograr algo, según Bandura?', null, '{}'::jsonb, null, 1, array['fase11','respuesta_breve']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('a7debb9f-9291-552d-aa2c-0db86fa7c5da', '{"aceptadas": ["autoeficacia", "la autoeficacia"], "solucion": "autoeficacia"}'::jsonb, 'Es un elemento clave del enfoque social cognitivo.', '{"leccion": "aprendizaje-biologia-y-rasgos", "bloque": "b2", "titulo": "Aprendizaje, biología y rasgos", "fragmento": "Para **Skinner**, la personalidad no es más que el conjunto de conductas aprendidas por refuerzo y castigo. **Albert Bandura** amplió esta idea con el **determinismo recíproco**: la persona, con sus pensamientos y creencias, su conducta y el ambiente se influyen mutuamente. Un elemento clave es la **autoeficacia**, la confianza en la propia capacidad para lograr algo.", "evidencia": ["la confianza en la propia capacidad para lograr algo"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('f29c5633-28dc-5503-992b-3fc945e63e97', 'f11-per-13', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '2fdef6dd-e714-5f16-84da-38c7e5f6e003', '802fe934-4f23-55f5-92dd-f45177514330', 'seleccion_multiple', '¿Qué valoran sobre todo las culturas colectivistas?', null, '{"opciones": ["La armonía del grupo y la interdependencia", "La competición entre personas", "Destacar como individuo", "La independencia de la familia"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
