insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('f29c5633-28dc-5503-992b-3fc945e63e97', '{"correcta": [0]}'::jsonb, 'En ellas el grupo y la familia tienen prioridad.', '{"leccion": "cultura-y-evaluacion", "bloque": "b2", "titulo": "Personalidad, cultura y evaluación", "fragmento": "La cultura influye en cómo se expresa y se valora la personalidad. En las culturas **individualistas**, como Estados Unidos o gran parte de Europa occidental, se valoran la independencia, la autonomía y destacar como individuo. En las **colectivistas**, como muchas de Asia, África y América Latina, se valoran la armonía del grupo, la familia y la interdependencia. Lo que en una cultura se ve como seguridad en uno mismo, en otra puede verse como falta de modestia.", "evidencia": ["se valoran la armonía del grupo, la familia y la interdependencia"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
