values ('28bc0b86-5a4f-5b20-96d3-e968c48f02b7', 'f11-per-14', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '2fdef6dd-e714-5f16-84da-38c7e5f6e003', '802fe934-4f23-55f5-92dd-f45177514330', 'relacionar', 'Relaciona cada test con su tipo.', null, '{"izquierda": ["MMPI", "Rorschach", "Test de Apercepción Temática"], "derecha": ["Autoinforme", "Proyectivo", "Proyectivo con historias"]}'::jsonb, null, 1, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
