insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('28bc0b86-5a4f-5b20-96d3-e968c48f02b7', '{"pares": {"MMPI": "Autoinforme", "Rorschach": "Proyectivo", "Test de Apercepción Temática": "Proyectivo con historias"}}'::jsonb, 'Los de autoinforme preguntan directamente; los proyectivos usan estímulos ambiguos.', '{"leccion": "cultura-y-evaluacion", "bloque": "b5", "titulo": "Personalidad, cultura y evaluación", "fragmento": "Los **tests de autoinforme** preguntan directamente a la persona sobre sí misma, con respuestas como «verdadero o falso» o escalas de acuerdo. Son fáciles de aplicar y de corregir, y los mejor construidos son fiables y válidos. El más usado en clínica es el **MMPI**, el Inventario Multifásico de Personalidad de Minnesota, con cientos de ítems y escalas clínicas. Incluye **escalas de validez** que detectan si alguien responde al azar, exagera sus problemas o intenta dar una imagen demasiado buena. Los **tests proyectivos** presentan estímulos ambiguos y suponen que la persona proyecta en ellos su mundo interno. En el **Rorschach**, se pregunta qué se ve en manchas de tinta. En el **Test de Apercepción Temática**, se pide inventar una historia sobre láminas con escenas poco claras. En las **frases incompletas**, se completan frases como «Mi madre...». Su interpretación depende mucho del evaluador, por lo que tienen problemas de **fiabilidad** y **validez**, aunque algunos clínicos los usan para generar hipótesis.", "evidencia": ["se pide inventar una historia sobre láminas"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('7d42e627-a748-570b-81ef-8b0dcbaa96dd', 'f11-per-15', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '2fdef6dd-e714-5f16-84da-38c7e5f6e003', '802fe934-4f23-55f5-92dd-f45177514330', 'verdadero_falso_razonado', 'Los tests proyectivos son más fiables que los de autoinforme.', null, '{"razones": ["Verdadero, porque nadie puede falsearlos.", "Falso, porque su interpretación es subjetiva y tienen baja fiabilidad.", "Falso, porque los proyectivos no se usan nunca."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('7d42e627-a748-570b-81ef-8b0dcbaa96dd', '{"valor": false, "razon": 1}'::jsonb, 'Los autoinformes bien construidos son más fiables y válidos.', '{"leccion": "cultura-y-evaluacion", "bloque": "b7", "titulo": "Personalidad, cultura y evaluación", "fragmento": "Tipos de tests de personalidad: Autoinforme | MMPI, cuestionarios de los Cinco Grandes | Objetivos, fiables y fáciles de corregir | La persona puede falsear sus respuestas · Proyectivos | Rorschach, TAT, frases incompletas | Pueden revelar aspectos no conscientes | Interpretación subjetiva, baja fiabilidad", "evidencia": ["Interpretación subjetiva, baja fiabilidad"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('2a3222c5-cda1-547a-a576-25f2991069a5', 'f11-per-16', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '2fdef6dd-e714-5f16-84da-38c7e5f6e003', '802fe934-4f23-55f5-92dd-f45177514330', 'seleccion_multiple', '¿Para qué sirven los tests de personalidad que circulan por internet?', null, '{"opciones": ["Sirven para diagnosticar trastornos", "Pueden entretener, pero no sirven para diagnosticar", "Permiten elegir pareja con seguridad", "Sustituyen al MMPI"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('2a3222c5-cda1-547a-a576-25f2991069a5', '{"correcta": [1]}'::jsonb, 'Los tests clínicos deben aplicarlos profesionales formados.', '{"leccion": "cultura-y-evaluacion", "bloque": "b8", "titulo": "Personalidad, cultura y evaluación", "fragmento": "Uso responsable. Los tests de personalidad con valor clínico solo deben aplicarlos e interpretarlos profesionales formados. Los tests de personalidad que circulan por internet pueden ser entretenidos, pero no sirven para diagnosticar ni para tomar decisiones importantes.", "evidencia": ["no sirven para diagnosticar ni para tomar decisiones importantes"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('3ee10a28-3ea5-5f5a-ae10-5165dc5c793c', 'f11-soc-1', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dc79e25a-aa73-5db8-99ba-804cc686a8ab', 'fbd0a928-5ace-5d76-b5d5-026caf83e497', 'relacionar', 'Relaciona cada sesgo con su ejemplo.', null, '{"izquierda": ["Error fundamental de atribución", "Sesgo actor observador", "Sesgo de autoservicio"], "derecha": ["Aprobé porque estudié; suspendí porque la prueba era injusta", "El camarero es antipático, no que está desbordado", "Yo llego tarde por el tráfico; tú, por desorganizado"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('3ee10a28-3ea5-5f5a-ae10-5165dc5c793c', '{"pares": {"Error fundamental de atribución": "El camarero es antipático, no que está desbordado", "Sesgo actor observador": "Yo llego tarde por el tráfico; tú, por desorganizado", "Sesgo de autoservicio": "Aprobé porque estudié; suspendí porque la prueba era injusta"}}'::jsonb, 'Son errores sistemáticos al explicar la conducta.', '{"leccion": "atribucion-y-roles", "bloque": "b4", "titulo": "Cómo explicamos la conducta: atribución y roles", "fragmento": "Sesgos al explicar la conducta: Error fundamental de atribución | Explicar la conducta ajena por la personalidad e ignorar la situación | El camarero es antipático, no que está desbordado · Sesgo actor observador | Explicar la propia conducta por la situación y la ajena por la personalidad | Yo llego tarde por el tráfico; tú, por desorganizado · Sesgo de autoservicio | Atribuir los éxitos a uno mismo y los fracasos a las circunstancias | Aprobé porque estudié; suspendí porque la prueba era injusta · Creencia en un mundo justo | Pensar que cada uno tiene lo que merece | Culpar a una víctima de lo que le ocurrió", "evidencia": ["Yo llego tarde por el tráfico; tú, por desorganizado"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('4c29ddc3-bb21-58ea-99b1-d1ad886626d1', 'f11-soc-2', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dc79e25a-aa73-5db8-99ba-804cc686a8ab', 'fbd0a928-5ace-5d76-b5d5-026caf83e497', 'seleccion_multiple', '¿En qué culturas es más fuerte el error fundamental de atribución?', null, '{"opciones": ["Es igual en todas", "En las individualistas", "En las colectivistas", "Solo aparece en niños"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('4c29ddc3-bb21-58ea-99b1-d1ad886626d1', '{"correcta": [1]}'::jsonb, 'Las culturas colectivistas prestan más atención a la situación.', '{"leccion": "atribucion-y-roles", "bloque": "b3", "titulo": "Cómo explicamos la conducta: atribución y roles", "fragmento": "Cuando vemos a alguien hacer algo, buscamos una explicación, una **atribución**. Puede ser **interna** o disposicional, basada en la personalidad («llega tarde porque es irresponsable»), o **externa** o situacional, basada en las circunstancias («llega tarde porque había un atasco»). Con los demás tendemos a sobrestimar lo interno y a infravalorar la situación: es el **error fundamental de atribución**. Es más fuerte en las culturas individualistas que en las colectivistas.", "evidencia": ["Es más fuerte en las culturas individualistas que en las colectivistas"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('e17629b4-e09d-5503-b63b-9fd671c408be', 'f11-soc-3', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dc79e25a-aa73-5db8-99ba-804cc686a8ab', 'fbd0a928-5ace-5d76-b5d5-026caf83e497', 'verdadero_falso_razonado', 'El experimento de la cárcel de Stanford hoy se considera una prueba sin fallos del poder de la situación.', null, '{"razones": ["Falso, porque nunca se llegó a realizar.", "Verdadero, porque se repitió con miles de personas.", "Falso, se critica por su muestra pequeña, el doble papel de Zimbardo y los indicios de que se animó a los guardias."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('e17629b4-e09d-5503-b63b-9fd671c408be', '{"valor": false, "razon": 2}'::jsonb, 'Sigue siendo un ejemplo clásico, pero con serias críticas metodológicas.', '{"leccion": "atribucion-y-roles", "bloque": "b8", "titulo": "Cómo explicamos la conducta: atribución y roles", "fragmento": "En 1971, **Philip Zimbardo** asignó al azar a estudiantes universitarios el papel de guardias o de presos en una cárcel simulada en la Universidad de Stanford. En pocos días, algunos guardias empezaron a humillar a los presos y varios presos mostraron un fuerte malestar, por lo que el estudio se detuvo antes de tiempo. Se interpretó como prueba del poder de la situación. Hoy se critica mucho: la muestra era pequeña, el propio Zimbardo actuó como director de la prisión y hay indicios de que se animó a los guardias a ser duros. Aun así, sigue siendo un ejemplo clásico del debate sobre situación y persona.", "evidencia": ["Hoy se critica mucho"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('453ba187-40f5-5f3f-9e7a-d164fc531a2e', 'f11-soc-4', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dc79e25a-aa73-5db8-99ba-804cc686a8ab', 'fbd0a928-5ace-5d76-b5d5-026caf83e497', 'seleccion_multiple', '¿Qué es un guion en psicología social?', null, '{"opciones": ["Un sesgo de memoria", "Una secuencia de conducta esperada en una situación", "Una técnica de persuasión", "Una actitud negativa hacia un grupo"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('453ba187-40f5-5f3f-9e7a-d164fc531a2e', '{"correcta": [1]}'::jsonb, 'Junto con roles y normas, los guiones orientan la conducta.', '{"leccion": "atribucion-y-roles", "bloque": "b7", "titulo": "Cómo explicamos la conducta: atribución y roles", "fragmento": "Un **rol social** es el conjunto de conductas que se esperan de alguien según su posición: estudiante, madre, médico. Las **normas sociales** son reglas, a menudo implícitas, sobre cómo comportarse, y los **guiones** son secuencias de conducta esperadas en una situación. Adaptamos nuestra conducta al rol casi sin darnos cuenta: la misma persona se comporta distinto como jugadora en un partido y como invitada en una boda.", "evidencia": ["los guiones son secuencias de conducta esperadas en una situación"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('bc17a627-7425-54d0-91f5-498f26d1c438', 'f11-soc-5', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dc79e25a-aa73-5db8-99ba-804cc686a8ab', 'f5637222-0038-5416-b8aa-396b00268cee', 'caso_clinico', '¿Qué está intentando reducir con esa respuesta?', 'Luis sabe que fumar es muy perjudicial, pero sigue fumando. Cuando su hermana se lo recuerda, responde: «Mi abuelo fumó toda la vida y llegó a los noventa».', '{"opciones": ["El pensamiento grupal", "El efecto espectador", "La holgazanería social", "La disonancia cognitiva"]}'::jsonb, null, 1, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('bc17a627-7425-54d0-91f5-498f26d1c438', '{"correcta": [3]}'::jsonb, 'Cambia su creencia para que no choque con su conducta.', '{"leccion": "actitudes-y-persuasion", "bloque": "b4", "titulo": "Actitudes, disonancia y persuasión", "fragmento": "Según **Leon Festinger**, sentimos malestar cuando dos de nuestras ideas, o una idea y una conducta, se contradicen. Lo llamó **disonancia cognitiva**. Un fumador que sabe que fumar es malo para la salud la experimenta. Para reducirla puede dejar de fumar, pero a menudo es más fácil cambiar la idea: «mi abuelo fumó y vivió hasta los noventa» o «de algo hay que morir».", "evidencia": ["mi abuelo fumó y vivió hasta los noventa"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('55cb6432-5ebd-5f1c-8931-0889f75ef557', 'f11-soc-6', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dc79e25a-aa73-5db8-99ba-804cc686a8ab', 'f5637222-0038-5416-b8aa-396b00268cee', 'relacionar', 'Relaciona cada ruta de la persuasión con su característica.', null, '{"izquierda": ["Pie en la puerta", "Ruta central", "Ruta periférica"], "derecha": ["La calidad de los argumentos", "Señales superficiales: atractivo, fama, número de argumentos", "Un favor pequeño facilita uno mayor"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('55cb6432-5ebd-5f1c-8931-0889f75ef557', '{"pares": {"Ruta central": "La calidad de los argumentos", "Ruta periférica": "Señales superficiales: atractivo, fama, número de argumentos", "Pie en la puerta": "Un favor pequeño facilita uno mayor"}}'::jsonb, 'La ruta central produce cambios más duraderos.', '{"leccion": "actitudes-y-persuasion", "bloque": "b8", "titulo": "Actitudes, disonancia y persuasión", "fragmento": "Las dos rutas de la persuasión: Central | La calidad de los argumentos | Duradero y resistente · Periférica | Señales superficiales: atractivo, fama, número de argumentos | Rápido pero frágil Otra técnica es el **pie en la puerta**: quien acepta un favor pequeño tiene más probabilidades de aceptar después uno mayor. Por ejemplo, alguien que pone una pegatina pequeña de seguridad vial en su coche acepta luego con más facilidad un cartel grande en su jardín.", "evidencia": ["Señales superficiales: atractivo, fama, número de argumentos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('85dd5508-aeb8-5c4f-a6d1-008d2e7acbe4', 'f11-soc-7', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dc79e25a-aa73-5db8-99ba-804cc686a8ab', 'f5637222-0038-5416-b8aa-396b00268cee', 'seleccion_multiple', '¿Por qué valoramos más un grupo cuyo ingreso fue muy duro?', null, '{"opciones": ["Porque esos grupos siempre son mejores", "Para reducir la disonancia: nos convencemos de que el esfuerzo valió la pena", "Porque la ruta periférica es más fuerte", "Por el efecto espectador"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('85dd5508-aeb8-5c4f-a6d1-008d2e7acbe4', '{"correcta": [1]}'::jsonb, 'Justificamos el sufrimiento valorando más lo conseguido.', '{"leccion": "actitudes-y-persuasion", "bloque": "b6", "titulo": "Actitudes, disonancia y persuasión", "fragmento": "La disonancia explica fenómenos curiosos. Cuanto más duro es el ingreso en un grupo, más se valora pertenecer a él: si hemos sufrido para entrar, nos convencemos de que valía la pena. Por eso algunas organizaciones usan ritos de iniciación exigentes. Y si hacemos algo contrario a nuestra opinión por una recompensa pequeña, tendemos a cambiar la opinión para justificarnos, porque la recompensa no basta para explicarlo.", "evidencia": ["Cuanto más duro es el ingreso en un grupo, más se valora pertenecer a él"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
