values ('88a93950-2b4f-56f0-8282-9afc4b6b0b60', 'f11-soc-8', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dc79e25a-aa73-5db8-99ba-804cc686a8ab', 'f5637222-0038-5416-b8aa-396b00268cee', 'respuesta_breve', 'Los tres componentes de una actitud son el afectivo, el conductual y el ___.', null, '{"completar": true}'::jsonb, null, 1, array['fase11','completar']::text[], 'Material integrado del tema', 'publicada')
