insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('88a93950-2b4f-56f0-8282-9afc4b6b0b60', '{"aceptadas": ["cognitivo"], "solucion": "cognitivo"}'::jsonb, 'Es el ABC de las actitudes.', '{"leccion": "actitudes-y-persuasion", "bloque": "b2", "titulo": "Actitudes, disonancia y persuasión", "fragmento": "Una **actitud** es una evaluación, positiva o negativa, de una persona, un objeto o una idea. Tiene tres componentes, que se recuerdan como el **ABC de las actitudes**: el **afectivo**, lo que sentimos; el **conductual**, cómo tendemos a actuar; y el **cognitivo**, lo que pensamos o creemos. Las actitudes predicen la conducta mejor cuando son fuertes, específicas y cuando no hay mucha presión social en contra.", "evidencia": ["y el cognitivo, lo que pensamos o creemos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('b810f4d0-0a3c-54cb-992a-cb61244472ef', 'f11-soc-9', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dc79e25a-aa73-5db8-99ba-804cc686a8ab', '91322a1a-aaf0-539d-8d93-13596dac3535', 'seleccion_multiple', 'En el experimento de Asch, ¿qué reducía mucho la conformidad?', null, '{"opciones": ["Que la tarea fuera más difícil", "Responder en público", "Que el grupo fuera más grande", "Que al menos otra persona discrepara del grupo"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('b810f4d0-0a3c-54cb-992a-cb61244472ef', '{"correcta": [3]}'::jsonb, 'Basta un aliado para que sea mucho más fácil discrepar.', '{"leccion": "conformidad-y-obediencia", "bloque": "b3", "titulo": "Conformidad, obediencia y grupos", "fragmento": "Qué aumenta la conformidad: Un grupo de entre tres y cinco personas unánimes.; Que ninguna otra persona discrepe: basta un aliado para reducirla mucho.; Responder en público en lugar de en privado.; Una tarea difícil o ambigua.; Pertenecer a una cultura colectivista.", "evidencia": ["basta un aliado para reducirla mucho"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('8e0a0429-8cbe-512b-8b97-6a9ed7e1441f', 'f11-soc-10', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dc79e25a-aa73-5db8-99ba-804cc686a8ab', '91322a1a-aaf0-539d-8d93-13596dac3535', 'relacionar', 'Relaciona cada tipo de influencia con su motivo.', null, '{"izquierda": ["Influencia informativa", "Influencia normativa", "Polarización grupal"], "derecha": ["El grupo acaba con posturas más extremas que sus miembros", "Pensar que los demás saben más", "Ser aceptados y evitar el rechazo"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('8e0a0429-8cbe-512b-8b97-6a9ed7e1441f', '{"pares": {"Influencia normativa": "Ser aceptados y evitar el rechazo", "Influencia informativa": "Pensar que los demás saben más", "Polarización grupal": "El grupo acaba con posturas más extremas que sus miembros"}}'::jsonb, 'Una busca aceptación, otra información correcta, y en grupo las posturas tienden a extremarse.', '{"leccion": "conformidad-y-obediencia", "bloque": "b4", "titulo": "Conformidad, obediencia y grupos", "fragmento": "Nos conformamos por dos razones. En la **influencia normativa**, seguimos al grupo para ser aceptados y evitar el rechazo. En la **influencia informativa**, lo seguimos porque pensamos que los demás saben más, sobre todo en situaciones confusas. Efectos de estar en grupo: Facilitación social | Rendimos mejor en tareas fáciles o bien aprendidas cuando nos observan · Holgazanería social | Nos esforzamos menos cuando el esfuerzo individual no se ve · Desindividuación | Perdemos la conciencia de nosotros mismos en multitudes anónimas · Polarización grupal | El grupo acaba con posturas más extremas que sus miembros", "evidencia": ["para ser aceptados y evitar el rechazo"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('424c7955-039f-5ed7-9326-9579b8f792f5', 'f11-soc-11', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dc79e25a-aa73-5db8-99ba-804cc686a8ab', '91322a1a-aaf0-539d-8d93-13596dac3535', 'verdadero_falso_razonado', 'En el estudio de Milgram, la obediencia se mantenía igual aunque el investigador diera las órdenes por teléfono.', null, '{"razones": ["Verdadero, porque las órdenes son órdenes.", "Falso, la obediencia bajaba cuando la autoridad estaba lejos.", "Falso, porque nadie obedeció nunca."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('424c7955-039f-5ed7-9326-9579b8f792f5', '{"valor": false, "razon": 1}'::jsonb, 'La presencia de la autoridad aumentaba la obediencia.', '{"leccion": "conformidad-y-obediencia", "bloque": "b7", "titulo": "Conformidad, obediencia y grupos", "fragmento": "La obediencia bajaba cuando el investigador daba las órdenes por teléfono, cuando la víctima estaba en la misma sala o cuando otros participantes se negaban. El estudio fue muy criticado por el estrés que causó, y hoy no se podría repetir igual por razones éticas. Su lección sigue vigente: la presión de una autoridad legítima puede llevar a personas normales a hacer daño.", "evidencia": ["cuando el investigador daba las órdenes por teléfono"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('e1209238-8520-5567-9dd1-9d424e285800', 'f11-soc-12', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dc79e25a-aa73-5db8-99ba-804cc686a8ab', '91322a1a-aaf0-539d-8d93-13596dac3535', 'seleccion_multiple', '¿Qué ayuda a evitar el pensamiento grupal?', null, '{"opciones": ["Buscar la unanimidad cuanto antes", "Que alguien haga de abogado del diablo", "Que el líder dé su opinión al principio", "Evitar consultar a expertos externos"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('e1209238-8520-5567-9dd1-9d424e285800', '{"correcta": [1]}'::jsonb, 'Las críticas y alternativas protegen contra decisiones apresuradas.', '{"leccion": "conformidad-y-obediencia", "bloque": "b9", "titulo": "Conformidad, obediencia y grupos", "fragmento": "El **pensamiento grupal** ocurre cuando un grupo valora tanto la unanimidad que deja de considerar alternativas y críticas, lo que lleva a malas decisiones. Para evitarlo conviene que el líder no dé su opinión al principio, pedir a alguien que haga de abogado del diablo y consultar a expertos externos. La **polarización grupal** es la tendencia de un grupo a terminar con posturas más extremas que las de sus miembros por separado.", "evidencia": ["pedir a alguien que haga de abogado del diablo"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('93b8b2da-73fc-566e-8ed1-fd98a41900c0', 'f11-soc-13', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dc79e25a-aa73-5db8-99ba-804cc686a8ab', 'b3998ee8-468e-5d3a-8386-d0029e145593', 'relacionar', 'Relaciona cada concepto con su componente.', null, '{"izquierda": ["Discriminación", "Estereotipo", "Prejuicio"], "derecha": ["Afectivo", "Cognitivo", "Conductual"]}'::jsonb, null, 1, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
