insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('93b8b2da-73fc-566e-8ed1-fd98a41900c0', '{"pares": {"Estereotipo": "Cognitivo", "Prejuicio": "Afectivo", "Discriminación": "Conductual"}}'::jsonb, 'El estereotipo es una creencia, el prejuicio una actitud y la discriminación una conducta.', '{"leccion": "prejuicio-agresion-y-ayuda", "bloque": "b2", "titulo": "Prejuicio, agresión, ayuda y atracción", "fragmento": "Tres conceptos relacionados: Estereotipo | Creencia generalizada sobre un grupo | Cognitivo · Prejuicio | Actitud negativa hacia una persona por su grupo | Afectivo · Discriminación | Trato injusto por pertenecer a un grupo | Conductual", "evidencia": ["Creencia generalizada sobre un grupo"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('5c62d05d-6d4b-5541-a9c7-b0f8064f0092', 'f11-soc-14', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dc79e25a-aa73-5db8-99ba-804cc686a8ab', 'b3998ee8-468e-5d3a-8386-d0029e145593', 'caso_clinico', '¿Qué explica mejor lo que ocurre?', 'Una persona se desmaya en una estación llena de gente. Muchos la miran, pero nadie se acerca durante varios minutos.', '{"opciones": ["La difusión de la responsabilidad del efecto espectador", "La falta total de empatía de todos", "La facilitación social", "La disonancia cognitiva"]}'::jsonb, null, 1, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('5c62d05d-6d4b-5541-a9c7-b0f8064f0092', '{"correcta": [0]}'::jsonb, 'Con muchos testigos, cada uno espera que actúe otro.', '{"leccion": "prejuicio-agresion-y-ayuda", "bloque": "b7", "titulo": "Prejuicio, agresión, ayuda y atracción", "fragmento": "En 1964, en Nueva York, se dijo que decenas de vecinos oyeron cómo atacaban a Kitty Genovese y nadie intervino. Aunque después se supo que el relato estaba exagerado, inspiró a Darley y Latané a estudiar el **efecto espectador**: cuantas más personas presencian una emergencia, menos probable es que una de ellas ayude. La causa principal es la **difusión de la responsabilidad**: cada uno piensa que otro actuará.", "evidencia": ["cada uno piensa que otro actuará"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('bd13a2c0-a42b-56ae-a330-ca304d9aa5c2', 'f11-soc-15', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dc79e25a-aa73-5db8-99ba-804cc686a8ab', 'b3998ee8-468e-5d3a-8386-d0029e145593', 'seleccion_multiple', '¿Qué reduce el prejuicio entre grupos?', null, '{"opciones": ["Buscar un chivo expiatorio", "Separar a los grupos", "El contacto en igualdad de condiciones y la cooperación hacia metas comunes", "Reforzar la identidad de endogrupo"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('bd13a2c0-a42b-56ae-a330-ca304d9aa5c2', '{"correcta": [2]}'::jsonb, 'Trabajar juntos por metas comunes reduce la distancia entre «nosotros» y «ellos».', '{"leccion": "prejuicio-agresion-y-ayuda", "bloque": "b3", "titulo": "Prejuicio, agresión, ayuda y atracción", "fragmento": "Dividimos el mundo en **endogrupo**, «nosotros», y **exogrupo**, «ellos». Tendemos a favorecer al endogrupo y a ver al exogrupo como más homogéneo. En momentos de frustración, a veces se busca un **chivo expiatorio**, un grupo al que culpar de los problemas. Los estereotipos pueden convertirse en **profecías autocumplidas**: si un docente espera poco de un alumno, puede tratarlo de forma que acabe rindiendo menos. El contacto en igualdad de condiciones y la cooperación hacia metas comunes reducen el prejuicio.", "evidencia": ["El contacto en igualdad de condiciones y la cooperación hacia metas comunes reducen el prejuicio"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('aa081cde-56c0-5916-b8c0-5f62c9ee7944', 'f11-soc-16', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'dc79e25a-aa73-5db8-99ba-804cc686a8ab', 'b3998ee8-468e-5d3a-8386-d0029e145593', 'respuesta_breve', '¿Cómo se llama el amor que reúne intimidad, pasión y compromiso según Sternberg?', null, '{}'::jsonb, null, 2, array['fase11','respuesta_breve']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('aa081cde-56c0-5916-b8c0-5f62c9ee7944', '{"aceptadas": ["amor consumado", "consumado", "el amor consumado"], "solucion": "amor consumado"}'::jsonb, 'Es la combinación completa de la teoría triangular.', '{"leccion": "prejuicio-agresion-y-ayuda", "bloque": "b11", "titulo": "Prejuicio, agresión, ayuda y atracción", "fragmento": "Nos atraen más las personas que tenemos cerca, por la **proximidad** y la mera exposición; las que se nos parecen en actitudes y valores, por la **semejanza**; y las que muestran que les gustamos, por la **reciprocidad**. El atractivo físico también influye, sobre todo al principio. **Robert Sternberg** propuso la **teoría triangular del amor**, con tres componentes: **intimidad**, **pasión** y **compromiso**. El **amor consumado** reúne los tres.", "evidencia": ["El amor consumado reúne los tres"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
