insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('ccf8a7de-1089-5a0f-83b5-112df1a7bc24', '{"pares": {"Psicología industrial o del personal": "Selección, formación y evaluación de los trabajadores", "Psicología organizacional": "Satisfacción, motivación, liderazgo y cultura de la organización", "Factores humanos": "Diseño de puestos, máquinas y herramientas adaptados a las personas"}}'::jsonb, 'Son las tres grandes ramas de la psicología del trabajo.', '{"leccion": "que-es-la-psicologia-del-trabajo", "bloque": "b3", "titulo": "Qué es la psicología del trabajo", "fragmento": "Las tres ramas: Psicología industrial o del personal | Selección, formación y evaluación de los trabajadores · Psicología organizacional | Satisfacción, motivación, liderazgo y cultura de la organización · Factores humanos | Diseño de puestos, máquinas y herramientas adaptados a las personas", "evidencia": ["Diseño de puestos, máquinas y herramientas adaptados a las personas"]}'::jsonb)
