insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('bba0a128-3566-565a-8311-6babec16566a', 'f11-tra-2', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'cb6fe6be-b131-5c2f-a843-94b7a3c90640', '0c18e0f0-986b-5e0d-8132-8f5b128be328', 'seleccion_multiple', '¿Qué crítica se hace a la gestión científica de Taylor?', null, '{"opciones": ["No aumentó la productividad", "Se centraba demasiado en el bienestar", "Prohibía medir el trabajo", "Trataba a las personas como piezas de una máquina"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('bba0a128-3566-565a-8311-6babec16566a', '{"correcta": [3]}'::jsonb, 'Ganó eficiencia, pero ignoró las necesidades de los trabajadores.', '{"leccion": "que-es-la-psicologia-del-trabajo", "bloque": "b5", "titulo": "Qué es la psicología del trabajo", "fragmento": "A finales del siglo XIX, el ingeniero **Frederick Taylor** propuso la **gestión científica**: estudiar con cronómetro cada movimiento de los trabajadores para encontrar la forma más eficiente de hacer cada tarea. Aumentó la productividad, pero trataba a las personas como piezas de una máquina. **Lillian Gilbreth**, psicóloga e ingeniera, estudió también los movimientos, pero puso en el centro el bienestar y la fatiga del trabajador, y aplicó sus ideas al diseño de cocinas y electrodomésticos.", "evidencia": ["trataba a las personas como piezas de una máquina"]}'::jsonb)
