insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('eb3e0922-4084-5f71-ade2-e8c101379a42', 'f11-tra-3', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'cb6fe6be-b131-5c2f-a843-94b7a3c90640', '0c18e0f0-986b-5e0d-8132-8f5b128be328', 'verdadero_falso_razonado', 'En los estudios de Hawthorne, la productividad solo mejoraba al aumentar la iluminación.', null, '{"razones": ["Falso, porque la productividad bajó siempre.", "Verdadero, porque más luz siempre ayuda.", "Falso, mejoraba tanto al subir como al bajar la luz."]}'::jsonb, null, 1, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('eb3e0922-4084-5f71-ade2-e8c101379a42', '{"valor": false, "razon": 2}'::jsonb, 'El cambio se atribuyó a sentirse atendidos y observados.', '{"leccion": "que-es-la-psicologia-del-trabajo", "bloque": "b8", "titulo": "Qué es la psicología del trabajo", "fragmento": "Entre 1924 y 1932, en la fábrica Hawthorne de la Western Electric, cerca de Chicago, se estudió si cambiar la iluminación mejoraba la productividad. Sorprendentemente, la productividad aumentaba tanto si se subía la luz como si se bajaba. Los investigadores concluyeron que los trabajadores rendían más porque se sentían atendidos y observados. Este **efecto Hawthorne** se ha discutido mucho después, pero los estudios dieron un giro importante: mostraron que las **relaciones sociales** y el **trato** influyen en el trabajo tanto como las condiciones físicas.", "evidencia": ["tanto si se subía la luz como si se bajaba"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('0181a494-5b26-504c-8556-702c68795066', 'f11-tra-4', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'cb6fe6be-b131-5c2f-a843-94b7a3c90640', '0c18e0f0-986b-5e0d-8132-8f5b128be328', 'respuesta_breve', 'En la Primera Guerra Mundial, el test Army ___ usaba dibujos para los reclutas que no sabían leer.', null, '{"completar": true}'::jsonb, null, 2, array['fase11','completar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('0181a494-5b26-504c-8556-702c68795066', '{"aceptadas": ["Beta"], "solucion": "Beta"}'::jsonb, 'El Alpha era para quienes sabían leer.', '{"leccion": "que-es-la-psicologia-del-trabajo", "bloque": "b6", "titulo": "Qué es la psicología del trabajo", "fragmento": "Durante la Primera Guerra Mundial, el ejército de Estados Unidos encargó a psicólogos tests para seleccionar a cientos de miles de reclutas: el **Army Alpha**, para quienes sabían leer, y el **Army Beta**, con dibujos para quienes no. Fue la primera aplicación masiva de los tests psicológicos a la selección de personal.", "evidencia": ["el Army Beta, con dibujos para quienes no"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('625facda-cb76-5053-95e2-a9808703b9e8', 'f11-tra-5', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'cb6fe6be-b131-5c2f-a843-94b7a3c90640', 'cfa12709-db1c-5e25-a91b-86c6c5a09edc', 'seleccion_multiple', '¿Qué tipo de entrevista predice mejor el rendimiento laboral?', null, '{"opciones": ["Una charla informal en la cafetería", "La no estructurada, porque es más natural", "La estructurada, con preguntas y criterios fijos", "Cualquiera, todas predicen igual"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('625facda-cb76-5053-95e2-a9808703b9e8', '{"correcta": [2]}'::jsonb, 'La estructura reduce los sesgos del entrevistador.', '{"leccion": "seleccion-y-evaluacion", "bloque": "b5", "titulo": "Selección, formación y evaluación del personal", "fragmento": "La **entrevista** es el método más usado, pero no siempre el mejor. En la **no estructurada**, el entrevistador conversa libremente y se deja llevar por la primera impresión, el parecido consigo mismo o el atractivo. En la **estructurada**, todos los candidatos responden a las mismas preguntas, relacionadas con el puesto, y se puntúan con criterios fijados de antemano. Así se reducen los sesgos y mejora mucho la predicción.", "evidencia": ["Así se reducen los sesgos y mejora mucho la predicción"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('d938acbb-e12e-5715-999b-3c71293e54a0', 'f11-tra-6', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'cb6fe6be-b131-5c2f-a843-94b7a3c90640', 'cfa12709-db1c-5e25-a91b-86c6c5a09edc', 'caso_clinico', '¿Qué problema tiene esta pregunta en España?', 'En una entrevista para un puesto administrativo, el entrevistador pregunta a una candidata si tiene pensado ser madre pronto.', '{"opciones": ["Es discriminatoria y no está permitida", "Es una pregunta estructurada correcta", "Mejora la validez de la entrevista", "Es un requisito profesional esencial"]}'::jsonb, null, 1, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('d938acbb-e12e-5715-999b-3c71293e54a0', '{"correcta": [0]}'::jsonb, 'La selección no puede discriminar por sexo ni por planes familiares.', '{"leccion": "seleccion-y-evaluacion", "bloque": "b6", "titulo": "Selección, formación y evaluación del personal", "fragmento": "La selección está regulada. En España, la Constitución y el **Estatuto de los Trabajadores** prohíben discriminar por sexo, origen, religión, edad, discapacidad, orientación sexual u otros motivos. No se puede, por ejemplo, preguntar a una candidata si piensa tener hijos. Solo se admite exigir una característica si es un **requisito profesional esencial** del puesto.", "evidencia": ["No se puede, por ejemplo, preguntar a una candidata si piensa tener hijos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
