values ('76eb9eec-e554-5dfc-beb6-ed4dddb8e681', 'f11-tra-7', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'cb6fe6be-b131-5c2f-a843-94b7a3c90640', 'cfa12709-db1c-5e25-a91b-86c6c5a09edc', 'relacionar', 'Relaciona cada sesgo de evaluación con su definición.', null, '{"izquierda": ["Efecto de lo reciente", "Efecto halo", "Indulgencia", "Tendencia central"], "derecha": ["Puntuar a todos demasiado alto", "Puntuar a todos en valores intermedios", "Una impresión general positiva o negativa tiñe todas las puntuaciones", "Valorar solo lo ocurrido en las últimas semanas"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
