insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('76eb9eec-e554-5dfc-beb6-ed4dddb8e681', '{"pares": {"Efecto halo": "Una impresión general positiva o negativa tiñe todas las puntuaciones", "Tendencia central": "Puntuar a todos en valores intermedios", "Indulgencia": "Puntuar a todos demasiado alto", "Efecto de lo reciente": "Valorar solo lo ocurrido en las últimas semanas"}}'::jsonb, 'Conocerlos ayuda a evaluar con más justicia.', '{"leccion": "seleccion-y-evaluacion", "bloque": "b10", "titulo": "Selección, formación y evaluación del personal", "fragmento": "Sesgos al evaluar el desempeño: Efecto halo | Una impresión general positiva o negativa tiñe todas las puntuaciones · Tendencia central | Puntuar a todos en valores intermedios · Indulgencia | Puntuar a todos demasiado alto · Efecto de lo reciente | Valorar solo lo ocurrido en las últimas semanas", "evidencia": ["Puntuar a todos en valores intermedios"]}'::jsonb)
