values ('15a6ebaa-77b2-5364-9cbb-a5a38b049b21', 'f11-tra-8', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'cb6fe6be-b131-5c2f-a843-94b7a3c90640', 'cfa12709-db1c-5e25-a91b-86c6c5a09edc', 'ordenar', 'Ordena el proceso habitual de incorporación de personal.', null, '{"elementos": ["Analizar el puesto", "Elegir las pruebas de selección", "Evaluar su desempeño", "Formar a la persona contratada", "Seleccionar al candidato"]}'::jsonb, null, 1, array['fase11','ordenar']::text[], 'Material integrado del tema', 'publicada')
