insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('15a6ebaa-77b2-5364-9cbb-a5a38b049b21', '{"orden": ["Analizar el puesto", "Elegir las pruebas de selección", "Seleccionar al candidato", "Formar a la persona contratada", "Evaluar su desempeño"]}'::jsonb, 'Todo parte de saber qué exige el puesto.', '{"leccion": "seleccion-y-evaluacion", "bloque": "b2", "titulo": "Selección, formación y evaluación del personal", "fragmento": "Antes de contratar hay que saber qué exige el puesto. El **análisis de puestos** describe las tareas que se realizan y las **competencias** necesarias: conocimientos, habilidades, capacidades y otras características. Se hace observando el trabajo, entrevistando a quienes lo hacen y usando cuestionarios. A partir de él se redacta la oferta y se eligen las pruebas de selección. Una vez contratadas, las personas necesitan **formación**. Una buena formación parte de un análisis de necesidades, combina teoría y práctica y se evalúa para comprobar que mejora el trabajo real, no solo que gusta a los asistentes.", "evidencia": ["A partir de él se redacta la oferta y se eligen las pruebas de selección"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
