values ('1830cfba-0686-58e1-bc3a-18215d6c59da', 'f11-tra-9', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'cb6fe6be-b131-5c2f-a843-94b7a3c90640', 'b46723db-851a-501c-9474-5703357741bc', 'ordenar', 'Ordena los componentes del desgaste profesional tal como se presentan.', null, '{"elementos": ["Agotamiento", "Baja eficacia", "Cinismo"]}'::jsonb, null, 1, array['fase11','ordenar']::text[], 'Material integrado del tema', 'publicada')
