insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('1830cfba-0686-58e1-bc3a-18215d6c59da', '{"orden": ["Agotamiento", "Cinismo", "Baja eficacia"]}'::jsonb, 'El desgaste combina agotamiento, distancia y sensación de no lograr nada.', '{"leccion": "satisfaccion-y-liderazgo", "bloque": "b6", "titulo": "Satisfacción, estrés y liderazgo", "fragmento": "Los componentes del desgaste profesional: Agotamiento: sensación de no tener energía.; Cinismo: distancia y actitud negativa hacia el trabajo y las personas.; Baja eficacia: sentir que no se logra nada.", "evidencia": ["Cinismo: distancia y actitud negativa hacia el trabajo y las personas"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
