values ('ca13ba42-e672-5cb2-bc40-7a3275103d7b', 'f11-tra-10', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'cb6fe6be-b131-5c2f-a843-94b7a3c90640', 'b46723db-851a-501c-9474-5703357741bc', 'seleccion_multiple', '¿Qué estilo de liderazgo se asocia a más compromiso y satisfacción?', null, '{"opciones": ["Ausente", "Basado en la teoría X", "Transaccional", "Transformacional"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
