insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('ca13ba42-e672-5cb2-bc40-7a3275103d7b', '{"correcta": [3]}'::jsonb, 'Inspirar con una visión y atender a cada persona mejora los resultados.', '{"leccion": "satisfaccion-y-liderazgo", "bloque": "b10", "titulo": "Satisfacción, estrés y liderazgo", "fragmento": "Estilos de liderazgo: Transaccional | Intercambia recompensas por cumplir objetivos y corrige errores | Cumplimiento de lo pactado · Transformacional | Inspira con una visión, motiva y atiende a cada persona | Más compromiso, satisfacción y rendimiento", "evidencia": ["Más compromiso, satisfacción y rendimiento"]}'::jsonb)
