insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('14d807c9-a468-5109-9eb8-90069255c4fd', 'f11-tra-11', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'cb6fe6be-b131-5c2f-a843-94b7a3c90640', 'b46723db-851a-501c-9474-5703357741bc', 'caso_clinico', '¿Qué describe mejor su situación?', 'Nuria, enfermera, siente que no le queda energía al final de cada turno, trata a los pacientes con distancia y frialdad y piensa que su trabajo no sirve de nada.', '{"opciones": ["Efecto Hawthorne", "Holgazanería social", "Liderazgo transaccional", "Desgaste profesional"]}'::jsonb, null, 2, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
