insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('14d807c9-a468-5109-9eb8-90069255c4fd', '{"correcta": [3]}'::jsonb, 'Presenta agotamiento, cinismo y baja eficacia.', '{"leccion": "satisfaccion-y-liderazgo", "bloque": "b5", "titulo": "Satisfacción, estrés y liderazgo", "fragmento": "El **síndrome de desgaste profesional** o burnout, que la Organización Mundial de la Salud reconoce como un fenómeno ligado al trabajo, tiene tres componentes: **agotamiento** emocional, **cinismo** o distancia mental hacia el trabajo y sensación de **baja eficacia**. Es frecuente en profesiones de ayuda, como la sanidad y la docencia, y se relaciona con mucha carga, poco control, escaso reconocimiento y conflictos de valores.", "evidencia": ["Es frecuente en profesiones de ayuda"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('fd39c3d3-9dd7-5e05-96f8-068f9924bd6b', 'f11-tra-12', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'cb6fe6be-b131-5c2f-a843-94b7a3c90640', 'b46723db-851a-501c-9474-5703357741bc', 'relacionar', 'Relaciona cada teoría de McGregor con su idea.', null, '{"izquierda": ["Cultura organizacional", "Teoría X", "Teoría Y"], "derecha": ["Los trabajadores buscan responsabilidades si se les da confianza", "Los trabajadores evitan el esfuerzo y hay que controlarlos", "Valores, normas y creencias compartidos"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('fd39c3d3-9dd7-5e05-96f8-068f9924bd6b', '{"pares": {"Teoría X": "Los trabajadores evitan el esfuerzo y hay que controlarlos", "Teoría Y": "Los trabajadores buscan responsabilidades si se les da confianza", "Cultura organizacional": "Valores, normas y creencias compartidos"}}'::jsonb, 'Las creencias de los jefes influyen en cómo dirigen.', '{"leccion": "satisfaccion-y-liderazgo", "bloque": "b11", "titulo": "Satisfacción, estrés y liderazgo", "fragmento": "Las ideas de los jefes sobre las personas influyen en cómo dirigen. Douglas McGregor describió la **teoría X**, según la cual los trabajadores evitan el esfuerzo y hay que controlarlos, y la **teoría Y**, según la cual buscan responsabilidades si se les da confianza. La **cultura organizacional** son los valores, normas y creencias compartidos en una organización; una cultura que valora a las personas y la justicia en el trato se asocia a más compromiso.", "evidencia": ["buscan responsabilidades si se les da confianza"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('04927cf0-6938-55c6-af36-875c9c437922', 'f11-tra-13', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'cb6fe6be-b131-5c2f-a843-94b7a3c90640', 'd5d6778b-5a26-5d92-a088-99444520fcd6', 'seleccion_multiple', 'Según los factores humanos, ¿qué hay detrás de muchos errores humanos?', null, '{"opciones": ["Un mal diseño de máquinas, pantallas o procedimientos", "La falta de inteligencia de los trabajadores", "El exceso de formación", "La mala suerte"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
