insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('04927cf0-6938-55c6-af36-875c9c437922', '{"correcta": [0]}'::jsonb, 'Un buen diseño hace difícil equivocarse.', '{"leccion": "factores-humanos", "bloque": "b3", "titulo": "Factores humanos y ergonomía", "fragmento": "Muchos accidentes que se atribuyen a un **error humano** se deben en realidad a un **mal diseño**: mandos parecidos que hacen cosas muy distintas, pantallas confusas o alarmas que suenan tanto que se ignoran. En la aviación, revisar el diseño de las cabinas y la comunicación entre pilotos redujo mucho los accidentes. El objetivo es crear sistemas que hagan difícil equivocarse y fácil detectar los errores.", "evidencia": ["se deben en realidad a un mal diseño"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('3d584a45-2822-5af6-b576-05f67b904f36', 'f11-tra-14', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'cb6fe6be-b131-5c2f-a843-94b7a3c90640', 'd5d6778b-5a26-5d92-a088-99444520fcd6', 'verdadero_falso_razonado', 'Las listas de verificación en cirugía son innecesarias si el equipo tiene experiencia.', null, '{"razones": ["Falso, porque sustituyen al cirujano.", "Verdadero, porque los expertos no se equivocan.", "Falso, porque reducen complicaciones al no depender de la memoria bajo presión."]}'::jsonb, null, 1, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('3d584a45-2822-5af6-b576-05f67b904f36', '{"valor": false, "razon": 2}'::jsonb, 'Incluso los expertos se benefician de no depender solo de la memoria.', '{"leccion": "factores-humanos", "bloque": "b5", "titulo": "Factores humanos y ergonomía", "fragmento": "Una herramienta sencilla y eficaz son las **listas de verificación**. La Organización Mundial de la Salud promovió una lista para los quirófanos, con pasos antes de la anestesia, antes de la incisión y antes de que el paciente salga del quirófano. Su uso se asoció a una reducción importante de complicaciones y muertes. Funcionan porque no dependen de que la memoria y la atención estén perfectas en un momento de presión.", "evidencia": ["Su uso se asoció a una reducción importante de complicaciones y muertes"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('d53d7787-d1c4-5dc3-b961-5b2723b73e9c', 'f11-tra-15', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'cb6fe6be-b131-5c2f-a843-94b7a3c90640', 'd5d6778b-5a26-5d92-a088-99444520fcd6', 'seleccion_multiple', '¿A qué altura conviene colocar la pantalla del ordenador?', null, '{"opciones": ["Muy por encima de los ojos", "En el regazo", "Lo más lejos posible", "A la altura de los ojos o algo por debajo"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
