insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('d53d7787-d1c4-5dc3-b961-5b2723b73e9c', '{"correcta": [3]}'::jsonb, 'Así se evita forzar el cuello.', '{"leccion": "factores-humanos", "bloque": "b8", "titulo": "Factores humanos y ergonomía", "fragmento": "Recomendaciones para un puesto con pantalla: Pantalla | A la altura de los ojos o algo por debajo y a un brazo de distancia · Silla | Con apoyo lumbar y los pies apoyados en el suelo · Teclado y ratón | Cerca, con los codos en ángulo recto y las muñecas rectas · Pausas | Levantarse y cambiar de postura con frecuencia · Iluminación | Sin reflejos en la pantalla", "evidencia": ["A la altura de los ojos o algo por debajo"]}'::jsonb)
