values ('206f623e-8072-51c3-bba8-644e31d84a70', 'f11-tra-16', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'cb6fe6be-b131-5c2f-a843-94b7a3c90640', 'd5d6778b-5a26-5d92-a088-99444520fcd6', 'respuesta_breve', '¿Qué derecho reconocido en España protege a quien teletrabaja de estar siempre disponible?', null, '{}'::jsonb, null, 2, array['fase11','respuesta_breve']::text[], 'Material integrado del tema', 'publicada')
