insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('8c06b5fe-9acc-52bd-a45c-52f504c12d1d', 'f11-est-1', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '287401d4-a27d-58e8-af83-cfebb38d4767', 'a6f000ba-9601-5c9d-abc4-7e971ab61fac', 'relacionar', 'Relaciona cada concepto con su definición.', null, '{"izquierda": ["Distrés", "Eustrés", "Valoración primaria", "Valoración secundaria"], "derecha": ["Decidir si la situación es una amenaza o un reto", "Decidir si se tienen recursos para afrontarla", "Estrés negativo que desborda", "Estrés positivo que activa ante un reto"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('8c06b5fe-9acc-52bd-a45c-52f504c12d1d', '{"pares": {"Eustrés": "Estrés positivo que activa ante un reto", "Distrés": "Estrés negativo que desborda", "Valoración primaria": "Decidir si la situación es una amenaza o un reto", "Valoración secundaria": "Decidir si se tienen recursos para afrontarla"}}'::jsonb, 'El estrés depende de cómo valoramos la situación y nuestros recursos.', '{"leccion": "que-es-el-estres", "bloque": "b2", "titulo": "Qué es el estrés y cómo responde el cuerpo", "fragmento": "El **estrés** es el proceso por el que percibimos y respondemos a sucesos, llamados **estresores**, que valoramos como amenazantes o desafiantes. No todo el estrés es malo: el **eustrés** es el estrés positivo que nos activa ante un reto, como preparar un viaje ilusionante. El **distrés** es el negativo, que nos desborda. Un nivel moderado de estrés mejora el rendimiento, mientras que uno excesivo lo empeora. Para **Richard Lazarus**, lo que genera estrés no es el suceso en sí, sino cómo lo valoramos. En la **valoración primaria** nos preguntamos si la situación es irrelevante, positiva o amenazante. En la **valoración secundaria**, si tenemos recursos para afrontarla. Una misma entrevista de trabajo puede ser un desafío estimulante para quien se siente preparado y una amenaza para quien cree que no lo está.", "evidencia": ["el eustrés es el estrés positivo que nos activa ante un reto"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
