values ('342d5400-758f-56fd-ab74-716f46183537', 'f11-est-2', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '287401d4-a27d-58e8-af83-cfebb38d4767', 'a6f000ba-9601-5c9d-abc4-7e971ab61fac', 'ordenar', 'Ordena las fases del síndrome general de adaptación de Selye.', null, '{"elementos": ["Agotamiento", "Alarma", "Resistencia"]}'::jsonb, null, 1, array['fase11','ordenar']::text[], 'Material integrado del tema', 'publicada')
