insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('342d5400-758f-56fd-ab74-716f46183537', '{"orden": ["Alarma", "Resistencia", "Agotamiento"]}'::jsonb, 'Si el estrés continúa, tras resistir llega el agotamiento.', '{"leccion": "que-es-el-estres", "bloque": "b9", "titulo": "Qué es el estrés y cómo responde el cuerpo", "fragmento": "Las fases del síndrome general de adaptación: Alarma: el cuerpo detecta el estresor y activa la respuesta de lucha o huida.; Resistencia: el cuerpo se adapta y mantiene la activación para afrontar el estrés.; Agotamiento: si el estrés continúa, se agotan los recursos y aumenta el riesgo de enfermar.", "evidencia": ["Agotamiento: si el estrés continúa, se agotan los recursos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('b801bed8-400b-528f-af0f-4ac1c7e9f0af', 'f11-est-3', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '287401d4-a27d-58e8-af83-cfebb38d4767', 'a6f000ba-9601-5c9d-abc4-7e971ab61fac', 'seleccion_multiple', '¿Qué ocurre en la respuesta de lucha o huida?', null, '{"opciones": ["Se reduce la glucosa en sangre", "Baja la tensión arterial y se activa la digestión", "Se acelera el corazón, aumenta la respiración y se frena la digestión", "Se activa el sistema parasimpático"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('b801bed8-400b-528f-af0f-4ac1c7e9f0af', '{"correcta": [2]}'::jsonb, 'El sistema simpático prepara el cuerpo para actuar ante el peligro.', '{"leccion": "que-es-el-estres", "bloque": "b6", "titulo": "Qué es el estrés y cómo responde el cuerpo", "fragmento": "A principios del siglo XX, **Walter Cannon** describió la respuesta de **lucha o huida**: ante una amenaza, el sistema nervioso simpático acelera el corazón, aumenta la respiración y la tensión arterial, libera glucosa para tener energía y frena la digestión. Es una reacción muy útil ante un peligro físico breve, como un coche que se nos echa encima, pero el cuerpo la activa también ante amenazas sociales o imaginadas.", "evidencia": ["acelera el corazón, aumenta la respiración y la tensión arterial"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('5c022878-dd67-532d-85e9-06894b855649', 'f11-est-4', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '287401d4-a27d-58e8-af83-cfebb38d4767', 'a6f000ba-9601-5c9d-abc4-7e971ab61fac', 'verdadero_falso_razonado', 'El cortisol es beneficioso aunque se mantenga elevado mucho tiempo.', null, '{"razones": ["Falso, porque el cortisol no interviene en el estrés.", "Falso, mantenido mucho tiempo debilita las defensas y daña el organismo.", "Verdadero, porque siempre reduce la inflamación."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
