insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('5c022878-dd67-532d-85e9-06894b855649', '{"valor": false, "razon": 1}'::jsonb, 'A corto plazo es útil; a largo plazo, perjudicial.', '{"leccion": "que-es-el-estres", "bloque": "b10", "titulo": "Qué es el estrés y cómo responde el cuerpo", "fragmento": "Además de la vía rápida del sistema simpático, hay una vía hormonal más lenta: el **eje hipotálamo hipófiso suprarrenal**. El hipotálamo estimula a la hipófisis, que a su vez estimula a las glándulas suprarrenales para que liberen **cortisol**, la principal hormona del estrés. El cortisol moviliza energía y reduce la inflamación a corto plazo, pero, mantenido mucho tiempo, debilita las defensas y daña el organismo.", "evidencia": ["mantenido mucho tiempo, debilita las defensas y daña el organismo"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('601f112c-dcfe-5d5a-9714-3f87e525a0f7', 'f11-est-5', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '287401d4-a27d-58e8-af83-cfebb38d4767', '5eb094b0-f23a-5fd7-89ef-a2bb10f5bde3', 'seleccion_multiple', '¿Qué acontecimiento tiene la puntuación más alta en la escala de Holmes y Rahe?', null, '{"opciones": ["Las vacaciones", "La muerte del cónyuge", "El matrimonio", "El cambio de residencia"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
