insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('601f112c-dcfe-5d5a-9714-3f87e525a0f7', '{"correcta": [1]}'::jsonb, 'Es el suceso que más reajuste exige según la escala.', '{"leccion": "fuentes-de-estres", "bloque": "b3", "titulo": "De dónde viene el estrés", "fragmento": "Algunos acontecimientos de la escala de Holmes y Rahe: Muerte del cónyuge | 100 · Divorcio | 73 · Matrimonio | 50 · Despido | 47 · Cambio de residencia | 20 · Vacaciones | 13", "evidencia": ["Muerte del cónyuge"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('f696e5ca-e96d-50dc-a9e4-59f7e559894a', 'f11-est-6', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '287401d4-a27d-58e8-af83-cfebb38d4767', '5eb094b0-f23a-5fd7-89ef-a2bb10f5bde3', 'verdadero_falso_razonado', 'Solo los acontecimientos negativos producen estrés.', null, '{"razones": ["Falso, porque sucesos positivos como casarse también exigen adaptarse.", "Verdadero, porque lo positivo siempre relaja.", "Falso, porque ningún acontecimiento produce estrés."]}'::jsonb, null, 1, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('f696e5ca-e96d-50dc-a9e4-59f7e559894a', '{"valor": false, "razon": 0}'::jsonb, 'Todo cambio importante exige reajuste.', '{"leccion": "fuentes-de-estres", "bloque": "b2", "titulo": "De dónde viene el estrés", "fragmento": "En los años sesenta, **Thomas Holmes y Richard Rahe** elaboraron una escala de **acontecimientos vitales**, puntuados según el reajuste que exigen. En lo más alto estaba la muerte del cónyuge, seguida del divorcio, la separación o la cárcel. También incluía sucesos positivos, como casarse, tener un hijo o unas vacaciones, porque todo cambio exige adaptarse. Las personas que acumulaban muchas puntuaciones en un año tenían más probabilidades de enfermar.", "evidencia": ["porque todo cambio exige adaptarse"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('72d2e85c-19cf-5a73-a524-a55726471a60', 'f11-est-7', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '287401d4-a27d-58e8-af83-cfebb38d4767', '5eb094b0-f23a-5fd7-89ef-a2bb10f5bde3', 'seleccion_multiple', '¿Qué dicen algunos estudios sobre las contrariedades diarias?', null, '{"opciones": ["Que eliminan el efecto de los grandes sucesos", "Que solo afectan a los niños", "Que no influyen en la salud", "Que predicen problemas de salud tanto o más que los grandes acontecimientos"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('72d2e85c-19cf-5a73-a524-a55726471a60', '{"correcta": [3]}'::jsonb, 'Las pequeñas molestias acumuladas pesan.', '{"leccion": "fuentes-de-estres", "bloque": "b6", "titulo": "De dónde viene el estrés", "fragmento": "Las **contrariedades diarias**, como el tráfico, las colas, perder las llaves o discutir con un compañero, parecen menores, pero se acumulan. Algunos estudios encuentran que predicen problemas de salud tanto o más que los grandes acontecimientos. Del mismo modo, las pequeñas **satisfacciones diarias** ayudan a compensarlas.", "evidencia": ["predicen problemas de salud tanto o más que los grandes acontecimientos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
