values ('42c684b3-0686-56f6-8ed6-1d2e720b0f8f', 'f11-est-8', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '287401d4-a27d-58e8-af83-cfebb38d4767', '5eb094b0-f23a-5fd7-89ef-a2bb10f5bde3', 'respuesta_breve', 'El estrés que se mantiene durante mucho tiempo se llama estrés ___.', null, '{"completar": true}'::jsonb, null, 1, array['fase11','completar']::text[], 'Material integrado del tema', 'publicada')
