insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('42c684b3-0686-56f6-8ed6-1d2e720b0f8f', '{"aceptadas": ["crónico", "cronico"], "solucion": "crónico"}'::jsonb, 'Sus fuentes incluyen el trabajo, la pobreza y la discriminación.', '{"leccion": "fuentes-de-estres", "bloque": "b8", "titulo": "De dónde viene el estrés", "fragmento": "El **estrés crónico** es el que se mantiene durante mucho tiempo. Una fuente importante es el **trabajo**: mucha exigencia con poco control, inseguridad laboral o falta de reconocimiento. Otra es la **desigualdad**: vivir en la pobreza, en barrios con violencia o sufrir **discriminación** de forma repetida mantiene activada la respuesta de estrés. Cuidar durante años de un familiar dependiente es otra fuente de estrés crónico muy estudiada.", "evidencia": ["El estrés crónico es el que se mantiene durante mucho tiempo"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('20c597fc-5d16-5ea7-9f94-1f449e3b6bf7', 'f11-est-9', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '287401d4-a27d-58e8-af83-cfebb38d4767', '38af4826-ccb8-52da-9a95-9f50f98722fb', 'seleccion_multiple', '¿Qué componente del patrón tipo A se asocia más al riesgo de infarto?', null, '{"opciones": ["La hostilidad", "La competitividad deportiva", "La puntualidad", "El perfeccionismo en el orden"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('20c597fc-5d16-5ea7-9f94-1f449e3b6bf7', '{"correcta": [0]}'::jsonb, 'La desconfianza y el enfado frecuentes son lo realmente dañino.', '{"leccion": "estres-y-enfermedad", "bloque": "b3", "titulo": "Estrés y enfermedad", "fragmento": "En los años cincuenta, dos cardiólogos describieron el **patrón de conducta tipo A**: personas competitivas, impacientes, con prisa constante y hostiles. Parecían tener más infartos. Investigaciones posteriores mostraron que el componente realmente dañino es la **hostilidad**, la desconfianza y el enfado frecuentes hacia los demás. La **depresión** también se asocia a más riesgo cardiaco y peor recuperación tras un infarto.", "evidencia": ["el componente realmente dañino es la hostilidad"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('a4f383f5-6f04-56ef-8358-ddaab3b403b6', 'f11-est-10', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '287401d4-a27d-58e8-af83-cfebb38d4767', '38af4826-ccb8-52da-9a95-9f50f98722fb', 'caso_clinico', '¿Qué explica mejor lo que le ocurre?', 'Rocío lleva tres años cuidando a su madre con demencia. Se resfría con mucha frecuencia y un pequeño corte en la mano tardó semanas en curarse.', '{"opciones": ["Tiene mala suerte", "El cuidado mejora sus defensas", "Sufre indefensión aprendida por los resfriados", "El estrés crónico ha debilitado su sistema inmunitario"]}'::jsonb, null, 2, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('a4f383f5-6f04-56ef-8358-ddaab3b403b6', '{"correcta": [3]}'::jsonb, 'La psiconeuroinmunología muestra que el estrés mantenido debilita las defensas.', '{"leccion": "estres-y-enfermedad", "bloque": "b6", "titulo": "Estrés y enfermedad", "fragmento": "La **psiconeuroinmunología** estudia cómo se relacionan la mente, el sistema nervioso y el sistema inmunitario. El cortisol mantenido debilita las defensas. Se ha visto que las heridas cicatrizan más despacio en personas estresadas, como los cuidadores de familiares con demencia, y que las personas con más estrés se resfrían con más facilidad al exponerse al virus. El estrés también empeora enfermedades como el **asma**.", "evidencia": ["las heridas cicatrizan más despacio en personas estresadas"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('620d4982-b156-590d-ae27-da8126e8cccd', 'f11-est-11', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '287401d4-a27d-58e8-af83-cfebb38d4767', '38af4826-ccb8-52da-9a95-9f50f98722fb', 'relacionar', 'Relaciona cada estilo explicativo con su consecuencia.', null, '{"izquierda": ["Indefensión aprendida", "Optimista", "Pesimista"], "derecha": ["Dejar de intentar cambiar la situación", "Más persistencia y mejor salud", "Más riesgo de indefensión y depresión"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
