insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('620d4982-b156-590d-ae27-da8126e8cccd', '{"pares": {"Pesimista": "Más riesgo de indefensión y depresión", "Optimista": "Más persistencia y mejor salud", "Indefensión aprendida": "Dejar de intentar cambiar la situación"}}'::jsonb, 'Cómo explicamos los fracasos influye en cómo afrontamos los siguientes.', '{"leccion": "estres-y-enfermedad", "bloque": "b10", "titulo": "Estrés y enfermedad", "fragmento": "Dos formas de explicar un fracaso: Pesimista | Es culpa mía, siempre me pasa y afecta a todo | Más riesgo de indefensión y depresión · Optimista | Ha sido esta vez, por esta situación concreta | Más persistencia y mejor salud **Martin Seligman** observó que perros que habían recibido descargas que no podían evitar, más tarde, en una situación en la que sí podían escapar saltando una barrera, no lo intentaban. Habían aprendido que hicieran lo que hicieran no cambiaría nada. Lo llamó **indefensión aprendida**. En las personas se relaciona con la depresión: cuando alguien cree que no tiene control sobre lo que le pasa, deja de intentar cambiarlo.", "evidencia": ["Más riesgo de indefensión y depresión"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('4aa8d410-1762-57ef-87bf-45c433c14773', 'f11-est-12', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '287401d4-a27d-58e8-af83-cfebb38d4767', '38af4826-ccb8-52da-9a95-9f50f98722fb', 'seleccion_multiple', 'En las mujeres, ¿qué síntomas de infarto son más habituales que en los hombres?', null, '{"opciones": ["Náuseas, falta de aire, cansancio o dolor en la espalda o la mandíbula", "Picor en los brazos", "Solo dolor intenso en el pecho", "Fiebre alta"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
