insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('4aa8d410-1762-57ef-87bf-45c433c14773', '{"correcta": [0]}'::jsonb, 'Reconocerlos permite actuar a tiempo y llamar al 112.', '{"leccion": "estres-y-enfermedad", "bloque": "b4", "titulo": "Estrés y enfermedad", "fragmento": "Reconocer un infarto. El síntoma más frecuente es el dolor o la presión en el pecho, pero en las mujeres es más habitual que aparezcan náuseas, falta de aire, cansancio o dolor en la espalda o la mandíbula. Ante la sospecha, llama al 112 de inmediato.", "evidencia": ["en las mujeres es más habitual que aparezcan náuseas, falta de aire, cansancio"]}'::jsonb)
