values ('11fc0874-ad6f-5213-8c53-a54b063a62a4', 'f11-est-13', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '287401d4-a27d-58e8-af83-cfebb38d4767', 'a3adc9b9-7b97-5bd8-a920-059120f48aaa', 'relacionar', 'Relaciona cada tipo de afrontamiento con su ejemplo.', null, '{"izquierda": ["Centrado en el problema", "Centrado en la emoción", "Evitación"], "derecha": ["Hacer un plan de estudio por semanas", "Recurrir al alcohol para no pensar", "Salir a caminar y hablar con una amiga"]}'::jsonb, null, 1, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
