insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('11fc0874-ad6f-5213-8c53-a54b063a62a4', '{"pares": {"Centrado en el problema": "Hacer un plan de estudio por semanas", "Centrado en la emoción": "Salir a caminar y hablar con una amiga", "Evitación": "Recurrir al alcohol para no pensar"}}'::jsonb, 'La evitación alivia a corto plazo pero empeora las cosas.', '{"leccion": "afrontar-y-bienestar", "bloque": "b3", "titulo": "Afrontar el estrés y cultivar el bienestar", "fragmento": "Dos tipos de afrontamiento: Centrado en el problema | Cambiar la situación | Hacer un plan de estudio por semanas · Centrado en la emoción | Manejar lo que sentimos | Salir a caminar y hablar con una amiga El **afrontamiento** son los esfuerzos para manejar las situaciones estresantes. El **centrado en el problema** intenta cambiar la situación: organizar el tiempo, pedir información o buscar soluciones. El **centrado en la emoción** intenta manejar lo que sentimos: hablar con alguien, relajarse o ver la situación de otra manera. El primero suele funcionar mejor cuando la situación se puede cambiar, y el segundo cuando no. Evitar el problema o recurrir al alcohol alivia a corto plazo pero empeora las cosas.", "evidencia": ["Hacer un plan de estudio por semanas"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('2537692c-5c4b-5170-ba86-7e54e8f71a5a', 'f11-est-14', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '287401d4-a27d-58e8-af83-cfebb38d4767', 'a3adc9b9-7b97-5bd8-a920-059120f48aaa', 'seleccion_multiple', '¿Qué factor protege mucho frente al estrés y se asocia a vivir más?', null, '{"opciones": ["Trabajar más horas", "Evitar los problemas", "El apoyo social", "El aislamiento"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('2537692c-5c4b-5170-ba86-7e54e8f71a5a', '{"correcta": [2]}'::jsonb, 'Las buenas relaciones protegen la salud.', '{"leccion": "afrontar-y-bienestar", "bloque": "b4", "titulo": "Afrontar el estrés y cultivar el bienestar", "fragmento": "Dos factores protegen mucho. El **control percibido**: sentir que podemos influir en lo que nos pasa reduce el impacto del estrés, incluso si no usamos ese control. Y el **apoyo social**: las personas con buenas relaciones viven más, enferman menos y se recuperan antes. El aislamiento social es un factor de riesgo para la salud comparable a otros más conocidos.", "evidencia": ["las personas con buenas relaciones viven más"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('9da0de08-7990-5fdf-8cde-d612fba0cf87', 'f11-est-15', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', '287401d4-a27d-58e8-af83-cfebb38d4767', 'a3adc9b9-7b97-5bd8-a920-059120f48aaa', 'verdadero_falso_razonado', 'Ganar la lotería hace a las personas permanentemente mucho más felices.', null, '{"razones": ["Falso, porque el dinero nunca influye en la felicidad.", "Falso, por la adaptación hedónica la felicidad vuelve con el tiempo a su nivel habitual.", "Verdadero, porque el dinero aumenta siempre la felicidad."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('9da0de08-7990-5fdf-8cde-d612fba0cf87', '{"valor": false, "razon": 1}'::jsonb, 'El dinero ayuda a cubrir necesidades, pero su efecto se diluye.', '{"leccion": "afrontar-y-bienestar", "bloque": "b9", "titulo": "Afrontar el estrés y cultivar el bienestar", "fragmento": "Un hallazgo sorprendente es la **adaptación hedónica**: tras un gran cambio, bueno o malo, como ganar la lotería o sufrir un accidente, la felicidad tiende a volver con el tiempo a su nivel habitual. El dinero aumenta la felicidad cuando cubre las necesidades básicas, pero a partir de cierto punto añade cada vez menos. Lo que más se asocia a la felicidad son las buenas relaciones, el sentido de lo que hacemos y prácticas como la **gratitud** y ayudar a otros.", "evidencia": ["la felicidad tiende a volver con el tiempo a su nivel habitual"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
