insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('84d7023c-c495-5965-b733-85068431f5ef', '{"correcta": [3]}'::jsonb, 'Ni la rareza ni romper normas bastan por sí solas.', '{"leccion": "que-es-un-trastorno", "bloque": "b3", "titulo": "Qué es un trastorno psicológico", "fragmento": "Lo que suele indicar un trastorno: Malestar significativo para la persona.; Interferencia en el trabajo, los estudios, las relaciones o el cuidado de uno mismo.; Pensamientos, emociones o conductas poco habituales en su contexto cultural.; Duración suficiente, no una reacción breve y esperable ante un suceso.", "evidencia": ["Malestar significativo para la persona"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
