insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('9872847a-a698-582f-9241-ba9530825e3e', '{"pares": {"Sobrenatural": "Posesión, brujería o castigo divino", "Biológica": "Genes, química cerebral y alteraciones del cerebro", "Diátesis y estrés": "Una vulnerabilidad previa más un estrés desencadenante"}}'::jsonb, 'El modelo de diátesis y estrés integra lo biológico y lo ambiental.', '{"leccion": "que-es-un-trastorno", "bloque": "b9", "titulo": "Qué es un trastorno psicológico", "fragmento": "Perspectivas sobre los trastornos: Sobrenatural | Posesión, brujería o castigo divino | Edad Media: exorcismos y la «piedra de la locura» · Biológica | Genes, química cerebral y alteraciones del cerebro | Estudios de gemelos y neuroimagen · Psicológica | Aprendizaje, pensamientos y experiencias | Modelos cognitivos y conductuales · Diátesis y estrés | Una vulnerabilidad previa más un estrés desencadenante | Modelo integrador actual", "evidencia": ["Una vulnerabilidad previa más un estrés desencadenante"]}'::jsonb)
