insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('2ac725d9-fcf0-53ab-b619-bc62e9ca69aa', 'f11-tras-3', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd2e85041-8f26-57e1-8402-42ca488be33e', '88b42530-9af7-5a45-aeda-8b2039098527', 'verdadero_falso_razonado', 'Los trastornos psicológicos son poco frecuentes en la población.', null, '{"razones": ["Verdadero, solo los sufre una de cada mil personas.", "Falso, alrededor de una de cada cuatro o cinco personas sufrirá alguno en su vida.", "Falso, porque todo el mundo tiene uno."]}'::jsonb, null, 1, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('2ac725d9-fcf0-53ab-b619-bc62e9ca69aa', '{"valor": false, "razon": 1}'::jsonb, 'Son muy frecuentes y a menudo aparecen juntos.', '{"leccion": "que-es-un-trastorno", "bloque": "b7", "titulo": "Qué es un trastorno psicológico", "fragmento": "Los trastornos psicológicos son muy frecuentes: se estima que alrededor de una de cada cuatro o cinco personas sufrirá alguno a lo largo de su vida. Es habitual la **comorbilidad**, que una misma persona tenga más de un trastorno a la vez, como ansiedad y depresión.", "evidencia": ["alrededor de una de cada cuatro o cinco personas"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
