insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('21cacd40-760c-579b-a504-4e6dc173aded', '{"pares": {"Fobia específica": "Miedo intenso e irracional a un objeto o situación concretos", "Ansiedad social": "Miedo intenso a ser evaluado o a hacer el ridículo ante los demás", "Agorafobia": "Miedo a lugares de los que sería difícil escapar o recibir ayuda", "Ansiedad generalizada": "Preocupación excesiva y difícil de controlar sobre muchos temas"}}'::jsonb, 'Todos implican ansiedad excesiva, pero ante situaciones distintas.', '{"leccion": "ansiedad-toc-y-tept", "bloque": "b3", "titulo": "Ansiedad, TOC y estrés postraumático", "fragmento": "Principales trastornos de ansiedad: Fobia específica | Miedo intenso e irracional a un objeto o situación concretos, como las alturas o las arañas · Ansiedad social | Miedo intenso a ser evaluado o a hacer el ridículo ante los demás · Trastorno de pánico | Crisis repentinas de miedo intenso y temor persistente a que se repitan · Agorafobia | Miedo a lugares de los que sería difícil escapar o recibir ayuda · Ansiedad generalizada | Preocupación excesiva y difícil de controlar sobre muchos temas", "evidencia": ["Miedo a lugares de los que sería difícil escapar o recibir ayuda"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('937269b6-877f-5151-8a74-84f1acd715e7', 'f11-tras-6', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd2e85041-8f26-57e1-8402-42ca488be33e', '02c8215c-d6c9-5a9b-95a9-49604e1cb20d', 'caso_clinico', '¿Qué trastorno es más probable?', 'Laura vuelve a casa varias veces cada mañana para comprobar que ha cerrado la puerta, aunque lo recuerda. Si no lo hace, siente una angustia insoportable. Llega tarde al trabajo casi todos los días.', '{"opciones": ["Trastorno de pánico", "Trastorno obsesivo compulsivo", "Trastorno bipolar", "Fobia específica"]}'::jsonb, null, 2, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('937269b6-877f-5151-8a74-84f1acd715e7', '{"correcta": [1]}'::jsonb, 'La obsesión por la puerta abierta genera angustia y la comprobación es una compulsión.', '{"leccion": "ansiedad-toc-y-tept", "bloque": "b6", "titulo": "Ansiedad, TOC y estrés postraumático", "fragmento": "En el **trastorno obsesivo compulsivo** aparecen **obsesiones**, pensamientos, imágenes o impulsos intrusivos que generan mucha angustia, como el miedo a contaminarse o a haber dejado la puerta abierta. Para reducir esa angustia, la persona realiza **compulsiones**, conductas o actos mentales repetitivos, como lavarse las manos muchas veces o comprobar la cerradura una y otra vez. El alivio es breve y refuerza el ciclo. Relacionados con el TOC están el **trastorno por acumulación** y el **trastorno dismórfico corporal**, la preocupación excesiva por un defecto físico mínimo o inexistente.", "evidencia": ["comprobar la cerradura una y otra vez"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('a0564805-3372-576b-bd7f-05c47dc82c48', 'f11-tras-7', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd2e85041-8f26-57e1-8402-42ca488be33e', '02c8215c-d6c9-5a9b-95a9-49604e1cb20d', 'seleccion_multiple', '¿Qué ocurre con la mayoría de personas que viven un suceso traumático?', null, '{"opciones": ["Desarrollan esquizofrenia", "No desarrollan TEPT", "Pierden la memoria del suceso", "Desarrollan TEPT siempre"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
