insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('a0564805-3372-576b-bd7f-05c47dc82c48', '{"correcta": [1]}'::jsonb, 'El riesgo depende del suceso, de la historia previa y del apoyo social.', '{"leccion": "ansiedad-toc-y-tept", "bloque": "b10", "titulo": "Ansiedad, TOC y estrés postraumático", "fragmento": "La mayoría de las personas que viven un trauma no desarrollan TEPT. Aumentan el riesgo la gravedad del suceso, haber sufrido otros traumas, la falta de apoyo social y una respuesta de estrés más intensa. El **apoyo social** tras el suceso es uno de los factores de protección más importantes.", "evidencia": ["La mayoría de las personas que viven un trauma no desarrollan TEPT"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
