values ('d9e26c60-6abb-5ebe-927a-bbf900bf0736', 'f11-tras-8', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd2e85041-8f26-57e1-8402-42ca488be33e', '02c8215c-d6c9-5a9b-95a9-49604e1cb20d', 'ordenar', 'Ordena los grupos de síntomas del TEPT tal como se presentan.', null, '{"elementos": ["Cambios negativos en el ánimo", "Evitación", "Hiperactivación", "Reexperimentación"]}'::jsonb, null, 1, array['fase11','ordenar']::text[], 'Material integrado del tema', 'publicada')
