insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('d9e26c60-6abb-5ebe-927a-bbf900bf0736', '{"orden": ["Reexperimentación", "Evitación", "Cambios negativos en el ánimo", "Hiperactivación"]}'::jsonb, 'Son los cuatro grupos de síntomas del TEPT.', '{"leccion": "ansiedad-toc-y-tept", "bloque": "b9", "titulo": "Ansiedad, TOC y estrés postraumático", "fragmento": "Grupos de síntomas del TEPT: Reexperimentación: recuerdos intrusivos, pesadillas, sensación de revivirlo.; Evitación de lugares, personas o pensamientos que recuerdan el trauma.; Cambios negativos en el ánimo y en las creencias sobre uno mismo y el mundo.; Hiperactivación: sobresaltos, irritabilidad, problemas de sueño y concentración.", "evidencia": ["Hiperactivación: sobresaltos, irritabilidad"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('fa3c52b2-8bc5-594c-a219-65af46dc5465', 'f11-tras-9', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd2e85041-8f26-57e1-8402-42ca488be33e', '4da0fc77-3162-5b80-87ea-f786343dd2e3', 'caso_clinico', '¿Qué es lo más probable?', 'Desde hace un mes, Andrés apenas disfruta de nada, duerme mal, ha perdido el apetito, le cuesta concentrarse y piensa que no vale nada y que su vida nunca va a mejorar.', '{"opciones": ["Un episodio depresivo mayor", "Esquizofrenia", "Tristeza normal sin importancia", "Un episodio maníaco"]}'::jsonb, null, 2, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('fa3c52b2-8bc5-594c-a219-65af46dc5465', '{"correcta": [0]}'::jsonb, 'Cumple la duración y varios síntomas típicos, incluida la tríada cognitiva negativa.', '{"leccion": "animo-y-esquizofrenia", "bloque": "b2", "titulo": "Trastornos del estado de ánimo y esquizofrenia", "fragmento": "El **trastorno depresivo mayor** se caracteriza por un ánimo triste o una **pérdida de interés** o de placer casi todos los días durante al menos dos semanas, junto con otros síntomas: cambios en el sueño y el apetito, cansancio, dificultad para concentrarse, sentimientos de culpa o inutilidad y pensamientos de muerte. No es simple tristeza: interfiere de forma clara en la vida. Es una de las principales causas de discapacidad en el mundo y es más frecuente en mujeres. En la depresión influyen factores genéticos, alteraciones en neurotransmisores como la serotonina y en el eje del estrés, y factores psicológicos. **Aaron Beck** describió la **tríada cognitiva**: una visión negativa de uno mismo («no valgo nada»), del mundo («todo me sale mal») y del futuro («nunca va a mejorar»). La indefensión aprendida y el estilo explicativo pesimista, que vimos en el tema del estrés, también contribuyen.", "evidencia": ["una visión negativa de uno mismo"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('ade6f679-9fe6-5741-b721-8d0607647eb5', 'f11-tras-10', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd2e85041-8f26-57e1-8402-42ca488be33e', '4da0fc77-3162-5b80-87ea-f786343dd2e3', 'relacionar', 'Relaciona cada tipo de síntoma de la esquizofrenia con su ejemplo.', null, '{"izquierda": ["Desorganización", "Negativos", "Positivos"], "derecha": ["Falta de motivación y aplanamiento emocional", "Lenguaje y conducta desorganizados", "Oír voces o sentirse perseguido"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('ade6f679-9fe6-5741-b721-8d0607647eb5', '{"pares": {"Positivos": "Oír voces o sentirse perseguido", "Desorganización": "Lenguaje y conducta desorganizados", "Negativos": "Falta de motivación y aplanamiento emocional"}}'::jsonb, 'Los positivos se añaden a la experiencia; los negativos son pérdidas.', '{"leccion": "animo-y-esquizofrenia", "bloque": "b8", "titulo": "Trastornos del estado de ánimo y esquizofrenia", "fragmento": "Síntomas de la esquizofrenia: Positivos | Alucinaciones, como oír voces; delirios, creencias falsas firmes como sentirse perseguido · Desorganización | Lenguaje y conducta desorganizados · Negativos | Falta de motivación, aplanamiento emocional, pobreza del lenguaje, aislamiento", "evidencia": ["Lenguaje y conducta desorganizados"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('b58d24d6-22ad-5cfb-a00d-b113c6bfaa0b', 'f11-tras-11', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd2e85041-8f26-57e1-8402-42ca488be33e', '4da0fc77-3162-5b80-87ea-f786343dd2e3', 'verdadero_falso_razonado', 'Preguntar directamente a alguien si piensa en suicidarse aumenta el riesgo.', null, '{"razones": ["Verdadero, porque le da la idea.", "Falso, porque el suicidio no tiene señales de alarma.", "Falso, no aumenta el riesgo y puede abrir la puerta a pedir ayuda."]}'::jsonb, null, 1, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('b58d24d6-22ad-5cfb-a00d-b113c6bfaa0b', '{"valor": false, "razon": 2}'::jsonb, 'Hablar abiertamente ayuda; en España se puede llamar al 024.', '{"leccion": "animo-y-esquizofrenia", "bloque": "b5", "titulo": "Trastornos del estado de ánimo y esquizofrenia", "fragmento": "Si piensas en hacerte daño. Los pensamientos de suicidio son un síntoma que puede tratarse, no una salida. Señales de alarma son hablar de querer morir o de ser una carga, despedirse, regalar objetos queridos o aislarse. Si te ocurre a ti o a alguien cercano, pide ayuda ya: en España, llama al 024, la línea de atención a la conducta suicida, o al 112 si hay peligro inmediato. Preguntar directamente a alguien si piensa en suicidarse no aumenta el riesgo y puede abrir la puerta a pedir ayuda.", "evidencia": ["no aumenta el riesgo y puede abrir la puerta a pedir ayuda"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('48a9518f-317f-5923-8e71-c10850922488', 'f11-tras-12', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd2e85041-8f26-57e1-8402-42ca488be33e', '4da0fc77-3162-5b80-87ea-f786343dd2e3', 'verdadero_falso_razonado', 'La esquizofrenia consiste en tener una doble personalidad.', null, '{"razones": ["Verdadero, así lo describe el DSM.", "Falso, es una pérdida parcial de contacto con la realidad, no una doble personalidad.", "Falso, porque la esquizofrenia no existe."]}'::jsonb, null, 1, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('48a9518f-317f-5923-8e71-c10850922488', '{"valor": false, "razon": 1}'::jsonb, 'Es una confusión muy extendida con el trastorno de identidad disociativo.', '{"leccion": "animo-y-esquizofrenia", "bloque": "b7", "titulo": "Trastornos del estado de ánimo y esquizofrenia", "fragmento": "La **esquizofrenia** es un trastorno grave que afecta a alrededor del uno por ciento de la población y suele empezar al final de la adolescencia o al inicio de la adultez. La persona pierde en parte el contacto con la realidad. No tiene nada que ver con tener una «doble personalidad», una confusión muy extendida.", "evidencia": ["No tiene nada que ver con tener una «doble personalidad»"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('ab23d493-bd4d-5049-b06f-ca627bacbe9e', 'f11-tras-13', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd2e85041-8f26-57e1-8402-42ca488be33e', '1b3943b1-c4ef-56cf-ae5f-33ccaf46d27a', 'seleccion_multiple', '¿Qué caracteriza al trastorno del espectro autista?', null, '{"opciones": ["Dificultades en la comunicación social e intereses o conductas restringidos y repetitivos", "Miedo a ser evaluado", "Episodios de euforia y depresión", "Alucinaciones y delirios"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('ab23d493-bd4d-5049-b06f-ca627bacbe9e', '{"correcta": [0]}'::jsonb, 'Su intensidad y necesidades de apoyo varían mucho, de ahí el término espectro.', '{"leccion": "otros-trastornos", "bloque": "b3", "titulo": "Desarrollo, disociación y personalidad", "fragmento": "El **trastorno del espectro autista** se caracteriza por dificultades persistentes en la **comunicación y la interacción social** y por **conductas, intereses o actividades restringidos y repetitivos**, como rutinas muy rígidas o intereses muy intensos. Se habla de espectro porque su intensidad y sus necesidades de apoyo varían mucho. Tiene una base genética fuerte. Es importante saberlo: numerosos estudios con millones de niños han demostrado que **las vacunas no causan autismo**; el artículo que lo afirmó fue retirado por fraude.", "evidencia": ["dificultades persistentes en la comunicación y la interacción social"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('0ebf0c42-785a-52c7-b8aa-fb99c172b1f9', 'f11-tras-14', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd2e85041-8f26-57e1-8402-42ca488be33e', '1b3943b1-c4ef-56cf-ae5f-33ccaf46d27a', 'relacionar', 'Relaciona cada grupo de trastornos de la personalidad con su rasgo común.', null, '{"izquierda": ["A", "B", "C"], "derecha": ["Ansiosos o temerosos", "Dramáticos, emocionales o erráticos", "Raros o excéntricos"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('0ebf0c42-785a-52c7-b8aa-fb99c172b1f9', '{"pares": {"A": "Raros o excéntricos", "B": "Dramáticos, emocionales o erráticos", "C": "Ansiosos o temerosos"}}'::jsonb, 'El DSM agrupa así los trastornos de la personalidad.', '{"leccion": "otros-trastornos", "bloque": "b8", "titulo": "Desarrollo, disociación y personalidad", "fragmento": "Grupos de trastornos de la personalidad: A | Raros o excéntricos | Paranoide, esquizoide, esquizotípico · B | Dramáticos, emocionales o erráticos | Antisocial, límite, histriónico, narcisista · C | Ansiosos o temerosos | Evitativo, dependiente, obsesivo compulsivo de la personalidad", "evidencia": ["Ansiosos o temerosos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('320f45f9-bf54-5741-ad2f-90bba1f9778d', 'f11-tras-15', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd2e85041-8f26-57e1-8402-42ca488be33e', '1b3943b1-c4ef-56cf-ae5f-33ccaf46d27a', 'seleccion_multiple', '¿Por qué es controvertido el trastorno de identidad disociativo?', null, '{"opciones": ["Porque es el trastorno más frecuente", "Porque se cura con fármacos", "Porque solo aparece en niños", "Porque algunos expertos creen que puede verse favorecido por la sugestión en terapia y la cultura popular"]}'::jsonb, null, 2, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('320f45f9-bf54-5741-ad2f-90bba1f9778d', '{"correcta": [3]}'::jsonb, 'Unos lo vinculan a traumas graves y otros a la sugestión.', '{"leccion": "otros-trastornos", "bloque": "b5", "titulo": "Desarrollo, disociación y personalidad", "fragmento": "En los **trastornos disociativos** se altera la integración normal de la conciencia, la memoria o la identidad. En la **amnesia disociativa**, la persona no recuerda información personal importante, normalmente relacionada con un trauma. En el **trastorno de identidad disociativo**, antes llamado de personalidad múltiple, la persona presenta dos o más identidades distintas. Es un diagnóstico controvertido: algunos expertos lo relacionan con traumas graves en la infancia y otros creen que puede verse favorecido por la sugestión en terapia y la cultura popular.", "evidencia": ["puede verse favorecido por la sugestión en terapia"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('7d0ff738-0447-5ed8-80f0-83e304c9e62d', 'f11-tras-16', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'd2e85041-8f26-57e1-8402-42ca488be33e', '1b3943b1-c4ef-56cf-ae5f-33ccaf46d27a', 'respuesta_breve', '¿Qué siglas tiene el trastorno por déficit de atención e hiperactividad?', null, '{}'::jsonb, null, 1, array['fase11','respuesta_breve']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('7d0ff738-0447-5ed8-80f0-83e304c9e62d', '{"aceptadas": ["TDAH"], "solucion": "TDAH"}'::jsonb, 'Incluye inatención, hiperactividad e impulsividad desde la infancia.', '{"leccion": "otros-trastornos", "bloque": "b2", "titulo": "Desarrollo, disociación y personalidad", "fragmento": "El **trastorno por déficit de atención e hiperactividad** se caracteriza por **inatención**, como distraerse con facilidad y perder cosas, y por **hiperactividad e impulsividad**, como no poder estar quieto o interrumpir. Los síntomas aparecen en la infancia, se dan en varios contextos, como casa y colegio, e interfieren en el funcionamiento. Tiene un componente genético importante y en muchas personas continúa en la adultez.", "evidencia": ["El trastorno por déficit de atención e hiperactividad"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('1c0afbdd-83da-5f4a-bbee-d34f7f704b08', 'f11-ter-1', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'e4f88da1-4700-5108-989e-539f65ae5248', '3d1a6388-9277-51a8-b454-64bea8b01d7e', 'ordenar', 'Ordena estos hitos en el tratamiento de los trastornos.', null, '{"elementos": ["Finales del siglo XVIII: Pinel y el tratamiento moral.", "Finales del siglo XX: desinstitucionalización y atención comunitaria.", "Mediados del siglo XX: psicofármacos eficaces.", "Siglo XIX: Dorothea Dix y los hospitales públicos.", "Siglos de encierro en manicomios."]}'::jsonb, null, 1, array['fase11','ordenar']::text[], 'Material integrado del tema', 'publicada')
