insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('1c0afbdd-83da-5f4a-bbee-d34f7f704b08', '{"orden": ["Siglos de encierro en manicomios.", "Finales del siglo XVIII: Pinel y el tratamiento moral.", "Siglo XIX: Dorothea Dix y los hospitales públicos.", "Mediados del siglo XX: psicofármacos eficaces.", "Finales del siglo XX: desinstitucionalización y atención comunitaria."]}'::jsonb, 'El tratamiento pasó del encierro a la atención en la comunidad.', '{"leccion": "historia-y-acceso", "bloque": "b5", "titulo": "Del manicomio a la atención actual", "fragmento": "Hitos en el tratamiento: Siglos de encierro en manicomios.; Finales del siglo XVIII: Pinel y el tratamiento moral.; Siglo XIX: Dorothea Dix y los hospitales públicos.; Mediados del siglo XX: psicofármacos eficaces.; Finales del siglo XX: desinstitucionalización y atención comunitaria.", "evidencia": ["Mediados del siglo XX: psicofármacos eficaces"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('931873a8-ea72-5021-8b23-e5d7a57cede7', 'f11-ter-2', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'e4f88da1-4700-5108-989e-539f65ae5248', '3d1a6388-9277-51a8-b454-64bea8b01d7e', 'seleccion_multiple', '¿Qué permitió iniciar la desinstitucionalización a mediados del siglo XX?', null, '{"opciones": ["La llegada de los primeros psicofármacos eficaces", "El aumento de manicomios", "La desaparición de los trastornos", "La prohibición de la psicoterapia"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('931873a8-ea72-5021-8b23-e5d7a57cede7', '{"correcta": [0]}'::jsonb, 'Los fármacos permitieron que muchas personas vivieran fuera de los hospitales.', '{"leccion": "historia-y-acceso", "bloque": "b4", "titulo": "Del manicomio a la atención actual", "fragmento": "A mediados del siglo XX, la llegada de los primeros **psicofármacos eficaces** permitió que muchas personas vivieran fuera de los hospitales. Empezó la **desinstitucionalización**: el cierre de los grandes hospitales psiquiátricos y el traslado de la atención a la **comunidad**. En España, la reforma psiquiátrica de los años ochenta integró la salud mental en el sistema sanitario general. El reto ha sido crear suficientes recursos comunitarios: cuando faltan, algunas personas quedan sin atención.", "evidencia": ["la llegada de los primeros psicofármacos eficaces"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('0592abee-99d8-586c-8093-61186f4f0afc', 'f11-ter-3', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'e4f88da1-4700-5108-989e-539f65ae5248', '3d1a6388-9277-51a8-b454-64bea8b01d7e', 'verdadero_falso_razonado', 'En España, un ingreso psiquiátrico involuntario puede decidirlo cualquier familiar.', null, '{"razones": ["Falso, porque los ingresos involuntarios no existen.", "Falso, es excepcional y debe autorizarlo un juez.", "Verdadero, basta con la firma de un familiar."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('0592abee-99d8-586c-8093-61186f4f0afc', '{"valor": false, "razon": 1}'::jsonb, 'Casi todo el tratamiento es voluntario; el involuntario requiere autorización judicial.', '{"leccion": "historia-y-acceso", "bloque": "b8", "titulo": "Del manicomio a la atención actual", "fragmento": "Casi todo el tratamiento es **voluntario**: la persona decide pedir ayuda. Solo en casos excepcionales, cuando alguien con un trastorno grave supone un riesgo serio para sí mismo o para otros y no puede decidir, la ley permite un **ingreso involuntario**, que en España debe autorizar un juez.", "evidencia": ["que en España debe autorizar un juez"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
