insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('88a13401-58a1-5f2c-b3bb-fb9f14153bcc', '{"aceptadas": ["024", "el 024"], "solucion": "024"}'::jsonb, 'Es la línea de atención a la conducta suicida, disponible a todas horas.', '{"leccion": "historia-y-acceso", "bloque": "b9", "titulo": "Del manicomio a la atención actual", "fragmento": "Recursos en España. Ante una crisis o ideas de hacerte daño, llama al 024, la línea de atención a la conducta suicida, disponible a todas horas. En una emergencia, llama al 112. Para problemas que no son urgentes, pide cita con tu médico de atención primaria.", "evidencia": ["llama al 024"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('f141faea-147b-584d-abe3-771185d214e2', 'f11-ter-5', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'e4f88da1-4700-5108-989e-539f65ae5248', 'b18e78ea-6ce2-5457-9e4b-143c5f85a38e', 'relacionar', 'Relaciona cada terapia con sus técnicas.', null, '{"izquierda": ["Centrada en el cliente", "Cognitivo conductual", "Conductual", "Psicoanálisis"], "derecha": ["Asociación libre, interpretación de sueños y transferencia", "Empatía, aceptación incondicional y escucha activa", "Exposición, desensibilización sistemática, refuerzo", "Reestructuración cognitiva, tareas y exposición"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
