insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('f141faea-147b-584d-abe3-771185d214e2', '{"pares": {"Psicoanálisis": "Asociación libre, interpretación de sueños y transferencia", "Centrada en el cliente": "Empatía, aceptación incondicional y escucha activa", "Conductual": "Exposición, desensibilización sistemática, refuerzo", "Cognitivo conductual": "Reestructuración cognitiva, tareas y exposición"}}'::jsonb, 'Cada enfoque tiene objetivos y técnicas propios.', '{"leccion": "las-psicoterapias", "bloque": "b12", "titulo": "Las principales psicoterapias", "fragmento": "Las grandes psicoterapias: Psicoanálisis | Hacer consciente lo inconsciente | Asociación libre, interpretación de sueños y transferencia · Centrada en el cliente | Favorecer el crecimiento personal | Empatía, aceptación incondicional y escucha activa · Conductual | Cambiar conductas problemáticas | Exposición, desensibilización sistemática, refuerzo · Cognitivo conductual | Cambiar pensamientos y conductas | Reestructuración cognitiva, tareas y exposición", "evidencia": ["Empatía, aceptación incondicional y escucha activa"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('084a0d7d-f738-5ed0-a76b-5a7ab0aedf62', 'f11-ter-6', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'e4f88da1-4700-5108-989e-539f65ae5248', 'b18e78ea-6ce2-5457-9e4b-143c5f85a38e', 'caso_clinico', '¿Qué técnica está usando?', 'Pablo tiene pánico a los perros. Su terapeuta le enseña a relajarse y después le pide que mire fotos de perros, luego vídeos, después que observe un perro a lo lejos y, por último, que acaricie a un perro tranquilo.', '{"opciones": ["Terapia de juego", "Terapia electroconvulsiva", "Desensibilización sistemática", "Asociación libre"]}'::jsonb, null, 1, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('084a0d7d-f738-5ed0-a76b-5a7ab0aedf62', '{"correcta": [2]}'::jsonb, 'Combina relajación con una jerarquía de situaciones de menos a más temidas.', '{"leccion": "las-psicoterapias", "bloque": "b7", "titulo": "Las principales psicoterapias", "fragmento": "La **terapia conductual** aplica los principios del aprendizaje para cambiar conductas problemáticas. En la **terapia de exposición**, la persona se enfrenta de forma gradual y controlada a lo que teme, sin escapar, hasta que el miedo disminuye por extinción. La **desensibilización sistemática** de Joseph Wolpe combina la relajación con una **jerarquía de miedo**, una lista de situaciones ordenadas de menos a más angustiosas que se recorren poco a poco. La **realidad virtual** permite hoy exponer a situaciones difíciles de recrear, como volar.", "evidencia": ["combina la relajación con una jerarquía de miedo"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('1d50a955-e861-50fc-80fa-2b803e1bf97e', 'f11-ter-7', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'e4f88da1-4700-5108-989e-539f65ae5248', 'b18e78ea-6ce2-5457-9e4b-143c5f85a38e', 'seleccion_multiple', '¿Qué terapia tiene más respaldo científico para la ansiedad, la depresión, el TOC o el insomnio?', null, '{"opciones": ["La terapia cognitivo conductual", "La hipnosis", "El psicoanálisis clásico", "La terapia de juego"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('1d50a955-e861-50fc-80fa-2b803e1bf97e', '{"correcta": [0]}'::jsonb, 'Es estructurada, breve y la más estudiada para estos problemas.', '{"leccion": "las-psicoterapias", "bloque": "b11", "titulo": "Las principales psicoterapias", "fragmento": "La **terapia cognitivo conductual** combina ambos enfoques: cambia a la vez los pensamientos y las conductas. Es estructurada, breve, centrada en el presente y con tareas entre sesiones. Es la terapia con más respaldo científico para muchos trastornos, como la ansiedad, la depresión, el TOC o el insomnio.", "evidencia": ["Es la terapia con más respaldo científico para muchos trastornos"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('deb095b5-8d27-582f-ab6e-a36fad4ccfb0', 'f11-ter-8', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'e4f88da1-4700-5108-989e-539f65ae5248', 'b18e78ea-6ce2-5457-9e4b-143c5f85a38e', 'respuesta_breve', 'Albert ___ creó la terapia racional emotiva, que discute las creencias irracionales.', null, '{"completar": true}'::jsonb, null, 1, array['fase11','completar']::text[], 'Material integrado del tema', 'publicada')
