insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('deb095b5-8d27-582f-ab6e-a36fad4ccfb0', '{"aceptadas": ["Ellis"], "solucion": "Ellis"}'::jsonb, 'Aaron Beck desarrolló la terapia cognitiva de la depresión.', '{"leccion": "las-psicoterapias", "bloque": "b10", "titulo": "Las principales psicoterapias", "fragmento": "La **terapia cognitiva** parte de que no nos afectan tanto los hechos como lo que pensamos de ellos. **Albert Ellis** creó la terapia racional emotiva, que discute las creencias irracionales como «tengo que hacerlo todo perfecto». **Aaron Beck** desarrolló la terapia cognitiva para la depresión, que ayuda a detectar los **pensamientos automáticos** negativos y a comprobar si los datos los respaldan.", "evidencia": ["Albert Ellis creó la terapia racional emotiva"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('252b911a-fb5e-52b9-a4da-47a5644251ec', 'f11-ter-9', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'e4f88da1-4700-5108-989e-539f65ae5248', '9eba0622-3126-5576-8c3f-353d864c6407', 'relacionar', 'Relaciona cada grupo de fármacos con su uso principal.', null, '{"izquierda": ["Antidepresivos", "Antipsicóticos", "Estabilizadores del ánimo", "Estimulantes"], "derecha": ["Depresión y algunos trastornos de ansiedad", "Esquizofrenia y otros trastornos psicóticos", "TDAH", "Trastorno bipolar"]}'::jsonb, null, 2, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
