insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('252b911a-fb5e-52b9-a4da-47a5644251ec', '{"pares": {"Antidepresivos": "Depresión y algunos trastornos de ansiedad", "Antipsicóticos": "Esquizofrenia y otros trastornos psicóticos", "Estabilizadores del ánimo": "Trastorno bipolar", "Estimulantes": "TDAH"}}'::jsonb, 'Cada grupo actúa sobre neurotransmisores distintos.', '{"leccion": "tratamientos-biomedicos-y-formatos", "bloque": "b2", "titulo": "Tratamientos biomédicos y formatos de terapia", "fragmento": "Grupos de psicofármacos: Antidepresivos | Depresión y algunos trastornos de ansiedad | Aumentan la serotonina o la noradrenalina, por ejemplo bloqueando su recaptación · Ansiolíticos | Ansiedad intensa a corto plazo | Potencian el GABA; las benzodiacepinas generan dependencia · Antipsicóticos | Esquizofrenia y otros trastornos psicóticos | Bloquean receptores de dopamina · Estabilizadores del ánimo | Trastorno bipolar | El litio y otros reducen los cambios extremos · Estimulantes | TDAH | Aumentan la dopamina y la noradrenalina", "evidencia": ["Trastorno bipolar"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('0e0a00e9-4765-5e13-aa35-1987b0c3bae9', 'f11-ter-10', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'e4f88da1-4700-5108-989e-539f65ae5248', '9eba0622-3126-5576-8c3f-353d864c6407', 'verdadero_falso_razonado', 'La terapia electroconvulsiva actual se aplica sin anestesia y está desaconsejada en todos los casos.', null, '{"razones": ["Falso, porque se usa para tratar el TDAH.", "Falso, se aplica con anestesia y es eficaz en depresiones graves resistentes.", "Verdadero, porque es un castigo antiguo."]}'::jsonb, null, 2, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('0e0a00e9-4765-5e13-aa35-1987b0c3bae9', '{"valor": false, "razon": 1}'::jsonb, 'Su imagen es negativa por el pasado, pero hoy es segura y eficaz en casos concretos.', '{"leccion": "tratamientos-biomedicos-y-formatos", "bloque": "b5", "titulo": "Tratamientos biomédicos y formatos de terapia", "fragmento": "La **terapia electroconvulsiva** consiste en provocar una breve convulsión con una corriente eléctrica mientras el paciente está bajo anestesia general y con relajantes musculares. Su imagen pública es muy negativa por cómo se aplicaba en el pasado, pero hoy es un tratamiento seguro y de los más eficaces para la **depresión grave** que no responde a otros tratamientos. Puede causar pérdidas de memoria, normalmente pasajeras. La **estimulación magnética transcraneal** usa campos magnéticos sobre el cuero cabelludo para estimular zonas concretas de la corteza, sin anestesia, y también se usa en la depresión resistente.", "evidencia": ["mientras el paciente está bajo anestesia general"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('f653e767-7c91-5913-9a0f-38b8e2dcaa24', 'f11-ter-11', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'e4f88da1-4700-5108-989e-539f65ae5248', '9eba0622-3126-5576-8c3f-353d864c6407', 'seleccion_multiple', '¿Qué ventaja tiene la terapia de grupo?', null, '{"opciones": ["Apoyo mutuo, sentir que no se está solo y menor coste", "Permite recetar fármacos", "Atención totalmente personalizada", "No necesita terapeuta"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('f653e767-7c91-5913-9a0f-38b8e2dcaa24', '{"correcta": [0]}'::jsonb, 'Compartir con personas con problemas parecidos ayuda.', '{"leccion": "tratamientos-biomedicos-y-formatos", "bloque": "b7", "titulo": "Tratamientos biomédicos y formatos de terapia", "fragmento": "Formatos de terapia: Individual | Una persona y su terapeuta | Atención totalmente personalizada · De grupo | Varias personas con problemas parecidos y uno o dos terapeutas | Apoyo mutuo, sentir que no se está solo y menor coste · De pareja | Los dos miembros de la pareja | Mejorar la comunicación y resolver conflictos · Familiar | Toda la familia o parte de ella | Cambiar patrones de relación que mantienen el problema", "evidencia": ["Apoyo mutuo, sentir que no se está solo y menor coste"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('7dc58c42-1fd5-5f35-a2f3-5ee4c10e3bd4', 'f11-ter-12', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'e4f88da1-4700-5108-989e-539f65ae5248', '9eba0622-3126-5576-8c3f-353d864c6407', 'caso_clinico', '¿Qué formato de terapia parece más indicado?', 'Una adolescente tiene problemas de conducta. El terapeuta observa que sus padres discuten constantemente delante de ella y que cada uno le da normas contradictorias.', '{"opciones": ["Ningún tratamiento", "Terapia familiar", "Terapia electroconvulsiva", "Terapia individual solo con la adolescente"]}'::jsonb, null, 2, array['fase11','caso_clinico']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('7dc58c42-1fd5-5f35-a2f3-5ee4c10e3bd4', '{"correcta": [1]}'::jsonb, 'La terapia familiar trabaja los patrones de relación que mantienen el problema.', '{"leccion": "tratamientos-biomedicos-y-formatos", "bloque": "b8", "titulo": "Tratamientos biomédicos y formatos de terapia", "fragmento": "La **terapia familiar** parte de que el problema de una persona forma parte del **sistema familiar**: la forma en que la familia se comunica, se organiza y reparte los papeles puede mantenerlo. Por eso trabaja con todos sus miembros. Los **grupos de autoayuda**, como los de personas con una adicción o familiares de personas con un trastorno, no los dirige un terapeuta, pero ofrecen apoyo valioso.", "evidencia": ["el problema de una persona forma parte del sistema familiar"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('b4ce0148-e415-59a6-8e5d-a6c222d6f240', 'f11-ter-13', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'e4f88da1-4700-5108-989e-539f65ae5248', 'c8411233-54c3-5131-950e-d741d311ea8d', 'verdadero_falso_razonado', 'Una recaída significa que el tratamiento de una adicción ha fracasado.', null, '{"razones": ["Falso, las recaídas son frecuentes y señalan que hay que ajustar el tratamiento.", "Verdadero, hay que empezar de cero y no tiene sentido seguir.", "Falso, porque las adicciones no tienen recaídas."]}'::jsonb, null, 1, array['fase11','verdadero_falso_razonado']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('b4ce0148-e415-59a6-8e5d-a6c222d6f240', '{"valor": false, "razon": 0}'::jsonb, 'La prevención de recaídas forma parte del tratamiento.', '{"leccion": "adicciones-cultura-y-eficacia", "bloque": "b2", "titulo": "Adicciones, cultura y qué hace que la terapia funcione", "fragmento": "El tratamiento de un **trastorno por consumo de sustancias** suele empezar por la **desintoxicación**, retirar la sustancia con supervisión médica para manejar la abstinencia. Después siguen la **psicoterapia**, sobre todo cognitivo conductual, para identificar las situaciones de riesgo y aprender a afrontarlas; a veces fármacos que reducen el deseo o sustituyen la sustancia de forma controlada; y la **prevención de recaídas**. Las recaídas son frecuentes y no significan fracaso, sino una señal de que hay que ajustar el tratamiento.", "evidencia": ["Las recaídas son frecuentes y no significan fracaso"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('1cba8cd1-9639-56d3-9431-886b56d59038', 'f11-ter-14', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'e4f88da1-4700-5108-989e-539f65ae5248', 'c8411233-54c3-5131-950e-d741d311ea8d', 'seleccion_multiple', '¿Cómo se tratan mejor la adicción y la depresión cuando aparecen juntas?', null, '{"opciones": ["Esperando a que una desaparezca sola", "Tratando ambos problemas a la vez y de forma coordinada", "Tratando solo la depresión", "Tratando solo la adicción"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
