insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('1cba8cd1-9639-56d3-9431-886b56d59038', '{"correcta": [1]}'::jsonb, 'En la patología dual, los mejores resultados vienen del tratamiento integrado.', '{"leccion": "adicciones-cultura-y-eficacia", "bloque": "b3", "titulo": "Adicciones, cultura y qué hace que la terapia funcione", "fragmento": "Muchas personas con una adicción tienen también otro trastorno, como depresión, ansiedad o estrés postraumático. Es lo que se llama **patología dual**. A veces la sustancia se empezó a usar para aliviar ese malestar. Los mejores resultados se obtienen cuando se tratan **ambos problemas a la vez** y de forma coordinada.", "evidencia": ["cuando se tratan ambos problemas a la vez"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('a85e863f-6bbe-50e5-93a4-d0e8791ebf43', 'f11-ter-15', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'e4f88da1-4700-5108-989e-539f65ae5248', 'c8411233-54c3-5131-950e-d741d311ea8d', 'relacionar', 'Relaciona cada concepto con su definición.', null, '{"izquierda": ["Alianza terapéutica", "Competencia cultural", "Desintoxicación"], "derecha": ["Entender y respetar la cultura del paciente", "Relación de confianza y colaboración entre paciente y terapeuta", "Retirar la sustancia con supervisión médica"]}'::jsonb, null, 1, array['fase11','relacionar']::text[], 'Material integrado del tema', 'publicada')
on conflict (id) do update set module_id = excluded.module_id, lesson_id = excluded.lesson_id, tipo = excluded.tipo, enunciado = excluded.enunciado, caso = excluded.caso, payload = excluded.payload, media_id = excluded.media_id, dificultad = excluded.dificultad, etiquetas = excluded.etiquetas, fuente = excluded.fuente, estado = 'publicada';
insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('a85e863f-6bbe-50e5-93a4-d0e8791ebf43', '{"pares": {"Desintoxicación": "Retirar la sustancia con supervisión médica", "Competencia cultural": "Entender y respetar la cultura del paciente", "Alianza terapéutica": "Relación de confianza y colaboración entre paciente y terapeuta"}}'::jsonb, 'Son piezas clave de un tratamiento eficaz y respetuoso.', '{"leccion": "adicciones-cultura-y-eficacia", "bloque": "b2", "titulo": "Adicciones, cultura y qué hace que la terapia funcione", "fragmento": "El tratamiento de un **trastorno por consumo de sustancias** suele empezar por la **desintoxicación**, retirar la sustancia con supervisión médica para manejar la abstinencia. Después siguen la **psicoterapia**, sobre todo cognitivo conductual, para identificar las situaciones de riesgo y aprender a afrontarlas; a veces fármacos que reducen el deseo o sustituyen la sustancia de forma controlada; y la **prevención de recaídas**. Las recaídas son frecuentes y no significan fracaso, sino una señal de que hay que ajustar el tratamiento. La cultura influye en cómo se viven y se expresan los problemas psicológicos, en si se busca ayuda y en qué se espera de ella. En algunas culturas el malestar emocional se expresa sobre todo con síntomas físicos, y pedir ayuda fuera de la familia se vive como una vergüenza. La **competencia cultural** es la capacidad del terapeuta de conocer, entender y respetar la cultura del paciente, y de adaptar el tratamiento sin imponer sus propios valores. Las minorías y las personas migrantes acceden menos a la atención en salud mental, y la competencia cultural ayuda a reducir esa brecha. La **alianza terapéutica**, la relación de confianza en la que paciente y", "evidencia": ["retirar la sustancia con supervisión médica"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
insert into public.course_questions (id, legacy_id, course_id, module_id, lesson_id, tipo, enunciado, caso, payload, media_id, dificultad, etiquetas, fuente, estado)
values ('6620daaa-7a90-521f-8acb-44cc918a6772', 'f11-ter-16', 'bb2ec0e6-6384-5269-98fa-72cafd57cf55', 'e4f88da1-4700-5108-989e-539f65ae5248', 'c8411233-54c3-5131-950e-d741d311ea8d', 'seleccion_multiple', '¿Qué es uno de los mejores predictores del éxito de una terapia?', null, '{"opciones": ["Que el terapeuta hable mucho", "Que la terapia dure muchos años", "El precio de las sesiones", "La alianza terapéutica"]}'::jsonb, null, 1, array['fase11','seleccion_multiple']::text[], 'Material integrado del tema', 'publicada')
