insert into private.course_answer_keys (question_id, clave, explicacion, referencia) values ('6620daaa-7a90-521f-8acb-44cc918a6772', '{"correcta": [3]}'::jsonb, 'La relación de confianza y colaboración es un factor común a todas las terapias eficaces.', '{"leccion": "adicciones-cultura-y-eficacia", "bloque": "b9", "titulo": "Adicciones, cultura y qué hace que la terapia funcione", "fragmento": "La **alianza terapéutica**, la relación de confianza en la que paciente y terapeuta trabajan juntos hacia objetivos compartidos, es uno de los mejores predictores del éxito. Por eso, si no te sientes cómodo con un terapeuta después de varias sesiones, es razonable hablarlo con él o buscar otro.", "evidencia": ["es uno de los mejores predictores del éxito"]}'::jsonb)
on conflict (question_id) do update set clave = excluded.clave, explicacion = excluded.explicacion, referencia = excluded.referencia, updated_at = now();
